(window.GIM_TS=window.GIM_TS||{})["Berakhot.0"]={"from":0,"a":[["ראשיתה של מסכת ברכות — ראשונה לכל המסכתות שבששת הסדרים — היא בענין קריאת שמע, שיש בה קבלת עול מלכות שמים וקבלת עול מצוות, והריהי משמשת איפוא כיסוד ושורש לכל הנשנה בעקבותיה. ופותחים בדיני זמן קריאת שמע: \u0003מאימתי\u0004 (ממתי, מאיזו שעה) מתחיל הזמן בו \u0003קורין\u0004 (קוראים) \u0003את\u0004 קריאת \u0003שמע בערבין\u0004 (בערבים)? \u0003משעה שהכהנים\u0004 הטמאים (כגון מצורע או זב) שנטהרו \u0003נכנסים לאכול בתרומתן.\u0004 ועד מתי הוא זמן קריאת שמע של ערבית? \u0003עד סוף האשמורה הראשונה\u0004 של הלילה. שכך מובנה של המלה \"ובשכבך\" הנאמרת במצות קריאת שמע של ערבית (דברים ו, ז) — כאשר נפנה האדם לשכב על מיטתו על מנת לישון, וזמן הקריאה הריהו איפוא פרק הזמן בו אנשים מכינים את עצמם לשנת הלילה, והוא בחלקו הראשון של הלילה, אלו \u0003דברי ר' אליעזר.\u0004","\u0003וחכמים אומרים:\u0004 זמן קריאת שמע של ערבית הוא \u0003עד חצות\u0004 הלילה.","ואילו \u0003רבן גמליאל אומר\u0004 כי מותר לקרות קריאת שמע של ערבית \u0003עד שיעלה עמוד השחר,\u0004 שכן מובנה של המלה \"ובשכבך\" — כל זמן שבני אדם שוכבים בלילה על מיטתם, והרי זה איפוא כל הלילה כולו.","ומסופר שכן אף נהג רבן גמליאל כהוראתו, שכך היה \u0003מעשה ובאו\u0004 (שבו לביתם) \u0003בניו\u0004 של רבן גמליאל בשעה מאוחרת בלילה \u0003מבית המשתה\u0004 (מקום בו נערכה סעודת נישואין), \u0003ואמרו לו:\u0004 עדיין \u0003לא קרינו\u0004 (קראנו) \u0003את\u0004 קריאת \u0003שמע\u0004 של ערבית בשל טרדתנו בשמחת חתן וכלה, ופסק \u0003להם\u0004 אביהם: \u0003אם לא עלה\u0004 עדיין \u0003עמוד השחר חייבין אתם לקרות.\u0004 ובהיות ודעת רבן גמליאל הינה דעת יחיד כנגד דעת שאר החכמים הסבורים כי זמן קריאת שמע הוא עד חצות, הטעים את הוראתו שכן היא גם לדעת חכמים, \u0003ו\u0004כי \u0003לא\u0004 בהלכה \u0003זו\u0004 (קריאת שמע) \u0003בלבד אמרו, אלא\u0004 גם \u0003כל מה שאמרו חכמים \"עד חצות\",\u0004 מעיקר הדין \u0003מצותן עד שיעלה עמוד השחר.\u0004","ומביא רבן גמליאל כמה דוגמאות לעקרון זה, כגון: מצות \u0003הקטר\u0004 (שריפת) \u0003חלבים ואיברים\u0004 של הקרבנות על המזבח, אשר בשל ריבוי הקרבנות שהוקרבו לא הספיקו במהלך היום להעלות על המזבח את כל החלבים והאיברים, ועל כן המשיכו להקטירם כל הלילה, ככתוב \"זאת תורת העולה, היא העולה על מוקדה על המזבח כל הלילה עד הבוקר ואש המזבח תוקד בו\" (ויקרא ו, ב), \u0003ו\u0004כן \u0003כל הנאכלים ליום אחד,\u0004 אותם קרבנות, כמו החטאת והאשם, שמותר לאכלם רק ביום שחיטתם ובלילה שלאחריו, אף שאמרו חכמים שהם נאכלים \"ליום ולילה עד חצות\" מדין התורה \u0003מצותן עד שיעלה עמוד השחר,\u0004 אבל לא מאוחר יותר, ככתוב \"ביום קרבנו יאכל לא יניח ממנו עד בקר\" (ויקרא ז, טו). \u0003אם כן, למה אמרו חכמים\u0004 שזמנם \u0003\"עד חצות\"\u0004 — \u0003כדי להרחיק\u0004 את ה\u0003אדם מן העבירה,\u0004 שאם יתירו מתחילה לעשות את המצוה עד עלות השחר, עלול אדם להתרשל ולדחותה, עד אשר יעבור זמנה של המצוה.","המשנה פתחה בדיני קריאת שמע בשאלה מאימתי קוראים את קריאת שמע של ערבית, ושואלים על כך: ה\u0003תנא\u0004 של משנתנו \u0003היכא קאי דקתני\u0004 \u0005[היכן הוא עומד\u0006 בהסתמך על אלו דברים קודמים הוא ממשיך, בזה \u0005ש\u0006הוא \u0005שונה]\u0006 \u0003\"מאימתי\"?\u0004 שמסגנון זה נראה כאילו כבר שנה קודם למשנתנו זו את עיקר ההלכה של חובת קריאת שמע בערבית, ומעתה הוא ממשיך ומפרט אותה. והרי משנתנו הינה המשנה הראשונה בששת סדרי המשנה?","\u0003ותו\u0004 \u0005[ועוד]\u0006 שאלה: \u0003מאי שנא דתני\u0004 \u0005[מה שונה,\u0006 מדוע שינה התנא מן הסדר, בכך \u0005ש\u0006הוא \u0005שונה,\u0006 עוסק\u0005]\u0006 כאן \u0003ב\u0004נושא של קריאת שמע של \u0003ערבית ברישא\u0004 \u0005[בתחילה]?\u0006 \u0003לתני\u0004 \u0005[שישנה]\u0006 את דינה של קריאת שמע של \u0003שחרית ברישא\u0004 \u0005[בתחילה]!\u0006 שהרי רוב המצוות נוהגות ביום, ואף בקרבנות מוקדם קרבן השחר לקרבן הערב (תוהרא\"ש).","על שתי השאלות הללו באה תשובה אחת: ה\u0003תנא אקרא קאי, דכתיב\u0004 \u0005[על הכתוב עומד,\u0006 נסמך\u0005, ש\u0006כך \u0005נאמר]:\u0006 \"ודברת בם בשבתך בביתך ובלכתך בדרך ו\u0003בשכבך ובקומך\"\u0004 (דברים ו, ז), שבאמצעות סגנון זה, מלמדנו התנא כי ההלכות שבתורה שבעל פה הריהן נסמכות על האמור בתורה שבכתב. \u0003ו\u0004מתוך שנסמכו דברי המשנה על כתוב זה, \u0003הכי קתני\u0004 \u0005[כך שנינו],\u0006 שכך יש לשנות במשנה: \u0003זמן קריאת שמע\u0004 של \u0003שכיבה\u0004 שנצטווינו עליה בתורה \u0003אימת\u0004 \u0005[מתי]\u0006 הוא? — \u0003משעה שהכהנים נכנסין לאכול בתרומתן.\u0004 ומובן, כי בשל ההסתמכות על המקרא, גם המשנה מתחילה לבאר קודם מהו \"בשכבך\".","\u0003ו\u0004באשר לשאלה מדוע הקדימה המשנה את קריאת שמע של ערבית לקריאת שמע של שחרית, \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר אחר: \u0003יליף\u0004 \u0005[למד]\u0006 התנא סדר זה \u0003מברייתו\u0004 (בריאתו) \u0003של עולם, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 במעשה בראשית: \u0003\"ויהי ערב ויהי בקר יום אחד\"\u0004 (בראשית א, ה), והרי שהיום מתחיל מן הערב ולא מן הבוקר. ומטעמים אלה ראוי לפתוח תחילה בהלכות קריאת שמע הנוהגת בערב.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 ב\u0003סיפא דקתני\u0004 \u0005[\u0006ב\u0005סוף\u0006 המשנה \u0005ששנינו]\u0006 בהמשך הפרק \u0003\"בשחר מברך שתים,\u0004 שתי ברכות, \u0003לפניה,\u0004 לפני קריאת שמע, \u0003ואחת לאחריה, ובערב מברך שתים לפניה ושתים לאחריה\", ו\u0004הלא לפי האמור נכון היה \u0003לתני\u0004 \u0005[שישנה]\u0006 של \u0003ערבית ברישא\u0004 \u0005[בתחילה]!\u0006","ועונים: אכן, ה\u0003תנא פתח\u0004 דבריו \u0003ב\u0004הלכות הנוגעות ל\u0003ערבית, והדר תני\u0004 \u0005וחזר\u0006 ו\u0005שנה]\u0006 אחר כך \u0003ב\u0004הלכות \u0003שחרית,\u0004 ו\u0003עד\u0004 (מתוך) \u0003דקאי\u0004 \u0005[ש\u0006הוא \u0005עומד,\u0006 נמצא\u0005]\u0006 \u0003בשחרית, פריש מילי\u0004 \u0005[פירש\u0006 כל \u0005עניני]\u0006 \u0003שחרית, והדר פריש מילי\u0004 \u0005[וחזר\u0006 אחר כך ו\u0005פירש עניני]\u0006 \u0003ערבית.\u0004","מעתה נפנים לברר את המשך הדברים במשנה. \u0003אמר מר\u0004 \u0005[החכם]\u0006 במשנה שזמן תחילת קריאת שמע הוא \u0003משעה שהכהנים\u0004 הטמאים שנטהרו \u0003נכנסים לאכול בתרומתן.\u0004 ואולם, שעה זו שבה הכהנים נכנסים לאכול בתרומתן איננה ציון זמן מוגדר כשלעצמו, ו\u0003מכדי\u0004 \u0005[הרי]\u0006 ה\u0003כהנים אימת קא אכלי\u0004 \u0005[מתי הם אוכלים]\u0006 \u0003תרומה?\u0004 — \u0003משעת צאת הכוכבים,\u0004 ואם כן \u0003לתני\u0004 \u0005[שישנה]\u0006 במפורש: \u0003\"משעת צאת הכוכבים\"!\u0004","ומשיבים: אכן, לקביעת זמן קריאת שמע פשוט היה יותר לומר שהוא זמן צאת הכוכבים, ואולם על ידי סגנון זה \u0003מלתא אגב אורחיה קמשמע לן\u0004 \u0005[דבר\u0006 נוסף \u0005השמיע לנו בדרך אגב]\u0006 — \u0003כהנים אימת קא אכלי\u0004 \u0005[מתי הם אוכלים]\u0006 \u0003בתרומה\u0004 — \u0003משעת צאת הכוכבים. והא קמשמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]\u0006 אגב כך חידוש הלכה ש\u0003כפרה לא מעכבא\u0004 \u0005[אינה מעכבת],\u0006 שאף שכבר טבל הכהן לטהרתו, מכל מקום חייב הוא עדיין להביא קרבן מיוחד לכפרה, וכל עוד לא הביאו עדיין לא הגיע איפוא לטהרה שלימה, ואף על פי כן מותר לו כבר לאכול בתרומה. חידוש זה המובא במשנתנו בדרך אגב, מתפרש בברייתא בשלמותו, כשהוא נדרש מלשון הכתוב. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר בדיני טומאה \"נפש אשר תגע בו וטמאה עד הערב, ולא יאכל מן הקדשים כי אם רחץ בשרו במים. ובא השמש וטהר ואחר יאכל מן הקדשים כי לחמו הוא\" (ויקרא כב, ו), ויש ללמוד מן האמור \u0003\"ובא השמש וטהר\"\u0004 שדווקא \u0003ביאת\u0004 (שקיעת) \u0003שמשו\u0004 היא ה\u0003מעכבתו מלאכול בתרומה, ואין כפרתו\u0004 (הבאת הקרבנות המכפרים) \u0003מעכבתו מלאכול בתרומה.\u0004","ודנים בראיה המובאת בברייתא: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005],\u0006 ש\u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"ובא השמש\"\u0004 פירושו \u0003ביאת השמש,\u0004 שהיא שקיעתה המלאה, ולכן \u0003\"וטהר\"\u0004 יהא משמעו \u0003טהר יומא\u0004 \u0005[נטהר,\u0006 הושלם \u0005היום],\u0006 שיבוא השמש, ויהא האויר נקי, ויראו הכוכבים (רה\"ג), והמילים \"ובא השמש וטהר\" הן ביטוי אחד שמשמעו שקיעתה המלאה של השמש."],["\u0003דילמא\u0004 \u0005[אולי]\u0006 פירוש \"ובא השמש\" — \u0003ביאת אורו הוא,\u0004 רק תחילתה של השקיעה, \u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"וטהר\"\u0004 — \u0003טהר גברא\u0004 \u0005[יטהר האדם],\u0006 שילך הכהן הטמא עם תחילת השקיעה, ויקריב את קרבנותיו (כפרתו) ורק אז יהא כשר לאכול את התרומה (תוספות)?!","על כך \u0003אמר רבה בר רב שילא: אם כן,\u0004 שפירוש המלה \"וטהר\" הוא ציווי לכהן ללכת ולהיטהר, \u0003לימא קרא\u0004 \u0005[יאמר הכתוב]:\u0006 \u0003\"ויטהר\",\u0004 וישתמש בביטוי חד משמעי, ומאחר שלא נאמר בתורה כך, עלינו לומר ש\u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"וטהר\"\u0004 — \u0003טהר יומא\u0004 \u0005[טהר היום],\u0006 ויהא זה \u0003כדאמרי אינשי\u0004 \u0005[כפי שאומרים אנשים]\u0006 כפתגם עממי: \u0003\"איערב שמשא, ואדכי יומא\"\u0004 \u0005[שקעה השמש, ונטהר היום].\u0006","\u0003במערבא, הא\u0004 \u0005[בארץ ישראל,\u0006 סברה \u0005זו]\u0006 של \u0003רבה בר רב שילא לא שמיע להו\u0004 \u0005[שמעו],\u0006 \u0003ובעו לה מיבעיא\u0004 \u0005[ושאלו אותה בשאלה]:\u0006 האם \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"ובא השמש\"\u0004 כוונתו \u0003ביאת שמשו הוא, ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"וטהר\"\u0004 — \u0003טהר יומא\u0004 \u0005[טהר היום],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003ביאת אורו הוא, ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"וטהר\"\u0004 — \u0003טהר גברא\u0004 \u0005[יטהר האדם],\u0006 שניסו לברר את ההלכה מתוך הכתוב, והגיעו לספק בהבנתו,","\u0003ו\u0004שאלה זו \u0003הדר פשטו לה\u0004 \u0005[חזרו ופתרו אותה]\u0006 \u0003מברייתא. מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנינו]\u0006 \u0003בברייתא\u0004 שנקבעה שעת קריאת שמע משעה שהכהנים רשאים לאכול בתרומתם, \u0003סימן לדבר\u0004 — \u0003צאת הכוכבים.\u0004 הרי \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שיש להבין כי \"ובא השמש\" — \u0003ביאת שמשו הוא, ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"וטהר\"\u0004 — \u0003טהר יומא\u0004 \u0005[יטהר היום],\u0006 וכפי שהגיעו לסיכום זה בבבל.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 במשנתנו כי זמן תחילת קריאת שמע בערב הוא \u0003משעה שהכהנים נכנסים לאכול בתרומתן. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לדעה זו ממה ששנינו בברייתא: \u0003מאמתי קורין\u0004 (קוראים) \u0003את שמע בערבין\u0004 — \u0003מ\u0004שעה \u0003שהעני נכנס לאכול פתו במלח, עד שעה שעומד ליפטר מתוך סעודתו.\u0004 ומבררים תחילה אם אכן קיימת כאן מחלוקת, או שזו שיטה אחת שנאמרה באופני התבטאות שונים.","\u0003סיפא\u0004 \u0005[הסוף]\u0006 של הברייתא, הקובעת את סוף זמן קריאת שמע בשעה שעומד העני להיפטר מתוך סעודתו \u0003ודאי פליגא אמתניתין\u0004 \u0005[חלוקה על משנתנו],\u0006 שוודאי שאין סעודת העני נמשכת עד סוף האשמורה, שהרי כעני ודאי סעודתו דלה ביותר ואינו מאריך בה. ואולם ביחס ל\u0003רישא\u0004 \u0005[ההתחלה]\u0006 בברייתא הקובעת את תחילת זמן קריאת שמע של ערב יש לברר: \u0003מי לימא פליגא אמתניתין\u0004 \u0005[האם לומר\u0006 כי \u0005חולקת\u0006 היא \u0005על משנתנו]?\u0006","ומיד דוחים הנחה זו: \u0003לא,\u0004 זמן אכילתו של ה\u0003עני ו\u0004הזמן בו נטהר ה\u0003כהן\u0004 לאכול בתרומה \u0003חד שיעורא\u0004 \u0005[שיעור אחד]\u0006 \u0003הוא.\u0004","\u0003ו\u0004כדי לברר את הנושא \u0003רמינהו\u0004 \u0005[משליכים,\u0006 מביאים מן התוספתא\u0005]\u0006 שכך שנינו בה: \u0003מאימתי מתחילין לקרות קריאת שמע בערבית\u0004 — \u0003משעה שבני אדם נכנסין לאכול פתן בערבי שבתות,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים\u0004 כמשנתנו: \u0003משעה שהכהנים זכאין לאכול בתרומתן.\u0004 ו\u0003סימן לדבר: צאת הכוכבים. ואף על פי שאין ראיה\u0004 מפורשת \u0003לדבר\u0004 זה ששעת צאת הכוכבים היא תחילת הזמן לקריאת שמע של ערבית, לכל הפחות יש \u0003זכר לדבר\u0004 שצאת הכוכבים נחשב כרגיל תחילתו של הלילה, כי כאשר מספר נחמיה על בנין החומה בימי בית שני \u0003נאמר: \"ואנחנו עשים במלאכה וחצים מחזיקים ברמחים מעלות השחר עד צאת הכוכבים\"\u0004 (נחמיה ד, טו), \u0003ואומר\u0004 עוד: \u0003\"והיו לנו הלילה משמר והיום מלאכה\"\u0004 (נחמיה ד, טז), הרי שהיום מסתיים עם צאת הכוכבים.","עוד לפני שדנים בהשוואת המקורות, מבררים תמיהה מסויימת בלשון התוספתא. בהוכחתם מן המקרא אין חכמים מסתפקים בפסוק אחד, אלא מוסיפים עוד \"ואומר...\", אך לכאורה אין צורך בתוספת זו שהרי כל ההוכחה מצויה כבר בפסוק הראשון, ואם כן \u0003מאי\u0004 \u0005[\u0006לשם \u0005מה]\u0006 מוסיפים \u0003\"ואומר\"?\u0004","ומשיבים: אין די בפסוק הראשון לבדו, לפי שאפשר להקשות: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003מכי ערבא שמשא, ליליא\u0004 \u0005[מכאשר ששוקעת השמש, לילה]\u0006 \u0003הוא, ואינהו דמחשכי ומקדמי\u0004 \u0005[והם שהחשיכו והקדימו],\u0006 שמשום חשיבות העבודה עבדו גם בלילה, על כן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה מן הפסוק \u0003\"והיו לנו הלילה משמר והיום מלאכה\"\u0004 שהזמן בין עלות השחר לצאת הכוכבים נקרא בפירוש \"יום\".","כדי להשוות את שלוש השיטות בקביעת זמן תחילת קריאת שמע, הועלתה מתחילה השערה \u0003קא סלקא דעתך\u0004 \u0005[עלה על דעתך]\u0006 לומר שהזמן בו אוכל \u0003עני\u0004 את סעודתו כרגיל, \u0003ו\u0004הזמן שבו אוכלים \u0003בני אדם\u0004 סתם את סעודתם בליל שבת \u0003חד שעורא\u0004 \u0005[שיעור אחד]\u0006 \u0003הוא,\u0004 כיון שבשני המקרים חפצים להקדים ככל האפשר את זמן הסעודה משום שאין רוצים (או יכולים) להדליק נרות נוספים להאיר בשעת האוכל. \u0003ו\u0004אולם, \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי זמן סעודת ה\u0003עני ו\u0004הזמן ש\u0003כהן\u0004 שנטהר מטומאתו רשאי לאכול בתרומה \u0003חד שעורא\u0004 \u0005[שיעור אחד]\u0006 \u0003הוא,\u0004 מכאן ששיטת \u0003חכמים היינו\u0004 \u0005[זוהי]\u0006 בדיוק שיטת \u0003ר' מאיר,\u0004 ומה היא איפוא המחלוקת ביניהם?","\u0003אלא\u0004 על כן יש לדחות את מה שאמרנו, ולומר כי \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003'עני'\u0004 הוא \u0003שעורא\u0004 \u0005[שיעור]\u0006 \u0003לחוד ו'כהן'\u0004 הוא \u0003שעורא\u0004 \u0005[שיעור]\u0006 \u0003לחוד.\u0004 ואולם דברים אלה היו מבוססים רק על הנחה כי 'עני' ו'בני אדם' זהים הם, ואפשר לדחות את המסקנה הזו, ולומר כי \u0003לא\u0004 כן הוא, אלא \u0003'עני' ו'כהן' חד שעורא\u0004 \u0005[שיעור אחד]\u0006 \u0003הוא,\u0004 ודווקא \u0003'עני' ו'בני אדם' לאו חד שעורא\u0004 \u0005[לא שיעור אחד]\u0006 \u0003הוא,\u0004 ודעת התנא בברייתא זהה לשיטת שאר התנאים, ורק ר' מאיר לבדו חולק עליהם.","אפשר איפוא להניח ש'עני' ו'כהן' הינם שיעור אחד, ושואלים: \u0003ו\u0004כי \u0003עני וכהן חד שעורא\u0004 \u0005[שיעור אחד]\u0006 \u0003הוא? ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לשיטה זו ממה ששנינו בבריתא אחרת, שבה הובאו שיטות אחרות בקביעות זמן קריאת שמע של ערבית: \u0003מאימתי מתחילין לקרות\u0004 קריאת \u0003שמע בערבין\u0004 — \u0003משעה שקדש היום בערבי שבתות,\u0004 אלו \u0003דברי ר' אליעזר,\u0004 שלדעתו יש להקדים את זמן הקריאה לשעת כניסת השבת. \u0003ר' יהושע אומר\u0004 כשיטת משנתנו: \u0003משעה שהכהנים מטוהרים לאכול בתרומתן. ר' מאיר\u0004 מביע גם הוא דעה, שאינה זהה לדעתו בתוספתא, ו\u0003אומר\u0004 שתחילת זמן קריאת שמע היא עוד לפני שנטהרו הכהנים, כלומר, \u0003משעה שהכהנים טובלין לאכול בתרומתן. אמר לו ר' יהודה:\u0004 כיצד אפשר לקבוע קריאת שמע של ערבית עם טבילת הכהנים, \u0003והלא\u0004 ה\u0003כהנים מבעוד יום הם טובלים\u0004 כדי שבהגיע הערב (שהוא תחילת היום הבא) יהיו כבר טהורים, ואם כן כיצד אפשר לקרוא לזמן זה לילה? \u0003ר' חנינא אומר\u0004 שהזמן הוא \u0003משעה שעני נכנס לאכול פתו במלח. ואילו ר' אחאי ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' אחא\u0004 ש\u0003אומר: משעה שרוב בני אדם נכנסים להסב\u0004 בימות השבוע.","עד כאן לשון הברייתא, ולענייננו \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003'עני' ו'כהן' חד שעורא\u0004 \u0005[שיעור אחד]\u0006 \u0003הוא,\u0004 אם כן שיטת \u0003ר' חנינא היינו\u0004 \u0005[זוהי]\u0006 בדיוק שיטת \u0003ר' יהושע,\u0004 ומאחר שמובאות שתי הדעות יחד, ברור כי שני שיעורים אלה אינם זהים!","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003שעורא\u0004 \u0005[השיעור]\u0006 של \u0003'עני' לחוד ושעורא\u0004 \u0005[והשיעור]\u0006 של \u0003'כהן' לחוד,\u0004 ומאחר שאין כל ערעור להוכחה זו הפעם, מסכימים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","ולאחר שהחלטנו כי שני שיעורים אלה שונים הם, ראוי לברר \u0003הי מינייהו\u0004 \u0005[איזה מהם]\u0006 \u0003מאוחר\u0004 יותר? והתשובה היא כי \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר ששל \u0003'עני' מאוחר\u0004 יותר. שכן \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי של \u0003עני מוקדם\u0004 יותר, הלא אי אפשר להקדים שיעור אחר לשיעורו של ר' יהושע, אלא אם כן מחזיקים בשיטה שהלילה מתחיל עם השקיעה, ואז לכאורה שיטת \u0003ר' חנינא היינו\u0004 \u0005[זוהי]\u0006 בדיוק שיטת \u0003ר' אליעזר. אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד ממנה]\u0006 כי \u0003שעורא\u0004 \u0005[השיעור]\u0006 של \u0003'עני' מאוחר\u0004 יותר. ומעירים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","שנינו כי \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא שזמן קריאת שמע של ערבית לשיטת ר' מאיר הוא משעה שטובלים הכהנים. ועל כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהודה\u0004 לר' מאיר: \u0003והלא כהנים מבעוד יום הם טובלים!\u0004","ומעירים: והלא \u0003שפיר קאמר ליה\u0004 \u0005[יפה אמר לו]\u0006 \u0003ר' יהודה לר' מאיר,\u0004 ומה יענה על כך ר' מאיר? תשובת ר' מאיר קשורה במחלוקת יסודית בקביעת תחילת הלילה. לאחר השקיעה מתחילה שעת דמדומים, שאינה לא יום ולא לילה, וקיימה מחלוקת תנאים בקביעת שיעורו המדויק של זמן מסופק זה הקרוי \"בין השמשות\". לדעת ר' יהודה (וגם לדעת ר' נחמיה, החולק עליו בפרטים) נמשך זמן זה שעה ארוכה לאחר שקיעת החמה. ואילו ר' יוסי סבור כי \"בין השמשות\" הוא קטע פעוט של זמן, החל מיד לפני צאת הכוכבים, שהיא תחילת הלילה. ר' יהודה הקשה על ר' מאיר, שמאחר שהכהנים טובלים לפני בין השמשות, ועד ללילה עליהם לחכות עוד שעה ארוכה, הרי שהטבילה היא ביום ממש.","על כך אומרים כי \u0003ר' מאיר הכי קאמר ליה\u0004 \u0005[כך אמר לו]\u0006 לר' יהודה: \u0003מי סברת דאנא\u0004 \u0005[האם סבור אתה כי אני]\u0006 על \u0003בין השמשות דידך קא אמינא\u0004 \u0005[שלך,\u0006 כשיטתך \u0005אומר אני]\u0006 את דבריי? \u0003אנא\u0004 \u0005[אני]\u0006 על \u0003בין השמשות\u0004 של \u0003ר' יוסי קא אמינא\u0004 \u0005[אמרתי],\u0006 ולדעתו \u0003בין השמשות כהרף עין, זה,\u0004 הלילה — \u0003נכנס, וזה,\u0004 היום — \u0003יוצא, ואי אפשר לעמוד עליו\u0004 מפני קטנותו, והשעה שהכהנים טובלים בה (לשיטה זו) הריהי ברגעים הסמוכים לצאת הכוכבים שהוא הזמן הנחשב כבר כלילה."],["בברייתא האחרונה הוזכרה דעת ר' מאיר שזמן קריאת שמע בערבית הוא מזמן שהכהנים טובלים לאכול בתרומתם. ובתוספתא שנינו משמו כי זמנה הוא משעה שבני אדם נכנסים לאכול בערבי שבתות, ואם כן \u0003קשיא \u0004\u0005[קשה]\u0006 מדברי \u0003ר' מאיר \u0004על דברי \u0003ר' מאיר \u0004עצמו! ומשיבים: \u0003תרי תנאי אליבא\u0004 \u0005[שני תנאים לשיטת]\u0006 \u0003ר' מאיר,\u0004 כלומר, שני תנאים תלמידי ר' מאיר חולקים בשאלה זו, וכל אחד מהם ייחס לרבו דעה אחרת.","וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' אליעזר\u0004 על דברי \u0003ר' אליעזר\u0004 עצמו, שבמשנה הוא אומר שזמן קריאת שמע מצאת הכוכבים (\"משעה שהכהנים נכנסים לאכול בתרומתן\") ובברייתא שנינו משמו כי הזמן הוא משעה שקדש היום בערבי שבתות!","ומשיבים: כאן יש שתי תשובות אפשריות, או \u0003תרי תנאי אליבא\u0004 \u0005[שני תנאים לשיטת]\u0006 \u0003ר' אליעזר, ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תשובה אחרת לדבר: \u0003רישא לאו\u0004 \u0005[תחילת\u0006 המשנה \u0005לא]\u0006 שיטת \u0003ר' אליעזר היא.\u0004 שאפשר להבין שהשיטה השנוייה במשנה שקוראים את שמע בערבית משעה שהכהנים נכנסים לאכול בתרומתם, היא אינה מדברי ר' אליעזר ורק חציה השני של ההלכה, \"עד סוף האשמורה הראשונה\", היא היא דברי ר' אליעזר.","במשנה שנינו כי ר' אליעזר קבע כי סוף זמן קריאת שמע של ערבית הוא \u0003עד סוף האשמורה\u0004 הראשונה בלילה. האשמורה נזכרת במקרא כחלק מהלילה, ואולם עדיין יש לדעת לכמה אשמורות (או משמרות) מתחלק הלילה, אם לשלוש או לארבע אשמורות.","ויש לשאול איפוא משום מה נקט ר' אליעזר ביטוי שאין משמעותו מוגדרת בבירור ולא השתמש בביטוי לשוני מבורר (תוהרא\"ש), שכן \u0003מאי קסבר\u0004 \u0005[מה\u0006 בעצם \u0005סבור הוא]\u0006 \u0003ר' אליעזר? אי קסבר\u0004 \u0005[אם הוא סבור]\u0006 כי בן \u0003שלש משמרות הוי\u0004 \u0005[הוא]\u0006 \u0003הלילה, לימא\u0004 \u0005[שיאמר]\u0006 אם כן במפורש \u0003\"עד ארבע שעות\". ואי קסבר\u0004 \u0005[ואם הוא סבור]\u0006 כי בן \u0003ארבע משמרות הוי\u0004 \u0005[הוא]\u0006 \u0003הלילה, לימא\u0004 \u0005[שיאמר]\u0006 אם כן במפורש \u0003\"עד שלש שעות\"!\u0004","ומשיבים: \u0003לעולם קסבר\u0004 \u0005[סבור הוא]\u0006 כי בן \u0003שלש משמרות הוי\u0004 \u0005[הוא]\u0006 \u0003הלילה,\u0004 ומה שהשתמש בלשון \"אשמורות\" \u0003הא קמשמע לן\u0004 \u0005[זה משמיע לנו]:\u0006 \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003משמרות ברקיע ואיכא\u0004 \u0005[ויש]\u0006 \u0003משמרות בארעא\u0004 \u0005[בארץ],\u0006 שגם בעולם העליון (הרקיע) וגם בעולמנו יש חלוקה כזו של הלילה. \u0003דתניא\u0004 \u0005[\u0006כפי \u0005ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר:\u0004 שבן \u0003שלש משמרות הוי\u0004 \u0005[הוא]\u0006 \u0003הלילה, ועל כל משמר ומשמר יושב הקדוש ברוך הוא ושואג כארי,\u0004 מצער זכרון חורבן המקדש. ודימוי זה נלמד ממה \u0003שנאמר: \"ה' ממרום ישאג, וממעון קדשו יתן קולו שאג ישאג על נוהו\u0004 הידד כדורכים יענה אל כל יושבי הארץ\u0003\"\u0004 (ירמיהו כה, ל), ולפי שנזכר בפסוק זה שלוש פעמים שורש המלה \"שאג\", הרי זה מרמז לשלש שאגות.","\u0003וסימן לדבר\u0004 לחילופי משמרות שלמעלה: שינויים גם בעולמנו, ב\u0003משמרה ראשונה\u0004 ה\u0003חמור נוער,\u0004 ב\u0003שניה\u0004 ה\u0003כלבים, צועקים\u0004 (נובחים), וב\u0003שלישית\u0004 כבר מתחילים האנשים להתעורר, \u0003ותינוק יונק משדי אמו, ואשה מספרת\u0004 (משוחחת) \u0003עם בעלה.\u0004","ברייתא זו קבעה סימני היכר חיצוניים למשמרות, ועל כך שואלים: \u0003מאי קא חשיב\u0004 \u0005[מה מנה]\u0006 \u0003ר' אליעזר\u0004 בסימנים אלה, \u0003אי\u0004 \u0005[אם]\u0006 את \u0003תחלת\u0004 ה\u0003משמרות קא חשיב\u0004 \u0005[הוא מונה]\u0006 — הרי ל\u0003תחלת\u0004 ה\u0003משמרה\u0004 ה\u0003ראשונה סימנא\u0004 \u0005[סימן]\u0006 \u0003למה לי?\u0004 והלא תחילת משמרה זו \u0003אורתא\u0004 \u0005[ערב]\u0006 \u0003הוא,\u0004 ואין איפוא צורך בסימנים מיוחדים! ואם נאמר כי את \u0003סוף\u0004 ה\u0003משמרות קא חשיב\u0004 \u0005[הוא מונה],\u0006 אף ל\u0003סוף משמרה אחרונה למה לי סימנא\u0004 \u0005[סימן]?\u0006 והלא \u0003יממא\u0004 \u0005[יום]\u0006 \u0003הוא,\u0004 ואין איפוא צורך בסימן נוסף!","ומשיבים: \u0003אלא\u0004 יש להבין את הסימנים שנתן כך: \u0003חשיב\u0004 \u0005[\u0006הוא \u0005מונה]\u0006 את \u0003סוף\u0004 ה\u0003משמרה\u0004 ה\u0003ראשונה, ותחלת\u0004 ה\u0003משמרה\u0004 ה\u0003אחרונה,\u0004 ששתיהן צריכות לסימן, ובמשמרה האמצעית נתן סימן ל\u0003אמצעית דאמצעיתא\u0004 \u0005[אמצע\u0006 המשמרה \u0005האמצעית].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 לעולם \u0003כולהו\u0004 \u0005[בכולן]\u0006 את \u0003סוף\u0004 ה\u0003משמרות קא חשיב\u0004 \u0005[הוא מונה],\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שלסוף המשמרה ה\u0003אחרונה לא צריך\u0004 סימן מיוחד, שהרי יום הוא — יש לומר כי בכל זאת יש ערך לסימן.","\u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 הלכה למעשה — \u0003למיקרי\u0004 \u0005[לקרוא]\u0006 \u0003קריאת שמע למאן דגני\u0004 \u0005[למי ששוכב]\u0006 \u0003בבית אפל ולא ידע\u0004 \u0005[ואינו יודע]\u0006 \u0003זמן קריאת שמע אימת\u0004 \u0005[מתי\u0006 הוא\u0005].\u0006 שהישן בבית אפל אינו רואה את תחילת אור היום, ולכן ניתן לו סימן, \u0003כיון\u0004 ש\u0003אשה מספרת עם בעלה ותינוק יונק משדי אמו\u0004 כבר נסתיימה המשמרה האחרונה בלילה, ואז \u0003ליקום וליקרי\u0004 \u0005[יעמוד\u0006 ממיטתו \u0005ויקרא]\u0006 קריאת שמע.","\u0003אמר רב יצחק בר שמואל משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב:\u0004 בן \u0003שלש משמרות הוי\u0004 \u0005[הוא]\u0006 \u0003הלילה, ועל כל משמר ומשמר יושב הקדוש ברוך הוא ושואג כארי,\u0004 כי עבודת המקדש היתה קשורה בזמני המשמרות (תוהרא\"ש), \u0003ואומר: \"אוי לבנים שבעונותיהם החרבתי את ביתי ושרפתי את היכלי והגליתים לבין אומות העולם\".\u0004","עם הזכרת משמעותם העליונה של זמני אשמורות הלילה מובא מעשה בהקשר דומה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יוסי: פעם אחת הייתי מהלך בדרך ונכנסתי לחורבה\u0004 (בית שנעזב ואין בו דיירים) \u0003אחת מחורבות ירושלים להתפלל\u0004 בה. בצאתי מן החורבה התגלה לפני כי \u0003בא אליהו\u0004 הנביא \u0003זכור לטוב ושמר\u0004 (המתין) \u0003לי על הפתח\u0004 של החורבה, \u0003(והמתין לי) עד שסיימתי תפלתי. לאחר שסיימתי תפלתי אמר לי\u0004 אליהו כדרך שפונים אל הרב: \u0003\"שלום עליך, רבי\". ואמרתי לו\u0004 כתשובה: \u0003\"שלום עליך, רבי ומורי\". ואמר לי: בני, מפני מה נכנסת לחורבה זו? אמרתי לו:\u0004 על מנת \u0003להתפלל. ואמר לי\u0004 אליהו: \u0003היה לך להתפלל בדרך. ואמרתי לו:\u0004 לא יכולתי להתפלל בדרך מאחר ו\u0003מתירא הייתי שמא יפסיקו בי עוברי דרכים,\u0004 ולא יוכל להתרכז בתפילה כראוי, אמר לו אליהו: \u0003היה לך להתפלל תפלה קצרה.\u0004 כי קיים נוסח מקוצר של תפילה, שנועד לאלה שאין ביכולתם להתפלל תפילה ארוכה.","ור' יוסי מסכם כי \u0003באותה שעה\u0004 משיחה קצרה זו \u0003למדתי ממנו שלשה דברים: למדתי שאין נכנסין לחורבה, ולמדתי שמתפללין בדרך\u0004 במקום הצורך, ואין להיכנס דווקא לבית להתפלל, \u0003ולמדתי שהמתפלל בדרך מתפלל תפלה קצרה\u0004 שיוכל לכוון לבו בה.","\u0003ו\u0004לאחר דברי ההקדמה \u0003אמר לי\u0004 אליהו: \u0003בני, מה קול שמעת בחורבה זו? ואמרתי לו\u0004 בתשובה: \u0003שמעתי\u0004 בחורבה \u0003בת קול,\u0004 כעין הד מאותה שאגה ששואג הקדוש ברוך הוא (מהרש\"א) \u0003שמנהמת כיונה ואומרת: \"אוי לבנים שבעונותיהם החרבתי את ביתי ושרפתי את היכלי והגליתים לבין האומות\". ואמר לי\u0004 אליהו: \u0003חייך וחיי ראשך, לא שעה זו בלבד אומרת כך,\u0004 קול זה אינו חד פעמי, \u0003אלא\u0004 חוזר \u0003בכל יום ויום, שלש פעמים אומרת כך. ולא זו בלבד אלא\u0004 גם בשעות אחרות כשמזכירים את גדולת ה', וכגון \u0003בשעה שישראל נכנסין לבתי כנסיות ולבתי מדרשות ועונין\u0004 באמירת הקדיש \u0003\"יהא שמיה\u0004 \u0005[שמו]\u0006 \u0003הגדול מבורך\u0004 (בנוסח הקדיש: \"יהא שמיה רבא מברך\"), \u0003הקדוש ברוך הוא מנענע ראשו, ואומר: אשרי המלך שמקלסין\u0004 (משבחים) \u0003אותו בביתו כך,\u0004 כי כשהיה המקדש, בית ה' בנוי, היה הקדוש ברוך הוא משובח שם בתהילה זו, ועתה בזמן הגלות \u0003מה לו לאב שהגלה את בניו,\u0004 כלומר, מה רבה היא הרגשת הכאב של האב המגלה את בניו, \u0003ואוי להם לבנים שגלו מעל שולחן אביהם,\u0004 ומוסיפים כאב לאב בכאבם שלהם (רשש\"ט).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003מפני שלשה דברים אין נכנסין לחורבה: מפני\u0004 ה\u0003חשד\u0004 של זנות, ו\u0003מפני המפולת,\u0004 שעשויה החורבה להתמוטט, \u0003ומפני המזיקין\u0004 (שדים). נתינת שלושה טעמים להלכה אחת נראית מיותרת, ושואלים מדוע ניתן הטעם \u0003\"מפני חשד\", ותיפוק ליה\u0004 \u0005[ותצא לו\u0006 ילמד הלכה זו\u0005]\u0006 מן הטעם הפשוט יותר \u0003\"משום מפולת\"?\u0004"],["ועונים: מדובר כאן אפילו \u0003בחדתי\u0004 \u0005[ב\u0006חורבה \u0005חדשה],\u0006 שאינה עתיקה, ושאין בה סכנת מפולת, ולכן יש לתת את טעם החשד, להזהיר מלהיכנס אף לחורבה כזו.","ועוד מקשים על טעם החשד: \u0003ותיפוק ליה\u0004 \u0005[ותצא,\u0006 תילמד \u0005לו\u0006 הלכה זו\u0005]\u0006 \u0003משום מזיקין,\u0004 שמטעם זה, תיאסר הכניסה לחורבה? ומשיבים: \u0003בתרי\u0004 \u0005[בשניים],\u0006 כשנכנסים שניים, ומקובל כי אין המזיקים פוגעים אלא באדם בודד.","על כך מקשים: \u0003אי בתרי\u0004 \u0005[אם בשניים]\u0006 — \u0003חשד נמי ליכא\u0004 \u0005[גם כן אין]!\u0006 שהלכה היא שמותר לשני גברים להתייחד עם אשה, ואין חושדים בהם. ואם שניים נכנסים לחורבה, הלא גם נימוק החשד אינו שייך בהם. ומתרצים: \u0003בתרי ופריצי\u0004 \u0005[בשניים, ופרוצים].\u0006 שכאשר היו הנכנסים ידועים כפרוצים, חשודים הם אפילו בשניים.","ומעתה באים לברר מדוע נזקקים לנימוק השני \u0003\"מפני המפולת\", ותיפוק ליה\u0004 \u0005[ותצא,\u0006 תילמד \u0005לו\u0006 הלכה זו\u0005]\u0006 \u0003משום\u0004 הטעמים \u0003חשד ומזיקין!\u0004","ומשיבים: יש מקרים שבהם יש להיזקק לנימוק זה של מפולת, וכגון \u0003בתרי וכשרי\u0004 \u0005[בשניים וכשרים],\u0006 שבכגון זה אין לחשוש מפני המזיקים, ואף אין לחשוד בהם בזנות, ואולם סכנת המפולת קיימת גם אז.","ועתה לבירור הנימוק השלישי \u0003\"מפני המזיקין\"\u0004 לשם מה יש להזכירו, \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 \u0003מפני\u0004 הטעמים של \u0003חשד ומפולת!\u0004","ומשיבים: יש מקרים בהם רק נימוק זה קיים, וכגון \u0003בחורבה חדתי\u0004 \u0005[חדשה],\u0006 שלמפולת אין לחוש \u0003ובתרי וכשרי\u0004 \u0005[ובשניים וכשרים],\u0006 שאף אין לחשוש לחשד זנות כי האנשים כשרים.","ואולם, שואלים, \u0003אי בתרי\u0004 \u0005[אם\u0006 מדובר \u0005בשניים],\u0006 הלא \u0003מזיקין נמי ליכא\u0004 \u0005[גם כן אינם],\u0006 ואין אם אם כן בכגון זה איסור כלל להכנס לחורבה!","ומשיבים: אף שבדרך כלל אין לשניים לחוש ממזיקים, בכל זאת \u0003במקומן\u0004 של המזיקים, כשהחורבה ידועה כמקום המיועד למשכן המזיקים (עיין ישעיהו יג, כא), \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006, ויש לחשוש מפניהם אף בשניים. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003לעולם\u0004 מדובר \u0003בחד\u0004 \u0005[באחד],\u0006 \u0003ובחורבה חדתי דקאי בדברא\u0004 \u0005[חדשה העומדת בשדה],\u0006 \u0003דהתם\u0004 \u0005[ששם]\u0006 במקרה כזה \u0003משום חשד ליכא\u0004 \u0005[אין]\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אשה בדברא לא שכיחא\u0004 \u0005[בשדה אינה מצויה],\u0006 ומאחר שהחורבה חדשה אין גם לחוש למפולת, \u0003ומשום מזיקין איכא\u0004 \u0005[יש]\u0006 מקום לחשוש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003ארבע משמרות הוי\u0004 \u0005[הריהו]\u0006 \u0003הלילה,\u0004 אלו \u0003דברי רבי. ר' נתן אומר: שלש.\u0004","ומבארים: \u0003מאי טעמיה\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' נתן\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויבא גדעון ומאה איש אשר אתו בקצה המחנה ראש האשמרת התיכונה\"\u0004 וגו' (שופטים ז, יט), ו\u0003תנא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003אין\u0004 משמעות לשון \u0003\"תיכונה\" אלא שיש לפניה ולאחריה,\u0004 נמצא איפוא מלשון הכתוב כי שלוש אשמורות הן בלילה, שעל כן ניתן לדבר על \"אשמורת תיכונה\".","\u0003ורבי,\u0004 מה אומר הוא על ראיה זו? — אין זו הוכחה ניצחת, ואפשר לומר כי \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 המלה \u0003\"תיכונה\"\u0004 — \u0003אחת מן התיכונה שבתיכונות,\u0004 שיתכן כי יש שתי אשמורות, ששתיהן הן \"תיכונות\" וה\"תיכונה\" שנאמרה בכתוב אינה אלא אחת מן התיכונות.","\u0003ור' נתן\u0004 משיב כי בכל זאת \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \"אחת מן ה\u0003תיכונה שבתיכונות\"?\u0004 הלא \u0003\"תיכונה\" כתיב\u0004 \u0005[נאמר]!\u0006 ונראה מכאן שיש רק שלוש משמרות.","ו\u0003מאי טעמיה\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי?\u0004 — \u0003אמר ר' זריקא, אמר ר' אמי, אומר ר' יהושע בן לוי:\u0004 דברי רבי מבוססים על השוואת שני פסוקים. \u0003כתוב אחד אומר: \"חצות לילה אקום להודות לך על משפטי צדקך\"\u0004 (תהלים קיט, סב), \u0003וכתוב אחד אומר: \"קדמו עיני אשמורות\u0004 לשיח באמרתך\u0003\"\u0004 (תהלים קיט, קמח), שהוא מקדים את הבוקר בשתי האשמורות בבואו ללמוד תורה. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניתן ליישב את שני הפסוקים הללו, רק אם נאמר כי \u0003ארבע משמרות הוי\u0004 \u0005[הריהו]\u0006 \u0003הלילה,\u0004 והקדמת שתי משמרות הריהי בדיוק \"חצות לילה\".","\u0003ור' נתן,\u0004 כיצד מיישב הוא את שני הפסוקים הללו? — ר' נתן \u0003סבר לה\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 בבעיה זו \u0003כ\u0004שיטת \u0003ר' יהושע. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהושע אומר:\u0004 מותר לקרות קריאת שמע של שחר, של זמן הקימה, \u0003עד שלש שעות\u0004 ביום, \u0003שכן דרך מלכים לעמוד\u0004 משנתם \u0003בשלש שעות.\u0004 ומאחר שדרך מלכים לקום בתחילת השעה השלישית של היום, אם היה דוד קם בחצות לילה, הרי \u0003שית דליליא\u0004 \u0005[שש\u0006 שעות \u0005של הלילה],\u0006 \u0003ותרתי דיממא\u0004 \u0005[ושתים\u0006 משעות \u0005היום],\u0006 ביחד \u0003הוו להו\u0004 \u0005[הריהן]\u0006 \u0003שתי משמרות\u0004 של ארבע שעות, ויכול היה דוד לומר ש\"קדמו עיני אשמורות\" ביחס לשאר מלכי העולם.","\u0003רב אשי אמר\u0004 שאפשר להתאים את הפסוקים לדעת ר' נתן בדרך אחרת: \u0003משמרה ופלגא\u0004 \u0005[וחצי]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003\"משמרות\" קרו להו\u0004 \u0005[קוראים להן],\u0006 ועל כן, גם אם קם דוד המלך בחצות יכול היה לומר \"קדמו עיני אשמורות\".","מאחר שהובא דבר ממסורת חכמים מסויימת, מביאים דבר הלכה בנושא אחר אשר נמסר גם הוא באותו אופן. \u0003אמר ר' זריקא, אמר ר' אמי, אמר ר' יהושע בן לוי: אין אומרים בפני המת\u0004 במקום הסמוך למת \u0003אלא דבריו של מת\u0004 בלבד, שאם מדברים בפניו דברים אחרים, יש לראות בזה משום ביזוי למת, אשר אינו יכול עוד לדבר, והאחרים מראים את עליונותם עליו כשהם עוסקים בדיבור. ועל כן אין לעסוק במחיצתו אלא בדבריו. בפרטי הדברים קיימות שתי גירסות המובאות בשמו, של ר' אבא בר כהנא.","לגירסה אחת \u0003אמר ר' אבא בר כהנא: לא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו \u0003אלא\u0004 כשמדברים \u0003בדברי תורה, אבל מילי דעלמא לית לן\u0004 \u0005[בדברים סתם אין לנו]\u0006 \u0003בה\u0004 איסור, שאין משום בושת למת אם אינו מדבר דווקא בדברים סתם משלו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 גירסה אחרת משמו של ר' אבא בר כהנא: \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו \u0003אלא בדברי תורה וכל שכן מילי דעלמא\u0004 \u0005[בדברים סתם],\u0006 שאפילו בדברי תורה שמצווה לדבר בהם יש להימנע מלומר אלא דברי המת, כל שכן בדברים שאין מצווה לעסוק בהם.","מאחר שהובאו הדברים בענין דוד המלך, מביאים עוד מסורות ופסוקים המציירים את דוד ואת מעשיו. על פי האמור נראה כי דוד המלך היה קם בחצות כל לילה לעבודת בוראו, ושואלים: \u0003ו\u0004כי \u0003דוד בפלגא דליליא הוה קאי\u0004 \u0005[בחצות הלילה היה עומד,\u0006 קם\u0005]?\u0006 והרי \u0003מאורתא הוה קאי\u0004 \u0005[בערב היה קם]!\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"קדמתי בנשף ואשועה\u0004 לדברך יחלתי\" (תהלים קיט, קמז), ו\u0003ממאי\u0004 \u0005[ממה,\u0006 מהיכן\u0005]\u0006 יודעים אנו \u0003דהאי\u0004 \u0005[שזה]\u0006 לשון \u0003\"נשף\" אורתא\u0004 \u0005[ערב]\u0006 \u0003הוא?\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בנשף בערב יום באישון לילה ואפלה\"\u0004 (משלי ז, ט), ומסתבר איפוא שהיה דוד קם לעבודת הבורא עוד בשעות הנשף! סתירה זו מיישבים בדרכים שונות.","\u0003אמר ר' אושעיא, אמר ר' אחא: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך התכוון לומר \u0003דוד: מעולם לא עבר עלי חצות לילה בשינה,\u0004 שלעתים אכן היה מקיים \"קדמתי בנשף ואשועה\", אך בכל אופן תמיד לפחות \"חצות לילה אקום להודות לך\".","ואילו \u0003ר' זירא אמר: עד חצות לילה היה\u0004 דוד \u0003מתנמנם כסוס,\u0004 שהסוס אינו ישן ממש, אלא אף בשעת מנוחתו הריהו רק מתנמנם, ואילו \u0003מכאן ואילך היה מתגבר כארי. רב אשי אמר: עד חצות לילה היה עוסק בדברי תורה,\u0004 וכפי שנאמר \"קדמתי בנשף ואשועה לדבריך יחלתי\", \u0003מכאן ואילך\u0004 היה עוסק \u0003בשירות ותשבחות,\u0004 וכפי שנאמר \"חצות לילה אקום להודות לך","עד כאן היה הדיון מבוסס על ההנחה ש\"נשף\" משמעו ערב. ושואלים: \u0003ו\u0004כי \u0003\"נשף\" אורתא\u0004 \u0005[ערב]\u0006 \u0003הוא? הא\u0004 \u0005[\u0006ו\u0005הרי]\u0006 \u0003\"נשף\" צפרא\u0004 \u0005[בוקר]\u0006 \u0003הוא! דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויכם דוד מהנשף ועד הערב למחרתם\"\u0004 וגו' (שמואל א' ל, יז). \u0003מאי לאו\u0004 \u0005[האם\u0006 הכוונה היא \u0005לא]\u0006 \u0003מצפרא\u0004 \u0005[מהבוקר]\u0006 \u0003ועד ליליא\u0004 \u0005[הלילה]?\u0006 ש\"נשף\" משמעו בוקר!","ומשיבים: \u0003לא, מאורתא\u0004 \u0005[מערב]\u0006 \u0003ועד אורתא\u0004 \u0005[ערב],\u0006 שהיכם דוד מערב עד לערב הבא.","אך תשובה זו אינה מתקבלת, שכן \u0003אי הכי לכתוב\u0004 \u0005[אם כן, שיכתוב]\u0006 \u0003\"מהנשף ועד הנשף\" או \"מהערב ועד הערב\",\u0004 שכן אין טעם לכתוב בפסוק אחד שני ביטויים שונים לאותו מושג!","\u0003אלא אמר רבא:\u0004 המלה \"נשף\" משמעה גם ערב וגם בוקר כי \u0003תרי נשפי הוו\u0004 \u0005[שני \"נשפים\" הם],\u0006 שמשמעותם אחת — לציין את שעת הדמדומים, שאת המלה \"נשף\" יש להסביר לפי הארמית: \u0003נשף ליליא ואתי יממא, נשף יממא ואתי ליליא\u0004 \u0005[קפץ הלילה ובא היום, קפץ היום ובא הלילה].\u0006","כשאמר דוד המלך \"חצות לילה אקום\" הבינו זאת שהיה קם בדיוק בחצות. ושואלים: \u0003ודוד מי הוה ידע פלגא דליליא אימת\u0004 \u0005[ודוד האם ידע אימתי חצות הלילה]?\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003משה רבינו לא הוה ידע\u0004 \u0005[היה יודע],\u0006 ומנין לך זאת — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 שאמר משה לפרעה \"כה אמר ה' \u0003כחצות הלילה אני יוצא בתוך מצרים\"\u0004 (שמות יא, ד), והמלה \"כחצות\" שנאמרה בכ' הדמיון, מובנת: בערך בחצות לילה.","ויש לברר \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"כחצות\",\u0004 מי אמר ביטוי מסופק זה. \u0003אילימא\u0004 \u0005[אם לומר]\u0006 ש\u0003אמר ליה קודשא בריך הוא\u0004 \u0005[לו הקדוש ברוך הוא]\u0006 בעצמו למשה \u0003\"כחצות\"\u0004 — \u0003מי איכא ספיקא קמי שמיא\u0004 \u0005[וכי יש ספק לפני השמים,\u0006 הקדוש ברוך הוא\u0005]?!\u0006 \u0003אלא\u0004 יש להבין שכך היה: ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 ה' \u0003מחר \"בחצות\" כי השתא, ואתא איהו\u0004 \u0005[ובא הוא,\u0006 משה\u0005]\u0006 \u0003ואמר \"כחצות\", אלמא: מספקא ליה\u0004 \u0005[מכאן שמסופק היה],\u0006 ואם משה רבינו שגדול היה בנבואתו לא ידע בוודאות, \u0003ו\u0004כי \u0003דוד הוה ידע\u0004 \u0005[היה יודע]?!\u0006 לשאלה זו ניתנות תשובות אחדות.","האחת היא: \u0003דוד, סימנא הוה ליה\u0004 \u0005[סימן היה לו]\u0006 לדעת מתי חצות הלילה, ש\u0003אמר רב אחא בר ביזנא, אמר ר' שמעון חסידא: כנור היה תלוי למעלה ממטתו של דוד, וכיון שהגיע\u0004 שעת \u0003חצות לילה,\u0004 היתה \u0003בא רוח צפונית\u0004 שהיא רוח של חצות \u0003ונושבת בו ו\u0004כתוצאה מזה היה הכינור \u0003מנגן\u0004 בו \u0003מאליו,\u0004 ו\u0003מיד היה\u0004 דוד \u0003עומד\u0004 ממיטתו \u0003ועוסק בתורה עד שעלה עמוד השחר. כיון שעלה עמוד השחר נכנסו חכמי ישראל אצלו\u0004 להתייעץ עמו על מצב האומה, ובכלל זה בעיית המחסור. \u0003אמרו לו: אדונינו המלך, עמך ישראל צריכין פרנסה. אמר להם\u0004 המלך: \u0003לכו והתפרנסו זה מזה,\u0004 שיקבלו חסרי הפרנסה עזרתם מאחרים. \u0003אמרו לו\u0004 חכמי ישראל כתשובה לדבריו, בדרך משל: \u0003אין הקומץ משביע את הארי,\u0004 אין קומץ אחד של מזון יכול להשביע את האריה הגדול, \u0003ואין הבור מתמלא מחוליתו\u0004 (פתחו), שבור המים אינו מתמלא ממי הגשמים היורדים רק על פתחו, אלא צריך למשוך לו מים בצינורות מן הסביבה עד שיתמלא (גאונים), וכמו כן אין העם מסוגל לפרנס עצמו משלו בלבד. \u0003אמר להם\u0004 המלך: \u0003לכו ופשטו ידיכם בגדוד,\u0004 במלחמה על העמים מסביב, להרחיב את גבולות הארץ, ולתת אפשרויות של פרנסה ליושביה.","\u0003מיד יועצים\u0004 (מתייעצים) החכמים \u0003באחיתופל\u0004 אם ראוי בעונה זו לצאת למלחמה, וכיצד צריך לנהוג בה, \u0003ונמלכין בסנהדרין\u0004 כדי לקבל את ההיתר הדרוש מהסנהדרין לצאת למלחמת הרשות (תוהרא\"ש), \u0003ושואלין באורים ותומים\u0004 אחר כך, לשאול בדבר ה' אם יעלו למלחמה ואם יצליחו בה.","על דברי אגדה זו \u0003אמר רב יוסף: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 ממנו בסיס אגדה זו? — \u0003\"ואחרי אחיתפל בניהו בן יהוידע ואביתר ושר צבא למלך יואב\"\u0004 (במקרא: ואחרי אחיתופל יהוידע בן בניהו\"... דברי הימים א' כז, לד).","והטעמת דברי המקרא כפי ביאורה באגדה הריהם: \u0003אחיתופל\u0004 — \u0003זה יועץ,\u0004 שאותו היו שואלים לראשונה עצה אם לעשות פעולה מסויימת, \u0003וכן הוא אומר: \"ועצת אחיתפל אשר יעץ בימים ההם כאשר ישאל איש בדבר האלהים\u0004 כן כל עצת אחיתופל גם לדוד גם לאבשלום\u0003\"\u0004 (שמואל ב טז, כג)."],["\u0003בניהו בן יהוידע\u0004 — \u0003זה סנהדרין,\u0004 שכן הוא היה ראש הסנהדרין, \u0003\"ואביתר\"\u0004 האמור בכתוב זה — הרי \u0003אלו אורים ותומים,\u0004 שכן אביתר בן אחימלך הכהן היה ממונה על השאלה באורים ותומים (עיין שמואל א כג, ט).","\u0003וכן הוא אומר\u0004 באשר לתפקידו של בניהו בן יהוידע כראש הסנהדרין: \u0003\"ובניהו בן יהוידע על הכרתי ועל הפלתי\"\u0004 (יעויין שמואל ב' כ, כג). \u0003ולמה נקרא שמם\u0004 של הסנהדרין \u0003\"כרתי\" ו\"פלתי\"? \"כרתי\"\u0004 נקראו — לפי \u0003שכורתים דבריהם\u0004 ומחליטים החלטות פסוקות, ו\u0003\"פלתי\"\u0004 — \u0003שמופלאים בדבריהם\u0004 ובחכמתם. וראש הכרתי והפלתי הריהו ראש הסנהדרין. והרי לפי סדר הפסוק, קודם יועצים באחיתופל ונמלכים בסנהדרין ושואלים באורים ותומים, \u0003ו\u0004רק \u0003אחר כך \"שר צבא למלך יואב\"\u0004 — שלו ניתנו הפקודות לעמוד בראש צבא המלחמה.","\u0003אמר רב יצחק בר אדא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 ממנו ניתן ללמוד על כך שכינורו של דוד היה מעירו עם שחר — \u0003\"עורה כבודי עורה הנבל וכנור אעירה שחר\"\u0004 (תהלים נז, ט), המתפרש: עורה כבודי, שכבר התעורר הנבל המנגן, ומעתה צריך אני לעסוק בתורה עד השחר.","\u0003ר' זירא אמר\u0004 פתרון אחר לשאלה שהתעוררה בענין קביעת זמן חצות: \u0003משה לעולם הוה ידע\u0004 \u0005[היה יודע]\u0006 את שעת חצות, \u0003ודוד נמי הוה ידע\u0004 \u0005[גם כן היה יודע].\u0006","ושואלים: \u0003וכיון\u0004 ש\u0003דוד הוה ידע\u0004 \u0005[היה יודע],\u0006 \u0003כנור למה ליה\u0004 \u0005[לו]?\u0006 ומשיבים: הכנור שימש אותו כדי \u0003לאתעורי משנתיה\u0004 \u0005[להתעורר משנתו].\u0006","וכן גם במשה, שאם תאמר: \u0003וכיון\u0004 ש\u0003משה הוה ידע\u0004 \u0005[היה יודע],\u0006 \u0003למה ליה למימר\u0004 \u0005[לו לומר]\u0006 בלשון \u0003\"כחצות\",\u0004 ולא אמר \"בחצות\"? — טעם הדבר, \u0003משה קסבר\u0004 \u0005[היה סבור]:\u0006 \u0003שמא יטעו אצטגניני פרעה,\u0004 ויחשבו את שעת חצות הלילה מוקדם יותר, ומשום שלא תגיע הפורענות \u0003יאמרו \"משה בדאי הוא\".\u0004 ונקט משה בכלל ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003למד לשונך לומר \"איני יודע\", שמא תתבדה ותאחז.\u0004","\u0003רב אשי אמר:\u0004 קושיה זו מיסודה אינה, כי משה רבינו \u0003בפלגא אורתא דתליסר נגהי ארבסר הוה קאי\u0004 \u0005[בחצות הלילה של שלשה עשר אור לארבעה עשר, היה עומד]\u0006 כשאמר דברי נבואה זו, \u0003והכי קאמר\u0004 \u0005[וכך אמר]\u0006 \u0003משה לישראל, אמר הקדוש ברוך הוא: למחר כחצות הלילה כי האידנא\u0004 \u0005[כמו שעה זו]\u0006 בשעת חצות \u0003אני יוצא בתוך מצרים,\u0004 ונמצא כי \"כחצות\" אין משמעו בערך בחצות, אלא השוואה — בשעת חצות כזו.","ועוד בענין דמותו של דוד המלך. נאמר: \u0003\"לדוד, שמרה נפשי כי חסיד אני\"\u0004 (תהלים פו, א–ב). ודנים \u0003לוי ור' יצחק\u0004 בפירושו של פירוש זה, במה התבטאה במיוחד חסידותו של דוד כאדם העושה דברים יותר ממה שמוטלת עליו חובתו. \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 דברי דוד על חסידותו מוסבים על השכמתו בעוד לילה לתפילה, ו\u0003כך אמר דוד לפני הקדוש ברוך הוא: רבונו של עולם,\u0004 וכי \u0003לא חסיד אני? ש\u0004הרי \u0003כל מלכי מזרח ומערב ישנים עד שלש שעות, ו\u0004אילו \u0003אני,\u0004 אף שאני מלך כמותם \u0003\"חצות לילה אקום להודות לך\"\u0004 (תהלים קיט, סב).","\u0003ואידך\u0004 \u0005[ו\u0006החכם \u0005האחר\u0006], אמר, \u0003כך אמר דוד לפני הקדוש ברוך הוא: רבונו של עולם,\u0004 וכי \u0003לא חסיד אני? ש\u0004הרי \u0003כל מלכי מזרח ומערב יושבים אגודות אגודות בכבודם, ו\u0004אילו \u0003אני\u0004 נוהג כחכם המורה הוראות לעם, שהיו באות אלי נשים בשאלות טומאה וטהרה, והיו \u0003ידי מלוכלכות בדם\u0004 אשה לדעת אם הוא דם טמא ונדה היא, או לא, \u0003ובשפיר,\u0004 שהוא נפל בדרגה מסויימת של היווצרותו, כשעדיין אינו ברור אם הוא נחשב לוולד, \u0003ובשליא,\u0004 \"לבוש\" העור שהוולד נולד בו, ושלעתים אשה מפלת שליא בלי קשר נראה לעין עם ולד. וכל זה היה נעשה על מנת להגדיר את מעמדה של האשה, אם טמאה היא אם לאו (ועיין ויקרא טו, יט–ל בענין הדם. ובויקרא יב, א–ח לענין שפיר ושליא). וכל זאת עשיתי \u0003כדי לטהר אשה לבעלה,\u0004 שאם מטהר החכם, לאחר העיון בדם בשפיר ובשליא, את האשה, מותרת היא לשהות עם בעלה, ועל ידי כך מוסיף אהבה וחיבה ואף מרבה ומוסיף נפשות בישראל (הריא\"ף). \u0003ולא עוד,\u0004 לא רק שהייתי משפיל את עצמי לעסוק בדבר שנראה לכאורה כאינו הולם את כבוד המלך, \u0003אלא כל מה שאני עושה, אני נמלך במפיבשת רבי,\u0004 הוא מפיבושת בן יהונתן בן שאול המלך, \u0003ואומר לו: \"מפיבשת רבי, יפה דנתי? יפה חייבתי? יפה זכיתי? יפה טהרתי? יפה טמאתי?\", ולא בושתי.\u0004 ובשל ויתור זה על כבודו ראוי אני להקרא \"חסיד\".","ו\u0003אמר רב יהושע בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך — \u0003\"ואדברה בעדתיך נגד מלכים ולא אבוש\"\u0004 (תהלים קיט, מו) שיש בו רמז כפול, הן לעיסוקו של דוד בתורה שלא כמנהג מלכי מזרח ומערב, ואף לגבי הפרט השני — שהרי היה מפיבושת בן מלכים, ולא בוש דוד לומר דברי תורה בפניו, אף כי יתכן שיטעה בהם ויצטרך מפיבושת לתקן שגגתו, ועל כך","\u0003תנא\u0004 \u0005[שנינו]\u0006 בתוספתא ממסורת התנאים: \u0003לא \"מפיבשת\" שמו, אלא \"איש בשת\" שמו\u0004 האמיתי, \u0003ולמה נקרא שמו מפיבשת?\u0004 — \u0003שהיה מבייש פני דוד בהלכה,\u0004 שבדרשה זו מתפרשת \"מפיבושת\" כקיצור של \"בושת פנים\" ו\u0003לפיכך\u0004 שלא בוש דוד להודות על טעותו \u0003זכה דוד ויצא ממנו כלאב,\u0004 שמסורת היא שהיה חכם ביותר,","\u0003ו\u0004כן גם \u0003אמר ר' יוחנן: לא \"כלאב\" שמו אלא \"דניאל\" שמו\u0004 (כדרך שאמנם כתוב שמו ברשימה אחרת של יחס בני דוד), \u0003ולמה נקרא שמו \"כלאב\"\u0004 — \u0003שהיה מכלים פני מפיבשת בהלכה,\u0004 כלומר, כל אב מכלים את האב—הרב.","\u0003ועליו\u0004 על בן חכם זה \u0003אמר שלמה ב\u0004ספר \u0003חכמתו \"בני אם חכם לבך ישמח לבי גם אני\"\u0004 (משלי כג, טו), שדוד נהנה לראות שבנו גדול בתורה עד שיוכל להשיב דבר למפיבושת, \u0003ו\u0004כן הוא \u0003אומר\u0004 עליו: \u0003\"חכם בני ושמח לבי ואשיבה חרפי דבר\"\u0004 (משלי כז, יא).","על דברי דוד \"שמרה נפשי כי חסיד אני\" תוהים: \u0003ודוד מי קרי לנפשיה\u0004 \u0005[האם קרא לעצמו]\u0006 \u0003\"חסיד\"? ו\u0004הרי דוד לא היה בטוח כל עיקר אם אמנם חסיד הוא, שכן \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"לולא האמנתי לראות בטוב ה' בארץ חיים\"\u0004 (תהלים כז, יג) ועל המלה \"לולא\" מצויות נקודות, שמשמען הוא שיש פקפוק ואי ודאות מסויימת במלה זו (עיין באבות דר' נתן, פרק לד) \u0003ו\u0004כך מביאים בתוספתא, \u0003תנא משמיה\u0004 \u0005[שנוי משמו]\u0006 של \u0003ר' יוסי: למה נקוד\u0004 — כאילו יש ספק — \u0003על\u0004 המילה \u0003\"לולא\"?\u0004 — כך \u0003אמר,\u0004 התכוון לומר, \u0003דוד לפני הקדוש ברוך הוא: רבונו של עולם,\u0004 אמנם \u0003מובטח אני בך שאתה משלם שכר טוב לצדיקים לעתיד לבוא,\u0004 שיהא טוב ה' בארץ החיים הנצחיים, \u0003אבל\u0004 עדיין קיים ספק אותו מביע דוד ב\"לולא\", והוא ספיקו האישי של דוד: \u0003איני יודע אם יש לי חלק ביניהם אם לאו\u0004 \u0005[לא],\u0006 כלומר, אם \"טוב ה' בארץ חיים\" נכון גם לו (זהב שבה). על כל פנים, לענייננו נראה שדוד לא היה בטוח שחסיד הוא, שהרי הוא מפקפק אם יש לו חלק במתן שכרם של צדיקים, ואיך אם כן הגדיר את עצמו כ\"חסיד\"?!","ומשיבים: אין חשש זה מוכיח, כי אכן ידע דוד המלך שחסיד הוא, אלא חשש לחלקו לעולם הבא \u0003שמא יגרום\u0004 לו בעתיד \u0003החטא\u0004 ויפסידו. ומביאים ראיות, כי יש מקום לחוש שיגרום החטא ולא תתקיים הבטחה טובה במלואה.","וכפי שאמר \u0003ר' יעקב בר אידי,\u0004 שהיה \u0003רמי\u0004 \u0005[משליך,\u0006 מראה סתירה בין שני פסוקים\u0005];\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 שאמר ה' ליעקב בחזון הסולם: \u0003\"והנה אנכי עמך ושמרתיך בכל אשר תלך\"\u0004 (בראשית כח, טו), \u0003ו\u0004כאשר חזר יעקב לארצו ושמע שעשו הולך לקראתו, \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויירא יעקב מאד\u0004 ויצר לו \u0003\"\u0004וגו' (בראשית לב, ח), ומדוע לא סמך יעקב על הבטחת ה'? אלא מתוך שחשש \u0003אמר\u0004 לעצמו: \u0003שמא יגרום החטא,\u0004 שאולי יחטא אחר כך, ולא תתקיים בו הבטחת השמירה.","ולעתים גם קורה שהחטא גורם, \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 בפירוש הכפילות בפסוק בשירת הים \u0003\"עד יעבר עמך ה', עד יעבר עם זו קנית,\u0004 תביאמו ותטעמו בהר נחלתך, מכון לשבתך פעלת ה'\u0003\"\u0004(שמות טו, טז–יז),","ודרשו: \u0003\"עד יעבר עמך ה'\"\u0004 — \u0003זו ביאה ראשונה\u0004 של העם לארץ ישראל בימי יהושע, \u0003\"עד יעבר עם זו קנית\"\u0004 — \u0003זו ביאה שניה\u0004 לארץ לאחר גלות בבל. ומאחר שהושוו בפסוק שתי ביאות אלו לארץ ישראל, \u0003מכאן אמרו חכמים: ראוים היו ישראל ליעשות להם נס בימי עזרא\u0004 הסופר \u0003כדרך שנעשה להם בימי יהושע בן נון.\u0004 ומשום מה לא נעשו אז נסים כאלה — \u0003אלא שגרם החטא.\u0004","מכאן שבים לדון בפירוש משנתנו. שנינו במשנה ש\u0003חכמים אומרים\u0004 שזמן קריאת שמע של ערבית הוא \u0003עד חצות\u0004 הלילה. ושואלים: \u0003חכמים כמאן סבירא להו\u0004 \u0005[כ\u0006שיטת \u0005מי הם סבורים]\u0006 בפירוש המלה \"ובשכבך\" שבתורה, \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004שיטת \u0003ר' אליעזר סבירא להו\u0004 \u0005[סבורים הם]\u0006 ש\"ובשכבך\" פירושו הזמן שבו הולכים אנשים לישון כרגיל — אם כן \u0003לימרו\u0004 \u0005[שיאמרו]\u0006 \u0003כר' אליעזר\u0004 גם בפסק ההלכה, שזמנה הוא עד סוף האשמורה הראשונה."],["\u0003ואי\u0004 \u0005[אם]\u0006 \u0003כ\u0004שיטת \u0003רבן גמליאל סבירא להו\u0004 \u0005[סבורים הם]\u0006 ש\"ובשכבך\" פירושו כל אותו זמן בו אנשים ישנים, ובכלל זה כל הלילה — \u0003לימרו\u0004 \u0005[שיאמרו]\u0006 אם כן \u0003כרבן גמליאל,\u0004 ויפסקו כמוהו שעד עלות השחר מותר לקרות קריאת שמע של ערב.","ומשיבים: מבחינת הבנת המקראות \u0003לעולם כרבן גמליאל סבירא להו\u0004 \u0005[סבורים הם]\u0006 \u0003ו\u0004אולם \u0003הא דקא אמרי\u0004 \u0005[זה שאומרים הם]\u0006 \u0003\"עד חצות\",\u0004 הריהו רק סייג לדבר \u0003כדי להרחיק את האדם מן העבירה. כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 בביאור ענין זה, שבענין קריאת שמע \u0003חכמים עשו סייג לדבריהם, כדי שלא\u0004 יווצר מצב ש\u0003יהא אדם בא מן השדה בערב\u0004 והוא עייף מעבודת היום, ומשום שהוא יודע שזמן קריאת שמע הוא עד עלות השחר, \u0003ואומר\u0004 בלבו: \u0003\"אלך לביתי ואוכל קימעא\u0004 (מעט) \u0003ואשתה קימעא, ואישן קימעא, ואחר כך אקרא קריאת שמע ואתפלל\u0004 תפילת ערבית \u0003\", ו\u0004בינתיים \u0003חוטפתו שינה ונמצא ישן כל הלילה. אבל\u0004 מאחר שאדם חושש שאם ירדם אולי לא יתעורר לפני חצות ולא יקרא קריאת שמע בזמנה, לכן מעתה כאשר \u0003אדם בא מן השדה בערב\u0004 הריהו \u0003נכנס לבית הכנסת\u0004 ובבית הכנסת עד שמגיעים לתפילה עוסק הוא בדברי תורה, ש\u0003אם\u0004 הוא \u0003רגיל לקרות\u0004 במקרא בלבד — \u0003קורא. ואם רגיל לשנות\u0004 משניות, שהיא דרגה גבוהה יותר בלימוד — \u0003שונה, וקורא קריאת שמע ומתפלל\u0004 כיאות, \u0003ו\u0004כשהוא הולך לביתו הריהו \u0003אוכל\u0004 את \u0003פתו\u0004 במנוחת הדעת \u0003ומברך\u0004 עליה.","ומסיימת הברייתא באזהרה: \u0003וכל העובר על דברי חכמים חייב מיתה.\u0004","סיום זה מעורר פליאה, \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003בכל דוכתא\u0004 \u0005[מקום]\u0006 אחר ש\u0003לא קתני\u0004 \u0005[שנה\u0006 בו\u0005]\u0006 \u0003\"חייב מיתה\", ומאי שנא הכא דקתני\u0004 \u0005[ומה שונה כאן ששנה\u0006 בו\u0005]\u0006 \u0003\"חייב מיתה\"?\u0004 שלכאורה אין חומרה מיוחדת בסייג קריאת שמע. על כך משיבים שתי תשובות, ועיקרן, שלא משום חומרת העבירה נאמר כאן \"חייב מיתה\", אלא משום החשש שלא יוכלו לעמוד בדבר או שיזלזלו במיוחד בסייג זה.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003משום אונס שינה,\u0004 שאדם הבא מעבודתו רוצה מאד לישון, וצריך להזהירו במיוחד על כך. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003לאפוקי ממאן דאמר\u0004 \u0005[להוציא מ\u0006דעת \u0005מי שאומר]\u0006 \u0003\"תפלת ערבית רשות\"\u0004 ואינה חובה כשאר התפילות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שתפילת ערבית היא \u0003חובה,\u0004 והעובר על דברי חכמים אף בפרט זה — חייב מיתה.","בברייתא זו \u0003אמר מר\u0004 \u0005[החכם]\u0006 שהחוזר מעיסוקיו בערב, נכנס לבית הכנסת, \u0003קורא קריאת שמע ומתפלל.\u0004 הרי שבערב, כביום, קוראים תחילה קריאת שמע ואחר כך מתפללים. והרי זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' יוחנן.\u0004 ש\u0003אמר ר' יוחנן: איזהו בן העולם הבא\u0004 — \u0003זה הסומך גאולה\u0004 (הברכה על הגאולה, שהיא הברכה שלאחר קריאת שמע) \u0003לתפלה של ערבית. ר' יהושע בן לוי אומר: תפלות באמצע תקנום,\u0004 בין שתי קריאות שמע, של בוקר ושל ערב. ולכן, יש להתפלל קודם תפילת ערבית, ואחר כך לקרוא קריאת שמע של שעת שכיבה.","ההבדל למעשה בין שתי הדעות ברור הוא, אלא שמבררים עוד: \u0003במאי קא מפלגי\u0004 \u0005[במה הם חלוקים],\u0006 כלומר, מה הוא הבסיס למחלוקתם?","ומשיבים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שחלוקים הם בפירוש משמעות \u0003קרא\u0004 \u0005[\u0006המקרא הכתוב\u0005],\u0006 ו\u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שחלוקים הם ב\u0003סברא.\u0004","ומפרטים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שחלוקים הם ב\u0003סברא,\u0004 שהם חלוקים בענין ברכת הגאולה הנאמרת לאחר קריאת שמע ואשר היא מבוססת על הזכרת גאולת מצרים, שהיא הגאולה הראשונה. והשאלה היא אם אמנם גאולה זו החלה כבר בלילה, ולכן ראו לסמוך אף את גאולת מצרים הנזכרת בלילה לתפילת ישראל, בבקשה שתהא הגאולה קרובה, או שמא לא החלה אלא ביום.","ש\u0003ר' יוחנן סבר\u0004 \u0005[סבור]\u0006 שה\u0003גאולה מאורתא נמי הוי\u0004 \u0005[גם כן מן הערב היתה],\u0006 \u0003אלא\u0004 שה\u0003גאולה מעלייתא\u0004 \u0005[המעולה,\u0006 השלמה\u0005]\u0006 \u0003לא הויא\u0004 \u0005[היתה]\u0006 אמנם \u0003אלא עד צפרא\u0004 \u0005[הבוקר],\u0006 אך מאחר שהחלה גאולת ישראל מבערב, ראוי לצרף את ברכת הגאולה אף לתפילת ערבית בכל יום. ואילו \u0003ר' יהושע בן לוי סבר\u0004 \u0005[סבור]\u0006 כי \u0003כיון\u0004 ש\u0003לא הויא\u0004 \u0005[היתה]\u0006 הגאולה \u0003אלא מצפרא\u0004 \u0005[מהבוקר]\u0006 — \u0003לא הויא\u0004 \u0005[היתה]\u0006 גאולת הערב \u0003גאולה מעלייתא\u0004 \u0005[מעולה],\u0006 ולכך אין חובה לסמוך את התפילה להזכרת הגאולה של ערבית, שאינה גאולה שלימה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שאפשר להבין את מחלוקת ר' יוחנן ור' יהושע בן לוי, לא על בסיס הבדלי סברות כי אם על סמך \u0003קרא\u0004 \u0005[מקרא],\u0006 הבדלי פירוש המקרא, \u0003ושניהם מקרא אחד דרשו,\u0004 והוא \u0003\"\u0004ו\u0003בשכבך ובקומך\",\u0004 ששניהם מבינים שיש בו השוואה של קריאת שמע של ערב לקריאת שמע של בוקר.","ואולם, \u0003ר' יוחנן סבר\u0004 \u0005[סבור]:\u0006 \u0003מקיש\u0004 \u0005[משווה\u0006 המקרא\u0005]\u0006 \u0003שכיבה לקימה, מה\u0004 בשעת \u0003קימה\u0004 — \u0003קריאת שמע ואחר כך תפלה,\u0004 שבשעות הבוקר הכל מודים שיש לסמוך גאולה לתפילה, \u0003אף שכיבה נמי\u0004 \u0005[גם כן]\u0006 — \u0003קריאת שמע ואחר כך תפלה.\u0004 ואילו \u0003ר' יהושע בן לוי סבר\u0004 \u0005[סבור]:\u0006 \u0003מקיש שכיבה לקימה,\u0004 והוא מוצא צד אחר של השוואה: \u0003מה קימה\u0004 — \u0003קריאת שמע סמוך למטתו,\u0004 ו\"בקומך\" משמעו — סמוך ככל האפשר לשעת הקימה, \u0003אף שכיבה נמי\u0004 \u0005[גם כן]\u0006 — \u0003קריאת שמע סמוך למטתו,\u0004 שתהא חובת קריאת שמע של \"בשכבך\" אף היא סמוכה ככל האפשר לזמן השכיבה ממש.","לדעת ר' יוחנן מצוה לסמוך אף ברכת הגאולה שאחרי קריאת שמע של ערבית לתפילה, ואולם \u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא,\u0004 כיצד יתכן לעשות זאת? שהרי שנינו במשנה להלן: \u0003בערב מברך שתים,\u0004 שתי ברכות, \u0003לפניה,\u0004 לפני קריאת שמע, \u0003ושתים לאחריה. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003לסמוך\u0004 גאולה לתפילה, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא קא סמך\u0004 \u0005[סמך]\u0006 \u0003גאולה לתפלה, דהא בעי למימר\u0004 \u0005[שהרי צריך לומר]\u0006 \u0003\"השכיבנו\"\u0004 שהיא הברכה השניה הבאה לאחר ברכת הגאולה, ומפסיקה בין ברכת הגאולה לבין התפילה!","על כך \u0003אמרי\u0004 \u0005[אומרים]\u0006 כתשובה לשאלה: \u0003כיון דתקינו רבנן\u0004 \u0005[שתיקנו חכמים]\u0006 לומר \u0003\"השכיבנו\"\u0004 — \u0003כגאולה אריכתא דמיא\u0004 \u0005[ארוכה\u0006 היא \u0005נחשבת],\u0006 וכהמשכה של ברכת הגאולה, ולא כהפסק. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שחלקים שהוסיפו חכמים נחשבים כגוף התפילה ממש ולא כהוספות, גם בתפילת \u0003שחרית היכי מצי סמיך\u0004 \u0005[איך יוכל לסמוך]\u0006 גאולה לתפילה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן\u0004 עצמו : \u0003בתחלה,\u0004 בתחילתה של כל תפילה, \u0003אומר\u0004 המתפלל: \u0003\"ה' שפתי תפתח\u0004 ופי יגיד תהלתך\" (תהלים נא, יז) כהכנה לתפלה, \u0003ולבסוף הוא אומר: \"יהיו לרצון אמרי פי\u0004 והגיון לבי לפניך ה' צורי וגואלי\u0003\"\u0004 (תהלים יט, טו). והרי הפסוק \"ה' שפתי תפתח\" מפסיק בין גאולה לתפילה!","\u0003אלא התם\u0004 \u0005[שם]\u0006 \u0003כיון דתקינו רבנן למימר\u0004 \u0005[שתיקנו חכמים לומר]\u0006 \u0003\"ה' שפתי תפתח\"\u0004 — \u0003כתפלה אריכתא דמיא\u0004 \u0005[הריהי נחשבת לתפלה ארוכה],\u0006 ולא כהפסק חיצוני. \u0003הכא נמי\u0004 \u0005[כאן\u0006 בתפלת ערבית \u0005גם כן],\u0006 \u0003כיון דתקינו רבנן למימר\u0004 \u0005[שתיקנו חכמים לומר]\u0006 \u0003\"השכיבנו\"\u0004 — \u0003כגאולה אריכתא דמיא\u0004 \u0005[ארוכה התפילה נחשבת].\u0006","אגב דברי ר' יוחנן שהסומך גאולה לתפלה מובטח לו שהוא בן עולם הבא, צירפו אימרה דומה ש\u0003אמר ר' אלעזר, אמר ר' אבינא: כל האומר \"תהלה לדוד\"\u0004 (פרק קמה בספר תהלים) \u0003בכל יום שלש פעמים\u0004 — \u0003מובטח לו שהוא בן עולם הבא.\u0004","מאמר זה בשבחו של פרק זה בתהלים המכונה כרגיל \"אשרי\" משום שמקדימים לאמירתו את הפסוק \"אשרי יושבי ביתך עוד יהללוך סלה\" (תהלים פד, ה) עורר את השאלה: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 אשר בגללו מחשיבים כל כך מזמור זה?","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דאתיא\u0004 \u0005[ש\u0006הוא \u0005בא,\u0006 נסדר] \u0003באל\"ף בי\"ת,\u0004 שבמזמור זה מסודרים ראשי הפסוקים לפי סדר האל\"ף בי\"ת, \u0003נימא\u0004 \u0005[יאמר]\u0006 אם כן \u0003\"אשרי תמימי דרך\"\u0004 (פרק קיט בתהלים) \u0003דאתיא בתמניא אפין\u0004 \u0005[הבא בשמונה פנים],\u0006 שבו סדורים ראשי הפסוקים בסדר של כל האל\"ף בי\"ת כולו שמונה פעמים, ולפרק זה איפוא היתרון בכך על כל פרק אחר.","\u0003אלא\u0004 תאמר שהסיבה לאמירת פרק זה דווקא היא \u0003משום דאית ביה\u0004 \u0005[שיש בו,\u0006 בפרק זה\u0005]\u0006 את מלות השבח בענין הספקת מזון לכל יצור \u0003\"פותח את ידך\u0004 ומשביע לכל חי רצון\" (תהלים קמה, טז), אם כן \u0003נימא\u0004 \u0005[יאמר]\u0006 \u0003\"הלל הגדול\"\u0004 (כך מכונה מזמור קלו שבתהלים) \u0003דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 \u0003\"נתן לחם לכל בשר\u0004 כי לעולם חסדו\u0003\"\u0004 (תהלים קלו כה) נוסף לשאר שבחים שיש בו!","\u0003אלא\u0004 מעלתו של מזמור \"תהלה לדוד\" היא \u0003משום דאית ביה תרתי\u0004 \u0005[שיש בו שתים],\u0006 גם סדר אל\"ף בי\"ת, וגם שבח הספקת המזון לכל יצור.","ועוד על מזמור תהלים זה \u0003אמר ר' יוחנן: מפני מה לא נאמר\u0004 פסוק המתחיל באות \u0003נו\"ן ב\"אשרי\"\u0004 — \u0003מפני שיש בה מפלתן של שונאי ישראל,\u0004 שבאות זו נאמר פסוק שיש בו הדגשה יתירה של מפלת ישראל (\"שונאי ישראל\" הוא ביטוי בלשון סגי נהור) \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"נפלה לא תוסיף קום בתולת ישראל\u0004 נטשה על אדמתה אין מקימה \u0003\" (עמוס ה, ב), ולכן, הושמט הפסוק המתחיל בנו\"ן גם מ\"אשרי\". \u0004","כדי לרכך את משמעות פסוק זה עצמו היו \u0003במערבא מתרצי לה הכי\u0004 \u0005[בארץ ישראל מיישבים אותו כך],\u0006 על ידי שינוי בפיסוק: \u0003\"נפלה ולא תוסיף לנפול עוד, קום\u0004 (קומי) \u0003בתולת ישראל\", אמר רב נחמן בר יצחק: אפילו הכי\u0004 \u0005[כך ],\u0006 \u0003חזר דוד וסמכן ברוח הקדש,\u0004 שאף שלא הכניס דוד המלך במזמור זה פסוק הפותח באות נו\"ן המרמזת על נפילה, צפה דוד ברוח הקודש פסוק זה במקום שהוא עצמו השמיט את הנו\"ן במזמורו, והפסוק הבא המתחיל בסמ\"ך הריהו \u0003\"סומך ה' לכל הנפלים\u0004 וזוקף לכל הכפופים\u0003\"\u0004 (תהלים קמה, יד), ואם כן סמכן דוד ברוח הקודש לנופלים ועודדם, שאף כי נפלה בתולת ישראל — סומך ה' לנופלים.","אגב דברי ר' אלעזר בר אבינא, קשרו למאמר זה עוד מאמר אחר בשמו. \u0003אמר ר' אלעזר בר אבינא: גדול מה שנאמר ב\u0004מלאך \u0003מיכאל יותר ממה שנאמר ב\u0004מלאך \u0003גבריאל.\u0004 ש\u0003אילו במיכאל כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויעף אלי אחד מן השרפים\"\u0004 (ישעיהו ו, ו), כלומר, שבפריחה אחת של מעופו הריהו מגיע ועושה את שליחותו. \u0003ואילו גבי\u0004 \u0005[אצל]\u0006 \u0003גבריאל כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"והאיש גבריאל אשר ראיתי בחזון בתחלה מעף ביעף\u0004 נוגע אלי כעת מנחת ערב\" (דניאל ט, כא), שמן הביטוי \"מועף ביעף\" נלמד שאין הוא מגיע למטרתו במישרין במעוף אחד, כי אם בשתי פריחות \"מועף\" ו\"ביעף\".","לר' אלעזר בר אבינא, ברור היה ש\"אחד מן השרפים\" הוא מיכאל, ושואלים: \u0003מאי משמע דהאי\u0004 \u0005[מה\u0006 היא \u0005המשמעות,\u0006 כיצד מוכיחים\u0005, שאותו]\u0006 \u0003\"אחד\"\u0004 האמור בכתוב \u0003מיכאל הוא?\u0004","\u0003אמר ר' יוחנן:\u0004 דבר זה \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 בדרך השוואת המילים \u0003\"אחד\" \"אחד\"\u0004 כעין גזירה שווה; \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"ויעף אלי אחד מן השרפים\"\u0004 (ישעיהו ו, ו), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"והנה מיכאל אחד השרים הראשונים בא לעזרני\"\u0004 (דניאל י, יג), וכשם שבפסוק בדניאל מיכאל הוא \"אחד\" (ומשמעו במדרשי חז\"ל: אחד—מיוחד), כן גם \"אחד מן השרפים\" האמור בישעיהו, הוא בוודאי המיוחד שבהם — מיכאל. ולהשלמת הדברים מובאת תוספתא על דרגותיהם של המלאכים, על פי מספר הפריחות שצריך המלאך לעשות כדי להגיע למחוז חפצו.","\u0003תנא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003מיכאל\u0004 — \u0003ב\u0004פריחה \u0003אחת,\u0004 וכפי שנאמר, \u0003גבריאל\u0004 — \u0003בשתים, אליהו\u0004 הנביא — \u0003בארבע, ומלאך המות\u0004 — \u0003בשמנה. ו\u0004אולם \u0003בשעת המגפה\u0004 כשמלאך המוות נראה כמצוי בכל, הרי גם הוא מגיע לכל מקום \u0003באחת.\u0004","\u0003אמר ר' יהושע בן לוי: אף על פי שקרא אדם קריאת שמע בבית הכנסת\u0004 — \u0003מצוה לקרותו על מטתו\u0004 כדי שיקיים בפועל \"בשכבך\". \u0003אמר ר' יוסי: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 הרומז שיש לקרוא את שמע על מטתו כתוספת לחובת הקריאה בערב — \u0003\"רגזו ואל תחטאו אמרו בלבבכם על משכבכם ודמו סלה\"\u0004 (תהלים ד, ה), המתפרש כאן: אמרו את קריאת שמע שכתוב בה \"על לבבך\", על משכבכם, ואחר \"דומו\" — שתקו ונוחו בשינה.","על דברי ר' יהושע בן לוי \u0003אמר רב נחמן:\u0004"],["\u0003אם תלמיד חכם הוא\u0004 — \u0003אין\u0004 הוא \u0003צריך\u0004 לומר קריאת שמע על המטה, מאחר שתמיד הוא עוסק בתורה, ולא ירדם אלא מתוך עיסוק בדברי תורה. \u0003אמר אביי: אף תלמיד חכם מיבעי ליה למימר חד פסוקא דרחמי\u0004 \u0005[צריך הוא לומר פסוק אחד של רחמים],\u0006 \u0003כגון: \"בידך אפקיד רוחי, פדיתה אותי ה' אל אמת\"\u0004 (תהלים לא, ו).","ואגב הפסוק \"רגזו ואל תחטאו\" מביאים את מה ש\u0003אמר ר' לוי בר חמא, אמר ר' שמעון בן לקיש: לעולם ירגיז אדם יצר טוב על יצר הרע,\u0004 כלומר, שיילחם ללא הרף עם יצרו הרע המביאו לידי חטא. \u0003ש\u0004כן \u0003נאמר: \"רגזו ואל תחטאו\" אם נצחו\u0004 האדם ליצרו במלחמתו זו — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 נצחו בכך — \u0003יעסוק בתורה,\u0004 וכפי \u0003שנאמר\u0004 בהמשך הפסוק: \u0003\"אמרו בלבבכם\"\u0004 שהיא אמירת דברי תורה. \u0003אם\u0004 כתוצאה מכך \u0003נצחו\u0004 ליצרו הרע — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 נצחו — \u0003יקרא קריאת שמע,\u0004 שכן יש בה קבלת עול ה', והבטחת השכר והעונש. וכפי \u0003שנאמר\u0004 עוד בהמשך הפסוק: \u0003\"על משכבכם\"\u0004 שהוא רמז לקריאת שמע שנזכר בה \"בשכבך\". \u0003אם\u0004 כתוצאה מכך \u0003נצחו\u0004 — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 נצחו — \u0003יזכור לו יום המיתה,\u0004 וכפי \u0003שנאמר\u0004 בהמשך הכתוב: \u0003\"ודמו סלה\",\u0004 שהוא רמז ליום המיתה, ומשמעות הכתוב לפי זה היא: דומו דומייה מוחלטת, שהיא דומיית המוות.","\u0003ו\u0004עוד \u0003אמר ר' לוי בר חמא, אמר ר' שמעון בן לקיש, מאי דכתיב\u0004 \u0005[מהי\u0006 משמעות כתוב זה \u0005שנאמר]\u0006 שאמר ה' למשה \"עלה אלי ההרה והיה שם \u0003ואתנה לך את לחת האבן והתורה והמצוה אשר כתבתי להורתם\"\u0004 (שמות כד, יב), שבא לגלות לו לא רק את התורה שבכתב, אלא גם כל תורת ישראל לדורותיה. \u0003\"לחת\" — אלו עשרת הדברות\u0004 שנכתבו בלוחות הברית, \u0003\"תורה\" — זה מקרא,\u0004 כלומר, חמישה חומשי תורה. \u0003\"והמצוה\"\u0004 — \u0003זו משנה,\u0004 כי ביאורן של המצוות לפרטי קיומן למעשה מצוי בתורה שבעל פה, ובמיוחד במשנה. \u0003\"אשר כתבתי\"\u0004 — \u0003אלו נביאים וכתובים\u0004 שנכתבו בהשראה אלקית, \u0003\"להרתם\"\u0004 — \u0003זה תלמוד,\u0004 ביאור דברי המשנה, והסברתם הריהו יסוד ה\"הוראה\" הלכה למעשה, \u0003מלמד\u0004 פסוק זה \u0003שכולם נתנו למשה מסיני.\u0004","ומכאן שבים לדון בקריאת שמע על המטה. \u0003אמר ר' יצחק: כל הקורא קריאת שמע על מטתו, כאלו אוחז חרב של שתי פיות בידו\u0004 לשמור עליו מכל רע. וראיה לדבר, \u0003שנאמר: \"רוממות אל בגרונם וחרב פיפיות בידם\"\u0004 (תהלים קמט, ו), ושואלים: \u0003מאי משמע\u0004 \u0005[מה משמעות]\u0006 יש בפסוק המורה שבקריאת שמע עניינו? \u0003אמר מר זוטרא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אשי: מרישא דענינא\u0004 \u0005[מראש הענין],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בפסוק הקודם: \u0003\"יעלזו חסידים בכבוד ירננו על משכבותם\"\u0004 (תהלים קמט, ו), והרננה לה' שעל המשכב היא קריאת שמע שעל המטה. \u0003וכתיב בתריה\u0004 \u0005[ונאמר\u0006 מייד \u0005אחריו]:\u0006 \u0003\"רוממות אל בגרונם וחרב פיפיות בידם\". \u0004","ובשינוי מה, \u0003אמר ר' יצחק: כל הקורא קריאת שמע על מטתו\u0004 — \u0003מזיקין בדילין הימנו.\u0004 ורמז לדבר ממה \u0003שנאמר:\u0004 \"אדם לעמל יולד \u0003ובני רשף יגביהו עוף\"\u0004 (איוב ה, ז), ומבאר את חלקו הסתום של הפסוק: \u0003ואין\u0004 משמעות הלשון \u0003\"עוף\" אלא תורה,\u0004 כי התורה קשה להבנה וקלה לשיכחה כדבר המתעופף, שאי אפשר להחזיק בו כיאות, וכפי \u0003שנאמר: \"התעיף עיניך בו ואיננו\u0004 כי עשה יעשה לו כנפים כנשר יעוף בשמים\u0003\"\u0004 (משלי כג, ה). \u0003ואין\u0004 משמעות הלשון \u0003\"רשף\" אלא מזיקין,\u0004 וכפי \u0003שנאמר: \"מזי רעב ולחמי רשף וקטב מרירי\u0004 ושן בהמות אשלח בם עם חמת זוחלי עפר \u0003\" (דברים לב, כד), הרי שה\"רשף\" נמנה עם ה\"קטב מרירי\" (המבואר בדברי חז\"ל ככינוי למזיק).\u0004","על פסוק סתום זה \u0003אמר ר' שמעון בן לקיש\u0004 לדרוש: \u0003כל העוסק בתורה\u0004 — \u0003יסורין בדילין הימנו, שנאמר: \"ובני רשף יגביהו עוף\". ואין \"עוף\" אלא תורה, שנאמר \"התעיף עיניך בו ואיננו\", ואין \"רשף\" אלא יסורין, שנאמר: \"מזי רעב ולחמי רשף\",\u0004 ש\"לחומי רשף\" מושווה עם \"מזי רעב\", כיסורים שונים. ומכאן שעל ידי לימוד התורה (\"עוף\") יכול הוא להרחיק (\"יגביהו\") את היסורים (\"בני רשף\").","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: הא\u0004 \u0005[\u0006רעיון \u0005זה]\u0006 \u0003אפילו תינוקות של בית רבן\u0004 הלומדים רק את חומשי התורה ולא יותר, גם הם \u0003יודעין אותו, ש\u0004כן \u0003נאמר\u0004 במפורש: \u0003\"ויאמר אם שמוע תשמע לקול ה' אלקיך והישר בעיניו תעשה והאזנת למצותיו ושמרת כל חקיו כל המחלה אשר שמתי במצרים לא אשים עליך כי אני ה' רופאך\"\u0004 (שמות טו, כו). \u0003אלא\u0004 יש לדרוש כך: \u0003כל שאפשר לו לעסוק בתורה ואינו עוסק\u0004 — \u0003הקדוש ברוך הוא מביא עליו יסורין מכוערין ועוכרין אותו,\u0004 שלא זו בלבד שאין ה' מגן עליו, אלא שבאים עליו יסורין מכאיבים ומבישים, \u0003שנאמר: \"נאלמתי דומיה החשיתי מטוב וכאבי נעכר\"\u0004 (תהלים לט, ג), \u0003ואין\u0004 משמעות לשון \u0003\"טוב\" אלא תורה, שנאמר: \"כי לקח טוב נתתי לכם תורתי אל תעזבו\"\u0004 (משלי ד, ב), ולכן, כך יש לפרש את הפסוק: אם \"החשיתי מטוב\", כלומר, שתקתי מלעסוק בתורה — כעונש לכך בא \"כאבי נעכר\".","ובקשר לפסוק \"כי לקח טוב נתתי לכם\", \u0003אמר ר' זירא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חנינא בר פפא: בא וראה שלא כמדת הקדוש ברוך הוא מדת בשר ודם. מדת בשר ודם, אדם מוכר חפץ לחבירו, מוכר\u0004 — \u0003עצב, ולוקח\u0004 (קונה) — \u0003שמח,\u0004 כי אדם המוכר חפץ מחפציו הפרטיים מצטער על שהוציא את הדבר מרשותו. \u0003אבל הקדוש ברוך הוא אינו כן, נתן להם תורה לישראל\u0004 — \u0003ושמח\u0004 בנתינתו, \u0003שנאמר: \"כי לקח טוב נתתי לכם תורתי אל תעזבו\".\u0004 ו\"לקח טוב\" מתפרש כ\"מקח טוב\", שאף שכאילו \"מכר\" הקדוש ברוך הוא את התורה לישראל, שמח הוא במכירה, ומשבח אותה בעיני קוניה (ריא\"ף).","דובר מקודם בענין יסורים הבאים על אדם בשל חטאיו, ומכאן יבואר ענין היסורים בכלל, יסורים הבאים ללא חטא, ויסורי הצדיקים. \u0003אמר רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב חסדא: אם רואה אדם שיסורין באין עליו\u0004 — \u0003יפשפש במעשיו,\u0004 שמן הסתם כעונש על חטאיו באו היסורים, \u0003שנאמר: \"נחפשה דרכינו ונחקרה ונשובה עד ה'\"\u0004 (איכה ג, מ). אך אם \u0003פשפש\u0004 במעשיו \u0003ולא מצא\u0004 עבירה כזו שיהיו יסורים אלה ראויים לבוא עליו — \u0003יתלה בבטול תורה,\u0004 שה' מעניש את המבטל תורה ביסורים, כדי שיעלה על לבו את חומרת הדבר, \u0003שנאמר: \"אשרי הגבר אשר תיסרנו יה ומתורתך תלמדנו\"\u0004 (תהלים צד, יב), המתפרש: שמתוך שהוא מתייסר ישוב לכך ש\"מתורתך תלמדנו\".","\u0003ואם תלה\u0004 אף בעוון זה \u0003ולא מצא\u0004 — \u0003בידוע שיסורין של אהבה הם, שנאמר: \"כי את אשר יאהב ה' יוכיח\u0004 וכאב את בן ירצה\u0003\"\u0004 (משלי ג, יב).","וכן \u0003אמר רבא, אמר רב סחורה, אמר רב הונא: כל שהקדוש ברוך הוא חפץ בו\u0004 — \u0003מדכאו ביסורין, שנאמר: \"וה' חפץ דכאו החלי\u0004 אם תשים אשם נפשו יראה זרע יאריך ימים וחפץ ה' בידו יצלח\u0003\"\u0004 (ישעיה נג, י), שמי שה' חפץ בו — מחלה אותו.","\u0003יכול אפילו לא קבלם\u0004 את יסוריו \u0003מאהבה\u0004 חפץ בו ה'? — \u0003תלמוד לומר: \"אם תשים אשם נפשו\", מה אשם לדעת,\u0004 שכן קרבן אשם הוא מן הקרבנות שמביאים אותם רק מדעת ומרצון בלא כפיה, \u0003אף יסורין\u0004 — לדעת, ומרצונו.","\u0003ואם קבלם\u0004 מאהבה \u0003מה שכרו\u0004 — כפי שנאמר בהמשך הפסוק: \u0003\"יראה זרע יאריך ימים\". ולא עוד אלא\u0004 נוסף לברכות חומריות אלו \u0003שתלמודו מתקיים בידו\u0004 ולימוד תורתו זוכה להצלחה, \u0003שנאמר: \"וחפץ ה'\",\u0004 התורה, גילוי רצון ה', \u0003\"בידו יצלח\".\u0004","ובענין זה של יסורים מאהבה ומה הגדרתם \u0003פליגי\u0004 \u0005[חלוקים]\u0006 \u0003בה ר' יעקב בר אידי ור' אחא בר חנינא. חד\u0004 \u0005[אחד\u0006 מהם] \u0003אמר: אלו הם יסורין של אהבה\u0004 — \u0003כל שאין בהן בטול תורה,\u0004 כלומר, שיסורים אלה פוגעים אך בגוף ועדיין מסוגל הוא ללמוד תורה, וראיה לדבריו ממה \u0003שנאמר: \"אשרי הגבר אשר תיסרנו יה ומתורתך תלמדנו\"\u0004 שיסורים אלה של אהבה (\"אשרי\") הינם כאשר \"מתורתך תלמדנו\".","\u0003ו\u0004אילו \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: אלו הם יסורין של אהבה\u0004 — \u0003כל שאין בהן בטול תפלה,\u0004 וראיה לדבר, \u0003ש\u0004אחרי שמתוארים בפרק ס\"ו בתהלים יסורים הבאים על העם, \u0003נאמר: \"ברוך אלהים אשר לא הסיר תפלתי וחסדו מאתי\"\u0004 (תהלים סו, כ), כלומר, שלמרות היסורים מסוגל הסובל להתפלל לה'.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא, הכי\u0004 \u0005[כך]\u0006 \u0003אמר\u0004 אבי \u0003ר' חייא בר אבא: אלו ואלו\u0004 בין שאין בהם ביטול תורה, ובין שאין בהם ביטול תפילה, \u0003יסורין של אהבה הן, ש\u0004הסובל יסורים ללא חטא, \u0003נאמר\u0004 בו: \u0003\"כי את אשר יאהב ה' יוכיח\",\u0004 ובתוך יסוריו נמנים גם ביטול התורה והתפילה.","\u0003אלא מה תלמוד לומר \"ומתורתך תלמדנו\"\u0004 — \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"תלמדנו\",\u0004 לאמר: תלמד אותו, \u0003אלא תלמדנו\u0004 = תלמד אותנו. ומשמעו: \u0003דבר זה,\u0004 על ערכם של יסורים — \u0003מ\u0004תוך דיני \u0003תורתך תלמדנו,\u0004 ובדרך \"קל וחומר\":","\u0003קל וחומר משן ועין\u0004 שבדיני עבד. \u0003מה שן ועין שהן\u0004 אינן אלא \u0003אחד מאבריו של אדם,\u0004 אם גרם האדון להפיל את שינו או עינו — ה\u0003עבד יוצא בהן לחרות, יסורין שממרקין כל גופו של אדם\u0004 — \u0003על אחת כמה וכמה\u0004 שמתכפרים עוונותיו ביסוריו.","\u0003והיינו\u0004 \u0005[וזהו]\u0006 כשיטת \u0003ר' שמעון בן לקיש,\u0004 ש\u0003אמר ר' שמעון בן לקיש: נאמר\u0004 לשון \u0003\"ברית\" במלח, ונאמר\u0004 לשון \u0003\"ברית\" ביסורין, נאמר \"ברית\" במלח, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולא תשבית מלח ברית\u0004 אלהיך מעל מנחתך על כל קרבנך תקריב מלח\u0003\"\u0004 (ויקרא ב, יג), \u0003ונאמר \"ברית\" ביסורין, דכתיב\u0004 \u0005[שנאמר]\u0006 לאחר רשימת היסורים הבאים על הסרים מן התורה: \u0003\"אלה דברי הברית\"\u0004 (דברים כח, סט), \u0003מה \"ברית\" האמור במלח\u0004 — דרך הטבע היא ש\u0003מלח ממתקת את הבשר\u0004 מכשירתו לאכילה, \u0003אף \"ברית\" האמור ביסורין\u0004 היא כברית מלח ו\u0003יסורין ממרקין כל עונותיו של אדם\u0004 ומכשירים אותו לחיים עליונים.","ועוד בדבר חיבת היסורים \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן יוחאי אומר: שלש מתנות טובות נתן הקדוש ברוך הוא לישראל, וכולן לא נתנן אלא על ידי יסורין,\u0004 שצריך להזדכך ביסורים כדי לזכות בהן. ו\u0003אלו הן: תורה וארץ ישראל והעולם הבא.\u0004","\u0003תורה מנין\u0004 — \u0003שנאמר: \"אשרי הגבר אשר תיסרנו יה\"\u0004 ורק אחר כך \u0003\"ומתורתך תלמדנו\".\u0004","וביחס ל\u0003ארץ ישראל\u0004 נאמר: \u0003\"כי כאשר ייסר איש את בנו ה' אלהיך מיסרך\"\u0004 (דברים ח, ה), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]:\u0006 \u0003\"כי ה' אלהיך מביאך אל ארץ טובה\".\u0004","וכן \u0003העולם הבא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי נר מצוה ותורה אור ודרך חיים תוכחות מוסר\"\u0004 (משלי ו, כג), כלומר, אין להגיע אל \"דרך חיים\" הנצחיים בעולם הבא אלא על ידי \"תוכחות מוסר\" בעולם הזה.","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003ר' יוחנן\u0004 את הברייתא הבאה העוסקת אף היא בנושא זה: \u0003כל העוסק בתורה ובגמילות חסדים\u0004"],["\u0003וקובר את בניו\u0004 — \u0003מוחלין לו על כל עונותיו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן:\u0004 מה מקור הדברים הללו, \u0003בשלמא\u0004 \u0005[נניח]\u0006 בענין \u0003תורה וגמילות חסדים\u0004 שמכפרות, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"בחסד ואמת יכפר עון\"\u0004 (משלי טז, ו), ו\u0003\"חסד\"\u0004 — \u0003זו גמילות חסדים,\u0004 כמו \u0003שנאמר: \"רודף צדקה וחסד ימצא חיים צדקה וכבוד\"\u0004 (משלי כא, כא), שצדקה וחסד ניתנו יחד. ואילו \u0003\"אמת\"\u0004 — \u0003זו תורה, שנאמר: \"אמת קנה ואל תמכר\u0004 חכמה ומוסר ובינה\u0003\"\u0004 (משלי כג, כג). \u0003אלא\u0004 ה\u0003\"קובר את בניו\" מנין\u0004 לנו שמתכפרים בכך עוונותיו?","את התשובה לכך קיבל כאשר \u0003תנא ליה ההוא סבא\u0004 \u0005[שנה לו זקן אחד]\u0006 שלא נתפרש שמו, \u0003משום\u0004 (בשם) \u0003ר' שמעון בן יוחאי: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 מסקנה זו מהשוואת המילים \u0003\"עון\" \"עון\". כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"בחסד ואמת יכפר עון\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"ומשלם עון אבות אל חיק בניהם\"\u0004 (ירמיהו לב, יח), שמשום \"משלם עוון אבות אל חיק בניהם\" יכופר עוון האבות.","\u0003אמר ר' יוחנן: נגעים,\u0004 נגעי צרעת הבאים על האדם, \u0003ו\u0004יסורים הבאים מחמת \u0003בנים\u0004 — \u0003אינן יסורין של אהבה.\u0004","ושואלים: \u0003ו\u0004האם \u0003נגעים לא\u0004 יסורים של אהבה הם? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל מי שיש בו אחד מארבעה מראות נגעים הללו\u0004 שמנו חכמים בצרעת (עיין ויקרא יג) — \u0003אינן אלא מזבח כפרה!\u0004","ומשיבים: אמנם נגעים \u0003מזבח כפרה\u0004 — \u0003הוו\u0004 \u0005[הינן],\u0006 שיש בהם משום כפרת עוונות של אדם, ואולם \u0003יסורים של אהבה לא הוו\u0004 \u0005[אין הן].\u0006","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 הסבר אחר: \u0003הא\u0004 \u0005[זה]\u0006 דברי הברייתא שנגעים הם מזבח כפרה — הרי זה נאמר \u0003לן\u0004 \u0005[לנו],\u0006 לבני בבל, שאין הם נזהרים בחוץ לארץ כל כך בדיני טומאה, ויושב המצורע בין אחיו, ויסוריו הם לעצמו — הריהם בבחינת מזבח כפרה. \u0003והא\u0004 \u0005[וזה]\u0006 דברי ר' יוחנן שאין נגעים יסורים של אהבה — הרי זה נאמר \u0003להו\u0004 \u0005[להם],\u0006 לבני ארץ ישראל, שמאחר שנזהרים בטומאה ומפרישים את המצורע, אין יסוריו יסורי אהבה (רה\"ג).","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 דברי הברייתא שנגעים הם מזבח כפרה — כשהם \u0003בצנעא,\u0004 במקומות מוצנעים בגופו של אדם, \u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' יוחנן שאין הם יסורים של אהבה — הרי זה כשהם \u0003בפרהסיא,\u0004 במקומות גלויים שבגופו. ודברי ר' יוחנן שייכים בנגעים שבפרהסיא שהכל מתרחקים מהם.","\u0003ו\u0004עוד תמהים: וכי ייסורים מחמת \u0003בנים לא\u0004 יסורים של אהבה הם?! ומבררים: \u0003היכי דמי\u0004 \u0005[איך בדיוק מדובר],\u0006 \u0003אילימא דהוו להו\u0004 \u0005[אם תאמר שהיו להם ]\u0006 בנים \u0003ומתו, והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן\u0004 עצמו, כאשר היה מנחם מי שאירע בו אסון \u0003דין גרמא דעשיראה ביר\u0004 \u0005[זו\u0006 היא \u0005העצם של בני העשירי].\u0006 שמתו לו עשרה בנים בחייו והשאיר לעצמו זכרון מכאיב של עצם קטנה מבנו העשירי. והיה נוהג להראות אותה עצם, ובאמצעותה לנחם את הצריך ניחומים. ומאחר שנהג לנחם בכך, ודאי יסורים אלה יסורים של אהבה הם, ולכן הראה לאחרים שיש בכך צד של קרבת ה' (תוספות). ומדוע אמר ר' יוחנן שיסורי בנים אינם של אהבה? \u0003אלא\u0004 יש לומר ש\u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' יוחנן שאינם יסורים של אהבה — הרי זה באופן ש\u0003לא הוו ליה\u0004 \u0005[היו לו]\u0006 בנים \u0003כלל. והא\u0004 \u0005[וזה]\u0006 ששנינו שהם יסורים של אהבה — הרי זה באופן \u0003דהוו ליה\u0004 \u0005[שהיו לו]\u0006 בנים \u0003ומתו,\u0004 שהאבילות מכפרת על עוונותיו.","ועוד בענין היסורים, מסופר: \u0003ר' חייא בר אבא\u0004 שהיה תלמידו של ר' יוחנן \u0003חלש\u0004 \u0005[חלה].\u0006 \u0003על לגביה\u0004 \u0005[נכנס אצלו]\u0006 \u0003ר' יוחנן\u0004 רבו לביקור חולים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לר' חייא בר אבא: האם \u0003חביבין עליך יסורין?\u0004 הרוצה אתה להיות חולה ולסבלם? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: \u0003לא הן ולא שכרן.\u0004 כלומר, נכון הוא לוותר על היסורים ועל השכר הצפוי למקבלם באהבה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי ידך. יהב ליה ידיה, ואוקמיה\u0004 \u0005[נתן לו\u0006 ר' חייא בר אבא את \u0005ידו, והעמידו],\u0006 ר' יוחנן על רגליו ממטת חוליו, וחזר ר' חייא בר אבא לבריאותו.","וכן מסופר ש\u0003ר' יוחנן\u0004 עצמו \u0003חלש\u0004 \u0005[חלה].\u0006 \u0003על לגביה\u0004 \u0005[נכנס אצלו]\u0006 \u0003ר' חנינא\u0004 לביקור חולים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חנינא לר' יוחנן: האם \u0003חביבין עליך יסורין? אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003לא הן ולא שכרן. אמר ליה\u0004 \u0005[לו]\u0006 ר' חנינא: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי ידך. יהב ליה ידיה, ואוקמיה\u0004 \u0005[נתן לו\u0006 ר' חנינא את \u0005ידו, והעמידו],\u0006 ר' חנינא, וחזר ר' יוחנן לבריאותו.","ואולם שואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הוזקק ר' יוחנן לחכות עד שיבוא ר' חנינא וירפאנו, \u0003לוקים\u0004 \u0005[יעמיד]\u0006 \u0003ר' יוחנן לנפשיה\u0004 \u0005[את עצמו],\u0006 שהרי ראינו שגדול היה כוחו לרפא את תלמידו,","על כך \u0003אמרי\u0004 \u0005[אומרים]:\u0006 כלל הוא \u0003אין חבוש\u0004 (אסיר) \u0003מתיר עצמו מבית האסורים,\u0004 אלא זקוק הוא שאדם מן החוץ יתיר את כבליו.","ועוד מסופר ש\u0003ר' אלעזר\u0004 תלמידו של ר' יוחנן \u0003חלש\u0004 \u0005[חלה].\u0006 \u0003על לגביה\u0004 \u0005[נכנס אצלו]\u0006 \u0003ר' יוחנן\u0004 רבו לבקרו. \u0003חזא דהוה קא גני\u0004 \u0005[ראה שהיה שוכב]\u0006 \u0003בבית אפל. גלייה לדרעיה\u0004 \u0005[גילה\u0006 ר' יוחנן \u0005את זרועו]\u0006 \u0003ונפל\u0004 (נעשה) \u0003נהורא\u0004 \u0005[אור]\u0006 בבית, מחמת בוהק בשרו של ר' יוחנן. \u0003חזייה דהוה קא בכי\u0004 \u0005[ראהו\u0006 ר' יוחנן \u0005שהיה בוכה]\u0006 \u0003ר' אלעזר. אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003אמאי קא בכית\u0004 \u0005[מדוע אתה בוכה]?\u0006 וחשב ר' יוחנן שר' אלעזר בכה על היסורים שהיו לו בחייו, וניחמו: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום תורה\u0004 ש\u0003לא אפשת\u0004 \u0005[הרבית\u0006 ללמוד] כפי שרצית — הרי על כך כבר \u0003שנינו: אחד המרבה ואחד הממעיט, ובלבד שיכוין לבו לשמים. ואי\u0004 \u0005[ואם]\u0006 \u0003משום מזוני\u0004 \u0005[מזונות],\u0006 חוסר פרנסה, שהיה ר' אלעזר עני מאד — \u0003לא כל אדם זוכה לשתי שלחנות,\u0004 גם לשולחן עושר וגם לשולחן תורה, ומאחר שזכית לתורה — אינך צריך להצטער על שלא זכית לעושר. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום בני\u0004 \u0005[בנים]\u0006 שמתו אתה בוכה — \u0003דין גרמא דעשיראה ביר\u0004 \u0005[זו\u0006 היא \u0005העצם של בני העשירי],\u0006 והרי שיסורים אלה פוגעים בגדולים, ואלה הם יסורים של אהבה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אלעזר: לא על עצמי בוכה אני, אלא \u0003להאי שופרא דבלי בעפרא קא בכינא\u0004 \u0005[על אותו יופי הבלה בעפר אני בוכה],\u0006 שמראה יופיו של ר' יוחנן עורר אותו לחשוב על המוות, והוא הזדעזע מתוך המחשבה שיופי כזה סופו שיבלה בעפר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003על דא\u0004 \u0005[זה]\u0006 \u0003ודאי קא בכית\u0004 \u0005[\u0006ראוי \u0005לך לבכות],\u0006 \u0003ובכו תרוייהו\u0004 \u0005[שניהם]\u0006 על יופיו של העולם בכלל שהוא כה עראי וחולף ושהמוות נוטל ומבלה את הכל.","\u0003אדהכי והכי\u0004 \u0005[בין כה וכה]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003חביבין עליך יסורין? אמר ליה\u0004 \u0005[לו]\u0006 ר' אלעזר: \u0003לא הן ולא שכרן.\u0004 כיון ששמע כן \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי ידך, יהב ליה ידיה, ואוקמיה\u0004 \u0005[נתן לו ידו, והעמידו]\u0006 מחוליו.","ומסופר עוד מענין צידוק הדין: \u0003רב הונא תקיפו ליה\u0004 \u0005[החמיצו לו]\u0006 \u0003ארבע מאה דני דחמרא\u0004 \u0005[מאות חביות יין],\u0006 והיה ההפסד בכך גדול מאד. \u0003על לגביה\u0004 \u0005[נכנס אצלו]\u0006 \u0003רב יהודה אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רב סלא חסידא\u0004 \u0005[החסיד]\u0006 \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003ואמרי ליה\u0004 \u0005[ויש אומרים]\u0006 שהיו אלה \u0003רב אדא בר אהבה ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]\u0006 לרב הונא: \u0003לעיין מר במיליה\u0004 \u0005[יבדוק אדוני במעשיו]\u0006 שמא חטא יש בידו ומשום כך נענש. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ומי חשידנא בעינייכו\u0004 \u0005[והאם חשוד אני בעיניכם]\u0006 שבעל עבירה אני, שמייעצים אתם לי לפשפש במעשי? \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מי חשיד קודשא בריך הוא דעביד דינא\u0004 \u0005[\u0006ו\u0005האם חשוד הקדוש ברוך הוא שעושה דין]\u0006 \u0003בלא דינא\u0004 \u0005[דין,\u0006 בלא משפט\u0005]?!\u0006 והפסד זה ודאי בדין אירע, וראוי לך לפשפש במעשיך. שידעו בו חכמים דבר שנחשב לפגם, ורמזו שיש בפיהם מה לומר לו (תוספות).","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אי איכא מאן דשמיע עלי מלתא\u0004 \u0005[אם יש מי ששמע עלי דבר]\u0006 שעשיתי שלא כדין — \u0003לימא\u0004 \u0005[שיאמר].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הכי שמיע לן, דלא יהיב מר שבישא לאריסיה\u0004 \u0005[כך שמענו, שאין אדוני נותן זמורות\u0006 הגפנים לאריסו], שהאריס המעבד את שדהו של בעל הבית מקבל חלק מסויים מן היבול, ובתוך חלק זה מקבל הוא גם חלק בזמורות הגפנים שמזמרים בכל שנה, ועל רב הונא שמעו שאינו נותן לאריס את חלקו בזמורות.","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מי קא שביק לי מידי מיניה\u0004 \u0005[האם משאיר הוא לי משהו ממנו,\u0006 מן היבול\u0005]?\u0006 \u0003הא קא גניב\u0004 \u0005[\u0006ו\u0005הלא גונב הוא]\u0006 \u0003ליה כוליה\u0004 \u0005[\u0006את \u0005כולו]!\u0006 ומכיון שכן הריני רק מחזיר לעצמי את החלק שגנב ממני האריס.","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 כפתגם עממי: \u0003\"בתר גנבא גנוב, וטעמא טעים\"\u0004 \u0005[לאחר הגנב גנוב, ו\u0006את \u0005הטעם טעם]\u0006 שאף אם גונב אתה מן הגנב, טעם גניבה הינך טועם בכל זאת, וגם אם אין בדבר עבירה, דרך גניבה היא, ומי שגדול מחביריו נענש אף על כך. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003קבילנא\u0004 \u0005[מקבל אני]\u0006 \u0003עלי דיהיבנא ליה\u0004 \u0005[שאני נותן לו]\u0006 מעתה, את חלקו הראוי לו. ומאחר ששב רב הונא, החזיר לו הקדוש ברוך הוא את הפסדו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003הדר חלא והוה חמרא\u0004 \u0005[חזר החומץ ו\u0006הפך \u0005להיות יין].\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003אייקר חלא, ואיזדבן בדמי דחמרא\u0004 \u0005[התייקר החומץ, ונמכר בדמי יין].\u0006","וחוזרים לענין תפילה, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 משמו של התנא \u0003אבא בנימין\u0004 שהיה \u0003אומר: על שני דברים הייתי מצטער כל ימי\u0004 — \u0003על תפלתי שתהא לפני מטתי, ועל מטתי שתהא נתונה בין צפון לדרום.\u0004 דברים אלה צריכים בירור. על מה שאמר אבא בנימין \u0003\"על תפלתי שתהא לפני מטתי\",\u0004 השאלה היא: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"לפני מטתי\"? אילימא\u0004 \u0005[אם נאמר]\u0006 שהכוונה היא \u0003\"לפני מטתי\" ממש,\u0004 שהיה עומד לפני מטתו ומתפלל — קשה לקבל זאת, שכן \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רב יהודה, אמר רב, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יהושע בן לוי: מנין למתפלל שלא יהא דבר חוצץ בינו לבין הקיר\u0004 — \u0003שנאמר: \"ויסב חזקיהו פניו אל הקיר ויתפלל\"\u0004 (ישעיהו לח, ב) שיוכל להתרכז בתפילה, ומדוע התפלל אבא בנימין דווקא לפני מטתו? אלא \u0003לא תימא\u0004 \u0005[אל תאמר,\u0006 תפרש\u0005]\u0006 \u0003\"לפני מטתי\"\u0004 במובן המקום, \u0003אלא אימא\u0004 \u0005[אמור]\u0006 \u0003\"סמוך למטתי\",\u0004 במובן הזמן. שהקפיד לסמוך זמן קריאת שמע ותפילה של ערבית לזמן לכתו לישון (ר\"ח).","ומה שאמר אבא בנימין \u0003\"ועל מטתי שתהא נתונה בין צפון לדרום\",\u0004 מאחר ששכינה מצויה בין מזרח ומערב, שהוא כיוון המקדש, שקודש הקודשים שבו במערב והשער הראשי בו במזרח, ולכך הקפידו חכמים על כמה וכמה דברים שיש בהם משום גנאי שלא לעשותם בכיוון מזרח ומערב. ואבא בנימין היה נזהר גם שהמיטה שהוא שוכב בה לא תהא בין מזרח למערב.","ובשבח הדבר הוסיפו לדבר חכמים את מה ש\u0003אמר ר' חמא בר' חנינא, אמר ר' יצחק: כל הנותן מטתו בין צפון לדרום הויין ליה\u0004 \u0005[יש לו,\u0006 יהיו לו] בשכר זה \u0003בנים זכרים,\u0004 ורמז לדבר זה — ממה \u0003שנאמר: \"וצפונך תמלא בטנם ישבעו בנים\u0004 והניחו יתרם לעולליהם\" (תהלים יז, יד), ללמדנו שהנותן מטתו לכיוון צפון (\"צפונך\" = \"צפונך\"), שכרו — \"ישבעו בנים\".","\u0003רב נחמן בר יצחק\u0004 הוסיף ו\u0003אמר: אף אין אשתו\u0004 ההרה \u0003מפלת נפלים.\u0004 ומנין לנו כן — שהרי \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"וצפונך תמלא בטנם\", וכתיב התם\u0004 \u0005[ונאמר שם\u0006 בהריונה של רבקה\u0005]:\u0006 \u0003\"וימלאו ימיה ללדת והנה תומים בבטנה\"\u0004 (בראשית כה, כד), ו\"תמלא בטנם\" מתפרש איפוא כהריון ללא תקלות.","ועוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 מדברי אבא בנימין בהלכות תפילה. \u0003אבא בנימין אומר: שנים שנכנסו להתפלל\u0004 בבית הכנסת השוכן מחוץ לעיר. \u0003וקדם אחד מהם להתפלל,\u0004 שסיים את תפילתו לפני חבירו, \u0003ולא המתין את חברו\u0004 עד שיסיים את תפילתו. \u0003ויצא\u0004 מבית הכנסת והשאיר את חבירו לבדו בבית הכנסת. וחבירו שנשאר לבדו מפחד, ותפילתו מטורפת בלא הכוונה הראויה — נענש הוא ש\u0003טורפין לו תפלתו בפניו,\u0004 שאינה מתקבלת, וכאילו משליכים אותה בחזרה בפניו (תר\"י). ורמז לדבר — ממה \u0003שנאמר: \"טרף נפשו באפו הלמענך תעזב ארץ\u0004 ויעתק צור ממקומו\" (איוב יח, ד), שמי שעזב את חבירו לבדו, הריהו \"טורף נפשו באפו\" — גורם לכך שיטרפו \"נפשו\" — תפלתו, שפיכת נפשו לפני ה' — ב\"אפו\", בפניו. שכביכול אומר לו ה': הסבור אתה כי \"למענך\", כלומר, בשלך, בשביל שיצאת, \"תעזב ארץ\", שיעזוב את הארץ ולא יאזין לדברי החבר הממשיך להתפלל?","\u0003ולא עוד, אלא שגורם לשכינה שתסתלק מישראל, שנאמר\u0004 בהמשכו של הפסוק: \"ויעתק צור ממקמו\", כלומר, שהצור, ה', הולך ממקומו. \u0003וראיה לדבר שאין \"צור\" אלא הקדוש ברוך הוא,\u0004 ממה \u0003שנאמר: \"צור ילדך תשי\u0004 ותשכח אל מחוללך \u0003\" (דברים לב, יח).\u0004","\u0003ואם המתין לו\u0004 לחבירו בבית הכנסת \u0003מה שכרו?\u0004 שעל שכר קיום המצוה להיות מרובה לפחות כגודל עונשו של העבריין?"],["על כך \u0003אמר ר' יוסי בר' חנינא: זוכה לברכות הללו, שנאמר: \"לוא הקשבת למצותי ויהי כנהר שלומך וצדקתך כגלי הים. ויהי כחול זרעך וצאצאי מעיך\u0004 כמעותיו, לא יכרת ולא ישמד שמו מלפני\" (ישעיה מח, יח–יט). וכך הוא מפרש: אילו הקשבת למצוותי, ו\"מצוה\" מתפרש מלשון צוות = חבורה, כלומר, אם אתה נעשה צוות לחברך ואינך עוזבו בשעת התפילה — יתקיימו בך כל הברכות הכתובות בהמשכו של הפסוק (תר\"י).","ועוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אבא בנימין אומר: אלמלי נתנה רשות לעין לראות\u0004 — \u0003אין כל בריה יכולה לעמוד מפני המזיקין,\u0004 שכה רבים הם ומצויים בכל מקום, ולא היה אדם מסוגל להמשיך לחיות את חייו הרגילים, אילו היה רואה אותם.","וכעין הדברים הללו \u0003אמר אביי: אינהו נפישי מינן, וקיימי עלן כי כסלא לאוגיא\u0004 \u0005[הם,\u0006 המזיקים, \u0005מרובים מאתנו,\u0006 בני האדם, \u0005ועומדים עלינו כתלוליות העפר שמסביב לחפירות התלמים].\u0006","\u0003אמר רב הונא: כל חד וחד מינן, אלפא משמאליה ורבבתא מימיניה\u0004 \u0005[כל אחד ואחד מאתנו\u0006 בני האדם, \u0005אלף\u0006 מזיקים נמצאים \u0005משמאלו, ורבבה מימינו],\u0006 והרי זה כעין ביאור לכתוב \"יפול מצדך אלף ורבבה מימינך אליך לא יגש\" (תהלים צא, ז) שה' מגן על האדם מפני כל אותם המזיקים.","כעין סיכום על פעולות המזיקים \u0003אמר רבא: האי דוחקא דהוי\u0004 \u0005[אותו דוחק המצוי]\u0006 \u0003ב\"כלה\" \u0004(התכנסות ללימוד תורה) — \u0003מנייהו\u0004 \u0005[מהם,\u0006 מן המזיקים\u0005]\u0006 הוא בא, שאם לא כן מדוע כה צר המקום ב\"כלה\"? \u0003הני ברכי דשלהי\u0004 \u0005[אותן ברכיים המתעייפות]\u0006 — \u0003מנייהו\u0004 \u0005[מהם]\u0006 הן נגרמות, אף שלכאורה לא התאמץ האדם עד כדי כך. \u0003הני מאני דרבנן דבלו\u0004 \u0005[אותם בגדי החכמים הבלים]\u0006 — \u0003מחופיא דידהו\u0004 \u0005[מחיכוכם שלהם,\u0006 של המזיקים\u0005]\u0006 הם בלים, שהרי אין החכמים עסוקים במלאכה הגורמת לבליית הבגדים, ומשום מה יתבלו? \u0003הני כרעי דמנקפן\u0004 \u0005[אותן רגלים הנפצעות במכשולים]\u0006 — \u0003מנייהו\u0004 \u0005[מהם].\u0006","\u0003האי מאן דבעי למידע להו\u0004 \u0005[מי שרוצה לדעת אותם,\u0006 על קיומם] \u0003לייתי קיטמא נהילא, ונהדר אפורייה, ובצפרא חזי כי כרעי דתרנגולא\u0004 \u0005[יביא אפר מנופה, ויפזר סביב למטתו, ובבוקר יראה כעין רגלי תרנגול],\u0006 שרגלי השדים הינם כעין רגלי תרנגולים. \u0003האי מאן דבעי למחזינהו\u0004 \u0005[מי שרוצה לראותם],\u0006 \u0003ליתי שילייתא דשונרתא אוכמתא בת אוכמתא בוכרתא בת בוכרתא, וליקליה בנורא, ולשחקיה, ולימלי עיניה מניה, וחזי להו\u0004 \u0005[יביא שליית חתולה שחורה בת שחורה, בכורה בת בכורה, וישרפנה באש, וישחקנה,\u0006 וישים \u0005וימלא עיניו ממנה, ו\u0006כך \u0005יראה אותם].\u0006 וצריך הוא להיזהר באותו אפר, \u0003ו\u0004לכן \u0003לשדייה בגובתא דפרזלא, ולחתמיה בגושפנקא דפרזלא, דילמא גנבי מניה, ולחתום פומיה\u0004 \u0005[וישימנה בשפופרת ברזל, ויחתמנה בחותם ברזל, שמא יגנבו ממנו,\u0006 המזיקים, \u0005ויחתום פיה]\u0006 של השפופרת, \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ליתזק\u0004 \u0005[ינזק]\u0006 ואכן, \u0003רב ביבי בר אביי עבד הכי, חזא ואתזק\u0004 \u0005[עשה כן, ראה, והוזק],\u0006 \u0003בעו רבנן רחמי עליה, ואתסי\u0004 \u0005[בקשו חכמים רחמים עליו, ונרפא].\u0006","ועוד \u0003תניא\u0004 \u0005[שנוייה\u0006 ברייתא\u0005],\u0006 \u0003אבא בנימין אומר: אין תפלה של אדם נשמעת\u0004 כראוי \u0003אלא בבית הכנסת, שנאמר\u0004 בתפילת שלמה במקדש: \"ופנית אל תפלת עבדך ואל תחינתו, ה' אלהי, \u0003לשמע אל הרנה ואל התפלה\u0004 אשר עבדך מתפלל לפניך היום\" (מלכים א ח, כח). ובהמשך הכתוב נאמר \"לשמוע אל התפלה אשר יתפלל עבדך אל המקום הזה\" (מלכים א ח, כט) הרי שתפילתו של אדם נשמעת בבית המקדש, ובבית הכנסת שהוא מקדש מעט (הריא\"ף). וכך יש להבין, \u0003במקום רנה,\u0004 כלומר, בבית הכנסת שבו מרננים בציבור בשבחי ה' — \u0003שם תהא תפלה,\u0004 שהוא המקום הראוי לתפילה.","וכעין ביאור לדברי אבא בנימין בזה \u0003אמר רבין בר רב אדא, אמר ר' יצחק: מנין שהקדוש ברוך הוא מצוי בבית הכנסת\u0004 — \u0003שנאמר: \"אלהים נצב בעדת אל\u0004 בקרב אלהים ישפוט\" (תהלים פב, א) ו\"עדת אל\" היא המקום המיועד בו קהל ה' נועדים לשבחו, וה' מצוי (נצב) בעדתו.","\u0003ו\u0004מפסוק זה למדים: \u0003מנין לעשרה שמתפללין\u0004 בכל מקום \u0003ששכינה עמהם\u0004 —מאותו פסוק \u0003שנאמר: \"אלהים נצב בעדת אל\",\u0004 כי המספר הקטן ביותר של \"עדה\" הריהו עשרה (שהוא ה\"מנין\" לתפילה), ומבטיח איפוא הכתוב כי כאשר מצויה עדה של עשרה אנשים העומדים בתפילה לה', שכינתו מצויה שם.","\u0003ומנין לשלשה שיושבין בדין ששכינה עמהם, שנאמר\u0004 בהמשכו של הכתוב: \"בקרב אלהים ישפט\", ו\"אלהים\" בפסוק זה משמעו (כמו בשמות כב, ז–ח) — דיינים, שהם לפחות שלושה, הרי שבין הדיינים העוסקים בדין נמצא ה' והוא המסייע להם בהוצאת דין אמת.","\u0003ומנין לשנים שיושבין ועוסקין בתורה ששכינה עמהם\u0004 — \u0003שנאמר: \"אז נדברו יראי ה' איש אל רעהו ויקשב ה'\u0004 וישמע ויכתב ספר זכרון לפניו ליראי ה' ולחושבי שמו\" (מלאכי ג, טז), שאם נדברים שנים מיראי ה' איש אל רעהו, שכינת ה' מצויה שם, והוא מקשיב לדבריהם.","על האמור בכתוב זה שואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"ולחושבי שמו\"? אמר רב אשי:\u0004 אם \u0003חשב אדם לעשות מצוה, ונאנס, ולא עשאה\u0004 — \u0003מעלה עליו הכתוב כאילו עשאה,\u0004 והוא מ\"חושבי שמו\" שבכתוב.","ולהמשך דברי רבין בר רב אדא: \u0003ומנין שאפילו אחד שיושב ועוסק בתורה ששכינה עמו\u0004 — \u0003שנאמר: \"בכל המקום אשר אזכיר את שמי אבוא אליך וברכתיך\"\u0004 (שמות כ, כא), לאמור: אפילו אדם אחד הגורם להזכרת שם ה', שהוא כינוי לתורה (עיון יעקב) — בא אליו ה' ומברכו.","ושואלים: \u0003וכי מאחר\u0004 ש\u0003אפילו חד\u0004 \u0005[אחד]\u0006 העוסק בתורה שכינה עמו, \u0003תרי מבעיא\u0004 \u0005[שניים נצרכה]\u0006 לומר לנו ששכינה עמהם?! ומשיבים: בכל זאת קיים הבדל, \u0003תרי\u0004 \u0005[שניים]\u0006 — \u0003מכתבן מלייהו\u0004 \u0005[נכתבים דבריהם]\u0006 \u0003בספר הזכרונות,\u0004 וכפי שנאמר: \"ויכתב ספר זכרון\" (מלאכי ג, טז), \u0003חד\u0004 \u0005[אחד]\u0006 \u0003לא מכתבן מליה\u0004 \u0005[נכתבים דבריו]\u0006 \u0003בספר הזכרונות.\u0004","ומוסיפים לשאול: \u0003וכי מאחר\u0004 ש\u0003אפילו תרי\u0004 \u0005[שניים]\u0006 העוסקים בתורה שכינה עמהם, \u0003תלתא מבעיא\u0004 \u0005[שלושה נצרכה]\u0006 לומר ששכינה עמהם?! ומשיבים: שאף כאן יש צורך במקרא מיוחד, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003דינא שלמא בעלמא\u0004 \u0005[דין עשיית שלום בלבד]\u0006 \u0003הוא, ולא אתיא\u0004 \u0005[באה]\u0006 \u0003שכינה,\u0004 שאפשר לחשוב שהמשפט הוא רק מכשיר בידי אזרחי המדינה לייצב את שלום התושבים, והיושבים בדין אין מעלתם כלומדי תורה, על כן \u0003קמשמע לן דדינא נמי היינו\u0004 \u0005[השמיע לנו שדין הריהו גם כן]\u0006 \u0003תורה.\u0004","ושואלים עוד: \u0003וכי מאחר\u0004 ש\u0003אפילו תלתא\u0004 \u0005[שלשה]\u0006 שורה שכינה עמהם, \u0003עשרה מבעיא\u0004 \u0005[נצרכה]\u0006 לומר ששכינה שרויה עימם?! ומשיבים: \u0003עשרה\u0004 — \u0003קדמה\u0004 \u0005[מקדימה]\u0006 ה\u0003שכינה ואתיא\u0004 \u0005[ובאה],\u0006 שמשמעות הכתוב \"אלהים נצב בעדת אל\" — שה' נצב ועומד כבר כשבאה העדה להתפלל. ואילו \u0003תלתא\u0004 \u0005[שלושה]\u0006 — אין השכינה שורה עמהם \u0003עד דיתבי\u0004 \u0005[שיושבים]\u0006 הדיינים ודנים במשפט, שאז \"בקרב אלהים ישפוט\", גם הקדוש ברוך הוא המסייע עמהם, אך אינו מקדים וממתין לבואם.","ועוד מאמר אגדה \u0003אמר ר' אבין בר רב אדא, אמר ר' יצחק: מנין שהקדוש ברוך הוא מניח תפילין\u0004 — \u0003שנאמר: \"נשבע ה' בימינו ובזרוע עזו\"\u0004 (ישעיהו סב, ח), כיון שדרך הנשבע להישבע בחפץ של קדושה, יש לפרש כי \"ימינו\" ו\"זרוע עוזו\" שבהם נשבע ה' מרמזים לחפצי—קדושה,","\u0003\"בימינו\"\u0004 — \u0003זו תורה, שנאמר\u0004 בתיאור מתן תורה: \u0003\"מימינו אש דת למו\"\u0004 (דברים לג, ב), \u0003ו\u0004אילו \u0003\"זרוע עזו\"\u0004 שביד שמאל — \u0003אלו תפילין, שנאמר: \"ה' עז לעמו יתן\"\u0004 (תהלים כט, יא).","ומפרשים: ה' יתן לעמו את מצות התפילין, המוסיפה להם עוז. \u0003ומנין שהתפילין עוז הם לישראל\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וראו כל עמי הארץ כי שם ה' נקרא עליך ויראו ממך\"\u0004 (דברים כח, י). \u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר הגדול אומר: אלו תפילין שבראש\u0004 ששם ה' כתוב עליהם, ובהם מתקיים כפשוטו \"כי שם ה' נקרא עליך\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרב חייא בר אבין: הני\u0004 \u0005[אותם]\u0006 \u0003תפילין דמרי עלמא\u0004 \u0005[של רבון העולם]\u0006 \u0003מה כתיב בהו\u0004 \u0005[כתוב בהם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חייא בר אבין,\u0004 כתוב בהם: \u0003\"ומי כעמך ישראל גוי אחד בארץ\"\u0004 (דברי הימים א יז, כא). כלומר, שבתפילין של הקדוש ברוך הוא שעל ידם כביכול הוא מתקשר וזוכר את עולמו, התמצית היא — ישראל.","ומוסיף רב נחמן בר יצחק לשאול: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003משתבח קודשא בריך הוא בשבחייהו\u0004 \u0005[הקדוש ברוך הוא בשבחם]\u0006 של \u0003ישראל?\u0004 משיב לו רב חייא בר אבין: \u0003אין\u0004 \u0005[כן],\u0006 כן הוא הדבר, וכן מבואר הדבר בשני פסוקים הסמוכים זה לזה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"את ה' האמרת היום\u0004 להיות לך לאלהים וללכת בדרכיו ולשמור חוקיו ומצוותיו ומשפטיו ולשמוע בקולו\". \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וה' האמירך היום\u0004 להיות לו לעם סגולה כאשר דבר לך ולשמור כל מצוותיו\" (דברים כו, יז–יח), וצירוף פסוקים אלו, משמעו — \u0003אמר להם הקדוש ברוך הוא לישראל: אתם עשיתוני חטיבה אחת בעולם,\u0004 שייחדתם אותי, כמציאות נבדלת, כדבר מיוחד, החטוב לעצמו, שאין עוד כמוהו (יה\"ג), \u0003ו\u0004כגמול \u0003אני אעשה אתכם חטיבה אחת בעולם\u0004 שתהיו עם סגולה — בשל בחירתכם בה'.","\u0003אתם עשיתוני חטיבה אחת בעולם, שנאמר\u0004 שישראל מייחדים את ה' באמרם: \u0003\"שמע ישראל ה' אלהינו ה' אחד\"\u0004 (דברים ו, ד), \u0003ו\u0004כגמול \u0003אני אעשה אתכם חטיבה אחת בעולם,\u0004 שמייחד ומרומם את ישראל, באומרו: \u0003\"ומי כעמך ישראל גוי אחד בארץ\". הרי שהקדוש ברוך הוא משתבח בישראל, ולכן כתוב שבחם ב\"תפילין של רבון העולם\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: תינח בחד ביתא\u0004 \u0005[נוח\u0006 ומובן הדבר לגבי \u0005בית אחד]\u0006 שבתפילין, ואולם \u0003בשאר בתי מאי\u0004 \u0005[\u0006ה\u0005בתים מה\u0006 כתוב בהם\u0005]?\u0006 שהלא בתפילין של ראש ישנם ארבעה בתים, ובכל אחד מהם פרשיה אחרת העוסקת בשבח הבורא. ומה איפוא כתוב בענין שבחם של ישראל בשאר הבתים בתפילין שלו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: גם בשאר הבתים כתוב שבחם של ישראל, \u0003\"כי מי גוי גדול\u0004 אשר לו אלהים קרובים אליו, כה' אלוהינו בכל קראנו אליו\" (דברים ד, ז), \u0003\"ומי גוי גדול\u0004 אשר לו חוקים ומשפטים צדיקים ככל התורה הזאת אשר אני נותן לפניכם היום\" (דברים ד, ח), \u0003\"אשריך ישראל\u0004 מי כמוך עם נושע בה' מגן עזרך ואשר חרב גאותך ויכחשו אויביך לך ואתה על במותימו תדרוך\u0003\"\u0004 (דברים לג, כט), \u0003\"או הנסה אלהים\u0004 לבוא לקחת לו גוי מקרב גוי במסות באותיות ובמופתים \u0003\" וגו' (דברים ד, לד), \"ולתתך עליון\u0004 על כל הגויים אשר עשה לתהלה ולשם ולתפארת ולהיותך עם קדוש לה' אלהיך כאשר דיבר\" (שם כו, יט).","ומקשה רב אחא בנו של רבא מצד אחר: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 הלא \u0003נפישי להו טובי בתי\u0004 \u0005[מרובים הם הבתים\u0006 בתפילין \u0005הרבה],\u0006 יותר מארבעה פסוקי שבח. \u0003אלא,\u0004 כך יש לסדר את הפרשיות הללו בתפילין של בורא העולם: \u0003\"כי מי גוי גדול\" \"ומי גוי גדול\" דדמיין להדדי\u0004 \u0005[שדומים זה לזה]\u0006 — נמצאים \u0003בחד ביתא\u0004 \u0005[בבית אחד]\u0006 בתפילין, \u0003\"אשריך ישראל\" \"ומי כעמך ישראל\"\u0004 — \u0003בחד ביתא\u0004 \u0005[בבית אחד],\u0006 \u0003\"או הנסה אלהים\"\u0004 — \u0003בחד ביתא\u0004 \u0005[בבית אחד],\u0006 \u0003\"ולתתך עליון\"\u0004 — \u0003בחד ביתא\u0004 \u0005[בבית אחד].\u0006"],["וזה בתפילין של ראש שבהם ארבעה בתים נפרדים, \u0003ו\u0004אולם בתפילין של יד שאין בהם אלא בית אחד \u0003כולהו כתיבי באדרעיה\u0004 \u0005[כולם כתובים\u0006 בתפילין \u0005בזרועו],\u0006 בהמשך אחד.","ועוד \u0003אמר רבין בר רב אדא, אמר ר' יצחק: כל הרגיל לבא לבית הכנסת ולא בא יום אחד, הקדוש ברוך הוא משאיל בו,\u0004 כביכול, לברר מה אירע לו, \u0003שנאמר: \"מי בכם ירא ה' שמע בקול עבדו אשר הלך חשכים ואין נגה לו,\u0004 יבטח בשם ה' וישען באלהיו\" (ישעיהו נ, י), לאמור: ה' שואל כביכול, \"מי בכם ירא ה'\" מלבוא להיות \"שומע בקול עבדו\", שהוא שליח הציבור העוסק בעבודת ה' \"אשר הלך חשכים\", שהשכים בבוקר עוד לפני זמן התפילה.","אזי \u0003אם לדבר מצוה הלך,\u0004 הרי אף שהוא הולך בחושך — \u0003נוגה לו,\u0004 שאור המצוה מגן עליו, \u0003ואם לדבר הרשות,\u0004 לדברים שאינם של מצוה, \u0003הלך,\u0004 ונמנע משום כך מלהתפלל בבית הכנסת — \u0003אין נוגה לו\u0004 גם כאשר יאיר היום (מהרש\"א).","\u0003\"יבטח בשם ה'\" מאי טעמא\u0004 \u0005[מה הטעם]\u0006 להקפדה זו עליו? — \u0003משום דהוה ליה\u0004 \u0005[שהיה לו]\u0006 \u0003לבטוח בשם ה'\u0004 שלא יינזק אם יאחר בסידור ענייניו כדי להתפלל, \u0003ו\u0004הוא \u0003לא בטח.\u0004","ובאותו ענין \u0003אמר ר' יוחנן: בשעה שהקדוש ברוך הוא בא בבית הכנסת, ולא מצא בה עשרה\u0004 בני אדם — \u0003מיד הוא כועס, שנאמר: \"מדוע באתי ואין איש קראתי ואין עונה...\u0004 הן בגערתי אחריב ים אשים נהרות מדבר\" (ישעיה נ, ב).","על צד אחר של הקביעות בתפילה \u0003אמר ר' חלבו, אמר רב הונא: כל הקובע מקום לתפלתו\u0004 — \u0003אלהי אברהם בעזרו,\u0004 שהתפילה לה' הריהי כעבודת המקדש, ודרך כבוד הוא שיקבע לו מקום בו יהא נוהג לעבוד את עבודת הקודש הזו (הריא\"ף), והעושה כן — אלהי אברהם בעזרו, לפי שנוהג בכך מנהג חסידות כדרך אברהם אבינו.","\u0003וכשמת\u0004 אותו אדם שנהג במנהג זה, \u0003אומרים לו\u0004 (עליו): \u0003\"אי עניו, אי חסיד, מתלמידיו של אברהם אבינו\".\u0004 שמי שהיה מקפיד בקביעת מקום תפילתו, מן הסתם בכל דרכיו הריהו מתלמידי אברהם אבינו — עניו וחסיד (הריא\"ף).","וכאן המקום לשאול: \u0003ואברהם אבינו מנא לן\u0004 \u0005[מנין לנו]\u0006 ש\u0003קבע מקום\u0004 לתפילתו? ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וישכם אברהם בבקר אל המקום אשר עמד שם\u0004 את פני ה'\" (בראשית יט, כח) \u0003ואין\u0004 משמעות לשון \u0003\"עמידה\" אלא תפלה, שנאמר: \"ויעמד פינחס ויפלל\"\u0004 (תהלים קו, ל).","ועוד \u0003אמר ר' חלבו, אמר רב הונא: היוצא מבית הכנסת אל יפסיע פסיעה גסה\u0004 (פסיעות גדולות), לפי שנראה כבורח משם. \u0003אמר אביי\u0004 לפרש את דברי רב הונא: \u0003לא אמרן\u0004 \u0005[אמרנו],\u0006 לא נקבעה הלכה זו, \u0003אלא למיפק\u0004 \u0005[לצאת]\u0006 מבית הכנסת, שיש גנאי מיוחד ביציאה בפסיעה גסה מבית הכנסת, נוסף על כך שכרגיל אין לאדם ללכת בפסיעה גסה. \u0003אבל למיעל\u0004 \u0005[להיכנס]\u0006 — \u0003מצוה למרהט\u0004 \u0005[לרוץ],\u0006 שמותר ואף מצוה למהר בריצה לשם (הריא\"ף), \u0003שנאמר:\u0004 \"ונדעה \u0003נרדפה לדעת את ה'\"\u0004 (הושע ו, ג), שהנכנס במרוצה לבית הכנסת מראה בעצמו שהוא ממהר ולהוט ללכת אחרי ה'.","ומעין דברי אביי \u0003אמר ר' זירא: מריש כי הוה חזינא להו לרבנן דקא רהטי לפרקא בשבתא\u0004 \u0005[בראשונה, כאשר הייתי רואה אותם את החכמים שהם רצים לדרשה\u0006 של הרב \u0005בשבת],\u0006 \u0003אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003\"קא מחליין רבנן שבתא\"\u0004 \u0005[מחללים הם החכמים שבת],\u0006 שאסור לפסוע פסיעה גסה בשבת, משום כבוד השבת. \u0003כיון דשמענא להא\u0004 \u0005[ששמעתי את\u0006 ההלכה \u0005הזאת]\u0006 של \u0003ר' תנחום\u0004 ש\u0003אמר\u0004 בשם \u0003ר' יהושע בן לוי: לעולם ירוץ אדם לדבר הלכה ואפילו בשבת, שנאמר: \"אחרי ה' ילכו כאריה ישאג\"\u0004 (שם יא, י), כלומר, במהירות ובלי להתעכב כאילו היה ארי מאחריו (ברכת ה'), מאז \u0003אנא נמי רהיטנא\u0004 \u0005[אני גם כן רץ].\u0006","והוסיף ו\u0003אמר ר' זירא: אגרא דפרקא\u0004 \u0005[שכר הדרשה]\u0006 — \u0003רהטא\u0004 \u0005[הריצה],\u0006 לפי שרוב השומעים אינם מבינים יפה את עצם דברי החכם הדורש, ועיקר שכרם הוא בריצתם מתוך כוונה טובה לשמוע דברי תורה.","ובסגנון דברי ר' זירא \u0003אמר אביי: אגרא\u0004 \u0005[שכר]\u0006 ה\u0003כלה\u0004 (התכנסות ציבורית ללימוד תורה) — \u0003דוחקא\u0004 \u0005[הדוחק],\u0006 שעקב ריבוי הקהל קשה ללמוד שם, ועיקר השכר הוא בשל הדחקותם של השומעים לקלוט בכל זאת משהו מפי הדורש.","ובאותו סגנון \u0003אמר רבא: אגרא דשמעתא\u0004 \u0005[שכר השמועה],\u0006 דברי הלכה של האמוראים — \u0003סברא\u0004 \u0005[הסברה],\u0006 שעיקר השכר בלימוד התלמוד אינו בידיעת פסק ההלכה, כי אם בסברה שמוציא הוא מהם.","ו\u0003אמר רב פפא: אגרא דבי טמיא\u0004 \u0005[שכר\u0006 השהיה \u0005בבית האבל]\u0006 — \u0003שתיקותא\u0004 \u0005[השתיקה],\u0006 שהיא הדרך העיקרית שבה מבטאים המנחמים את השתתפותם בצערו של המתאבל.","\u0003אמר מר זוטרא: אגרא דתעניתא\u0004 \u0005[שכר התענית]\u0006 — \u0003צדקתא\u0004 \u0005[הצדקה],\u0006 שעיקר השכר בתענית הוא בכך שנותנים אז צדקה לעניים (ועיין ישעיהו נח).","ו\u0003אמר רב ששת: אגרא דהספדא\u0004 \u0005[שכר ההספד]\u0006 — \u0003דלויי\u0004 \u0005[הרמת קול בוכים],\u0006 שעל ידי זה מתעוררים השומעים לבכי ולצער על הנפטר.","ו\u0003אמר רב אשי: אגרא דבי הלולי\u0004 \u0005[שכר החתונה]\u0006 — \u0003מילי\u0004 \u0005[דברים],\u0006 שעיקר השכר אשר מקבלים המשתתפים בשמחת החתונה הוא במילים הטובות שאומרים לבני הזוג.","ושוב חוזרים לענין דרך הכבוד לבית הכנסת. \u0003אמר רב הונא: כל המתפלל אחורי בית הכנסת נקרא \"רשע\",\u0004 שכן כל הקהל פונה לצד אחד בעת התפילה, והוא מפנה פניו מבית הכנסת ומתפלל לצד אחר, ונראה כמבזה את בית הכנסת ואת המתפללים בו. ורמז לדבר — ממה \u0003שנאמר: \"סביב רשעים יתהלכון\u0004 כרום זולות לבני אדם\" (תהלים יב, ט), כלומר, \"סביב\" לבית הכנסת רק \"רשעים יתהלכון\".","\u0003אמר אביי: לא אמרן\u0004 \u0005[אמרנו]\u0006 קביעת הלכה זו \u0003אלא\u0004 באופן שהוא \u0003לא מהדר אפיה לבי כנישתא\u0004 \u0005[מחזיר פניו ל\u0006כיוון \u0005בית הכנסת],\u0006 \u0003אבל\u0004 כאשר הוא \u0003מהדר אפיה לבי כנישתא\u0004 \u0005[מחזיר פניו לבית הכנסת]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור.","ולחיזוק חומר האיסור מובא מעשה: \u0003ההוא גברא דקא מצלי\u0004\u0005 [אדם אחד היה מתפלל]\u0006 \u0003אחורי בי כנישתא\u0004 \u0005[בית הכנסת],\u0006 \u0003ולא מהדר אפיה לבי כנישתא\u0004 \u0005[היה מחזיר פניו לבית הכנסת].\u0006 \u0003חלף\u0004 \u0005[עבר]\u0006 שם \u0003אליהו\u0004 הנביא. \u0003חזייה\u0004 \u0005[ראהו]\u0006 אותו אדם, \u0003אידמי ליה כטייעא\u0004 \u0005[נדמה לו כערבי],\u0006 \u0003אמר ליה\u0004 \u0005לו]\u0006 אליהו לאותו אדם: \u0003כדו בר קיימת קמי מרך\u0004 \u0005[כך אתה עומד לפני אדונך]?!\u0006 \u0003שלף ספסרא וקטליה\u0004 \u0005[חרב והרגו],\u0006 ללמדנו כמה חמורה עבירה זו.","מאחר שדרש רב הונא את הפסוק \"סביב רשעים יתהלכון\" שסיומו \"כרום זולות לבני אדם\", מבררים את משמעות המילים הללו. \u0003אמר\u0004 (שאל ) \u0003ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מרבנן\u0004 \u0005[אחד החכמים]\u0006 ל\u0003רב ביבי בר אביי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003רב ביבי\u0004 הוא ששאל את \u0003רב נחמן בר יצחק: מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"כרם זלת לבני אדם\"?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אלו דברים שעומדים ברומו של עולם,\u0004 מצוות או תפילה (\"רום\") \u0003ובני אדם מזלזלין בהן (\"זולות לבני אדם\").\u0004","\u0003ר' יוחנן ור' אלעזר\u0004 תלמידו \u0003דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 פירוש אחר לכך: \u0003כיון שנצטרך אדם לבריות,\u0004 ובכך מזדלזל כבודו בפניהם (\" זולות לבני אדם\") — \u0003פניו משתנות ככרום, שנאמר: \"כרם זלת לבני אדם\".\u0004","ואולם עדיין יש להבין \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"כרום\"\u0004 זה שדובר בו? \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: עוף אחד יש בכרכי הים, ו\"כרום\" שמו, וכיון שחמה זורחת\u0004 הריהו \u0003מתהפך לכמה גוונין.\u0004 וכן גם מי שמזדקק לבריות פניו מסמיקות ומחוירות מבושה.","\u0003ר' אמי ור' אסי דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 המזדקק לבריות \u0003כאלו נדון בשני דינים, אש ומים, שנאמר: \"הרכבת אנוש לראשנו באנו באש ובמים\"\u0004 (תהלים סו, יב)","ועוד \u0003אמר ר' חלבו, אמר רב הונא: לעולם יהא אדם זהיר בתפלת המנחה, שהרי אליהו לא נענה אלא בתפלת המנחה, שנאמר: \"ויהי בעלות המנחה ויגש אליהו הנביא ויאמר\u0004 ה' אלהי אברהם יצחק וישראל היום יוודע כי אתה אלהים בישראל ואני עבדך ובדברך עשיתי את כל הדברים האלה. \u0003ענני ה' ענני\u0004 וידעו העם הזה כי אתה ה' האלהים\" וגו' (מלכים א יח, לו–לז), ומאחר שנענה בה אליהו, ודאי שיש בה חשיבות מיוחדת.","בדרך אגב מסבירים מדוע הוצרך לכפול ולומר \"ענני ה' ענני\". וכך מפרשים: \u0003\"ענני\"\u0004 פעם אחת — \u0003שתרד אש מן השמים,\u0004 כפי שביקש. \u0003ו\"ענני\"\u0004 בפעם השנית — \u0003שלא יאמרו\u0004 ישראל \u0003מעשי כשפים הם,\u0004 אלא יקבלו עליהם את האמונה בה' בשלמותה.","הוסיף \u0003ר' יוחנן\u0004 ו\u0003אמר: אף בתפלת ערבית\u0004 יש להיזהר, \u0003שנאמר: \"תכון תפלתי קטרת לפניך משאת כפי מנחת ערב\"\u0004 (תהלים קמא, ב). \u0003רב נחמן בר יצחק אמר: אף תפלת שחרית\u0004 ראויה לזהירות יתירה, \u0003שנאמר: \"ה' בקר תשמע קולי, בקר אערך לך ואצפה\"\u0004 (שם ה, ד).","\u0003ו\u0004עוד \u0003אמר ר' חלבו, אמר רב הונא: כל הנהנה מסעדת חתן ואינו משמחו\u0004 — \u0003עובר בחמשה קולות, שנאמר: \"קול ששון וקול שמחה קול חתן וקול כלה קול אומרים הודו את ה' צבאות\u0004 כי טוב ה' כי לעולם חסדו, מביאים תודה בית ה', כי אשיב את שבות הארץ כבראשונה אמר ה'\u0003\"\u0004 (ירמיה לג, יא). שחמישה קולות אלה בענין שמחת חתן וכלה, מכוונים כנגד הקולות של מתן תורה, שכן בשיר השירים נרמז מתן תורה בכינוי \"יום חתונתו\", ומי שאינו משמח את החתן עובר על קולות מתן תורה (ריא\"ף, מהרש\"א).","\u0003ואם משמחו מה שכרו? אמר ר' יהושע בן לוי: זוכה לתורה שנתנה בחמשה קולות, שנאמר: \"ויהי ביום השלישי בהית הבקר ויהי קלת וברקים וענן כבד על ההר וקל שופר\" וגו'\u0004 (שמות יט, טז), ומיעוט \"קולות\" הוא שניים. ובנוסף נאמר \"וקול שופר\", הרי שלושה. ועוד נאמר במתן תורה \u0003\"ויהי קול השפר\u0004 הולך וחזק מאד משה ידבר \u0003והאלהים יעננו בקול\"\u0004 (שם שם, יט), הרי שני קולות נוספים (\"קול השופר\" ו\"יעננו בקול\"), ועולה איפוא מספר הקולות הנאמרים במתן תורה לחמישה.","ושואלים: \u0003איני\u0004 \u0005[האם כן הוא]?\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 גם \u0003\"וכל העם רואים את הקולות\u0004 ואת הלפידים ואת קול השופר\" וגו' (שמות כ, יח), ואם כן נזכרים במתן תורה קולות נוספים!","ומשיבים: \u0003אותן קולות,\u0004 של \u0003קודם מתן תורה הוו\u0004 \u0005[היו],\u0006 ואינם נמנים בחשבון הקולות האמורים שהיו במהלך מתן התורה.","\u0003ר' אבהו אמר:\u0004 שכר המשמח את החתן הוא \u0003כאילו הקריב\u0004 קרבן \u0003תודה\u0004 במקדש, \u0003ש\u0004כן \u0003נאמר\u0004 בפסוק זה שבירמיה: \u0003\"מבאים תודה בית ה'\".\u0004 ו\u0003רב נחמן בר יצחק אמר:\u0004 כל המשמח את החתן נחשב לו \u0003כאילו בנה אחת מחורבות ירושלים, ש\u0004כן \u0003נאמר\u0004 באותו פסוק: \u0003\"כי אשיב את שבות הארץ כבראשנה אמר ה'\".\u0004","\u0003ו\u0004עוד \u0003אמר ר' חלבו, אמר רב הונא: כל אדם שיש בו יראת שמים\u0004 — \u0003דבריו נשמעים, שנאמר: \"סוף דבר הכל נשמע את האלהים ירא\u0004 ואת מצוותיו שמור כי זה כל האדם\" (קהלת יב, יג), המתפרש: \"סוף דבר הכל נשמע\" — לדברים של מי שהוא \"את האלקים ירא ואת מצוותיו שמור\".","על סיומו של פסוק זה שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"כי זה כל האדם\"?\u0004 אמר ר' אלעזר, כי \u0003אמר הקדוש ברוך הוא\u0004 על אדם כזה: \u0003כל העולם כלו לא נברא אלא בשביל זה.\u0004 ואם כן, \"זה\" אדם זה שהוא מושלם, הוא התכלית של \"כל האדם\", שכל העולם לא נברא אלא בשבילו.","\u0003ר' אבא בר כהנא אמר: שקול זה כנגד כל העולם כולו,\u0004 והריהו לעצמו ממש נחשב כ\"כל האדם\", שכל בני האדם יחד שקולים הם כנגדו. \u0003ר' שמעון בן עזאי אומר, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' שמעון בן זומא אומר:\u0004 לא רק שהוא שקול כנגד כל העולם, אלא שכל העולם, כולו לא נברא אלא לצוות (לחברה) \u0003לזה,\u0004 למענו וכטפל אליו, \u0003שתהא לו חברה שיוכל להיות בצוותא עימה.\u0004","\u0003ו\u0004עוד \u0003אמר ר' חלבו, אמר רב הונא: כל שיודע בחברו שהוא רגיל ליתן לו שלום,\u0004 לא זו בלבד שחייב להחזיר לו שלום, אלא אף \u0003יקדים לו\u0004 ליתן \u0003שלום, שנאמר: \"בקש שלום ורדפהו\"\u0004 (תהלים לד, טו) — להקדים ברכתו של רעהו. \u0003ואם נתן לו\u0004 חבירו שלום \u0003ולא החזיר\u0004 — \u0003נקרא \"גזלן\", שנאמר: \"ואתם בערתם הכרם גזלת העני בבתיכם\"\u0004 (ישעיה ג, יד), שהדרך היחידה לגזול את העני, שאין לו אלא כבודו העצמי, היא כשאין עונים לו על ברכתו."],["ועוד בעניינים אלה, \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' יוסי: מנין שהקדוש ברוך הוא מתפלל? שנאמר: \"והביאותים אל הר קדשי ושמחתים בבית תפלתי\"\u0004 (ישעיהו נו, ז), \u0003\"בית תפלתם\" לא נאמר, אלא \"בית תפלתי\", מכאן שהקדוש ברוך הוא מתפלל\u0004.","ועל כך שואלים: \u0003מאי מצלי\u0004 \u0005[מה\u0006 הוא \u0005מתפלל],\u0006 מה אומר הוא בתפילתו, ולאן היא פונה?","\u0003אמר רב זוטרא בר טוביה, אמר רב,\u0004 כך אומר הוא: \u0003\"יהי רצון מלפני שיכבשו רחמי את כעסי\u0004 על עם ישראל בשל חטאיו, \u0003ויגולו רחמי על מדותי\u0004 שעל פיהן משלם ה' מדה כנגד מדה (אבודרהם), \u0003ואתנהג עם בני\u0004 (עם ישראל) \u0003במדת\u0004 ה\u0003רחמים, ואכנס להם לפנים משורת הדין\".\u0004","וכעין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' ישמעאל בן אלישע\u0004 הכהן הגדול: \u0003פעם אחת,\u0004 ביום כיפורים אחד, \u0003נכנסתי להקטיר קטורת לפני ולפנים\u0004 בבית קודש הקדשים, \u0003וראיתי\u0004 בחזון את \u0003אכתריאל יה ה' צבאות\u0004 שהוא אחד משמותיו של הקדוש ברוך הוא המבטאים את שלטונו העליון, \u0003שהוא יושב על כסא רם ונשא\u0004 (עיין ישעיהו ו׳:א׳), \u0003ואמר לי: \"ישמעאל בני, ברכני\"! אמרתי לו\u0004 כנוסח תפילתו: \u0003\"יהי רצון מלפניך, שיכבשו רחמיך את כעסך, ויגולו רחמיך על מדותיך, ותתנהג עם בניך במדת הרחמים, ותכנס להם לפנים משורת הדין\". ונענע לי\u0004 הקדוש ברוך הוא \u0003בראשו,\u0004 כמרוצה מן הברכה הזו. \u0003וקמשמע לן\u0004 \u0005[והשמיע לנו]\u0006 חידוש בפרטי המעשה בזה, ש\"נענע לו הקדוש ברוך הוא בראשו\" \u0003שלא תהא ברכת הדיוט קלה בעיניך,\u0004 שהרי ה' עצמו מבקש מהאדם שיברכנו, כל שכן אדם לאדם.","ועוד בענינים אלה, \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' יוסי: מנין שאין מרצין לו לאדם\u0004 ומנסים לפייס אותו \u0003בשעת כעסו,\u0004 אלא מרצים אותו לאחר שירגע מכעסו — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 כאשר בקש משה השראת השכינה מחדש על ישראל, לאחר חטא העגל, אמר לו הקדוש ברוך הוא: \u0003\"פני ילכו והנחתי לך\"\u0004 (שמות לג, יד), וכך הוא מפרשו, \u0003אמר לו הקדוש ברוך הוא למשה: המתן לי עד שיעברו פנים של זעם\u0004 (\"פני\" של כעס \"ילכו\"), \u0003ואניח לך,\u0004 ואמלא את בקשתך. ואף באדם יש להמתין עד שיעבור כעסו.","על כך שואלים: \u0003ומי איכא רתחא קמיה דקודשא בריך הוא\u0004 \u0005[והאם יש כעס לפני הקדוש ברוך הוא]?\u0006 האפשר לדבר על המושג \"כעס\" אצל ה'?","ועונים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דתניא\u0004 \u0005[\u0006כפי \u0005ששנינו\u0006 בברייתא\u0005]\u0006 שנאמר \"אלהים שופט צדק \u0003ואל זעם בכל יום\"\u0004 (תהלים ז, יב), הרי שיש זעם לפניו.","\u0003וכמה\u0004 משך \u0003זעמו\u0004 — \u0003רגע. וכמה\u0004 זמן הוא \u0003רגע\u0004 — \u0003אחד מחמשת רבוא ושמונת אלפים ושמנה מאות ושמנים ושמנה בשעה, וזו היא רגע.\u0004 ומוסיף: \u0003ואין כל בריה יכולה לכוין אותה שעה\u0004 שבה זועם הקדוש ברוך הוא, \u0003חוץ מבלעם הרשע, דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"ויודע דעת עליון\"\u0004 (במדבר כד, טז). שאין לפרש לגבי בלעם \"יודע דעת עליון\" במובן הנבואי השלם.","שכן \u0003השתא\u0004 \u0005[עכשיו]\u0006 ברור הדבר שאפילו \u0003דעת בהמתו לא הוה ידע\u0004 \u0005[היה יודע],\u0006 ואם כן \u0003דעת עליון\u0004 יכול אתה לומר כי \u0003הוה ידע\u0004 \u0005[היה יודע]?\u0006 שאם לא יכול היה לעמוד בתוכחתה של אתונו ודאי לא הגיע לידיעת \"דעת עליון\".","\u0003אלא: מלמד, שהיה יודע לכוין אותה שעה שהקדוש ברוך הוא כועס בה,\u0004 ובאותה שעה היה מקלל, ומאחר שעת זעם היא לפני ה', היתה קללתו מתקיימת.","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003נביא לישראל: \"עמי זכר נא מה יעץ בלק מלך מואב\u0004 ומה ענה אותו בלעם בן בעור מן השטים עד הגלגל למען דעת צדקות ה'\" (מיכה ו, ה). \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"למען דעת צדקות ה'\"\u0004 —","\u0003אמר ר' אלעזר,\u0004 ש\u0003אמר להם הקדוש ברוך הוא לישראל: דעו כמה צדקות עשיתי עמכם שלא כעסתי בימי בלעם הרשע, שאלמלי כעסתי\u0004 — \u0003לא נשתייר משונאיהם של ישראל\u0004 (לשון נקיה עבור ישראל) \u0003שריד ופליט.\u0004 אלא שבאותם ימים לא זעם ה' ולא יכלה קללת בלעם להתקיים.","\u0003והיינו דקאמר ליה\u0004 \u0005[וזהו שאמר לו]\u0006 \u0003בלעם לבלק: \"מה אקב לא קבה אל ומה אזעם לא זעם ה'\"\u0004 (במדבר כג, ח), \u0003מלמד\u0004 מקרא זה \u0003שכל אותם הימים לא זעם.\u0004","\u0003וכמה\u0004 משך \u0003זעמו\u0004 — \u0003רגע. וכמה\u0004 זמן הוא \u0003רגע?\u0004 על כך \u0003אמר ר' אבין ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' אבינא: רגע כמימריה\u0004 \u0005[כאמירתו],\u0006 כשיעור הזמן שנאמרת המלה \"רגע\".","\u0003ומנא לן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003רגע\u0004 בלבד ה' \u0003רתח\u0004 \u0005[כועס],? —\u0006 \u0003שנאמר: \"כי רגע באפו חיים ברצונו\"\u0004 (תהלים ל, ו). \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ראיה אחרת לדבר \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"חבי כמעט רגע עד יעבר זעם\"\u0004 (ישעיהו כו, כ), הרי שזעם ה' עובר כעבור רגע.","ושואלים: \u0003ואימת רתח\u0004 \u0005[ואימתי כועס]\u0006 הקדוש ברוך הוא? \u0003אמר אביי: בהנך תלת שעי קמייתא כי חיורא כרבלתא דתרנגולא וקאי אחד כרעא\u0004 \u0005[באותן שלוש שעות ראשונות\u0006 של היום כאשר מלבינה כרבולת התרנגול ועומד על רגל אחת], שבבעלי חיים ניכרת שעת הזעם כשנראה שהחיים מסתלקים מהם, והם מחווירים לפתע.","ושואלים: \u0003כל שעתא ושעתא נמי קאי הכי\u0004 \u0005[שעה ושעה גם כן\u0006 הוא \u0005עומד כך]\u0006 ומה סימן הוא זה?","ומשיבים: יש הבדל, שכן \u0003כל שעתא\u0004 \u0005[שעה]\u0006 — \u0003אית ביה שורייקי סומקי\u0004 \u0005[יש בה,\u0006 בכרבולת, \u0005חוטים אדומים,\u0006 שלא החווירו לגמרי\u0005],\u0006 ואילו \u0003בההיא שעתא\u0004 \u0005[באותה שעה]\u0006 שהקדוש ברוך הוא כועס \u0003לית ביה שורייקי סומקי\u0004 \u0005[אין בה חוטים אדומים].\u0006","ומסופר: \u0003ההוא מינא דהוה בשבבותיה\u0004 \u0005[אותו מין שהיה בשכנותו]\u0006 של \u0003ר' יהושע בן לוי, הוה קא\u0004 \u0005[\u0006ו\u0005היה הוא,\u0006 אותו מין\u0005]\u0006 \u0003מצער ליה טובא בקראי\u0004 \u0005[אותו הרבה בכתובים],\u0006 שהיה מטריד את ר' יהושע בן לוי בכפירתו ובעיוות המקראות. \u0003יומא חד שקל תרנגולא\u0004 \u0005[יום אחד לקח\u0006 ר' יהושע בן לוי \u0005תרנגול],\u0006 \u0003ואוקמיה בין כרעיה דערסא, ועיין ביה\u0004 \u0005[והעמידו בין רגלי המטה\u0006 שהיה יושב עליה \u0005והסתכל בה],\u0006 \u0003סבר\u0004 \u0005[חשב]:\u0006 \u0003כי מטא ההיא שעתא, אלטייה\u0004 \u0005[כאשר תבוא אותה שעה\u0006 של זעם, \u0005אקללנו]\u0006 ואפטר ממנו. \u0003כי מטא ההיא שעתא\u0004 \u0005[כאשר באה אותה שעה]\u0006 — \u0003ניים\u0004 \u0005[נרדם],\u0006 ועבר הזמן. \u0003אמר\u0004 ר' יהושע בן לוי לעצמו: \u0003שמע מיניה\u0004 \u0005[למד ממנה],\u0006 ממה שנרדמתי כי \u0003לאו אורח ארעא למעבד הכי\u0004 \u0005[אין\u0006 זה מנהג \u0005דרך ארץ לעשות כן],\u0006 שאין ראוי לקלל אנשים ואפילו הם חוטאים. שכן \u0003\"ורחמיו על כל מעשיו\"\u0004 (תהלים קמה, ט) \u0003כתיב\u0004 \u0005[נאמר],\u0006 אף על הרשעים.","וגם אין ראוי לאדם להיות הגורם להענשת אחר, שכן \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"גם ענוש לצדיק לא טוב\"\u0004 (משלי יז, כו), שאף הצדיק לא טוב שיעניש בני אדם.","ו\u0003תנא\u0004 \u0005[שנויה\u0006 תוספתא\u0005]\u0006 בביאור הטעם לזעמו של ה', \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' מאיר: בשעה שהחמה זורחת, וכל מלכי מזרח ומערב מניחים כתריהם בראשיהם ומשתחוים לחמה, מיד כועס הקדוש ברוך הוא.\u0004 ומאחר שדבר זה קורה בשעות הראשונות של כל יום, הרי שבאותו זמן זועם הקדוש ברוך הוא על עולמו.","\u0003ו\u0004עוד \u0003אמר ר' יוחנן משום ר' יוסי: טובה מרדות\u0004 (יסורים, חרטה) \u0003אחת בלבו של אדם יותר מכמה מלקיות\u0004 שמלקים אותו אחרים, כאשר אינו חש בלבו את הדברים. וראיה לדבר מדברי הנביא, \u0003שנאמר: \"ורדפה את מאהביה\u0004 ולא תשיג אותם ובקשתם ולא תמצא \u0003ואמרה אלכה ואשובה אל אישי הראשון כי טוב לי אז מעתה\"\u0004 (הושע ב, ט), ומועיל הדבר יותר מכמה עונשים הכתובים בפרק זה (שם יא—טו). \u0003וריש לקיש אמר\u0004 והוסיף, שמן הכתובים נראה שמרדות שבלב טובה \u0003יותר ממאה מלקיות, שנאמר: \"תחת גערה במבין מהכות כסיל מאה\"\u0004 (משלי יז, י).","\u0003ואמר ר' יוחנן משום ר' יוסי\u0004 להסביר בהרחבה את בקשת משה באותה התגלות: \u0003שלשה דברים בקש משה מלפני הקדוש ברוך הוא\u0004 באותו מעמד, \u0003ונתן לו. בקש שתשרה שכינה על ישראל\u0004 ולא תעזבם, \u0003ונתן לו, שנאמר:\u0004 \"ובמה יודע אפוא כי מצאתי חן בעיניך אני ועמך \u0003הלוא בלכתך עמנו\u0004 ונפלינו אני ועמך מכל העם אשר על פני האדמה\" (שמות לג, טז), ו\"הלוא בלכתך עמנו\" משמעו — השראת השכינה על ישראל.","\u0003בקש שלא תשרה שכינה על אומות העולם, ונתן לו, שנאמר: \"ונפלינו אני ועמך\u0004 מכל העם אשר על פני האדמה\" (שם) על ידי השראת השכינה.","ועוד \u0003בקש להודיעו דרכיו של הקדוש ברוך הוא\u0004 בהנהגת העולם, \u0003ונתן לו, שנאמר: \"הודיעני נא את דרכיך\u0004 ואדעך\" (שם יג), שרצה משה להבין את סודות הנהגת העולם, ו\u0003אמר לפניו: רבונו של עולם! מפני מה יש צדיק וטוב לו, ויש צדיק ורע לו, יש רשע וטוב לו, ויש רשע ורע לו? אמר לו\u0004 הקדוש ברוך הוא: \u0003משה,\u0004 טעם הדבר הוא: \u0003צדיק וטוב לו\u0004 — \u0003צדיק בן צדיק\u0004 המקבל שכר גם בשל צדקת אבותיו. \u0003צדיק ורע לו\u0004 — \u0003צדיק בן רשע,\u0004 שמקבל עונש אבותיו. \u0003רשע וטוב לו\u0004 — \u0003רשע בן צדיק,\u0004 המקבל שכר בשל צדקת אבותיו. \u0003רשע ורע לו\u0004 — \u0003רשע בן רשע,\u0004 המקבל עונש גם בשל רשעות אבותיו.","ודנים בהרחבה בענין זה, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003צדיק וטוב לו\u0004 — \u0003צדיק בן צדיק, צדיק ורע לו\u0004 — \u0003צדיק בן רשע.\u0004 על כך מקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 וכי נענש הבן תמיד בעוון אבותיו? \u0003והא כתיב\u0004 \u0005[והרי\u0006 במקום אחר \u0005נאמר]:\u0006 \u0003\"פקד עון אבות על בנים\u0004 ועל בני בנים, על שלשים ועל רבעים\" (שמות לד, ז), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפסוק אחר: \"לא יומתו אבות על בנים \u0003ובנים לא יומתו על אבות\u0004 איש בחטאו יומתו\" (דברים כד, טז), \u0003ורמינן קראי אהדדי\u0004 \u0005[והשלכנו,\u0006 הקשינו את ה\u0005כתובים זה על זה],\u0006","\u0003ומשנינן\u0004 \u0005[ותירצנו]:\u0006 \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שנאמר שה' מעניש את הבנים בעוון אבותיהם — הרי זה רק \u0003כשאוחזין מעשה אבותיהם בידיהם, והא\u0004 \u0005[וזה],\u0006 הכתוב השני שאין הבן נענש בעון האב — הרי זה \u0003כשאין אוחזין מעשה אבותיהם בידיהם,\u0004 כלשון הכתוב \"פוקד עון אבות על בנים על שלשים ועל רבעים לשונאי\" (שמות כ, ה). הרי שאין צדיק נענש בעוון אביו הרשע.","\u0003אלא, הכי קאמר ליה\u0004 \u0005[כך אמר לו]\u0006 הקדוש ברוך הוא למשה כשהסביר לו את דרכיו: \u0003צדיק וטוב לו\u0004 — \u0003צדיק גמור,\u0004 שכל מעשיו טובים הם, וגמולו כולו טוב, בעולם הזה ובעולם הבא. \u0003צדיק ורע לו\u0004 — \u0003צדיק שאינו גמור,\u0004 שמאחר שיש בידו מיעוט עבירות, נפרעים ממנו בעולם הזה, כדי שיהא ראוי לחיי העולם הבא. וכן \u0003רשע וטוב לו\u0004 — \u0003רשע שאינו גמור,\u0004 שעל מיעוט הזכויות שבידו משלם לו ה' בעולם הזה, שלא יהא זכאי לקבל שכר בעולם הבא, ואולם \u0003רשע ורע לו\u0004 — \u0003רשע גמור,\u0004 שכיון שאין בידו מצוות — כל ימיו רעים (מהרש\"א).","\u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על דעת \u0003ר' מאיר,\u0004 ש\u0003אמר ר' מאיר: שתים נתנו לו ואחת לא נתנו לו,\u0004 שמילא הקדוש ברוך הוא שתים מבקשותיו של משה, והבטיחו שתשרה שכינה על ישראל ושלא תשרה על אומות העולם. ואולם לא הודיעו את דרכי הנהגתו, \u0003ש\u0004בתשובת ה' למשה \u0003נאמר: \"וחנתי את אשר אחן\u0004 ורחמתי את אשר ארחם\" (שם לג, יט), שמשמעו שה' חונן על פי דרכו לכל אדם \u0003אף על פי שאינו הגון,\u0004 שלעיני האדם אינו נראה כראוי לחנינה, וכן \u0003\"ורחמתי את אשר ארחם\"\u0004 — \u0003אף על פי שאינו הגון.\u0004 ולדעת ר' מאיר, אפילו למשה רבינו לא נתגלה סוד דרכי ההשגחה. ומוסיפים להביא עוד מאמרי חכמים בביאור מקראות הצריכים הבהרה באותו ענין.","על מאמר ה' למשה \u0003\"ויאמר לא תוכל לראות את פני\u0004 כי לא יראני האדם וחי\" (שם שם, כ), \u0003תנא משמיה\u0004 \u0005[שנה\u0006 חוזר המשניות משמו] של \u0003ר' יהושע בן קרחה, כך אמר לו הקדוש ברוך הוא למשה: כשרציתי\u0004 להראותך את כבודי בסנה — \u0003לא רצית,\u0004 וכפי שנאמר: \"ויסתר משה פניו כי ירא מהביט אל אלהים\" (שם ג, ו), על כן \u0003עכשיו שאתה רוצה,\u0004 שכן בקשת \"הראני נא את כבודך\" — \u0003איני רוצה.\u0004 שדן ר' יהושע בן קרחה לחובה את הימנעות משה רבינו להביט אל כבוד ה' כשה' מתגלה אליו, וחפץ בקרבתו.","\u0003ופליגא\u0004 \u0005[חלוקה]\u0006 דעה זו על דברי \u0003ר' שמואל בר נחמני\u0004 ש\u0003אמר\u0004 משמו של \u0003ר' יונתן,\u0004 ש\u0003אמר ר' שמואל בר נחמני, אמר ר' יונתן: בשכר שלש זכה לשלש,\u0004 דווקא בגלל ענוות משה שהסתיר פניו זכה לכל הגילויים הגדולים.","\u0003בשכר \"ויסתר משה פניו\u0004 כי ירא מהביט אל האלהים\" — \u0003זכה\u0004 מדה כנגד מדה \u0003לקלסתר פנים,\u0004 שיהיו פניו מאירות. \u0003בשכר \"כי ירא\"\u0004 — \u0003זכה ל\"וייראו מגשת אליו\"\u0004 (שם לד, ל). \u0003בשכר\u0004 שנמנע \u0003\"מהביט\"\u0004 — \u0003זכה ל\"ותמנת ה' יביט\"\u0004 (במדבר יב, ח).","ומה ראה משה? על כך נאמר \u0003\"והסרתי את כפי וראית את אחרי\u0004 ופני לא יראו\" (שמות לג, כג). \u0003אמר רב חנא בר ביזנא, אמר ר' שמעון חסידא\u0004 \u0005[החסיד],\u0006 את הדימוי הזה \"וראית את אחורי\" יש לבאר כך: \u0003מלמד שהראה הקדוש ברוך הוא למשה קשר של תפילין\u0004 שכן קשר התפילין נמצא מאחורי הראש, וכבר נאמר שהקדוש ברוך הוא מניח תפילין.","\u0003ו\u0004עוד בקשר לנושא זה \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' יוסי: כל דבור ודבור שיצא מפי הקדוש ברוך הוא לטובה,\u0004 שהבטיח טוב לאדם או לאומה, ו\u0003אפילו\u0004 היתה הבטחה זו \u0003על תנאי\u0004 וכאפשרות בלבד, ולא כהבטחה מוחלטת — \u0003לא חזר בו\u0004 מהבטחה זו, וסופה שהיא מתקיימת.","\u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 שכן הדבר — \u0003ממשה רבינו, ש\u0004כן \u0003נאמר\u0004 במשה שהבטיחו \u0003\"הרף ממני ואשמידם\u0004 ואמחה את שמם מתחת השמים \u0003ואעשה אותך לגוי עצום\u0004 ורב ממנו\" (דברים ט, יד). ו\u0003אף על גב דבעא\u0004 \u0005[אף על פי שביקש]\u0006 \u0003משה רחמי עלה דמלתא ובטלה\u0004 \u0005[רחמים על הדבר ובטלו]\u0006 ולא נתקיימה הגזירה בישראל, \u0003אפילו הכי\u0004 \u0005[כך] —\u0006 \u0003אוקמה בזרעיה\u0004 \u0005[קיימה בזרעו],\u0006 שזרעו של משה נעשה \"גוי עצום ורב ממנו\" — מששים ריבוא של ישראל במדבר. \u0003שנאמר:\u0004 ברשימות יחס הלויים \u0003\"בני משה גרשום ואליעזר. ויהיו בני אליעזר רחביה הראש\u0004 ולא היו לאליעזר בנים אחרים \u0003ובני רחביה רבו למעלה\"\u0004 (דברי הימים א, כג, טו–יז)","\u0003ותני\u0004 \u0005[ושנה]\u0006 \u0003רב יוסף\u0004 ברייתא: \u0003\"למעלה\"\u0004 — \u0003מששים רבוא,\u0004 ודבר זה נלמד בדרך הגזירה השווה, \u0003אתיא\u0004 \u0005[באה]\u0006 מלימוד והשוואה של \u0003\"רביה\" \"רביה\".\u0004 שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"רבו למעלה\", וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"ובני ישראל פרו וישרצו וירבו\u0004 ויעצמו במאד מאד ותמלא הארץ אותם\" (שמות א, ז), וכשם שבני ישראל במצרים היו ששים רבוא, כן גם \"רבו למעלה\" שבבני רחביה מציין שרבו למעלה משישים רבוא."],["עד כאן הובאו דברים שאמר ר' יוחנן בשם התנא ר' יוסי, ומעתה מביאים מה ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: מיום שברא הקדוש ברוך הוא את העולם, לא היה אדם שקראו להקדוש ברוך הוא \"אדון\",\u0004 שלא נזכר שם זה, \u0003עד שבא אברהם וקראו \"אדון\", ש\u0004כן \u0003נאמר: \"ויאמר אדני אלהים במה אדע כי אירשנה\"\u0004 (בראשית טו, ח).","זכותו זו של אברהם מוזכרת במאמר אחר, ש\u0003אמר רב: אף דניאל לא נענה\u0004 בתפילתו \u0003אלא בשביל אברהם, ש\u0004כן \u0003נאמר: \"ועתה שמע אלהינו אל תפלת עבדך ואל תחנוניו והאר פניך על מקדשך השמם למען אדני\"\u0004 (דניאל ט, יז), שלכאורה אין לשונו של פסוק זה כראוי כי \u0003\"למענך\" מבעי ליה\u0004 \u0005[צריך,\u0006 ראוי \u0005היה לו\u0006 לומר\u0005],\u0006 \"והאר פניך על מקדשך השמם למענך\".","\u0003אלא\u0004 יש בכך רמז — \u0003למען אברהם שקראך \"אדון\".\u0004 וציין דניאל שם זה, על מנת להזכיר בכך את זכות אברהם, שתעמוד לו בתפילתו.","\u0003ו\u0004עוד \u0003אמר ר' יוחנן משום ר' שמעון בן יוחי: מנין שאין מרצין לו לאדם בשעת כעסו\u0004 — \u0003שנאמר: \"פני\u0004 (=כעסי) \u0003ילכו והנחותי לך\".\u0004","\u0003ו\u0004עוד \u0003אמר ר' יוחנן משום ר' שמעון בן יוחי\u0004 בענין דומה: \u0003מיום שברא הקדוש ברוך הוא את עולמו לא היה אדם שהודה להקדוש ברוך הוא\u0004 בלשון זו של הכרת טובה ותודה, \u0003עד שבאתה\u0004 (באה) \u0003לאה והודתו, ש\u0004כן נאמר: \"ותהר עוד ותלד בן ותאמר \u0003הפעם אודה את ה'\u0004 על כן קראה שמו יהודה\" (בראשית כט, לה).","מכיון שהוזכר שמו של יהודה בן לאה, והטעם לשמו, מביאים עוד אודות שמות אחרים, ובכלל זה \u0003ראובן. אמר ר' אלעזר:\u0004 את שמו של ראובן יש לראות כדבר נבואה שיצא מפיה של לאה, שכך \u0003אמרה לאה: ראו מה בין בני לבן חמי\u0004 (אבי בעלי, יצחק. והרי זה כינוי רומז לעשו) ש\u0003אילו בן חמי, אף על גב דמדעתיה זבניה לבכירותיה\u0004 \u0005[אף על פי שמדעתו מכר את בכורתו]\u0006 לאחיו יעקב, \u0003דכתיב\u0004 \u0005[\u0006כפי \u0005שנאמר]:\u0006 \u0003\"וימכר את בכרתו ליעקב\"\u0004 (בראשית כה, לג), מכל מקום \u0003חזו\u0004 \u0005[ראו]\u0006 \u0003מה כתיב ביה\u0004 \u0005[נאמר בו]:\u0006 \u0003\"וישטם עשו את יעקב\"\u0004 (שם כז, מא), ולא רק על ברכת יצחק חרה לעשו, אלא אף על דבר אחר,","\u0003וכתיב\u0004 \u0005[וכנאמר]\u0006 קודם לכן: \u0003\"ויאמר הכי קרא שמו יעקב ויעקבני זה פעמים\u0004 את בכורתי לקח והנה עתה לקח ברכתי \" (שם שם לו), שאף על הבכורה שמכר, לא ויתר.","\u0003ואילו בני,\u0004 ראובן, \u0003אף על גב דעל כרחיה שקליה\u0004 \u0005[אף על פי שבעל כרחו לקח]\u0006 \u0003יוסף לבכירותיה מניה\u0004 \u0005[את בכורתו ממנו],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \"ובני ראובן בכור ישראל, כי הוא הבכור \u0003ובחללו יצועי אביו נתנה בכרתו לבני יוסף\u0004 בן ישראל\" (דברי הימים א ה, א) \u0003אפילו הכי\u0004 \u0005[כן]\u0006 — \u0003לא אקנא ביה\u0004 \u0005[נתקנא בו],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 כאשר רצו אחי יוסף להרגו: \u0003\"וישמע ראובן ויצלהו מידם\u0004 ויאמר לא נכנו נפש \u0003\" (בראשית לז, כא). ועוד בענייני מדרש שמות. מוזכר שמה של\u0004","\u0003רות,\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות השם \u0003\"רות\"? אמר ר' יוחנן: שזכתה ויצא ממנה דוד שריוהו להקדוש ברוך הוא בשירות ותשבחות.\u0004 ו\"רות\" משמעו: המרווה.","על עיקרם של מדרשי שמות אלה ששמו של אדם מבטא במרומז את העתיד לקרות לו, שואלים: \u0003מנא לן דשמא גרים\u0004 \u0005[מנין לנו שהשם גורם]?\u0006 \u0003אמר ר' אליעזר,\u0004 שכך \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לכו חזו מפעלות ה' אשר שם שמות בארץ\"\u0004 (תהלים מו, ט), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"שמות\" אלא \"שמות\",\u0004 והשמות הניתנים לבני אדם הלא הם \"מפעלות אלהים בארץ\".","\u0003ו\u0004עוד דברים באגדה ש\u0003אמר ר' יוחנן משום ר' שמעון בן יוחי: קשה תרבות רעה\u0004 (גידול בנים קלוקל) \u0003בתוך ביתו של אדם יותר ממלחמת גוג ומגוג\u0004 שהיא הגדולה במלחמות, ושיאם של חבלי המשיח. שכן \u0003נאמר: \"מזמור לדוד בברחו מפני אבשלום בנו\"\u0004 (תהלים ג, א), \u0003וכתיב בתריה\u0004 \u0005[ונאמר\u0006 בפסוק של \u0005אחריו]:\u0006 \u0003\"ה' מה רבו צרי רבים קמים עלי\"\u0004 (תהלים ג, ב), \u0003ואילו גבי\u0004 \u0005[אצל]\u0006 \u0003מלחמת גוג ומגוג\u0004 הרמוזה בפרק ב' בתהלים, \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"למה רגשו גוים ולאמים יהגו ריק.\u0004 יתיצבו מלכי ארץ ורוזנים נוסדו יחד על ה' ועל משיחו... יושב בשמים ישחק ה' ילעג למו\" (שם ב, ב-ד), \u0003ואילו\u0004 הלשון \u0003\"מה רבו צרי\" לא כתיב\u0004 \u0005[נאמר]\u0006 במזמור זה, שכן מלחמת גוג ומגוג אינה כה מכאיבה ומצערת כצער גידולו בבית של בן משחית כאבשלום.","על הלשון בתחילת מזמור זה, שהיא גם כותרתו, תוהים: נאמר \u0003\"מזמור לדוד בברחו מפני אבשלום בנו\", \"מזמור לדוד\"?!\u0004 וכי מה מקום יש בהזדמנות זו למזמור? והלא \u0003\"קינה לדוד\" מיבעי ליה\u0004 \u0005[צריך,\u0006 היה \u0005לו\u0006 לומר\u0005]!\u0006","על כך \u0003אמר ר' שמעון בן אבישלום: משל למה הדבר דומה?\u0004 — \u0003לאדם שיצא עליו שטר חוב,\u0004 שנדרש הוא לשלם את המלווה הכתוב בשטר. \u0003קודם שפרעו היה עצב,\u0004 מפני הדאגה אלו מכשולים יבואו לו עם פרעון השטר, ואולם \u0003לאחר שפרעו\u0004 הוא \u0003שמח.\u0004","ו\u0003אף כן\u0004 היה \u0003דוד,\u0004 כי \u0003כיון שאמר לו הקדוש ברוך הוא\u0004 על ידי נתן הנביא לאחר חטא בת שבע: \u0003\"הנני מקים עליך רעה מביתך\"\u0004 (שמואל ב יב, יא) \u0003היה\u0004 דוד \u0003עצב,\u0004 כי \u0003אמר: שמא עבד או ממזר הוא\u0004 זה שיקום מביתי, שאדם פחות שכזה \u0003לא חייס\u0004 \u0005[חס]\u0006 \u0003עלי,\u0004 וינהג באכזריות יתירה. ואולם \u0003כיון דחזא\u0004 \u0005[שראה]\u0006 דוד ש\u0003אבשלום הוא\u0004 זה שבו נתקיימה הנבואה — \u0003שמח,\u0004 שכן היה בטוח שאבשלום יחוס עליו. \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003אמר\u0004 לשון \u0003\"מזמור\",\u0004 להודות לה' שעונשו בא בדרך זו, הקלה יותר.","\u0003ו\u0004עוד \u0003אמר ר' יוחנן משום ר' שמעון בן יוחי: מותר להתגרות\u0004 (לריב) \u0003ברשעים בעולם הזה,\u0004 שאף שדרך רשעים צלחה, מותר להתגרות בהם, ואינו צריך לחשוש מפניהם (מהרש\"א), \u0003ש\u0004כן \u0003נאמר: \"עזבי תורה יהללו רשע ושמרי תורה יתגרו בם\"\u0004 (משלי כח, ד).","כעין זה \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003ר' דוסתאי בר' מתון אומר: מותר להתגרות ברשעים בעולם הזה, שנאמר: \"עזבי תורה יהללו רשע\u0004 ושומרי תורה יתגרו בם\". \u0003ואם לחשך\u0004 (ילחש לך, יאמר לך) \u0003אדם לומר\u0004 כנגד זה: \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"אל תתחר במרעים אל תקנא בעשי עולה\"\u0004 (תהלים לז, א) ומפרשו שאין לריב עם הרשעים, אף לא להיות קנאי כנגד עושי עוולה — \u0003אמור לו: מי שלבו נוקפו\u0004 (מכה אותו) מתוך פחד \u0003אומר כן. אלא\u0004 פירוש הפסוק כך הוא: \u0003\"אל תתחר במרעים\"\u0004 — אל תעשה עמם תחרות של מעשים רעים, \u0003להיות כמרעים,\u0004 ו\u0003\"אל תקנא בעשי עולה\"\u0004 — \u0003להיות כעושי עולה.\u0004","\u0003ו\u0004כראיה לפירוש המלה הכתוב \u0003אומר\u0004 במקום אחר: \u0003\"אל יקנא לבך בחטאים כי אם ביראת ה' כל היום\"\u0004 (משלי כג, יז) הרי שפירוש \"יקנא\" לענייננו הוא לרצות להיות כמרעים, ומזה מזהיר המקרא. מאימרות אלה נראה שצריך להלחם ברשעים.","ושואלים: \u0003איני\u0004 \u0005[כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יצחק: אם ראית רשע שהשעה משחקת לו\u0004 — \u0003אל תתגרה בו,\u0004 שכל עוד הכל מאיר לו פנים, ואף השעה—הזמן, שוחק לעומתו, אין סיכוי להצליח במלחמה בו, \u0003שנאמר: \"יחילו דרכיו בכל עת\u0004 מרום משפטיך מנגדו, כל צורריו יפיח בהם\" (תהלים י, ה) וכך פירושו של פסוק: \"יחילו דרכיו\" — יעשו דרכיו חיל, בכל עת. \u0003ולא עוד אלא שזוכה בדין, שנאמר: \"מרום משפטיך מנגדו\",\u0004 כלומר, שכאילו המשפט מורם עליו ואינו נוגע בו. \u0003ולא עוד אלא שרואה ב\u0004מפלת \u0003צריו, שנאמר: \"כל צורריו יפיח בהם\"!\u0004","ביישוב הסתירה מוצעים כמה הסברים: \u0003לא קשיא\u0004 \u0005[אינו קשה,\u0006 יש אפשרות להבין כך\u0005]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שיש להיזהר מלהתגרות ברשע, הרי זה \u0003במילי דידיה\u0004 \u0005[בדברים שלו,\u0006 בענייניו הפרטיים\u0005],\u0006 שגרם לו רעות, \u0003והא\u0004 \u0005[וזה]\u0006 שאמרנו שמצוה להלחם בו הרי זה \u0003במילי דשמיא\u0004 \u0005[בדברי שמים].\u0006","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003הא והא במילי דשמיא\u0004 \u0005[זה וזה\u0006 בשתי האמרות מדובר \u0005בדברי שמים],\u0006 \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 אלא יש להבחין כך: \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאין להתגרות ברשע הרי זה \u0003ברשע שהשעה משחקת לו, והא\u0004 \u0005[וזהו]\u0006 שאמרנו שמותר להתגרות ברשע הרי זה \u0003ברשע שאין השעה משחקת לו.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא\u0004 \u0005[זה וזה,\u0006 שתי האמרות\u0005]\u0006 מדברות \u0003ברשע שהשעה משחקת לו, ולא קשיא\u0004 \u0005[ואין\u0006 הדבר \u0005קשה],\u0006 אלא שחשוב לדעת מי הוא הנלחם ברשע; \u0003הא\u0004 \u0005[זה],\u0006 שאמרנו שמותר להתגרות ברשע, הרי זה \u0003בצדיק גמור\u0004 המתגרה בו, שלא יאונה לו כל רע, \u0003והא\u0004 \u0005[וזה],\u0006 שאמרנו שאין להתגרות ברשע, הרי זה \u0003בצדיק שאינו גמור.\u0004 וראיה לכך ממה ש\u0003אמר רב הונא: מאי דכתיב\u0004 \u0005[מהו שנאמר],\u0006 מה משמעות הכתוב \u0003\"למה תביט בוגדים תחריש בבלע רשע צדיק ממנו\"\u0004 (חבקוק א, יג), והדבר לכאורה תמוה, שכן \u0003וכי רשע בולע צדיק? והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \"צופה רשע לצדיק ומבקש להמיתו \u0003ה' לא יעזבנו בידו\u0004 ולא ירשיענו בהשפטו\" (תהלים לז, לב—לג), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"לא יאנה לצדיק כל און\"\u0004 (משלי יב, כא). \u0003אלא\u0004 הדגיש הכתוב ואמר \"כבלע רשע צדיק ממנו\", לומר: \u0003צדיק ממנו,\u0004 ואולם אינו צדיק מוחלט — \u0003בולע\u0004 הרשע, אך \u0003צדיק גמור\u0004 — \u0003אינו בולע.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 שהרשע יכול לבלוע את הצדיק כי \u0003שעה משחקת לו — שאני\u0004 \u0005[שונה],\u0006 שכשהשעה משחקת לו, שונים הדברים מן הרגיל, ואפילו צדיק יכול להינזק (ברכת ה').","\u0003ואמר ר' יוחנן משום ר' שמעון בר יוחי:\u0004 חשובה היא קביעת מקום לתפילה עד ש\u0003כל הקובע מקום לתפלתו\u0004 — \u0003אויביו נופלים תחתיו.\u0004 שחשובה היא קביעת מקום בתפילה, ורמז לדבר ממה \u0003שנאמר: \"ושמתי מקום לעמי לישראל ונטעתיו ושכן תחתיו\"\u0004 (שמואל ב ז, י), ועל ידי קביעת מקום זו יזכו למה שנאמר בהמשך הכתוב: \u0003\"ולא ירגז עוד ולא יסיפו בני עולה לענותו כאשר בראשונה\".\u0004 פסוק זה שהובא אגב הדרשה, שימש מקום להערה נוספת.","\u0003רב הונא רמי\u0004 \u0005[השליך\u0006 הראה סתירה\u0005]\u0006 שבספר שמואל \u0003כתיב\u0004 \u0005[נאמר]\u0006 פסוק זה הלשון \u0003\"לענותו\",\u0004 ואילו בספר דברי הימים (א יז, ט) \u0003כתיב\u0004 \u0005[נאמר]:\u0006 הלשון \u0003\"לכלותו\"\u0004 במקום \"לענותו\".","ויישב: \u0003בתחילה\u0004 — \u0003לענותו,\u0004 זו היא המחשבה הראשונה של שונאי ישראל \u0003ולבסוף\u0004 — \u0003לכלותו,\u0004 שהם מתכוונים להשמיד לגמרי את העם.","\u0003ו\u0004עוד \u0003אמר ר' יוחנן משום ר' שמעון בר יוחי: גדולה שמושה של תורה יותר מלמודה,\u0004 כלומר, לשמש את הרב ולהיות בחברתו גדול יותר מלקבל את דברי התורה שבפיו. שלימוד התורה הוא רק חלק מדרך החיים, והמשמש את הרב לומד ממעשיו כמו בדבריו את הדרך בה ילך. ולמדים זאת ממה \u0003שנאמר\u0004 בכתוב המדבר בשבח אלישע: \u0003\"פה אלישע בן שפט אשר יצק מים על ידי אליהו\"\u0004 (מלכים ב ג, יא). \u0003\"למד\"\u0004 מאליהו \u0003לא נאמר, אלא \"יצק\"\u0004 — \u0003מלמד\u0004 פסוק זה \u0003שגדולה שמושה\u0004 של תורה כיציקת מים על ידי מלמדיה \u0003יותר מלמודה,\u0004 ובגלל שימוש זה נשתבח אלישע.","בהמשך מאמרי ר' יוחנן בשם ר' שמעון בר יוחאי, מובא מעשה שעיקרו נסב על דברי ר' שמעון. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יצחק לרב נחמן: מאי טעמא לא אתי מר לבי כנישתא לצלויי\u0004 \u0005[מה הטעם אין אדוני בא לבית הכנסת להתפלל]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003לא יכילנא\u0004 \u0005[איני יכול],\u0006 משום חולשה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יצחק: \u0003לכנפי למר\u0004 \u0005[שיאספו לאדוני]\u0006 \u0003עשרה\u0004 אנשים \u0003וליצלי\u0004 \u0005[ויתפלל]\u0006 במנין בביתו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003טריחא לי מלתא\u0004 \u0005[קשה עלי הדבר]\u0006 להטריח את הציבור ולהביא את המתפללים אלי (סמ\"ג). הציע לו ר' יצחק אפשרות אחרת: \u0003ולימא ליה מר לשלוחא דצבורא, בעידנא דמצלי צבורא ליתי ולודעיה למר\u0004 \u0005[ויאמר אדוני לשליח הציבור\u0006 ש\u0005בזמן שמתפלל הציבור יבוא ויודיע לאדוני]\u0006 שיוכל להתפלל באותה שעה שהציבור מתפלל בה.","כשראה רב נחמן שר' יצחק מתאמץ למצוא דרך שיוכל להתפלל עם הציבור, שאלו: \u0003מאי כולי האי\u0004 \u0005[מה כל זה],\u0006 מה טעם להשתדלות יתירה זו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 שכך \u0003אמר ר' יוחנן משום ר' שמעון בן יוחי:\u0004"],["\u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 מה משמעות הכתוב \u0003\"ואני תפלתי לך ה' עת רצון\u0004 אלהים ברב חסדך ענני באמת ישעך\u0003\"\u0004 (תהלים סט, יד) שנראה ממקרא זה שהמתפלל מבקש שתהא תפילתו דווקא בעת מיוחדת שהיא עת רצון. \u0003אימתי\u0004 היא \u0003עת רצון\u0004 זו — \u0003בשעה שהצבור מתפללין.\u0004 שאין ה' משיב לריק פני הציבור, ולכן ראוי להשתדל להתפלל עם הציבור.","\u0003ר' יוסי בר' חנינא אמר מהכא\u0004 \u0005[מכאן],\u0006 ממקרא זה למדים אנו סגולת תפילת הרבים שהיא נענית: \u0003\"כה אמר ה' בעת רצון עניתיך\u0004 וביום ישועה עזרתיך\u0003\"\u0004 (ישעיה מט, ח).","ואילו \u0003ר' אחא בר' חנינא אמר מהכא\u0004 \u0005[מכאן]\u0006 נלמד דבר זה, שנאמר: \u0003\"הן אל כביר ולא ימאס\"\u0004 (איוב לו, ה) שהוא קורא: \"הן אל — כביר לא ימאס\", שלא ידחה ה' (\"ולא ימאס\") תפילתו של הציבור הגדול (\"כביר\"). \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"פדה בשלום נפשי מקרב לי כי ברבים היו עמדי.\u0004 ישמע אל ויענם...\" (תהלים נה, יט-כ), שהתפילה נענתה משום ש\"ברבים היו עמדי\", שעמדו יחד להתפלל.","\u0003תניא נמי הכי\u0004 \u0005[שנינו\u0006 בברייתא \u0005גם כן כך]\u0006 כדברי ראיה אחרונה זו, ובשינוי מה, \u0003ר' נתן אומר: מנין שאין הקדוש ברוך הוא מואס בתפלתן של רבים\u0004 — \u0003שנאמר: \"הן אל כביר ולא ימאס\", וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"פדה בשלום נפשי מקרב לי\u0004 כי ברבים היו עמדי \u0003\",\u0004 ולדעת ר' נתן לא דוד הוא האומר זאת על עצמו, אלא הם דברי ה' הפונה לבני אדם, וכך \u0003אמר הקדוש ברוך הוא: כל העוסק בתורה\u0004 הנקראת \"שלום\" (\"וכל נתיבותיה שלום\". משלי ג, יז), \u0003ובגמילות חסדים\u0004 אשר מעצם מהותו מביא שלום בין בני אדם, \u0003ומתפלל עם הצבור\u0004 (\"כי ברבים היו עמדי\") — \u0003מעלה אני עליו כאילו פדאני, לי ולבני, מבין אומות העולם.\u0004","ועוד בשבח התפילה ברבים, \u0003אמר ריש לקיש: כל מי שיש לו בית הכנסת בעירו,\u0004 הסמוך אליו, \u0003ואינו נכנס שם להתפלל, נקרא \"שכן רע\", שנאמר: \"כה אמר ה' על כל שכני הרעים הנגעים בנחלה אשר הנחלתי את עמי את ישראל\u0004 הנני נותשם מעל אדמתם ואת בית יהודה אתוש מתוכם\u0003\"\u0004 (ירמיה יב, יד), כלומר, אותו אדם שהינו רק נוגע ואינו נכנס אל מקום התפילה (\"נחלתי\"), הוא בכלל \"שכני הרעים\". \u0003ולא עוד אלא ש\u0004הוא נענש ש\u0003גורם\u0004 בשל כך \u0003גלות לו ולבניו, שנאמר\u0004 שם: \u0003\"הנני נתשם מעל אדמתם ואת בית יהודה אתוש מתוכם\".\u0004","ומסופר ש\u0003אמרו ליה\u0004 \u0005[לו]\u0006 החכמים \u0003לר' יוחנן: איכא סבי\u0004 \u0005[יש זקנים]\u0006 \u0003בבבל. תמה ואמר:\u0004 והלא \u0003\"למען ירבו ימיכם וימי בניכם על האדמה\u0004 אשר נשבע ה' לאבותיכם לתת להם כימי השמים על הארץ\" (דברים יא, כא) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ומשמע: \u0003אבל בחוצה לארץ\u0004 — \u0003לא,\u0004 ובזכות מה מאריכים איפוא ימים תושבי בבל? \u0003כיון דאמרי ליה\u0004 \u0005[שאמרו לו]\u0006 שבני בבל \u0003מקדמי ומחשכי לבי כנישתא\u0004 \u0005[משכימים ומעריבים לבית הכנסת],\u0006 \u0003אמר:\u0004 אם כן \u0003היינו דאהני להו\u0004 \u0005[זהו שהועיל להם].\u0006","וכדרך ש\u0003אמר ר' יהושע בן לוי לבניה\u0004 \u0005[לבניו]:\u0006 \u0003קדימו וחשיכו ועיילו לבי כנישתא, כי היכי דתורכו חיי\u0004 \u0005[השכימו והעריבו והכנסו לבית הכנסת, כך שתאריכו ימים].\u0006 ו\u0003אמר ר' אחא בר' חנינא: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המשמש מקור לדברים אלה — מה שנאמר: \u0003\"אשרי אדם שמע לי לשקד על דלתתי יום יום לשמור מזוזת פתחי\"\u0004 (משלי ח, לד), \u0003ו\u0004בענין המקיים דבר זה \u0003כתיב בתריה\u0004 \u0005[נאמר אחריו]:\u0006 \u0003\"כי מצאי מצא חיים\u0004 ויפק רצון מה'\u0003\"\u0004 (שם, לה).","ומתוך דברי כתוב זה \u0003אמר רב חסדא: לעולם יכנס אדם שני פתחים בבית הכנסת.\u0004 מאמר זה תמוה, ומיד שואלים \u0003שני פתחים\u0004 ממש \u0003סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 וכי מה יעשה אדם כשיש בבית הכנסת אך פתח אחד? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן את לשון רב חסדא, שייכנס אדם \u0003שיעור שני פתחים, ואחר כך יתפלל,\u0004 ועל ידי כך יקיים \"לשמור מזוזות פתחי\" בלשון רבים, שהם שני פתחים.","מתוך שהוזכר הפסוק \"כי מוצאי מצא חיים\", דנים עוד בביאורו. נאמר: \u0003\"על זאת יתפלל כל חסיד אליך לעת מצא\u0004 רק לשטף מים רבים אליו לא יגיעו\u0003\"\u0004 (תהלים לב, ו), ובמשמעות \"עת מצוא\" זו \u0003אמר ר' חנינא: \"לעת מצא\" זו אשה,\u0004 שהיא העת שבה צריך אדם למצוא אשה לישא אותה, ועל זאת יש לו להתפלל שימצא אשה טובה. וכפי \u0003ש\u0004אכן \u0003נאמר\u0004 הדבר בכתובים: \u0003\"מצא אשה מצא טוב\u0004 ויפק רצון מה'\u0003\"\u0004 (משלי יח, כב).","וכן נהגו לקרוא כך לנישואי אשה, כמו ש\u0003במערבא כי נסיב אינש אתתא\u0004 \u0005[במערב,\u0006 בארץ ישראל \u0005כאשר נושא אדם אשה]\u0006 \u0003אמרי ליה הכי\u0004 \u0005[אומרים לו כך]:\u0006 \u0003\"מצא או \"מוצא\"?\u0004 ששואלים אותו ברמז, מה היא האשה שנשא, האם ראוי לקרוא עליה את הפסוק המתחיל ב\u0003\"מצא\"\u0004 וכעין זה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מצא אשה מצא טוב ויפק רצון מה'\",\u0004 או שמא היא מאלו שעליהן נאמר הלשון \u0003\"מוצא\"\u0004 וכעין \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ומוצא אני מר ממות את האשה\"\u0004 (קהלת ז, כו).","ואילו \u0003ר' נתן אומר: \"לעת מצא\"\u0004 — \u0003זו תורה,\u0004 שהיא העת של חיפוש תורה, וכפי \u0003שנאמר\u0004 בפסוק המדבר בתורה: \u0003\"כי מצאי מצא חיים\",\u0004 הרי שזו היא המציאה המתבקשת.","\u0003רב נחמן בר יצחק אמר \"לעת מצא\"\u0004 — \u0003זו מיתה,\u0004 שראוי לאדם להתפלל \"לעת מצוא\", כשמוצא אותו המוות, שתהא יציאתו מן העולם בשלוה, וכפי \u0003שנאמר: \"למות תוצאות\"\u0004 (תהלים סח, כא), והריהו מפרש \"תוצאות\" ו\"מצוא\" כמלים בעלות משמעות זהה.","ומעין זה \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003תשע מאות ושלשה מיני מיתה נבראו בעולם, שנאמר: \"למות תוצאות\",\u0004 ו\u0003\"תוצאות\" בגימטריא הכי הוו\u0004 \u0005[כך הם],\u0006 תשע מאות ושלוש. ומבואר כי \u0003קשה שבכלן,\u0004 בכל דרכי המיתה — המיתה במחלת ה\u0003אסכרא, ניחא\u0004 \u0005[נוחה]\u0006 \u0003שבכלן\u0004 — מיתת \u0003נשיקה. אסכרא דמיא כחיזרא בגבבא דעמרא דלאחורי נשרא\u0004 \u0005[דומה כקוץ בגיזת צמר שלאחור\u0006 היא \u0005נושרת],\u0006 שעם הקוץ הנמשך החוצה נקרע גם הצמר עצמו, \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שהיא \u0003כפיטורי\u0004 \u0005[כחבלים]\u0006 \u0003בפי ושט,\u0004 הנכנסים בדוחק ושמשיכתם גורמת יסורים. ואילו מיתת \u0003נשיקה דמיא כמשחל בניתא מחלבא\u0004 \u0005[דומה כהוצאת שערה מחלב].\u0006 ויש לאדם להתפלל שלא תהא מיתתו קשה.","\u0003ר' יוחנן אמר: \"לעת מצא\"\u0004 — \u0003זו קבורה,\u0004 שראוי להתפלל לקבורה בכבוד ראוי. כסיוע לדבריו של ר' יוחנן \u0003אמר ר' חנינא, מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המרמז לכך — \u0003\"השמחים אלי גיל ישישו כי ימצאו קבר\"\u0004 (איוב ג, כב), הרי שישנם מצבים בהם שש אדם אל מציאת קבר שבו ינוח גופו. ו\u0003אמר רבה בר רב שילא, היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 כפתגם עממי: \u0003ליבעי אינש רחמי\u0004 \u0005[יבקש אדם רחמים]\u0006 על עצמו \u0003אפילו עד זיבולא בתרייתא שלמא\u0004 \u0005[\u0006השלכת רגבי עפר ב\u0005מעדר אחרון\u0006 בקבורתו \u0005שיהיה בשלום]\u0006","\u0003מר זוטרא אמר: \"לעת מצא\"\u0004 — \u0003זה בית הכסא.\u0004 שמאחר שלא היתה מערכת לניקוז מי השופכים ברוב המקומות, חייב היה אדם ליפנות לצרכיו במרחק מן העיר. ואי הנעימות ואף חשש הבזיון שבדבר גורמים שיראה אדם במציאת מקום מתאים \"עת מצוא\". \u0003אמרי במערבא\u0004 \u0005[אמרו במערב,\u0006 בארץ ישראל\u0005]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 דרך הפירוש של \u0003מר זוטרא עדיפא מכלהו\u0004 \u0005[עדיפה מכולן],\u0006 שכן מפורש במקרא שבית הכסא נקרא \"מוצא\" (ראה מלכים ב י, כז) (רא\"מ הורוביץ).","ושוב לנושא המרכזי של המסכת, בית הכנסת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרפרם בר פפא: לימא לן מר מהני מילי מעלייתא\u0004 \u0005[יאמר לנו אדוני מאותם דברים מעולים]\u0006 ש\u0003אמרת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב חסדא במילי דבי כנישתא\u0004 \u0005[בענייני בית הכנסת].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רפרם, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב חסדא: מאי דכתיב\u0004 \u0005[מהו שנאמר],\u0006 מה משמעות הכתוב \u0003\"אוהב ה' שערי ציון מכל משכנות יעקב\"\u0004 (תהלים פז, ב) יש לפרש: \u0003אוהב ה' שערים המצויינים בהלכה\u0004 (שהם \"שערי ציון\" — המיוחדים, הבולטים) \u0003יותר מבתי כנסיות ומבתי מדרשות,\u0004 אשר אף שהם המעולים ב\"משכנות יעקב\", מכל מקום אינם עסוקים בהלכה.","\u0003והיינו\u0004 \u0005[ו\u0006רעיון \u0005זה]\u0006 על ערכה העליון של התורה הביע ו\u0003אמר ר' חייא בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: מיום שחרב בית המקדש\u0004 אשר בו היתה השראת ה' בעולם \u0003אין לו להקדוש ברוך הוא בעולמו\u0004 מקום התגלות \u0003אלא ארבע אמות של\u0004 (שעוסקים בהן) ב\u0003הלכה בלבד.\u0004 ממאמר זה הוציאו אף מסקנות מעשיות.","\u0003ואמר אביי: מריש הוה גריסנא בגו ביתא, ומצלינא בבי כנישתא\u0004 \u0005[בראשונה הייתי לומד בתוך הבית,\u0006 בביתי, \u0005ומתפלל בבית הכנסת].\u0006 \u0003כיון דשמענא להא\u0004 \u0005[ששמעתי\u0006 שמועה \u0005זו]\u0006 ש\u0003אמר ר' חייא בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא\u0004 ש\u0003מיום שחרב בית המקדש אין לו להקדוש ברוך הוא בעולמו אלא ארבע אמות של הלכה בלבד,\u0004 ומתוך זה הבנתי את חשיבות ארבע אמות של הלכה, \u0003לא הוה מצלינא\u0004 \u0005[הייתי מתפלל]\u0006 \u0003אלא היכא דגריסנא\u0004 \u0005[במקום שהייתי לומד].\u0006","וכן מסופר כי \u0003ר' אמי ור' אסי אף על גב דהוו להו תליסר בי כנישתא\u0004 \u0005[אף על פי שהיו להם שלושה עשר בתי כנסת]\u0006 \u0003בטבריא לא מצלו\u0004 \u0005[התפללו]\u0006 \u0003אלא ביני עמודי, היכא דהוו גרסי\u0004 \u0005[בין העמודים, במקום שהיו לומדים].\u0006","\u0003ו\u0004עוד \u0003אמר ר' חייא בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: גדול הנהנה מיגיעו יותר מירא שמים\u0004 שיושב ובטל ממלאכה ומשתעשע ביראתו לה', ש\u0003אילו גבי\u0004 \u0005[אצל]\u0006 \u0003ירא שמים כתיב\u0004 \u0005[נאמר]\u0006 בכתוב \u0003\"אשרי איש ירא את ה'\u0004 במצותיו חפץ מאד\u0003\"\u0004 (תהלים קיב, א) \u0003ואילו גבי\u0004 \u0005[אצל]\u0006 ה\u0003נהנה מיגיעו כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"יגיע כפיך כי תאכל אשריך וטוב לך\"\u0004 (שם קכח, ב), ומפרשים: \u0003\"אשריך\"\u0004 — \u0003בעולם הזה, \"וטוב לך\"\u0004 — \u0003לעולם הבא, ולגבי\u0004 \u0005[ואצל]\u0006 \u0003ירא שמים\u0004 כתוב אמנם הלשון \"אשרי\", אך \u0003\"וטוב לך\" לא כתיב ביה\u0004 \u0005[נאמר בו].\u0006","\u0003ו\u0004עוד \u0003אמר ר' חייא בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: לעולם ידור אדם במקום רבו,\u0004 שעל ידי כך ימנע מעבירות. שכן מוצאים אנו \u0003שכל זמן ששמעי בן גרא\u0004 (שלפי המסורת היה הוא גדול בתורה ורבו של שלמה. ראה גיטין נט, א) היה \u0003קיים, לא נשא שלמה את בת פרעה,\u0004 לפי שכן במקרא, רק לאחר שמסופר על המתת שמעי (מלכים א ב׳:כ״ז), מסופר על נישואי שלמה לבת פרעה (תחילת פרק ג).","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003אל ידור\u0004 אדם במקום רבו!","ועונים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרו שידור אדם במקום רבו הרי זה באופן \u0003דכייף ליה\u0004 \u0005[ש\u0006הוא \u0005כפוף לו]\u0006 לרבו, ויעשה כפי שיורנו ואז טוב שידור עמו, ו\u0003הא\u0004 \u0005[זה]\u0006 שאמרו שלא ידור במקום רבו, הרי זה באופן \u0003דלא כייף ליה\u0004 \u0005[שאינו כפוף לו]\u0006 ויבוא לעשות קטטה עם רבו. ומן הדברים הללו שבים שנית אל הנושא המרכזי, בית הכנסת.","\u0003אמר רב הונא בר יהודה, אמר ר' מנחם, אמר ר' אמי: מאי דכתיב\u0004 \u0005[מהו שנאמר],\u0006 כיצד מתפרש הלכה למעשה הכתוב \u0003\"ועוזבי ה' יכלו\"\u0004 (ישעיהו א, כח) — \u0003זה המניח ספר תורה\u0004 בשעה שהוציאוהו לקרוא בתפילה, \u0003ויוצא\u0004 מבית הכנסת, שהרי הוא נראה כבורח מדבר ה'.","הלכה למעשה אמרו כי \u0003ר' אבהו נפיק\u0004 \u0005[היה יוצא]\u0006 \u0003בין גברא לגברא\u0004 \u0005[איש לאיש]\u0006 הקוראים בספר התורה. כי מאחר שמפסיקים בין קריאתו של אדם אחד לזו של הבא אחריו, ואף סוגרים את הספר לפי שעה, אין בכך משום ביזוי התורה כשיוצא.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: בין פסוקא לפסוקא\u0004 \u0005[בין פסוק לפסוק]\u0006 \u0003מהו\u0004 הדין בכגון זה? שמאחר ונהגו להפסיק בין פסוק לפסוק בתרגום לארמית, האם מותר בשעת הפסק זה לצאת החוצה.","לשאלה זו לא נמצאה תשובה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","מסופר כי \u0003רב ששת מהדר אפיה וגריס\u0004 \u0005[היה מחזיר,\u0006 מפנה את \u0005פניו,\u0006 מספר התורה בו קוראים, \u0005ולומד].\u0006 \u0003אמר\u0004 (כביאור להתנהגותו): \u0003אנן בדידן ואינהו בדידהו\u0004 \u0005[אנו בשלנו והם בשלהם].\u0006 ומאחר שבאותה שעה עסק בתורה שבעל פה, אין לראות בזה משום \"עוזבי ה'\".","ועוד \u0003אמר רב הונא בר יהודה, אמר ר' אמי: לעולם ישלים אדם פרשיותיו עם הצבור.\u0004 לפי שהציבור קורא בשבת פרשה מסויימת, וחייב כל אדם לקרוא במשך השבוע שלפני השבת אותה פרשה בפני עצמו \u0003שנים מקרא ואחד תרגום,\u0004 שיקרא שתי פעמים את המקרא ופעם אחת את תרגומו של המקרא,"],["וצריך לחזור כך כל פסוק ופסוק בתורה. \u0003ואפילו פסוק כגון \"עטרות ודיבן\u0004 ויעזר ונמרה וחשבון ואלעלה ושבם ונבו ובעון\" (במדבר לב, ג) שכל הנאמר בו הוא שמות מקומות, ואין בו איפוא כל שינוי תרגום לשפה הארמית, יש לקרוא את הפסוק ואת תרגומו. שכן גדול הוא שכרה של קריאה שלימה של התורה ותרגומה, \u0003ש\u0004כך אמרו: \u0003כל המשלים פרשיותיו עם הצבור\u0004 זוכה ש\u0003מאריכין לו\u0004 בשכר זה \u0003ימיו ושנותיו.\u0004","מאחר שהיה טרוד ביותר, \u0003רב ביבי בר אביי סבר לאשלומינהו לפרשייתא דכולא שתא במעלי יומא דכפורי\u0004 \u0005[חשב להשלים את פרשיות\u0006 התורה של \u0005כל השנה,\u0006 שלא הספיק לקרותן בזמנן, \u0005בערב יום הכפורים]\u0006 בו היה פנוי יותר \u0003תנא ליה\u0004 \u0005[שנה לו]\u0006 \u0003רב חייא מדפתי\u0004 דבר זה: \u0003כתיב\u0004 \u0005[נאמר]\u0006 בענין יום הכיפורים: \u0003\"ועניתם את נפשתיכם בתשעה לחדש בערב\u0004 מערב עד ערב תשבתו שבתכם\" (ויקרא כג, לב),","ותמהים: \u0003וכי בתשעה\u0004 בחודש תשרי \u0003מתענין?! והלא בעשרה\u0004 בחודש \u0003מתענין\u0004 (כנאמר בתחילת הפרשיה \"אך בעשור לחודש השביעי הזה יום הכפורים הוא מקרא קודש יהיה לכם ועניתם את נפשותיכם\". שם, כז)! \u0003אלא\u0004 רמז הכתוב \u0003לומר לך\u0004 כי \u0003כל האוכל ושותה בתשיעי\u0004 ומכין עצמו לצום שלמחרת, \u0003מעלה עליו הכתוב כאילו מתענה תשיעי ועשירי\u0004 רצופים. וצריך איפוא להקדיש את ערב יום הכיפורים לאכילה ושתיה, ולא לקריאתן של הפרשיות.","כששמע זאת רב ביבי \u0003סבר לאקדומינהו\u0004 \u0005[חשב להקדימן],\u0006 את קריאת הפרשיות לפני השבתות שקוראים בהן בציבור, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא סבא\u0004 \u0005[אותו זקן]\u0006 שלא נתפרש שמו, \u0003תנינא\u0004 \u0005[שנינו]:\u0006 \u0003ובלבד שלא יקדים ולא יאחר\u0004 קריאת הפרשיות מהזמן הקבוע להן, אלא יקראן עם הציבור.","ו\u0003כ\u0004פי ש\u0003אמר ר' יהושע בן לוי לבניה\u0004 \u0005[לבניו]:\u0006 \u0003אשלימו פרשיותייכו\u0004 \u0005[השלימו פרשיותיכם]\u0006 \u0003עם הצבור שנים מקרא ואחד תרגום.\u0004","\u0003ו\u0004עוד יעץ להם:\u0003הזהרו בורידין כ\u0004שיטת \u0003ר' יהודה, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בהלכות שחיטה: \u0003ר' יהודה אומר:\u0004 אין שחיטת עוף כשרה \u0003עד שישחוט את הורידין,\u0004 שהעוף אינו מותר בשחיטת הקנה והושט בו, אלא רק לאחר שחיטת הורידים בהם זורם הדם. ואף שאין הדבר מחוייב מעיקר ההלכה, מכל מקום ראוי לנהוג כך, כדי שיימנע מלבוא לידי מכשולים, כשיישאר הדם בתוך העוף ולא יצא כולו בשחיטה.","\u0003ו\u0004עוד יעץ ר' יהושע בן לוי: \u0003הזהרו ב\u0004כבודו של \u0003זקן ששכח תלמודו מחמת אונסו\u0004 (במחלות, או בטרדות החיים), שאף שאינו כעת תלמיד חכם, יש לכבדו על התורה שהיתה בו. \u0003דאמרינן\u0004 \u0005[ש\u0006כן \u0005אמרנו]:\u0006 \u0003לוחות ושברי לוחות מונחות בארון\u0004 הברית במקדש, שהיו בו לוחות הברית השלמים השניים, וגם שברי הלוחות הראשונים, שאף ששבורים הם כעת — אין לזלזל בקדושתם, ואף כן הזקן ששכח תלמודו מחמת אונסו דינו כשברי לוחות העדות.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא לבניה\u0004 \u0005[לבניו]\u0006 שלוש עצות: \u0003כשאתם חותכין בשר, אל תחתכו על גב היד.\u0004 ושני הסברים ניתנו בטעמו של דבר, \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003משום סכנה,\u0004 שעשוי הוא לחתוך בשגגה את ידו ולהסתכן. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003משום קלקול סעודה,\u0004 שאף אם לא יסתכן בכך, אפילו במעט דם שיצא ממנו יזהם את הבשר וימאיסנו מאכילה.","\u0003ו\u0004עוד יעץ: \u0003אל תשבו על מטת ארמית, ואל תעברו אחורי בית הכנסת בשעה שהצבור מתפללין.\u0004 וביאורם של הדברים: \u0003אל תשבו על מטת ארמית, איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שהיתה כוונתו ש\u0003לא תגנו\u0004 \u0005[תשכבו\u0006 לישון\u0005]\u0006 \u0003בלא קריאת שמע,\u0004 והעושה כן נחשב כ\"יושב על מיטת גוי\" כי הוא מתנהג שלא כראוי לאדם מישראל. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שרמז ש\u0003לא תנסבו גיורתא\u0004 \u0005[תישאו גיורת],\u0006 שמוטב לשאת אשה מבנות ישראל. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 כפשוטו, שלא ישב על מיטת \u0003ארמית\u0004 (גויה) \u0003ממש.\u0004","\u0003ומשום מעשה\u0004 שהיה ב\u0003רב פפא.\u0004 שפעם אחת \u0003רב פפא אזל\u0004 \u0005[הלך]\u0006 לענין מסויים \u0003לגבי\u0004 \u0005[אצל]\u0006 \u0003ארמית\u0004 (גויה אחת), ו\u0003הוציאה לו מטה\u0004 לישיבה עליה. ו\u0003אמרה לו: שב! אמר לה: איני יושב, עד שתגביהי את המטה\u0004 (כלומר, את המצעים המכסים את המטה). עשתה כן \u0003ומצאו שם תינוק מת.\u0004 ונמצא שאם היה רב פפא יושב על המטה היו מעלילים עליו שהוא זה שהמית את התינוק. \u0003מכאן\u0004 (על כן) \u0003אמרו חכמים: אסור לישב על מטת ארמית.\u0004","\u0003ו\u0004אשר לעצה שיעץ להם \u0003אל תעברו אחורי בית הכנסת בשעה שהצבור מתפללין\u0004 הרי הוראה זו \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003ל\u0004שיטתו של \u0003ר' יהושע בן לוי.\u0004 ש\u0003אמר ר' יהושע בן לוי: אסור לו לאדם שיעבור אחורי בית הכנסת בשעה שהצבור מתפללין,\u0004 לפי שהוא גורם שיחשדו בו שאינו חפץ להתפלל, ובז לבית הכנסת.","\u0003אמר אביי\u0004 לסייג את דברי ר' יהושע בן לוי בכמה גדרים: \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 איסור זה \u0003אלא\u0004 באופן \u0003דליכא פתחא אחרינא\u0004 \u0005[שאין פתח אחר]\u0006 לבית הכנסת, \u0003אבל\u0004 כאשר \u0003איכא פתחא אחרינא\u0004 \u0005[יש פתח אחר],\u0006 אף שרואים אותו עובר אחורי בית הכנסת — יתכן שיכנס לתוכו מן הפתח האחר, \u0003ו\u0004לכן \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 צד איסור. \u0003ו\u0004כן \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 איסור זה \u0003אלא\u0004 באופן \u0003דליכא בי כנישתא אחרינא\u0004 \u0005[שאין בית כנסת אחר]\u0006 בעיר, \u0003אבל\u0004 כאשר \u0003איכא בי כנישתא אחרינא\u0004 \u0005[יש בית כנסת אחר]\u0006 בעיר — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 צד איסור \u0003ו\u0004כן \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא\u0004 באופן \u0003דלא דרי טונא\u0004 \u0005[שאינו נושא משא],\u0006 \u0003ולא רהיט\u0004 \u0005[רץ],\u0006 \u0003ולא מנח\u0004 \u0005[מניח]\u0006 \u0003תפילין, אבל\u0004 אם \u0003איכא חד מהנך\u0004 \u0005[יש אחד מאלו] —\u0006 \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 צד איסור בדבר. כי כשהוא רץ או נושא משא, יודעים שהוא טרוד במלאכתו, והמניח תפילין מראה כי אימת שמים עליו, ולא יבואו לחשוד בו.","אגב עצת רבא לבניו שלא לחתוך בשר על גב ידם, מביאים עוד מה ש\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' עקיבא: בשלשה דברים אוהב אני את המדיים,\u0004 וראוי ללמוד מהם מנהגים אלו, ואלו הם: \u0003כשחותכין את הבשר\u0004 — \u0003אין חותכין אלא על השולחן,\u0004 ולא על היד, \u0003כשנושקין\u0004 נשיקה של קירבה או של כבוד — \u0003אין נושקין אלא על גב היד,\u0004 ועל ידי זה אינם גורמים אי נעימות לאיש שנשקו אותו, \u0003וכשיועצין\u0004 — \u0003אין יועצין אלא בשדה,\u0004 כך שאין אנשים זרים עשויים לשמוע דברי סוד.","\u0003אמר רב אדא בר אהבה: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המרמז שראוי לעשות כך — \u0003\"וישלח יעקב ויקרא לרחל וללאה השדה אל צאנו\"\u0004 (בראשית לא, ד), ורק שם נתייעץ עמן.","ובדומה לכך \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003אמר רבן גמליאל: בשלשה דברים אוהב אני את הפרסיים:\u0004 שיש בהם מידת צניעות, לפי ש\u0003הן צנועין באכילתן, וצנועין בבית הכסא, וצנועין בדבר אחר\u0004 (בזיווגם).","אף שדובר בשבח עניינים מסויימים של הפרסיים, יש מקום לראיה כוללת שונה שלהם, וכביאור למקרא המדבר במפלת בבל על ידי צבא מדי ופרס: \u0003\"אני צויתי למקדשי\u0004 גם קראתי גבורי לאפי עליזי גאותי\" (ישעיה יג, ג) \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 בשם ברייתא: \u0003אלו הפרסיים המקודשין ומזומנין לגיהנם,\u0004 שהוזכר בכתוב שהם רק מוכנים (מוקדשים) ביד ה' לעשות שליחות זעמו, ואף הם מיורדי הגיהנום.","ושבים לפירושה של המשנה. שנינו בה כי \u0003רבן גמליאל אומר\u0004 שסוף זמן קריאת שמע של ערבית הריהו עד עלות השחר. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר רב יהודה, אמר שמואל: הלכה כרבן גמליאל.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 מתוך הסתמכות עקרונית על שיטתו של רבן גמליאל, \u0003ר' שמעון אומר: פעמים שאדם קורא קריאת שמע שתי פעמים בלילה\u0004 ובזמנים סמוכים מאד, \u0003אחת קודם שיעלה עמוד השחר, ואחת לאחר שיעלה עמוד השחר, ו\u0004אף על פי כן \u0003יוצא בהן ידי חובתו אחת של יום ואחת של לילה,\u0004 זו שלפני עמוד השחר — כקריאת שמע של לילה (כשיטת רבן גמליאל), וזו שלאחר עלות עמוד השחר — כקריאת שמע של יום.","על סגנון הדברים בתוספתא מקשים מיד: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה]\u0006 בלשונה, שבראשית הדברים \u0003אמרת: פעמים שאדם קורא קריאת שמע שתי פעמים בלילה, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003לאחר שיעלה עמוד השחר\u0004 עדיין \u0003לילה הוא, והדר תני\u0004 \u0005[וחזר ושנה]\u0006 בהמשך: \u0003יוצא בהן ידי חובתו אחת של יום ואחת של לילה, אלמא יממא\u0004 \u0005[מכאן\u0006 ש\u0005יום]\u0006 \u0003הוא,\u0004 שאם לא כן אי אפשר לצאת חובת קריאת שמע של יום, ואם כן יש לכאורה סתירה פנימית בדבר מהותו של הזמן שלאחר עלות עמוד השחר, אם יום הוא או לילה.","ומשיבים: \u0003לא\u0004 — אין זו סתירה ו\u0003לעולם\u0004 אכן אותה שעה שלאחר עלות עמוד השחר כשעדיין חושך \u0003ליליא\u0004 \u0005[לילה]\u0006 \u0003הוא. והא דקרי ליה\u0004 \u0005[וזה ש\u0006הוא \u0005קורא לו],\u0006 לזמן זה \u0003\"יום\"\u0004 — משום \u0003דאיכא אינשי דקיימי בההיא שעתא\u0004 \u0005[שיש אנשים הקמים\u0006 משנתם \u0005באותה שעה]\u0006 ואפשר בדוחק לקרוא לשעה זו כבר זמן המתאים ל\"ובקומך\" שבתורה, אף כי הוא נחשב לכל שאר הדברים כלילה.","על דברים אלה שאמר ר' שמעון בן יוחאי \u0003אמר רב אחא בר חנינא, אמר ר' יהושע בן לוי: הלכה כר' שמעון בן יוחי.\u0004","\u0003איכא דמתני להא\u0004 \u0005[יש ששונים את זו],\u0006 את קביעת ההלכה כר' שמעון על ידי \u0003רב אחא בר חנינא אהא\u0004 \u0005[על\u0006 הלכה \u0005זו]\u0006 הדומה בסגנונה להלכה הקודמת. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יוחי אומר משום\u0004 (בשם) \u0003ר' עקיבא: פעמים שאדם קורא קריאת שמע שתי פעמים ביום, אחת קודם הנץ החמה, ואחת לאחר הנץ החמה, ויוצא בהן ידי חובתו, אחת של יום,\u0004 זו שלאחר הנץ החמה \u0003ואחת של לילה,\u0004 זו שקודם הנץ החמה.","ולכאורה \u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה]\u0006 בלשונה, שאף כאן קיים אותו קושי מגופם של דברים. שבתחילה \u0003אמרת\u0004 כי \u0003פעמים שאדם קורא קריאת שמע שתי פעמים ביום, אלמא\u0004 \u0005[מכאן]\u0006 שהשעה \u0003קודם הנץ החמה יממא\u0004 \u0005[יום]\u0006 \u0003הוא, והדר תני\u0004 \u0005[חזר ושנה]\u0006 \u0003יוצא בהן ידי חובתו אחת של יום ואחת של לילה, אלמא\u0004 \u0005[מכאן]\u0006 שזמן זה \u0003ליליא\u0004 \u0005[לילה]\u0006 \u0003הוא!\u0004"],["ובדרך דומה מתרצים גם כאן: \u0003לא,\u0004 שעה זו \u0003לעולם יממא\u0004 \u0005[יום]\u0006 \u0003הוא,\u0004 ומשום כך אפשר לקרות בה קריאת שמע של שחרית, \u0003והאי דקרו ליה \"ליליא\"\u0004 \u0005[ וזה שקוראים לו ,\u0006 לזמן הזה \u0005\"לילה\"]\u0006 — הרי זה משום \u0003דאיכא אינשי דגנו בההיא שעתא\u0004 \u0005[שיש אנשים הישנים באותה שעה],\u0006 ואפשר לומר כי עדיין זה זמן \"ובשכבך\", ומותר לקרוא בו קריאת שמע של ערבית.","\u0003אמר ר' אחא בר' חנינא, אמר ר' יהושע בן לוי: הלכה כר' שמעון שאמר משום\u0004 (בשם) \u0003ר' עקיבא.\u0004 על כך \u0003אמר ר' זירא: ובלבד שלא יאמר\u0004 כשהוא קורא קריאת שמע של ערבית לפני הנץ החמה, את הברכה שלאחר קריאת שמע \u0003\"השכיבנו\",\u0004 כי הבקשה לשכב בשלום המצויה בברכה זו אין לה מקום בשעות הבוקר.","כך נמסרה הלכה זו בבית המדרש, ואולם \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב יצחק בר יוסף\u0004 מארץ ישראל, מקומו של ר' יהושע בן לוי, לבבל, \u0003אמר\u0004 כי \u0003הא\u0004 \u0005[\u0006קביעה \u0005זו]\u0006 של \u0003ר' אחא בר' חנינא\u0004 ש\u0003אמר\u0004 בשם \u0003ר' יהושע בן לוי, לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש איתמר\u0004 \u0005[נאמרה],\u0006 \u0003אלא מכללא איתמר\u0004 \u0005[מכלל\u0006 הדברים, \u0005נאמרה],\u0006 שלא קבע ר' יהושע בן לוי הלכה פסוקה בנושא זה, אלא רק מתוך דבריו אפשר היה להסיק שזו היא דעתו.","ומעשה שהיה כך היה: \u0003דההוא זוגא דרבנן דאשתכור בהלולא דבריה\u0004 \u0005[שאותו זוג חכמים שהשתכרו בחתונת בנו]\u0006 של \u0003ר' יהושע בן לוי,\u0004 ונרדמו, ולא קראו קריאת שמע של ערבית, וכשהקיצו היה כבר לאחר עלות השחר. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' יהושע בן לוי\u0004 לשאול אם מותר להם עדיין לקרות קריאת שמע של ערבית, ואז \u0003אמר\u0004 להם: \u0003כדאי הוא ר' שמעון לסמוך עליו בשעת הדחק,\u0004 ואם כן לא פסק הלכה קבועה כדברי ר' שמעון, שכשאינו שעת הדחק אין לסמוך עליו להלכה.","במשנה סופר \u0003מעשה שבאו בניו של\u0004 רבן גמליאל ושאלו את אביהם אם מותר להם לקרות את שמע לאחר חצות הלילה.","על כך תמהים בגמרא: \u0003ו\u0004כי \u0003עד השתא\u0004 \u0005[עכשיו]\u0006 \u0003לא שמיע להו הא\u0004 \u0005[שמעו\u0006 הלכה \u0005זו]\u0006 של \u0003רבן גמליאל?!\u0004 וכי לא ידעו שלפי שיטתו מותר להם עדיין לקרוא קריאת שמע של לילה?","ומשיבים, כי בניו לא שאלו מה היא דעתו אלא \u0003הכי קאמרי ליה\u0004 \u0005[כך אמרו לו],\u0006 זו היתה כוונתם: האם \u0003רבנן פליגי עילווך\u0004 \u0005[חכמים חולקים עליך]\u0006 ביסודה של ההלכה, וסבורים כי קריאת שמע עד חצות ולא יותר, \u0003ו\u0004אם כן במחלוקת \u0003יחיד ורבים, הלכה כרבים,\u0004 ויש איפוא לנהוג הלכה למעשה כדעת חכמים שהם הרוב. \u0003או דלמא רבנן כוותך סבירא להו\u0004 \u0005[שמא חכמים כמותך סבורים הם]\u0006 שזמן קריאת שמע מן התורה הריהו כל הלילה, \u0003והאי דקאמרי\u0004 \u0005[וזה שהם אומרים]\u0006 \u0003\"עד חצות\"\u0004 — הרי זה \u0003כדי להרחיק\u0004 את ה\u0003אדם מן העבירה,\u0004 ולכן מי שנאנס ואינו יכול לקרות קודם — מותר לו לקרות אף לאחר חצות. \u0003אמר להו\u0004 \u0005[להם]\u0006 רבן גמליאל לבניו: \u0003רבנן כוותי סבירא להו\u0004 \u0005[חכמים כמותי סבורים הם],\u0006 \u0003וחייבין אתם\u0004 לקרוא. \u0003והאי דקאמרי\u0004 \u0005[וזה שהם אומרים]\u0006 \u0003\"עד חצות\"\u0004 — \u0003כדי להרחיק אדם מן העבירה,\u0004 אבל בדיעבד — מותר אף לדעת חכמים.","שנינו במשנה שאמר להם רבן גמליאל לבניו: \u0003ולא זו בלבד אמרו\u0004 שזמנה עד חצות, \u0003אלא\u0004 כל מה שאמרו חכמים עד חצות מצותן עד שיעלה עמוד השחר.","ותוהים על הסגנון, \u0003רבן גמליאל מי קאמר\u0004 \u0005[האם אמר]\u0006 \u0003\"עד חצות\", דקתני\u0004 \u0005[ששנינו]\u0006 \u0003\"ולא זו בלבד אמרו\"?\u0004 והרי אין רבן גמליאל מגביל את זמן קריאת שמע עד חצות, ומדוע הוא מתבטא \"ולא זו בלבד אמרו\"?","ומסבירים כי \u0003הכי קאמר להו\u0004 \u0005[כך אמר להם]\u0006 \u0003רבן גמליאל לבניה\u0004 \u0005[לבניו]\u0006 \u0003אפילו לרבנן דקאמרי\u0004 \u0005[ל\u0006שיטת \u0005חכמים האומרים]\u0006 שמצותה \u0003עד חצות\u0004, אף לדבריהם מעיקר דין התורה, \u0003מצותה,\u0004 כלומר, מותר הדבר, \u0003עד עלות השחר. והא דקא אמרי\u0004 \u0005[וזה שהם אומרים]\u0006 \u0003\"עד חצות\"\u0004 — הרי זה \u0003כדי להרחיק אדם מן העבירה.\u0004","במשנתנו מנה רבן גמליאל כמה דברים שמצותם עד שיעלה עמוד השחר, וכגון \u0003הקטר חלבים\u0004 ואברים.","ומעירים: \u0003ואילו אכילת פסחים לא קתני\u0004 \u0005[שנה],\u0006 הרי שמצוות אכילת קרבן הפסח אינה נמשכת עד השחר.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 למסקנה זו ממה ששנינו בברייתא: \u0003קריאת שמע ערבית, והלל בלילי פסחים\u0004 הנאמר עם הקרבת קרבן הפסח, \u0003ואכילת פסח,\u0004 כולם \u0003מצותן עד שיעלה עמוד השחר!\u0004","\u0003אמר רב יוסף: לא קשיא\u0004 \u0005[אינו קשה],\u0006 כי שני המקורות מבטאים שתי שיטות הלכתיות שונות: \u0003הא\u0004 \u0005[זה]\u0006 לשיטת \u0003ר' אלעזר בן עזריה, והא\u0004 \u0005[וזו]\u0006 לשיטת \u0003ר' עקיבא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 על הפסוק המדבר בענין מצוות אכילת הפסח \u0003\"ואכלו את הבשר בלילה הזה\u0004 צלי אש ומצות על מרורים יאכלוהו\" (שמות יב, ח), \u0003ר' אלעזר בן עזריה אומר\u0004 לפרש בדרך זו: \u0003נאמר כאן \"בלילה הזה\",\u0004 ומפסוק זה בלבד אין אנו יודעים עד מתי נמשך \"הלילה הזה\". \u0003ו\u0004אולם \u0003נאמר\u0004 אותו ביטוי \u0003להלן\u0004 באותו פרק בתורה: \u0003\"ועברתי בארץ מצרים בלילה הזה\u0004 והכיתי כל בכור בארץ מצרים מאדם ועד בהמה\" וגו' (שם יב, יב), ועל זמנה של מכת בכורות יודעים אנו מהכתוב \"כה אמר ה' כחצות הלילה אני יוצא בתוך מצרים ומת כל בכור בארץ מצרים\" וגו' (שם יא, ד—ה) ואם כן \u0003מה להלן\u0004 בענין מכת הבכורות \u0003עד חצות\u0004 כמפורש, \u0003אף כאן\u0004 בציווי האכילה הכוונה היא \u0003עד חצות.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' עקיבא: והלא כבר נאמר\u0004 \"וככה תאכלו אותו, מתניכם חגורים נעליכם ברגליכם ומקלכם בידכם ואכלתם אותו \u0003בחפזון\u0004 פסח הוא לה'\" (שם יב, יא), הרי שהפסח נאכל \u0003עד שעת חפזון,\u0004 שהיא השעה בה נחפזו ישראל לצאת ממצרים, כאמור \"ואתם לא תצאו איש מפתח ביתו עד בקר\", ואם כן אכילת הפסח היא עד עלות השחר. \u0003אם כן מה תלמוד לומר \"בלילה\"?\u0004","שהרי לדעה זו אין בכך קביעה מדוייקת, אלא יש לבאר כך: כי \u0003יכול\u0004 היית לומר כי \u0003יהא\u0004 הפסח \u0003נאכל כ\u0004שאר ה\u0003קדשים ביום,\u0004 שכן כל שאר הקרבנות זמן שחיטתם ואכילתם הריהו ביום, על כן \u0003תלמוד לומר \"בלילה\",\u0004 להדגיש: \u0003בלילה הוא נאכל, ולא ביום.\u0004 ובסיכום: ההבדל בין דברי ר' אלעזר בן עזריה ור' עקיבא הוא, אשר כפי הנראה האחד מסתמך על המלה \"בלילה\" והאחר על \"בחפזון\", מעתה ממשיכים לברר את דעות שני התנאים ביתר דיוק.","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לר' אלעזר בן עזריה דאית ליה\u0004 \u0005[שיש לו,\u0006 שהוא מחזיק בדעה\u0005]\u0006 כי \u0003גזירה שוה\u0004 נלמדת מהשוואת המילים \"בלילה הזה\" באכילת הפסח ו\"בלילה הזה\" במכת בכורות, ולשיטתו \u0003אצטריך למכתב ליה\u0004 \u0005[הוצרך לכתוב לו]\u0006 \u0003\"הזה\"\u0004 כדי להראות על שויון הזמנים. \u0003אלא לר' עקיבא\u0004 שאינו למד גזירה שווה זו \u0003האי\u0004 \u0005[אותו]\u0006 \u0003\"הזה\" מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו]?\u0006 ולשם מה ההדגשה \"הזה\"?","ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003לילה אחר הוא דאתא\u0004 \u0005[שבא],\u0006 כתוב זה, שאפשר היה להניח כי את קרבן הפסח יאכלו במשך שני לילות, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ופסח\u0004 נכלל בתוך סוג הקרבנות הקרוי \u0003קדשים קלים, ו\u0004גם \u0003שלמים\u0004 הם \u0003קדשים קלים,\u0004 ואם כן נשווה ביניהם ונאמר כי \u0003מה שלמים נאכלים לשני ימים ולילה אחד,\u0004 כלומר, ביום בו נשחטו, בלילה שאחר כך, וביום הבא — \u0003אף פסח נאכל שני לילות במקום שני ימים,\u0004 שהרי קרבן הפסח נשחט בערב, \u0003ו\u0004מתוך השוואה לשלמים \u0003יהא נאכל לשני לילות ויום אחד\u0004 שביניהם. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב \u0003\"בלילה הזה\"\u0004 לומר שהוא דווקא, שאך \u0003בלילה הזה הוא נאכל ואינו נאכל בלילה אחר.\u0004","ושואלים: אם כן כיצד ילמד ר' אלעזר בן עזריה מן המקראות שאין הפסח נאכל לשני לילות? ומשיבים: ל\u0003ר' אלעזר בן עזריה\u0004","\u0003מ\"לא תותירו עד בקר\" נפקא\u0004 \u0005[יוצאת]\u0006 מסקנה זו, שאם אסור להשאיר מקרבן הפסח עד בוקר, ודאי שאי אפשר להותיר ממנו עד ללילה השני. ואין צורך להדגיש שהפסח נאכל רק בלילה הראשון.","\u0003ור' עקיבא\u0004 מה הוא אומר על הלימוד מפסוק זה — לדעתו \u0003אי מהתם\u0004 \u0005[אם משם],\u0006 מפסוק זה שצויין, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"בקר\"\u0004 — \u0003בקר שני.\u0004 שהרי בתורה לא נאמר עד לאיזה בוקר אסור להשאיר את הפסח, ואפשר היה לחשוב שלאחר שנאכל הפסח, שני לילות אסור יהא להותיר ממנו לבוקר השני. ולכן יש להדגיש \"בלילה הזה\" ולא באחר.","\u0003ור' אלעזר\u0004 בן עזריה על פירכה זו \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 משמעות \u0003כל \"בקר\"\u0004 שנאמר במקרא — \u0003בקר ראשון הוא,\u0004 שאם אין הכתוב מציין אחרת, ודאי \"בוקר\" סתם האמור במקרא כוונתו לבוקר הראשון, שאם לא כן אין למקרא משמעות מוגדרת כלל.","על מחלוקת התנאים בין ר' עקיבא ור' אלעזר בן עזריה בדבר זמן אכילת הפסח מעירים \u0003הני תנאי כהני תנאי\u0004 \u0005[תנאים אלה כתנאים הללו]\u0006 שאף הם נחלקו בדבר. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר בכתוב \u0003\"שם תזבח את הפסח בערב כבוא השמש מועד צאתך ממצרים\"\u0004 (דברים טז, ו), ולאחר העיון מתברר שבפסוק זה מצויינים שלושה זמנים: \"בערב\" שמשמעו — שעות אחר הצהרים עד לשקיעה, \"כבוא השמש\" — שעת השקיעה, ו\"מועד צאתך מארץ מצרים\" שהוא כמבואר בספר שמות, בשעות הבוקר. על כן נראה כי זמנים אלה מקבילים לשלבים שונים במצוות הפסח, ובפירוטם נחלקו התנאים.","\u0003ר' אליעזר אומר: \"בערב\" אתה זובח\u0004 (שוחט) את הקרבן, \u0003ו\"כבוא השמש\" אתה אוכל\u0004 עד שעת חצות, \u0003ו\"מועד צאתך מארץ מצרים\" אתה שורף\u0004 את מה שנותר מן הקרבן. כדעת ר' אלעזר בן עזריה. \u0003ר' יהושע אומר: \"בערב\" אתה זובח,\u0004 ו\u0003\"כבוא השמש\" אתה אוכל, ועד מתי אתה אוכל והולך\u0004 (ממשיך לאכול) — \u0003עד \"מועד צאתך מארץ מצרים\",\u0004 כלומר, עד הבוקר, כדעת ר' עקיבא.","כגישה אחרת בהסברת מחלוקת ר' אלעזר בן עזריה ור' עקיבא, \u0003אמר ר' אבא: הכל מודים כשנגאלו ישראל ממצרים,\u0004 כשנתנה להם הרשות לצאת, \u0003לא נגאלו אלא בערב, שנאמר: \"\u0004כי בחודש האביב \u0003הוציאך ה' אלהיך ממצרים לילה\"\u0004 (דברים טז, א), \u0003וכשיצאו\u0004 בפועל — \u0003לא יצאו אלא ביום, שנאמר:\u0004 \"בחמשה עשר לחודש הראשון \u0003ממחרת הפסח יצאו בני ישראל ביד רמה\u0004 לעיני כל מצרים\" (במדבר לג, ג), הרי שיצאו בשעות היום,","ואולם \u0003על מה נחלקו\u0004 — \u0003על שעת חפזון\u0004 שנאמר בפסוק \"ואכלתם אותו בחפזון פסח הוא לה'\" (שמות יב, יא), ש\u0003ר' אלעזר בן עזריה סבר\u0004 \u0005[סבור]:\u0006 \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"חפזון\"\u0004 זה — \u0003חפזון\u0004 של \u0003מצרים,\u0004 שנחפזו המצרים לבוא לבתי ישראל לשלחם מפחד מכת הבכורות, והיתה שעה זו בחצות הלילה.","\u0003ור' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"חפזון\"\u0004 זה — \u0003חפזון\u0004 של \u0003ישראל,\u0004 שנחפזו לצאת, והיה זה בשעות הבוקר.","מעין דברי ר' אבא \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא גם כן כך] על הנאמר: \u0003\"הוציאך ה' אלהיך ממצרים לילה\"\u0004 יש לתמוה: \u0003וכי בלילה יצאו? והלא לא יצאו אלא ביום, שנאמר: \"ממחרת הפסח יצאו בני ישראל ביד רמה\"! אלא, מלמד שהתחילה להם\u0004 ה\u0003גאולה מבערב.\u0004","מאחר שנסבו הדברים האחרונים ביציאת מצרים מביאים עוד מדרשי אגדה בנושא זה. נאמר בפסוק \u0003\"דבר נא באזני העם\u0004 וישאלו איש מאת רעהו ואשה מאת רעותה כלי כסף וכלי זהב\" (שמות יא, ב), ולכאורה תמוהה המלה \"נא\", שכן \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 תלמידי \u0005בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ינאי: אין \"נא\" אלא לשון בקשה,\u0004 ומה טעם מדבר ה' לעם בלשון בקשה? ומסבירים שכך היתה כוונת הדברים: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003הקדוש ברוך הוא למשה: בבקשה ממך\u0004 (\"נא\"), \u0003לך ואמור להם לישראל: בבקשה מכם\u0004 (\"נא\"), \u0003שאלו ממצרים כלי כסף וכלי זהב,\u0004 כדי שתתקיים על ידי כך הבטחת ה' לאברהם בברית בין הבתרים, \u0003שלא יאמר\u0004"],["\u0003אותו צדיק,\u0004 אברהם, כי מדברי ה' באותו מעמד: \"ידוע תדע כי גר יהיה זרעך בארץ לא להם ועבדום וענו אותם ארבע מאות שנה. וגם את הגוי אשר יעבודו דן אנוכי ואחרי כן יצאו ברכוש גדול\" (בראשית טו, יג–יד) \u0003\"ועבדום וענו אתם\"\u0004 — \u0003קיים בהם, \"ואחרי כן יצאו ברכש גדול\"\u0004 — \u0003לא קיים בהם.\u0004","וממשיך ר' ינאי עוד להסביר את פני הדברים אז, \u0003שאמרו לו\u0004 ישראל למשה: \u0003ולואי שנצא בעצמנו!\u0004 ו\u0003משל\u0004 לכך: \u0003לאדם שהיה חבוש\u0004 (אסור) \u0003בבית האסורים והיו אומרים לו בני אדם\u0004 ומבטיחים לו: \u0003מוציאין אותך למחר מבית האסורין, ונותנין לך ממון הרבה, ואומר\u0004 הוא \u0003להם: בבקשה מכם, הוציאוני היום, ואיני מבקש כלום.\u0004 ואף ישראל עדיף היה להם השחרור מיד על הרכוש לאחר זמן.","בענין שלל מצרים המסופר בפסוק \"וה' נתן את חן העם בעיני מצרים \u0003וישאלום\u0004 וינצלו את מצרים\" (שמות יב, לו), \u0003אמר ר' אמי: מלמד שהשאילום בעל כרחם.\u0004 אך נחלקו הדעות מי אלה שעשו זאת בעל כרחם. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 \u0003בעל כרחם\u0004 של ה\u0003מצרים, ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 \u0003בעל כרחם\u0004 של \u0003ישראל.\u0004 ובעלי שתי הדעות מביאים סימוכין לדבריהם.","\u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003בעל כרחם\u0004 של ה\u0003מצרים\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בפרק המתאר את יציאת מצרים: \u0003\"ונות בית תחלק שלל\"\u0004 (תהלים סח, יג), ששאלה זו ששאלה אשה (\"נות בית\") מאת רעותה היתה בעצם \"שלל\" הניטל בעל כרחו של אויב. ו\u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי היה זה \u0003בעל כרחם\u0004 של \u0003ישראל\u0004 — \u0003משום משוי\u0004 (טורח המשא), שסברה היא שמן הסתם לא חפצו בני ישראל להעמיס על עצמם משא רב בדרך.","להמשכו של פסוק זה \u0003\"וינצלו את מצרים\"\u0004 ניתנו כמה פירושים. \u0003אמר ר' אמי\u0004 כי נרמז כאן \u0003שעשאוה כמצודה שאין בה דגן, וריש לקיש אמר,\u0004 הרמז שבפסוק כך הוא: \u0003עשאוה כמצולה\u0004 בים \u0003שאין בה דגים.\u0004","ובתוך הקשר הדברים דנים גם בהבטחת גאולת מצרים שנאמרה למשה בסנה, שכאשר שאל מה יאמר בדבר ה', נענה: \"ויאמר אלהים אל משה \u0003אהיה אשר אהיה,\u0004 ויאמר כה תאמר לבני ישראל אהיה שלחני אליכם\" (שמות ג, יד). \u0003אמר לו הקדוש ברוך הוא למשה, לך אמור להם לישראל: אני הייתי עמכם בשעבוד זה,\u0004 בגאולה זו, \u0003ואני אהיה עמכם בשעבוד מלכיות\u0004 לעתיד לבוא.","\u0003אמר\u0004 משה \u0003לפניו: רבונו של עולם, דיה לצרה בשעתה,\u0004 ואין צורך להזכיר את השעבוד שלעתיד. ואף הקדוש ברוך הוא הסכים עמו ו\u0003אמר לו הקדוש ברוך הוא: לך אמור להם\u0004 לבני ישראל רק \"אהיה שלחני אליכם\".","ואגב הסברת הכפלת המילים \"אהיה אשר אהיה\" מבארים גם הכפלת מילים בתפילת אליהו בהר הכרמל \u0003\"ענני ה' ענני\u0004 וידעו העם הזה כי אתה ה' האלהים ואתה הסיבות את לבם אחורנית\" (מלכים א יח, לז). ש\u0003אמר ר' אבהו: למה אמר אליהו \"ענני\" שתי פעמים? מלמד שאמר אליהו לפני הקדוש ברוך הוא: רבונו של עולם, \"ענני\"\u0004 — \u0003שתרד אש מן השמים ותאכל כל אשר על המזבח, ו\"ענני\"\u0004 — \u0003שתסיח דעתם\u0004 ממחשבה לעקוף את משמעות הדברים שהם רואים, \u0003כדי שלא יאמרו מעשה כשפים הם. שנאמר\u0004 שכך אמר אליהו: \u0003\"ואתה הסבת את לבם אחורנית\",\u0004 ויכול ה' אם כן גם להשיבם אל דרך האמת.","\u0003מאימתי\u0004 הוא הזמן בו מתחילים להיות \u0003קורין\u0004 (קוראים) \u0003את שמע בשחרית?\u0004 — \u0003משיכיר\u0004 האדם ויבדיל \u0003בין תכלת ללבן. ר' אליעזר אומר:\u0004 זמן זה הוא כאשר ניתן יהא להכיר \u0003בין תכלת לכרתי\u0004 (ירוק בהיר). \u0003וגומרה,\u0004 כלומר, סוף זמן קריאת שמע של שחרית שהוא זמן \"ובקומך\" הוא \u0003עד הנץ החמה,\u0004 השעה שבה מתחילה השמש לזרוח על הארץ. ואילו \u0003ר' יהושע אומר\u0004 כי אפשר לקרוא קריאת שמע של שחרית \u0003עד שלש שעות\u0004 מתחילת היום, שעדיין היא נחשבת לשעת קימה, \u0003שכן דרך מלכים לעמוד\u0004 (לקום משנתם) \u0003בשלש שעות.\u0004","ואף שיש זמן קבוע לקריאת שמע, מכל מקום \u0003הקורא\u0004 לאחר שנתאחר \u0003מכאן ואילך,\u0004 לאחר זמנה — \u0003לא הפסיד,\u0004 שאף שלא קיים מצוות קריאת שמע בזמנה, מכל מקום הריהו \u0003כאדם הקורא בתורה,\u0004 שקריאת שמע הריהי בכלל לימוד התורה, ושכרו כשכר הלומד תורה.","במשנה נאמר שזמן קריאת שמע של שחרית הוא משיכיר בין תכלת ללבן, ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 בדיוק \u0003בין תכלת ללבן? אילימא\u0004 \u0005[אם לומר]\u0006 שזו הבחנה \u0003בין גבבא דעמרא חיורא לגבבא דעמרא דתכלתא\u0004 \u0005[ערימת צמר לבן לערימת צמר של תכלת]\u0006 — \u0003הא בליליא נמי מידע ידעי\u0004 \u0005[הרי בלילה גם כן יודעים]\u0006 את ההבדל בין גוש לבן וגוש כהה. \u0003אלא\u0004 כך צריך להבין, שהמדובר הוא בציציות העשויות עם פתיל תכלת (עיין במדבר טו, לח), וההבחנה היא \u0003בין תכלת שבה ללבן שבה.\u0004 בקביעת זמן תחילת קריאת שמע של שחרית הובאו בברייתא דעות נוספות על אלו של המשנה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' מאיר אומר\u0004 כי תחילת היום היא כשאפשר להבחין בין שני בעלי חיים הדומים זה לזה, וכגון \u0003שיכיר בין זאב לכלב. ר' עקיבא\u0004 נותן סימן אחר — שיהא די אור כדי להבחין \u0003בין חמור לערוד\u0004 (חמור הבר). \u0003ואחרים אומרים: משיראה את חברו\u0004 (שהוא מכיר אותו רק הכרה קלושה. ירושלמי), כשהוא \u0003רחוק ארבע אמות\u0004 ממנו, \u0003ויכירנו.\u0004","\u0003אמר רב הונא: הלכה כאחרים. אמר אביי:\u0004 פסק ההלכה \u0003ל\u0004ענין \u0003תפילין\u0004 הריהו \u0003כאחרים,\u0004 שמשעה זו אפשר להניח תפילין, שמצוותם רק ביום. ו\u0003לקריאת שמע\u0004 ראוי לנהוג \u0003כותיקין,\u0004 שהם יראי שמים שהיו מהדרים במצוות. וכפי ש\u0003אמר ר' יוחנן\u0004 כי \u0003ותיקין היו גומרין אותה,\u0004 את קריאת שמע, \u0003עם הנץ החמה,\u0004 וכך ראוי לעשות.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003ותיקין היו גומרין אותה עם הנץ החמה, כדי שיסמוך גאולה\u0004 (ברכת הגאולה, הבאה מיד לאחר קריאת שמע) \u0003לתפלה, ונמצא מתפלל ביום.\u0004","על מנהג הותיקין \u0003אמר ר' זירא: מאי קראה\u0004 \u0005[מהו הכתוב],\u0006 המסייע לכך — \u0003\"ייראוך עם שמש ולפני ירח דור דורים\"\u0004 (תהלים עב, ה), שהשעה בה ראוי לבטא את מורא השמים (\"ייראוך\") תהא \"עם שמש\" — עם צאת השמש, בעת הנץ החמה.","\u0003העיד ר' יוסי בן אליקים משום\u0004 (בשם) \u0003קהלא קדישא\u0004 \u0005[הקהל הקדוש]\u0006 ש\u0003בירושלים\u0004 (קבוצה של חכמים שהיתה מצויה שם): \u0003כל הסומך גאולה לתפלה\u0004 עם הנץ החמה, \u0003אינו נזוק כל היום כולו.\u0004","\u0003אמר ר' זירא: איני\u0004 \u0005[\u0006וכי \u0005כן\u0006 הוא\u0005]?!\u0006 \u0003והא אנא סמכי ואיתזקי\u0004 \u0005[והרי אני סמכתי\u0006 גאולה לתפילה, \u0005וניזוקתי]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003במאי איתזקת\u0004 \u0005[במה ניזוקת]\u0006 — \u0003דאמטיית אסא לבי מלכא\u0004 \u0005[שהבאת הדס אל בית המלך],\u0006 שהוטל עליו כאחד מנכבדי הציבור להשתתף במשלחת שתביא מתנה למלך כליל—הדסים, והוא ראה בכך, העמדתו במצב בלתי נוח, ולא רצה בכבוד מפוקפק זה. ואולם \u0003התם נמי\u0004 \u0005[שם גם כן\u0006 באותו מקרה\u0005]\u0006 \u0003מבעי לך למיהב אגרא למחזי אפי מלכא\u0004 \u0005[צריך היית לתת שכר\u0006 כדי שתוכל \u0005לראות\u0006 את \u0005פני המלך]\u0006 שכן \u0003אמר ר' יוחנן: לעולם ישתדל אדם לרוץ לקראת מלכי ישראל\u0004 לראותם בכבודם. \u0003ולא לקראת מלכי ישראל בלבד, אלא אפילו לקראת מלכי אומות העולם, שאם יזכה\u0004 לראות בגאולת ישראל — \u0003יבחין בין מלכי ישראל למלכי אומות העולם,\u0004 כמה תרבה גדולת מלך ישראל לעתיד, ובאילו צורות תתבטא מלכותו, והרי שהיתה זו זכות לר' זירא לראות את פני המלך!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעא לעולא\u0004 לפני שנסע עולא לבבל: \u0003כי עיילת להתם\u0004 \u0005[\u0006כאשר \u0005תיכנס,\u0006 תבוא \u0005לשם,\u0006 לבבל\u0005]\u0006 \u0003שאיל בשלמא\u0004 \u0005[שאל בשלומו]\u0006 של \u0003רב ברונא אחי במעמד כל החבורה,\u0004 שהוא ראוי לכך, ש\u0003אדם גדול הוא ושמח במצות.\u0004 וראיה לדבר: \u0003זימנא חדא\u0004 \u0005[פעם אחת]\u0006 \u0003סמך גאולה לתפלה\u0004 בשעת הנץ החמה כותיקין (תוספות) \u0003ולא פסיק חוכא מפומיה כוליה יומא\u0004 \u0005[הפסיק צחוק\u0006 שמחה \u0005מפיו כל היום].\u0006","לעצם הענין שואלים: \u0003היכי מצי סמיך\u0004 \u0005[כיצד יתכן לסמוך]\u0006 גאולה לתפילה \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן: בתחלה\u0004 לפני התפילה \u0003הוא אומר: \"ה' שפתי תפתח\u0004 ופי יגיד תהלתך\" (תהלים נא, יז), \u0003ולבסוף,\u0004 אחר התפילה, \u0003הוא אומר: \"יהיו לרצון אמרי פי\u0004 והגיון לבי לפניך ה' צורי וגואלי\" (שם יט, טו), ואם כן יש פסוק המפריד בין גאולה לתפילה!","\u0003אמר ר' אלעזר: תהא\u0004 אמירה זו של הפסוק \"ה' שפתי תפתח\" \u0003בתפלה של ערבית\u0004 ולא בשחרית.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן: איזהו בן העולם הבא\u0004 — \u0003זה הסומך גאולה של ערבית לתפלה של ערבית,\u0004 ואם כן גם אז אין לומר פסוק קודם תפילה!","\u0003אלא אמר ר' אלעזר: תהא\u0004 אמירה זו \u0003בתפלת המנחה\u0004 שרק לפניה מקדימים לומר \"ה' שפתי תפתח\".","\u0003רב אשי אמר\u0004 הסבר אחר: \u0003אפילו תימא אכולהו\u0004 \u0005[תאמר\u0006 כי \u0005על\u0006 התפילות \u0005כולן]\u0006 אף שחרית וערבית אמר ר' יוחנן לפתוח בפסוק הבקשה, אלא \u0003כיון דקבעוה רבנן\u0004 \u0005[שקבעוהו חכמים],\u0006 לפסוק זה \u0003בתפלה\u0004 — הרי \u0003כתפלה אריכתא\u0004 \u0005[ארוכה]\u0006 \u0003דמיא\u0004 \u0005[\u0006היא \u0005נחשבת]\u0006 ונעשה חלק בלתי נפרד מן התפילה, ואם סומכים לו את ברכת הגאולה הרי זה כסמיכת גאולה לתפילה.","והביא ר' אשי חיזוק לדבריו: \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך],\u0006 אם כן ב\u0003ערבית היכי מצי סמיך\u0004 \u0005[כיצד יכול\u0006 הוא \u0005לסמוך],\u0006 שאפילו נאמר שאינו צריך לפתוח בפסוק \"ה' שפתי תפתח\" אף על פי כן \u0003הא בעי למימר\u0004 \u0005[הרי\u0006 הוא \u0005צריך לומר]\u0006 \u0003\"השכיבנו\"\u0004 לאחר ברכת הגאולה! \u0003אלא\u0004 ודאי יש לומר כי \u0003כיון דתקינו רבנן\u0004 \u0005[שתקנו חכמים]\u0006 לומר \u0003\"השכיבנו\"\u0004 — הרי \u0003כגאולה אריכתא דמיא\u0004 \u0005[ארוכה\u0006 היא \u0005נחשבת],\u0006 כהמשך ברכת הגאולה. \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 צריך לומר \u0003כיון\u0004 ש\u0003קבעוה רבנן\u0004 \u0005[קבעוהו חכמים]\u0006 לפסוק זה \u0003בתפלה\u0004 — \u0003כתפלה אריכתא דמיא\u0004 \u0005[ארוכה\u0006 היא \u0005נחשבת].\u0006","על סיום התפילה בפסוק \"יהיו לרצון\" וכו', דנים: \u0003מכדי, האי\u0004 \u0005[הרי, אותו]\u0006 \u0003\"יהיו לרצון אמרי פי\" משמע לבסוף,\u0004 שאפשר להבינו כסיום התפילה, בבקשה שיירצו דברי המתפלל שכבר אמרם, \u0003ו\u0004אולם \u0003משמע מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003דבעינא למימר\u0004 \u0005[שאני רוצה לומר]\u0006 שאפשר להשתמש בהם גם כפתיחה: יהיו לרצון אמרי פי שאני רוצה לומר. ואם כן יש לשאול: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003תקנוהו רבנן\u0004 \u0005[חכמים]\u0006 שיאמר \u0003לאחר שמונה עשרה ברכות? לימרו מעיקרא\u0004 \u0005[שיאמרו\u0006 פסוק זה \u0005בתחילה]\u0006 לפני שמונה עשרה!","על כך \u0003אמר ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי: הואיל ולא אמרו דוד\u0004 לפסוק זה \"יהיו לרצון\" \u0003אלא לאחר שמונה עשרה פרשיות\u0004 בתהלים (בסוף פרק יט בתהלים), \u0003לפיכך תקינו רבנן\u0004 \u0005[תיקנו חכמים]\u0006 לאומרו \u0003לאחר שמונה עשרה ברכות.\u0004","וכאן מקשים: \u0003הני\u0004 \u0005[אלה]\u0006 \u0003שמונה עשרה\u0004 הן?! והלא \u0003תשע עשרה הויין\u0004 \u0005[הן],\u0006 שהרי הפסוק כתוב במזמור התשעה עשר בתהלים!","ומשיבים \u0003\"אשרי האיש\"\u0004 (כלומר, הפרק הראשון בתהלים) \u0003ו\"למה רגשו גוים\"\u0004 (הפרק השני) \u0003חדא פרשה\u0004 \u0005[\u0006פרשה \u0005אחת]\u0006 \u0003היא,\u0004 הרי שעד פרק יט יש רק שמונה עשר פרקים.","וראיה לדבר ששני הפרקים הראשונים בתהלים נחשבים תמיד כפרק אחד — וכפי ש\u0003אמר ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי: מאה ושלש פרשיות אמר דוד, ולא אמר \"הללויה\"\u0004 בהם, \u0003עד שראה במפלתן של רשעים,\u0004 ורק אז יכול היה לומר בלב שלם \"הללויה\", \u0003שנאמר: \"יתמו חטאים מן הארץ ורשעים עוד אינם, ברכי נפשי את ה' הללויה\"\u0004 (תהלים קד, לה).","ואף כאן תמוה הדבר: וכי \u0003הני\u0004 \u0005[אלה]\u0006 \u0003מאה ושלש\u0004 הם? והלא \u0003מאה וארבע הויין\u0004 \u0005[הם]!\u0006 \u0003אלא שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי \u0003\"אשרי האיש\" ו\"למה רגשו גוים\" חדא פרשה\u0004 \u0005[\u0006פרשה \u0005אחת]\u0006 \u0003היא.\u0004","וראיה נוספת לאחדות שני הפרקים הללו מובאת ממה ש\u0003אמר ר' שמואל בר נחמני אמר ר' יוחנן:\u0004"],["\u0003כל פרשה שהיתה חביבה על דוד, פתח בה ב\"אשרי\" וסיים בה ב\"אשרי\". פתח ב\"אשרי\", דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003: \"אשרי האיש\u0004 אשר לא הלך בעצת רשעים ובדרך חטאים לא עמד ובמושב לצים לא ישב\u0003\"\u0004 (תהלים א, א), \u0003וסיים ב\"אשרי\", דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004נשקו בר פן יאנף ותאבדו דרך כי יבער כמעט אפו \u0003אשרי כל חוסי בו\"\u0004 (שם ב, יב, סיום הפרק), הרי ששני הפרקים הינם בעצם פרק אחד.","בקשר לדרשה כי לא אמר דוד \"הללויה\" עד שראה במפלתם של רשעים, מסופר: \u0003הנהו בריוני דהוו בשבבותיה\u0004 \u0005[אותם בריונים שהיו בשכנותו]\u0006 של \u0003ר' מאיר והוו קא מצערו ליה טובא\u0004 \u0005[והיו מצערים אותו הרבה].\u0006 \u0003הוה קא בעי\u0004 \u0005[היה מבקש]\u0006 \u0003ר' מאיר רחמי עלויהו\u0004 \u0005[רחמים עליהם]\u0006 \u0003כי היכי דלימותו\u0004 \u0005[שימותו].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]\u0006 לר' מאיר \u0003ברוריא דביתהו\u0004 \u0005[אשתו]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003דעתך,\u0004 על מה סומך אתה בתפילה זו שימותו הבריונים — \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003: \"יתמו חטאים מן הארץ\"\u0004 (תהלים קד, לה), וסבור אתה כי טוב לעולם בכליון הרשעים, ואולם \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \"יתמו \u0003חוטאים\u0004 \"? והלא \"יתמו \u0003חטאים\u0004 \"\u0003כתיב\u0004 \u0005[נאמר],\u0006 ויש להתפלל לכליונה של הרישעות ולא של הרשע.","\u0003ועוד, שפיל לסיפיה דקרא\u0004 \u0005[רד,\u0006 המשך \u0005לסופו של הפסוק]\u0006 שנאמר שם \u0003\"ורשעים עוד אינם\", כיון\u0004 ש\u0003\"יתמו חטאים\"\u0004 מכאן והלאה כיצד אפשר יהא ש\u0003\"רשעים עוד אינם\",\u0004 כלומר, שאינם עוד רשעים? \u0003אלא בעי רחמי עלויהו דלהדרו\u0004 \u0005[בקש רחמים עליהם שיחזרו]\u0006 \u0003בתשובה,\u0004 וממילא יתקיים \u0003\"ורשעים עוד אינם\".\u0004","ראה ר' מאיר צדקת דברי ברוריה ו\u0003בעא רחמי עלויהו, והדרו\u0004 \u0005[ביקש רחמים עליהם, וחזרו]\u0006 \u0003בתשובה.\u0004","על פירוש חריף אחר של ברוריה מספרים: \u0003אמר לה ההוא מינא\u0004 \u0005[אותו מין]\u0006 \u0003לברוריא: כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"רני עקרה לא ילדה\u0004 פצחי רנה וצהלי לא חלה כי רבים בני שוממה מבני בעולה אמר ה'\" (ישעיה נד, א), וכי \u0003משום\u0004 שהיא \u0003לא ילדה\u0004 — \u0003רני?\u0004 האם עליה לשמוח?","על דברי הלגלוג הללו \u0003אמרה ליה\u0004 \u0005[לו]\u0006 ברוריה: \u0003שטיא, שפיל לסיפיה דקרא\u0004 \u0005[שוטה, רד לסופו של הכתוב],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"כי רבים בני שוממה מבני בעולה אמר ה'\".\u0004","\u0003אלא מאי\u0004 \u0005[מה]\u0006 הוא פירושו של הביטוי \u0003\"רני עקרה לא ילדה\"\u0004 — \u0003רני כנסת ישראל שדומה לאשה עקרה שלא ילדה בנים\u0004 המיועדים \u0003לגיהנם כותייכו\u0004 \u0005[כמותכם].\u0006","בביאור מקראות בתהלים, מסופר על תשובה שניתנה למין אחר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מינא\u0004 \u0005[אותו מין]\u0006 \u0003לר' אבהו,\u0004 הרי \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003: \"מזמור לדוד בברחו מפני אבשלום בנו\"\u0004 (תהלים ג, א), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 כמו כן: \u0003\"\u0004למנצח אל תשחת \u0003לדוד מכתם בברחו מפני שאול במערה\"\u0004 (תהלים נז, א). \u0003הי\u0004 \u0005[איזה]\u0006 \u0003מעשה הוה ברישא\u0004 \u0005[היה בראשונה]?\u0006 \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003מעשה שאול הוה ברישא\u0004 \u0005[היה בראשונה],\u0006 והיה ראוי \u0003לכתוב ברישא\u0004 \u0005[שיכתוב\u0006 אותו \u0005בתחילה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו: \u0003אתון דלא דרשיתון\u0004 \u0005[אתם שאינכם דורשים]\u0006 \u0003סמוכין\u0004 — \u0003קשיא לכו\u0004 \u0005[קשה לכם],\u0006 ואולם \u0003אנן דדרשינן\u0004 \u0005[אנחנו שאנו דורשים]\u0006 \u0003סמוכין\u0004 — \u0003לא קשיא לן\u0004 \u0005[אינו קשה לנו],\u0006 שדרך חכמי ישראל ללמוד מתוך עצם סמיכותם וצירופם של מקראות כמה הלכות ולקחים מוסרים.","ועל אלה \u0003אמר ר' יוחנן: סמוכין מן התורה מנין,\u0004 כלומר, היכן נרמז לנו במקרא עצמו שיש מקום לדרוש סמיכות הפסוקים — \u0003שנאמר: \"\u0004מעשי ידיו אמת ומשפט נאמנים כל פקודיו \u0003סמוכים לעד לעולם עשוים באמת וישר\"\u0004 (תהלים קיא, ז–ח), ומכאן שראוי ללמוד אף מסמיכות פקודי ה'. ולדרשה זו הטעם להקדמת פרשת בריחת דוד מאבשלום, הוא בסמיכותה לפרק המספר על מלחמת גוג ומגוג (תהילים ב׳:א׳ \"למה רגשו גוים\").","\u0003למה נסמכה פרשת אבשלום לפרשת גוג ומגוג\u0004 — \u0003שאם יאמר לך אדם\u0004 מתוך פקפוק בנבואה בענין מלחמת גוג ומגוג (\"על ה' ועל משיחו\"): \u0003כלום יש עבד שמורד ברבו?!\u0004 כלומר, וכי יש אדם המסוגל למרוד בה'? \u0003אף אתה אמור לו: כלום יש בן שמורד באביו\u0004 ומנתק כל רגשות הטובה על הוייתו ועל גידולו? \u0003אלא\u0004 למרות זאת \u0003הוה\u0004 \u0005[היה]\u0006 בן כזה — אבשלום, \u0003הכא נמי הוה\u0004 \u0005[כאן גם כן היה,\u0006 יכול להיות\u0005]\u0006 שיווצר מצב שיבקשו בני אדם למרוד בה'.","פירוש על מזמורי תהלים אחרים \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי.\u0004 וכפתיחה לדבר אמר: \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר],\u0006 מה משמעות הפסוק \u0003\"פיה פתחה בחכמה ותורת חסד על לשונה\"\u0004 (משלי לא, כו) האמור בין שבחיה של \"אשת חיל\". מאחר שהפרק נדרש על חכמת התורה והעוסקים בה, \u0003כנגד מי אמר שלמה מקרא זה?\u0004 — \u0003לא אמרו אלא כנגד דוד אביו\u0004 שהיה הביטוי השלם של מי שפתח פיו בחכמה, \u0003שדר בחמשה עולמים\u0004 — חמישה שלבים של חיים, \u0003ואמר שירה,\u0004 שירת נפשו נגד כל אחד מהם. שחמש הפעמים שאומר דוד \"ברכי נפשי את ה'\" מפורשות כאן, כל אחת ביחסה ל\"עולם\" אחר.","\u0003דר במעי אמו, ואמר שירה\u0004 של שבח על תקופת ההריון, \u0003שנאמר: \"\u0004לדוד \u0003ברכי נפשי את ה' וכל קרבי את שם קדשו\"\u0004 (תהלים קג, א), שהוא מודה לה' על שיצר את קרבי אמו.","\u0003יצא לאויר העולם ונסתכל בכוכבים ומזלות, ואמר שירה,\u0004 שאחר השבח על בריאתו, ראוי לשבח את ה' על ברואיו הכוללים הגדולים, \u0003שנאמר: \"ברכו ה' מלאכיו גברי כח עושי דברו לשמע בקול דברו. ברכו ה' כל צבאיו\u0004 משרתיו עושי רצונו. ברכו ה' כל מעשיו בכל מקומות ממשלתו ברכי נפשי את ה'\" (תהלים קג, כ–כב), שהוא רואה את גודלם ומכיר שאינם אלא משרתיו עושי רצונו של הבורא (מעין הברכות).","\u0003ינק משדי אמו ונסתכל בדדיה ואמר שירה, שנאמר: \"ברכי נפשי את ה' ואל תשכחי כל גמוליו\"\u0004 (שם, ב), וקשר הדברים הוא מן המלה \"גמוליו\" המתקשרת עם \"גמולי מחלב\" (ישעיהו כח, ט).","ואולם עדיין יש מקום לבאר \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כל גמוליו\",\u0004 מה הוא השבח המיוחד שגמל ה' בכך, מלבד המזון לתינוק. \u0003אמר ר' אבהו! שעשה לה\u0004 לאשה \u0003דדים במקום בינה,\u0004 כלומר, ליד הלב מקור הבינה, ולא כרוב בעלי חיים.","\u0003וטעמא מאי\u0004 \u0005[ומה טעם]\u0006 עשה כן ה'? \u0003אמר ר' יהודה: כדי שלא יסתכל\u0004 הילד היונק \u0003במקום ערוה. רב מתנא אמר: כדי שלא יינק ממקום הטנופת\u0004 (הערוה).","שירה נוספת אמר דוד כאשר \u0003ראה\u0004 בחזון ובמציאות \u0003במפלתן של רשעים, ואמר שירה, שנאמר: \"יתמו חטאים מן הארץ ורשעים עוד אינם ברכי נפשי את ה' הללויה\"\u0004 (תהלים קד, לה).","ועוד עולם חמישי — \u0003נסתכל ביום המיתה, ואמר שירה, שנאמר: \"ברכי נפשי את ה', ה' אלהי גדלת מאד הוד והדר לבשת\"\u0004 (שם, א), שאף המוות הינו לצדיק עת של התעלות.","הקשר בין השבח האחרון לבין יום המיתה אינו ברור, ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כיצד אפשר להבין ש\u0003על יום המיתה נאמר?\u0004 ומשיבים: \u0003אמר רבה בר רב שילא,\u0004 אפשר ללמוד זאת \u0003מסיפא דעניינא\u0004 \u0005[מסוף הענין,\u0006 סוף הפרק\u0005],\u0006 שבפסוקיו האחרונים \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"תסתיר פניך יבהלון תוסף רוחם יגועון\u0004 ואל עפרם ישובון\" (שם, כט).","באותו פסוק עצמו קשורים עוד פירושים אחדים. מסופר כי \u0003רב שימי בר עוקבא ואמרי ליה\u0004 \u0005[ויש שאומרים]\u0006 שהיה זה \u0003מר עוקבא, הוה שכיח קמיה\u0004 \u0005[היה מצוי,\u0006 ללמוד \u0005לפני]\u0006 \u0003ר' שמעון בן פזי\u0004 שהיה בקי באגדה, שכן \u0003הוה\u0004 \u0005[היה]\u0006 \u0003מסדר אגדתא קמיה\u0004 \u0005[דברי אגדה לפני]\u0006 \u0003ר' יהושע בן לוי.\u0004 פעם \u0003אמר ליה\u0004 \u0005[לו]\u0006 לר' שמעון בן פזי: \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר],\u0006 מה משמעות הכתוב \u0003\"ברכי נפשי את ה' וכל קרבי את שם קדשו\"? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בא וראה שלא כמדת הקדוש ברוך הוא מדת בשר ודם.\u0004 שפסוק זה הוא שבח על יצירת האדם ברחם אמו. שכן \u0003בשר ודם צר צורה\u0004 (מצייר) \u0003על גבי הכותל\u0004 בגלוי, \u0003ו\u0004אף על פי כן \u0003אינו יכול להטיל בה\u0004 בצורה זו \u0003רוח ונשמה קרבים ובני מעים. ו\u0004אילו \u0003הקדוש ברוך הוא אינו כן,\u0004 שהוא \u0003צר צורה בתוך צורה\u0004 (את הולד ברחם האם) \u0003ומטיל בה רוח ונשמה קרבים ובני מעים. והיינו\u0004 \u0005[וזוהי]\u0006 גם הדרשה במה ש\u0003אמרה חנה\u0004 על לידת שמואל: \u0003\"אין קדוש כה' כי אין בלתך ואין צור כאלהינו\"\u0004 (שמואל א ב, ב),","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין צור כאלהינו\"\u0004 — \u0003אין צייר כאלהינו.\u0004 ומוסיפים עוד לדרוש את המשכו של פסוק זה.","\u0003מאי\u0004 \u0005[מה,\u0006 משמעות\u0005]\u0006 הכתוב \u0003\"כי אין בלתך\"? אמר ר' יהודה בן מנסיא: אל תקרי\u0004 \u0005[תקרא,\u0006 אל תבין\u0005]\u0006 \u0003\"כי אין בלתך\", אלא \"אין לבלותך\", \"\u0004שהמלה \"בלתך\" נדרשת כאילו היתה כתובה \"בלותך\" — לבלות אותך. כי \u0003שלא כמדת הקדוש ברוך הוא מדת בשר ודם: מדת בשר ודם\u0004 — \u0003מעשה ידיו מבלין אותו,\u0004 שהם מאריכים ימים אחריו, \u0003ו\u0004אילו \u0003הקדוש ברוך הוא מבלה\u0004 את \u0003מעשיו.\u0004","דברים אלה לא סיפקו את רב שימי בר עוקבא, ולכך \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא הכי קא אמינא\u0004 \u0005[אני כך אני אומר]\u0006 \u0003לך,\u0004 כלומר, זו היתה כוונתי בשאלה: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003חמשה \"ברכי נפשי\" כנגד מי אמרן דוד?\u0004 ענה לו: \u0003לא אמרן אלא כנגד הקדוש ברוך הוא, וכנגד\u0004 ה\u0003נשמה,\u0004 שכן \"ברכי נפשי את ה'\" הוא קביעת היחס בין נשמת האדם לבין ה', וחמישה \"ברכי נפשי\" הינם חמשה צדדים של דמיון בין נשמת האדם בגופו לבין כוח ה' בעולמו.","\u0003מה הקדוש ברוך הוא מלא כל העולם\u0004 — \u0003אף נשמה מלאה את כל הגוף. מה הקדוש ברוך הוא רואה ואינו נראה\u0004 — \u0003אף נשמה רואה ואינה נראית. מה הקדוש ברוך הוא זן את כל העולם כלו\u0004 — \u0003אף נשמה זנה את כל הגוף. מה הקדוש ברוך הוא טהור\u0004 — \u0003אף נשמה טהורה. מה הקדוש ברוך הוא יושב בחדרי חדרים\u0004 — \u0003אף נשמה יושבת בחדרי חדרים\u0004 (בסתר). ולכן \u0003יבא מי שיש בו חמשה דברים הללו\u0004 (הנפש) \u0003וישבח למי שיש בו חמשה דברים הללו.\u0004","בקשר לענין גאולה ותפילה מסופר על מחלת חזקיהו, ועל תפילתו לה' ורפואתו. וכך \u0003אמר רב המנונא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 מה משמעות הכתוב המדבר בשבח הקדוש ברוך הוא \u0003\"מי כהחכם ומי יודע פשר דבר\"\u0004 (קהלת ח, א) — \u0003מי כהקדוש ברוך הוא שיודע לעשות פשרה\u0004 (\"פשר דבר\" במשמעות — פשרה) \u0003בין שני צדיקים, בין חזקיהו\u0004 מלך יהודה \u0003לישעיהו\u0004 הנביא. שהיתה מחלוקת ביניהם מי מהם צריך ללכת לחבירו. \u0003חזקיהו אמר: ליתי\u0004 \u0005[יבוא]\u0006 \u0003ישעיהו גבאי\u0004 \u0005[אלי],\u0006 \u0003דהכי אשכחן\u0004 \u0005[ש\u0006כן \u0005כך מצאנו]\u0006 \u0003באליהו\u0004 הנביא \u0003דאזל לגבי\u0004 \u0005[שהלך אצל]\u0006 \u0003אחאב\u0004 מלך ישראל, שנאמר: \u0003\"וילך אליהו להראות אל אחאב\"\u0004 וגו' (מלכים א יח, ב), הרי שהנביא צריך ללכת אל המלך. ו\u0003ישעיהו אמר: ליתי\u0004 \u0005[יבוא]\u0006 \u0003חזקיהו גבאי\u0004 \u0005[אלי]\u0006 \u0003דהכי אשכחן\u0004 \u0005[ש\u0006כן \u0005כך מצאנו]\u0006 \u0003ביהורם בן אחאב\u0004 מלך ישראל \u0003דאזל לגבי\u0004 \u0005[שהלך אצל]\u0006 \u0003אלישע\u0004 הנביא, כפי שנאמר: \"וירדו אליו מלך ישראל ויהושפט מלך אדום\" (מלכים ב ג, יב).","\u0003מה עשה הקדוש ברוך הוא\u0004 לפשר בין שניהם — \u0003הביא יסורין\u0004 של מחלה \u0003על חזקיהו, ואמר לו לישעיהו: לך ובקר את החולה.\u0004 ואכן כך עשה ישעיהו, וכפי \u0003שנאמר: \"בימים ההם חלה חזקיהו למות ויבא אליו ישעיהו בן אמוץ הנביא ויאמר אליו כה אמר ה' צבאות צו לביתך כי מת אתה ולא תחיה\" וגו'\u0004 (ישעיהו לח, א), ומבררים את דברי הנביא: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003\"כי מת אתה ולא תחיה\"\u0004 — משמעות הכפילות היא: \"מת אתה\" — \u0003בעולם הזה, ו\"לא תחיה\"\u0004 — \u0003לעולם הבא,\u0004 שלא יהא חלקו בעולם הבא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 חזקיהו: \u0003מאי כולי האי\u0004 \u0005[מה כל זה]?\u0006 במה חטאתי שאענש כך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003משום\u0004 ש\u0003לא עסקת בפריה ורביה,\u0004 שלא נשא חזקיהו אשה עד אז. התנצל חזקיהו ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 לישעיהו: \u0003משום דחזאי לי\u0004 \u0005[שראיתי]\u0006 \u0003ברוח הקדש דנפקו מינאי בנין דלא מעלו\u0004 \u0005[שיצאו ממני בנים שאינם מעולים,\u0006 בנים רעים\u0005],\u0006 ואכן, בנו היה מנשה שהרבה לחטוא, וחשב שמוטב שלא יהיו לו בנים כלל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ישעיהו: \u0003בהדי כבשי דרחמנא\u0004 \u0005[בסתריו של הקדוש ברוך הוא]\u0006 \u0003למה לך\u0004 להתעסק? \u0003מאי דמפקדת איבעי לך למעבד\u0004 \u0005[מה שצווית\u0006 במצוות פריה ורביה \u0005היית צריך לעשות],\u0006 \u0003ומאי דניחא קמיה קודשא בריך הוא\u0004 \u0005[ומה שנוח בעיני הקדוש ברוך הוא]\u0006 — \u0003לעביד\u0004 \u0005[יעשה].\u0006","כיון שכך החליט ו\u0003אמר ליה\u0004 \u0005[לו],\u0006 לישעיהו: \u0003השתא הב\u0004 \u0005[עתה תן]\u0006 \u0003לי ברתך\u0004 \u0005[\u0006את \u0005בתך]\u0006 לאשה, \u0003אפשר דגרמא זכותא דידי ודידך, ונפקי מנאי בנין דמעלו\u0004 \u0005[אולי שתגרום זכותי וזכותך, ויצאו ממני בנים מעולים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ישעיהו: \u0003כבר נגזרה עליך גזירה,\u0004 ואין גזר דינך יכול להשתנות עוד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 חזקיהו: \u0003בן אמוץ, כלה נבואתך וצא!\u0004","שכל עוד דיבר הנביא בשליחות ה' חייב חזקיהו לשמוע לכל דבריו, אך אינו חייב לקבל את דעתו הפרטית של הנביא שאין לו עוד פתח לרחמים ולרפואה, כי \u0003כך מקובלני מבית אבי אבא\u0004 (הוא דוד המלך, אבי שושלת מלכי יהודה) ש\u0003אפילו\u0004 כאשר \u0003חרב חדה מונחת על צוארו של אדם, אל ימנע עצמו מן הרחמים,\u0004 ויכול הוא לקוות כי ייענה, כדרך שאירע לדוד עצמו כשראה את המלאך המשחית, ובכל זאת בקש רחמים ונענה. לענין זה שאין להתיאש מרחמי ה' מביאים סיוע מדברי חכמים.","שכן \u0003אתמר נמי\u0004 \u0005[נאמר גם כן],\u0006 \u0003ר' יוחנן ור' אליעזר דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אפילו חרב חדה מונחת על צוארו של אדם, אל ימנע עצמו מן הרחמים.\u0004 וראיה לדבר ממה \u0003שנאמר\u0004 בדברי איוב: \u0003\"הן יקטלני לו איחל\"\u0004 וגו' (איוב יג, טו). כלומר, אף כשהוא עומד להרגני, עדיין מייחל אני לרחמיו."],["וכן \u0003אמר ר' חנן: אפילו בעל החלומות,\u0004 אף אם בחלום אמיתי הבא על ידי מלאך (מעין הברכות), \u0003אומר לו לאדם\u0004 בחלומו כי \u0003למחר הוא\u0004 (כלומר, אתה) \u0003מת\u0004 — \u0003אל ימנע עצמו מן הרחמים. שנאמר: \"כי ברב חלמות והבלים ודברים הרבה כי את האלהים ירא\"\u0004 (קהלת ה, ו). ואף שנראה לו כי החלום אמיתי הוא, אפשר לחשוב אותו לדבר הבל ולבטוח בה'.","לאחר ששמע חזקיהו את הנבואה הקשה, \u0003מיד \"ויסב חזקיהו פניו אל הקיר ויתפלל אל ה'\"\u0004 (ישעיה לח, ב).","שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות \u0003\"קיר\"\u0004 לעניינו? כלומר, מדוע הסב חזקיה פניו לקיר? \u0003אמר ר' שמעון בן לקיש:\u0004 הרי זה ביטוי סמלי, ומשמעו שהתפלל אל ה' \u0003מקירות לבו,\u0004 וכפי \u0003ש\u0004אכן \u0003נאמר\u0004 בכתוב אחר: \u0003\"מעי מעי אוחילה קירות לבי\u0004 הומה לי לבי\u0003\"\u0004 (ירמיה ד, יט).","\u0003ר' לוי אמר:\u0004 חזקיהו התכוון להזכיר \u0003על עסקי קיר,\u0004 וכך \u0003אמר לפניו,\u0004 לפני ה': \u0003רבונו של עולם, ומה שונמית שלא עשתה אלא\u0004 עלית \u0003קיר אחת קטנה\u0004 עבור הנביא אלישע \u0003החיית את בנה, אבי אבא\u0004 (שלמה המלך) \u0003שחפה את ההיכל כולו בכסף ובזהב על אחת כמה וכמה\u0004 ראוי הוא שיחיו למענו את בן בנו. אמר חזקיהו בתפילתו: \"ויאמר אנא ה' \u0003זכר נא את אשר התהלכתי לפניך באמת ובלב שלם והטוב בעיניך עשיתי\u0004 ויבך חזקיהו בכי גדול\" (ישעיה לח, ג).","ושואלים \u0003מאי\u0004 \u0005[מהו]\u0006 במיוחד \u0003\"והטוב בעיניך עשיתי\"?\u0004 ובכך נחלקו הדעות; \u0003אמר רב יהודה אמר רב\u0004 שהזכיר את זכותו \u0003שסמך גאולה לתפלה\u0004 עם הנץ החמה, ולא איחר לישון כמנהג המלכים (עיון יעקב). ואילו \u0003ר' לוי אמר: שגנז ספר רפואות,\u0004 שהיו הכל סומכים עליו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ששה דברים\u0004 שיש בהם משום חידוש \u0003עשה חזקיהו המלך, על שלשה הודו לו\u0004 (הסכימו עמו) חכמי דורו, \u0003ועל שלשה לא הודו לו.\u0004","\u0003על שלשה\u0004 אלה \u0003הודו לו: גנז ספר רפואות\u0004 — \u0003והודו לו. כתת נחש הנחשת\u0004 שנעשו בו נסים לישראל (במדבר כא, ט), ומכיון שעשו אותו לעבודה זרה כיתת אותו (מלכים ב יח, ד) — \u0003והודו לו. גירר עצמות אביו\u0004 המלך אחז שהיה רשע \u0003על מטה של חבלים,\u0004 שלא נהג בקבורתו כבוד הראוי למלך (יעויין בדברי הימים ב כח, כז) — \u0003והודו לו\u0004 חכמים.","\u0003ו\u0004אילו \u0003על שלשה\u0004 מעשים אחרים שעשה \u0003לא הודו לו\u0004 חכמי דורו: \u0003סתם מי גיחון\u0004 (הוא נחל השילוח) והעביר את מימיו אל תוך העיר בניקבה (שם לב, ל) — \u0003ולא הודו לו, קצץ דלתות היכל ושגרם\u0004 (שלחם) \u0003למלך אשור\u0004 (מלכים ב יח, טז) — \u0003ולא הודו לו, עבר ניסן בניסן,\u0004 שהחליט על תוספת חודש נוסף לעיבור השנה בחודש ניסן עצמו, בעוד שהעיבור צריך להיעשות לכל המאוחר בחודש אדר (עיין דברי הימים ב ל, ב).","על מעשהו זה של חזקיהו תמהים: \u0003ומי לית ליה\u0004 \u0005[האם אין לו]\u0006 \u0003לחזקיהו,\u0004 האינו מסכים לדבר המקובל כי \u0003\"החדש הזה לכם ראש חדשים\u0004 ראשון הוא לכם לחדשי השנה\" (שמות יב, ב), שמשמע ממנו: \u0003זה ניסן ואין אחר ניסן?!\u0004 וכיצד יכול היה להוסיף עוד ניסן אחד, שלא ככתוב בתורה?","ומשיבים כי לא כך היה מעשה \u0003אלא,\u0004 חזקיהו \u0003טעה ב\u0004שיטתו של \u0003שמואל\u0004 (טעה בהלכה אשר לאחר דורות ניסח אותה שמואל), ש\u0003אמר שמואל: אין מעברין את השנה ביום שלשים של\u0004 חודש \u0003אדר, הואיל וראוי לקובעו\u0004 ליום זה כראש חודש \u0003ניסן.\u0004 כי ביום השלושים של כל חודש עשויים לבוא עדים אשר ראו את הירח בחידושו, ועל ידי כך קובעים כי זה הוא היום הראשון בחודש הבא. על כן אין לעבר את השנה ביום שלושים של אדר, כיון שיש אפשרות שיום זה יהא היום הראשון בניסן, ולכן לא היתה דעת חכמי הדור נוחה כשעיבר המלך את השנה ביום שלושים באדר. ואולם חזקיהו עצמו \u0003סבר: \"הואיל וראוי\"\u0004 — \u0003לא אמרינן\u0004 \u0005[איננו אומרים],\u0006 שלדעתו אין להמנע מעיבור השנה ביום זה, רק משום האפשרות.","ומתוך העיון בתפילת חזקיהו, \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' יוסי בן זמרא: כל התולה\u0004 תפילה או בקשה \u0003בזכות עצמו,\u0004 אף כשה' נענה לו — \u0003תולין לו בזכות אחרים. ו\u0004להיפך, \u0003וכל ה\u0004צנוע ו\u0003תולה\u0004 תפלתו \u0003בזכות אחרים\u0004 — \u0003תולין לו בזכות עצמו.\u0004","וראיה לדבר ממשה רבינו, שכן \u0003משה\u0004 כשביקש מחילה מה' על חטא העגל \u0003תלה בזכות אחרים, שנאמר: \"זכר לאברהם ליצחק ולישראל עבדיך\u0004 אשר נשבעת להם בך ותדבר אליהם ארבה את זרעכם ככוכבי השמים וכל הארץ הזאת אשר אמרתי אתן לזרעכם ונחלו לעולם \" (שמות לב, יג). וכאשר מסופר המעשה \u0003תלו לו\u0004 את סליחת ה' \u0003בזכות עצמו, שנאמר: \"ויאמר להשמידם לולי משה בחירו עמד בפרץ לפניו להשיב חמתו מהשחית\"\u0004 (תהלים קו, כג).","\u0003חזקיהו\u0004 ש\u0003תלה\u0004 את בקשתו \u0003בזכות עצמו, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003: \"זכר נא את אשר התהלכתי לפניך\" וגו'\u0004 (ישעיהו לח, ג), וכשנענה ה' לבקשתו \u0003תלה לו בזכות אחרים, שנאמר: \"וגנותי אל העיר הזאת להושיעה למעני ולמען דוד עבדי\"\u0004 (מלכים ב יט, לד), ולא הזכיר את זכותו של חזקיהו. \u0003והיינו\u0004 \u0005[וזהו]\u0006 מאמרו של \u0003ר' יהושע בן לוי.\u0004 ש\u0003אמר ר' יהושע בן לוי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"הנה לשלום מר לי מר\u0004 ואתה חשקת נפשי משחת בלי כי השלכת אחרי גוך כל חטאי \u0003\" (ישעיהו לח, יז) — שאפילו בשעה ששיגר\u0004 (שלח) \u0003לו הקדוש ברוך הוא שלום,\u0004 ובישר לו שיחלים מחוליו — \u0003מר הוא לו,\u0004 שלא התחשב ה' בזכותו שלו.","מאחר שהוזכרה עליית הקיר שעשתה האשה השונמית עבור הנביא אלישע, עוסקים עתה בכל אותה פרשה. השונמית הציעה לבעלה: \u0003\"נעשה נא עלית קיר קטנה\u0004 ונשים לו שם מיטה ושולחן וכסא ומנורה והיה בבואו אלינו יסור שמה\u0003\"\u0004 (מלכים ב ד, י).","ונחלקו \u0003רב ושמואל\u0004 בדעותיהם מה היתה אותה \"עלית קיר\", \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: עלייה\u0004 (קומה שניה) היתה להם על גגם, ו\u0003פרועה\u0004 (שאינה מקורה בגג) \u0003היתה, וקירוה\u0004 (עשו לה תקרה). \u0003וחד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: אכסדרה גדולה היתה\u0004 (מעין מרפסת סגורה) \u0003וחלקוה לשנים.\u0004","ומעירים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003אכסדרה\u0004 היתה זו וחילקוה לשנים, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 הביטוי \u0003\"קיר\",\u0004 שכל מה שהיה עליהם לעשות היה לבנות קיר באכסדרה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003עלייה\u0004 היתה זו, \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 הביטוי \u0003\"קיר\"?\u0004","ומשיבים: הוא מפרש \"קיר\" מלשון קירוי, שהיתה זו עליה \u0003שקירוה.\u0004","ומצד שני, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003עלייה\u0004 היתה זו, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 הביטוי \u0003\"עלית\". אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שהיתה זו \u0003אכסדרה מאי\u0004 \u0005[מה]\u0006 משמעות הביטוי \u0003\"עלית\"?\u0004","ומשיבים: לדעתו \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עלית\"\u0004 — \u0003מעולה שבבתים,\u0004 ולאו דווקא מקום גבוה.","ואגב ענין זה מביאים את דברי האשה השונמית לבעלה בענין הנביא אלישע: \u0003\"ונשים לו שם מטה ושלחן וכסא ומנורה\".\u0004","\u0003אמר אביי, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יצחק:\u0004 אדם גדול \u0003הרוצה להנות\u0004 מנדבת לבם של מכבדיו — \u0003יהנה,\u0004 ואין פסול בדבר, \u0003כאלישע\u0004 שנהנה מן השונמית ומאחרים. \u0003ושאינו רוצה להנות\u0004 — \u0003אל יהנה, כ\u0004מו שנהג \u0003שמואל הרמתי\u0004 שלא נהנה מן הבריות כלל. ומניין לנו? — \u0003שנאמר: \"ותשובתו הרמתה כי שם ביתו\u0004 ושם שפט את ישראל ויבן שם מזבח לה'\u0003\"\u0004 (שמואל א' ז, יז). \u0003ו\u0004כך ביאר ו\u0003אמר ר' יוחנן: שכל מקום שהלך שם\u0004 שמואל — \u0003ביתו עמו,\u0004 שלקח עמו את כל הנצרך לו כדי שלא יהנה מן הציבור. ויכול אדם לבחור בכל אחת מדרכים אלה.","עוד מסופר בענין השונמית: \u0003\"ותאמר אל אישה הנה נא ידעתי כי איש אלהים קדוש הוא\u0004 עובר עלינו תמיד\u0003\"\u0004 (מלכים ב ד, ט), \u0003אמר ר' יוסי בר' חנינא: מכאן שהאשה מכרת באורחין יותר מן האיש,\u0004 שהרי השונמית הכירה לפני בעלה בגדולת הנביא.","ועוד בענין זה, השונמית אומרת \u0003\"קדוש הוא\"\u0004 ושואלים: \u0003מנא\u0004 \u0005[מנין]\u0006 \u0003ידעה\u0004 שכן הוא? בכך נחלקו \u0003רב ושמואל. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: שלא ראתה זבוב עובר על שלחנו, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: סדין של פשתן הציעה על מטתו\u0004 ואף שהפשתן לבן ביותר וכל כתם נראה עליו \u0003לא ראתה קרי עליו\u0004 אף שעלול הדבר להתארע לאדם.","מהדגשת הדברים בפסוק זה \u0003\"קדוש הוא\"\u0004 לומד \u0003ר' יוסי בר' חנינא\u0004 כי השונמית רמזה בכך: \u0003הוא קדוש ו\u0004אולם \u0003משרתו\u0004 גיחזי \u0003אינו קדוש,\u0004 שלא ראתה בו כל סימן קדושה (עיון יעקב). וגם כאן הכירה כראוי, וכפי \u0003שנאמר\u0004 לאחר זמן: \u0003\"ויגש גיחזי להדפה\"\u0004 (שם ד, כז), ו\u0003אמר ר' יוסי בר' חנינא: שאחזה בהוד יפיה,\u0004 כלומר, כשדחף אותה אחזה בדדיה, בדרך פריצות.","על דברי הפסוק \u0003\"\u0004כי איש אלהים קדוש הוא \u0003עובר עלינו תמיד\"\u0004 (שם ד, ט), \u0003אמר ר' יוסי בר' חנינא משום\u0004 (בשם) \u0003ר' אליעזר בן יעקב:\u0004 מפסוק זה למדים בדרך רמז ש\u0003כל המארח תלמיד חכם בתוך ביתו ומהנהו מנכסיו\u0004 — \u0003מעלה עליו הכתוב כאילו מקריב תמידין.\u0004 ש\"איש אלהים עובר עלינו תמיד\", הרי זה כמו \"תמיד\".","\u0003ו\u0004עוד בדיני התפילה, \u0003אמר ר' יוסי בר' חנינא משום\u0004 (בשם) \u0003ר' אליעזר בן יעקב: אל יעמוד אדם במקום גבוה ויתפלל, אלא במקום נמוך ויתפלל.\u0004 ורמז לדבר ממה \u0003שנאמר: \"ממעמקים קראתיך ה'\"\u0004 (תהלים קל, א).","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 האומרת: \u0003לא יעמוד אדם לא על גבי כסא, ולא על גבי שרפרף, ולא במקום גבוה, ויתפלל, אלא במקום נמוך, ויתפלל.\u0004 וטעמו של דבר — \u0003לפי שאין גבהות לפני המקום. וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003: \"תפלה לעני כי יעטף\u0004 ולפני ה' ישפוך שיחו\u0003\"\u0004 (שם קב, א). שראוי לאדם שבתפילה ירגיש עצמו כעני המבקש בשפלות רוח.","\u0003ו\u0004עוד \u0003אמר ר' יוסי בר' חנינא משום ר' אליעזר בן יעקב: המתפלל צריך שיכוין את רגליו\u0004 שיצמידן זו לזו כרגל אחת, כדי להידמות בכך למלאכים, \u0003שנאמר\u0004 עליהם: \u0003\"ורגליהם רגל ישרה\"\u0004 (יחזקאל א, ז).","\u0003אמר ר' יצחק אמר ר' יוחנן ואמר ר' יוסי בר' חנינא משום ר' אליעזר בן יעקב: מאי דכתיב\u0004 \u0005[מהו שנאמר],\u0006 מה משמעות הכתוב \u0003\"לא תאכלו על הדם\"\u0004 (ויקרא יט, כו) — יש לפרשו: \u0003לא תאכלו קודם שתתפללו על דמכם.\u0004 שאין לאכול בבוקר קודם התפילה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 ש\u0003אמר ר' יצחק, אמר ר' יוחנן, אמר ר' יוסי בר' חנינא משום ר' אליעזר בן יעקב: כל האוכל ושותה, ואחר כך מתפלל — עליו הכתוב אומר\u0004 את תוכחת הנביא בשם ה': \u0003\"ואותי השלכת אחרי גוך\"\u0004 (מלכים א, יד, ט), וכוונתו לגבי כל אדם שאכל לפני שהתפלל, שהרי הוא משליך כאילו את ה' ומקדים לפניו את צרכי גוו, ואם כן הוא מעמיד את גאותו והכרת ערכו לעומת ה' (מהרש\"א), שכן \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"גוך\", אלא\u0004 כאילו היה כתוב \u0003\"גאיך\",\u0004 ופירושו: כך \u0003אמר הקדוש ברוך הוא: לאחר שנתגאה זה\u0004 ועסק בצרכי עצמו \u0003קבל עליו מלכות שמים.\u0004","שנינו במשנה ש\u0003ר' יהושע אומר\u0004 שסוף זמן קריאת שמע של שחרית הוא \u0003עד שלש שעות. אמר ר' יהודה אמר שמואל: הלכה\u0004 בענין זה \u0003כ\u0004שיטת \u0003ר' יהושע.\u0004","עוד שנינו במשנה כי \u0003הקורא מכאן ואילך,\u0004 לאחר שעבר זמן קריאת שמע \u0003לא הפסיד,\u0004 ושכרו כשל אדם הקורא בתורה. שהרי קריאת שמע פרק היא בתורה, והקורא בה, אף שלא בזמנה הריהו עוסק בתורה.","על דברים אלה \u0003אמר רב חסדא אמר מר עוקבא: ובלבד שלא יאמר\u0004 ברכת \"\u0003יוצר אור\u0004\" ושאר ברכות קריאת שמע, שכן ברכות אלה שייכות למצות קריאת שמע של שחרית, וכשקוראים קריאת שמע שלא בזמנה אין מקום לברכות.","על כך \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003הקורא מכאן ואילך לא הפסיד, כאדם שהוא קורא בתורה, אבל מברך הוא שתים לפניה ואחת לאחריה.\u0004 והוא היפך דברי רב חסדא. ומעירים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא על דברי \u0003רב חסדא, תיובתא\u0004 \u0005[קושיא].\u0006 ואכן נדחים דבריו מפני דברי הברייתא.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר רב חסדא אמר מר עוקבא\u0004 בדיוק להיפך: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות \u0003\"לא הפסיד\"\u0004 ששנינו במשנה — \u0003שלא הפסיד ברכות,\u0004 ומותר לו לברך ברכות אלה אפילו לאחר זמן הקריאה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כדבריו: \u0003הקורא מכאן ואילך לא הפסיד כאדם שקורא בתורה, אבל מברך הוא שתים לפניה ואחת לאחריה.\u0004","בהקשר לדברי המשנה, \u0003אמר ר' מני: גדול הקורא קריאת שמע בעונתה\u0004 (בזמנה) \u0003יותר מהעוסק בתורה.\u0004 וראיה לדבר — \u0003מדקתני\u0004 \u0005[ממה ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הקורא מכאן ואילך לא הפסיד כאדם הקורא בתורה. מכלל\u0004 הדבר אתה למד כי \u0003הקורא\u0004 קריאת שמע \u0003בעונתה\u0004 — \u0003עדיף\u0004 מזה שקורה שלא בזמנה ואינו אלא כקורא בתורה בלבד, שכן כשקורא קריאת שמע בזמנה הריהו מקיים באותה שעה גם מצוה של לימוד תורה וגם מצות קריאת שמע.","נחלקו בית שמאי ובית הלל על הדרך הראויה לקרוא בה את \"שמע\". \u0003בית שמאי אומרים:\u0004 יש לקרוא את פרשיות קריאת שמע כמשמען של המילים הכתובות בהן, ועל כן כשקוראים את קריאת שמע \u0003בערב\u0004 — \u0003כל אדם יטה\u0004 (ישכב מעט על צדו) \u0003ויקרא\u0004 קריאת שמע, ויקיים בזה \"ובשכבך\". \u0003ובבקר יעמוד\u0004 ויקיים בזה \"ובקומך\", וכפי \u0003שנאמר: \"בשכבך ובקומך\".\u0004","\u0003ובית הלל אומרים: כל אדם קורא כדרכו,\u0004 לפי המצב הנוח לו, בין ביום בין בלילה. וראיה לדבר ממה \u0003שנאמר\u0004 גם \u0003\"ובלכתך בדרך\",\u0004 כאשר אינו לא מוטה ולא עומד (מאירי).","ו\u0003אם כן\u0004 לדעת בית הלל \u0003למה נאמר \"בשכבך ובקומך\"\u0004 — לציון הזמן בלבד, \u0003בשעה שבני אדם שוכבים ובשעה שבני אדם עומדים.\u0004","בקשר להלכה זו \u0003אמר ר' טרפון\u0004 על עצמו: \u0003אני הייתי\u0004 פעם אחת \u0003בא בדרך\u0004 והפסקתי בדרכי \u0003והטתי לקרות כדברי בית שמאי,\u0004 כי אף שר' טרפון עצמו היה מבית הלל, סבר כי לקיים את המצוה כדרך בית שמאי יהיה מהודר יותר, ומוסכם לכל הדעות. \u0003ו\u0004אולם בכך \u0003סכנתי בעצמי\u0004 באותה שעה \u0003מפני הלסטים.\u0004","\u0003אמרו לו\u0004 חכמים: \u0003כדי היית\u0004 (ראוי היה לך) \u0003לחוב בעצמך,\u0004 להתחייב בנפשך, אפילו במיתה, לפי \u0003שעברת על דברי בית הלל,\u0004 וכפי שיבואר עוד ענין זה בגמרא."],["מתחילה מבררים את נימוקם של בית שמאי. \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בית הלל\u0004 — \u0003קא מפרשי טעמייהו וטעמא\u0004 \u0005[הריהם מפרשים טעמם וטעם]\u0006 \u0003בית שמאי,\u0004 שבית הלל מסבירים את הפסוקים שמהם ראיה לכאורה לשיטת בית שמאי על פי דרכם (\"ובשכבך\" — זמן שכיבה וכו'), ואף מוכיחים כי פירושם הוא המתקבל על הדעת (\"ובלכתך\"), \u0003אלא בית שמאי מאי טעמא לא אמרי\u0004 \u0005[מה טעם אינם אומרים]\u0006 \u0003כבית הלל?\u0004 מה אומרים הם כנגד דברי בית הלל?","על כך עונים, \u0003אמרי\u0004 \u0005[\u0006יכולים היו \u0005לומר]\u0006 \u0003לך בית שמאי: אם כן\u0004 שפירוש הכתוב לדעת בית הלל הריהו רק קביעת זמן, אם כן \u0003נימא קרא\u0004 \u0005[יאמר הכתוב]\u0006 \u0003\"בבוקר ובערב\",\u0004 ו\u0003מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 נאמר \u0003\"בשכבך ובקומך\"\u0004 במשמעות הכפולה? אלא ודאי הכוונה היא ש\u0003בשעת שכיבה\u0004 — תהא הקריאה ב\u0003שכיבה ממש, ובשעת קימה\u0004 — תהא הקריאה ב\u0003קימה ממש.\u0004","ועוד שואלים \u0003ובית שמאי: האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"ובלכתך בדרך\"\u0004 שבית הלל מוכיחים ממנו שכל אדם קורא כדרכו, \u0003מאי עבדי להו\u0004 \u0005[מה עושים להם]\u0006 בית שמאי בו בביאורם?","ומשיבים: הפסוק \u0003ההוא מבעי להו\u0004 \u0005[נצרך להם]\u0006 לבית שמאי כדי להוציא ממנו הלכות אחרות, \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]\u0006 הדורשת את המקרא הזה, שחיוב קריאת שמע חל \u0003\"בשבתך בביתך\"\u0004 — \u0003פרט לעוסק במצוה\u0004 שהוא פטור מקריאת שמע, \u0003\"ובלכתך בדרך\"\u0004 — \u0003פרט לחתן\u0004 שגם הוא פטור מן הקריאה. ובברייתא מוסיפים, \u0003מכאן,\u0004 ממדרש כתובים זה, \u0003אמרו: הכונס\u0004 (הנושא) \u0003את הבתולה\u0004 — \u0003פטור\u0004 מקריאת שמע בליל חופתו, \u0003ו\u0004כונס \u0003את האלמנה\u0004 — \u0003חייב.\u0004 מתחילה מבארים את הברייתא הזו לגופה.","ושואלים \u0003מאי משמע\u0004 \u0005[מהי המשמעות\u0006 בפסוק\u0005]\u0006 שממנו מסיקים כי משמעות הכתוב \"ובלכתך בדרך\" למעט חתן מחובת קריאת שמע?","\u0003אמר רב פפא,\u0004 כך למדים: \u0003כי\u0004 (כמו) \u0003דרך; מה דרך\u0004 הכתובה בפסוק מדברת בהולך בדרך \u0003רשות\u0004 שאינה מצוה עליו, \u0003אף כל\u0004 המחוייבים בקריאה עוסקים בפעולות \u0003רשות.\u0004 אך העוסק במצוה, כמו החתן, פטור מקריאה.","על כך מקשים: \u0003מי לא עסקינן\u0004 \u0005[האם איננו עוסקים]\u0006 אף במקרה \u0003דקא אזיל\u0004 \u0005[שהוא הולך]\u0006 \u0003לדבר מצוה,\u0004 שהרי בתורה כתוב סתם, בלי לפרט לשם מה היא ההליכה, ולכן ודאי היא כוללת את כל המקרים, \u0003ואפילו הכי\u0004 \u0005[כן]\u0006 \u0003אמר רחמנא\u0004 \u0005[הכתוב]:\u0006 \u0003לקרי\u0004 \u0005[לקרוא]\u0006 קריאת שמע. אלא ההוכחה היא מלשון הכתוב, שאם היתה הכוונה לכלול במצוה את הכל, \u0003אם כן לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"בשבת ובלכת\" מאי\u0004 \u0005[מה]\u0006 הלשון \u0003\"בשבתך ובלכתך\"?\u0004 — ודאי באו הכינויים להדגיש כי \u0003בשבת דידך\u0004 \u0005[בישיבה שלך]\u0006 \u0003ובלכת דידך\u0004 \u0005[שלך],\u0006 כאשר אתה עושה את הדברים למענך וברצונך \u0003הוא\u0004 המקרה \u0003דמחייבת\u0004 \u0005[ש\u0006אתה \u0003מחוייב]\u0004 בו בקריאה, \u0003הא\u0004 \u0005[אבל]\u0006 בשל \u0003מצוה\u0004 — \u0003פטירת\u0004 \u0005[פטור אתה],\u0006 כי הישיבה או ההליכה הינם ברצון ה'.","אם כן יש להסיק שכל העוסק בדבר שיש בו משום מצוה פטור מקריאת שמע, \u0003ואי הכי\u0004 \u0005[אם כן]\u0006 \u0003אפילו כונס את האלמנה נמי\u0004 \u0005[גם כן]\u0006 ייפטר מקריאת שמע, שהרי אף הוא עוסק במצוה ויפטר מן הקריאה, בניגוד למסקנת הברייתא?","ומשיבים כי בכל זאת יש הבדל בין הכונס בתולה ואלמנה: \u0003האי טריד\u0004 \u0005[זה\u0006 הכונס את הבתולה \u0005טרוד],\u0006 מפני שהוא חושש שמא לא תימצא כלתו בתולה, \u0003והאי לא טריד\u0004 \u0005[וזה\u0006 הכונס את האלמנה \u0005אינו טרוד].\u0006 נמצא איפוא שנפטר החתן מקריאה מפני שהוא טרוד במחשבתו.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום טרדא\u0004 (טרדה) נפטר אדם מקריאת שמע, אם כן \u0003אפילו טבעה ספינתו בים\u0004 והוא מודאג בשל כך, יפטר מן הקריאה! ומחזקים את השאלה, \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[כך הוא גם כן],\u0006 שבאמת אף מי שטבעה ספינתו ייפטר בשל כך, \u0003אלמה\u0004 \u0005[למה]\u0006 אם כן \u0003אמר רב אבא בר זבדא אמר רב\u0004 ש\u0003אבל חייב בכל המצות האמורות בתורה, חוץ מן התפילין,\u0004 שהוא פטור מהן, \u0003שהרי נאמר בהם\u0004 לשון \"פאר\", שנאמר: בכתוב ליחזקאל \u0003\"\u0004האנק דום מתים אבל לא תעשה \u0003פארך חבוש עליך\"\u0004 וכו' (יחזקאל כד, יז), ואין זה נאה שיהיה האבל עטור בתפילין שעליהן נאמר פאר (תוספות). ואם האבל הכואב וטרוד ביותר חייב בקריאת שמע, ודאי שכל הטרודים, ואף מי שטבעה ספינתו בים, והפסיד בכך רק כסף (ברכת ה') חייב בקריאת שמע, ומדוע אם כן נפטור את החתן בשל טרדתו, ולא את המאבד את רכושו?!","ומשיבים: יש בכל זאת הבדל, שכן \u0003התם\u0004 \u0005[שם,\u0006 בחתן\u0005]\u0006 \u0003טריד טרדא\u0004 \u0005[טרוד\u0006 הוא ב\u0005טרדה]\u0006 של \u0003מצוה,\u0004 שהרי דאגתו קשורה במצוה שעליו לעשות, ואילו \u0003הכא\u0004 \u0005[כאן,\u0006 במאבד ספינתו\u0005]\u0006 \u0003טריד טרדא\u0004 \u0005[טרוד\u0006 הוא\u0005]\u0006 טירדה של \u0003רשות.\u0004","ומכאן חוזרים לשאלה הראשונה: \u0003ובית שמאי\u0004 כיצד מפרשים הם את המלים \"בלכתך בדרך\"? (רש\"ש).","והם משיבים: הכתוב \u0003ההוא מבעי להו\u0004 \u0005[נצרך להם]\u0006 ללמד דבר אחר — \u0003פרט לשלוחי מצוה\u0004 שהם פטורים מקריאת שמע.","\u0003ובית הלל,\u0004 הלא ודאי גם הם מסכימים שהעוסקים במצוה פטורים מקריאת שמע, ולכאורה אין עוד תוקף לנימוק שהביאו מ\"בלכתך בדרך\"! והם מסבירים: \u0003ממילא,\u0004 מתוך הדברים הללו עצמם \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שאם אין אדם הולך בשליחות מצוה ש\u0003אפילו בדרך נמי קרי\u0004 \u0005[גם כן קורא].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא, \u0003בית הלל אומרים:\u0004 מותר לקרות קריאת שמע בכל מצב: \u0003עומדין וקורין, יושבין וקורין, ומטין וקורין, הולכין בדרך וקורין,\u0004 ואפילו \u0003עושין במלאכתן וקורין. ו\u0004בתוספתא מסופר \u0003מעשה\u0004 בשני התנאים \u0003ר' ישמעאל ור' אלעזר בן עזריה,\u0004 שניהם מתלמידי בית הלל, \u0003שהיו מסובין במקום אחד\u0004 עם תלמידיהם, \u0003והיה ר' ישמעאל מוטה\u0004 על המטה, כדרך המסובים, \u0003ו\u0004אילו \u0003ר' אלעזר בן עזריה\u0004 ישב \u0003זקוף. כיון שהגיע זמן קריאת שמע\u0004 של ערבית, \u0003הטה ר' אלעזר\u0004 וקרא קריאת שמע כשהוא מוטה, וכדעת בית שמאי. \u0003ו\u0004דווקא אז \u0003זקף ר' ישמעאל\u0004 וקרא זקוף. נראה שר' אלעזר נפגע, \u0003ואמר לו ר' אלעזר בן עזריה לר' ישמעאל: ישמעאל אחי, אמשול לך משל למה הדבר דומה\u0004 — \u0003משל לאחד שאומרים לו\u0004 כמחמאה \u0003זקנך מגודל\u0004 ונאה לך! \u0003אמר להם\u0004 אותו האיש: \u0003יהיה כנגד המשחיתים,\u0004 כלומר, אני מגדל זקן כדי להרגיז את המגלחים ומשחיתים את זקנם (רשב\"א). \u0003אף כך אתה, כל זמן שאני זקוף\u0004 — \u0003אתה מוטה, עכשיו כשאני הטתי\u0004 והריני כמשבח את מנהגך ועושה כדוגמתך \u0003אתה זקפת\u0004 כאילו כדי להראות שאתה נוהג ההיפך ממני.","\u0003אמר לו\u0004 ר' ישמעאל: \u0003אני עשיתי כדברי בית הלל\u0004 שלדעתם אפשר לקרוא קריאת שמע בכל מצב, \u0003ואתה עשית כדברי בית שמאי,\u0004 והרי שנהגתי כהלכה. \u0003ולא עוד אלא שמא יראו התלמידים ויקבעו הלכה לדורות\u0004 כדרך שנהגת אתה, ועל כן היה עלי להדגיש שאין זו חובה.","ושואלים בתלמוד: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"ולא עוד\"?\u0004 מדוע הצטרך ר' ישמעאל להוסיף נימוק אחר לדבריו, והרי לכאורה די היה לו לומר שנהג כבית הלל?","ומשיבים: חייב היה להוסיף נימוק זה, שכן \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003בית הלל נמי אית להו\u0004 \u0005[גם כן יש להם,\u0006 הם מסכימים\u0005]\u0006 שמותר לקרות כשהם \u0003מטין,\u0004 ויכול היה ר' ישמעאל להשאר מוטה גם לשיטת בית הלל, אלא \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא באופן שהוא \u0003מטה ואתא מעיקרא\u0004 \u0005[ובא מתחילה],\u0006 ובכגון זה ההטייה הריהי ככל מצב אחר. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 \u0003כיון\u0004 ש\u0003עד השתא\u0004 \u0005[עכשיו]\u0006 \u0003הוית\u0004 \u0005[היית]\u0006 \u0003זקוף והשתא\u0004 \u0005[ועכשיו]\u0006 \u0003מוטה, אמרי\u0004 \u0005[יאמרו]\u0006 התלמידים: \u0003שמע מינה\u0004 \u0005[למד ממנה,\u0006 מהטייה זו\u0005]\u0006 ש\u0003כבית שמאי סבירא להו\u0004 \u0005[סבורים הם],\u0006 וקיים חשש \u0003שמא יראו התלמידים ויקבעו הלכה לדורות\u0004 כבית שמאי. ולכן הוצרך ר' ישמעאל לזקוף.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יחזקאל:\u0004 מי ש\u0003עשה כדברי בית שמאי\u0004 — \u0003עשה,\u0004 ואין אומרים שלא נהג כהלכה, וכן מי שעשה \u0003כדברי בית הלל\u0004 — \u0003עשה,\u0004 שלדעה זו הודו בית הלל ובית שמאי זה לזה שאם עשה אדם מעשה כדעת החולקת — יצא. ואף שנקבעה הלכה כבית הלל, מכל מקום אף לבית הלל, הנוהג כבית שמאי — יצא.","ואילו \u0003רב יוסף אמר: עשה כדברי בית שמאי\u0004 — \u0003לא עשה ולא כלום,\u0004 וצריך לחזור ולעשות כדברי בית הלל. וראיה לדבר ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 בהלכות סוכה: \u0003מי שהיה ראשו ורובו\u0004 (רוב גופו) \u0003בסוכה, ושלחנו\u0004 שעליו הוא אוכל \u0003בתוך הבית, בית שמאי פוסלין,\u0004 שכן עשוי הוא להימשך אחר שולחנו ויתברר שאכילתו היתה מחוץ לסוכה. \u0003ובית הלל מכשירין,\u0004 שעדיין הוא נמצא ראשו ורובו בסוכה.","\u0003אמרו להם בית הלל לבית שמאי\u0004 כראיה לדבריהם: והלא \u0003מעשה שהלכו זקני בית שמאי וזקני בית הלל\u0004 בסוכות \u0003לבקר את ר' יוחנן בן החורנית, מצאוהו שהיה ראשו ורובו בסוכה ושלחנו בתוך הבית, ולא אמרו לו כלום.\u0004 הרי שאף בית שמאי לא מצאו פסול בדבר.","\u0003אמרו להם\u0004 בית שמאי: \u0003משם ראיה?!\u0004 לא כך היה המעשה, אלא \u0003אף הם אמרו לו\u0004 במפורש: \u0003אם כן היית נוהג לא קיימת מצות סוכה מימיך.\u0004 ומכאן אפשר להסיק כי לדעת החולקים, הנוהג כשיטה האחרת — לא יצא ידי חובתו כלל. ומשום כך כשנתקבלה להלכה שיטת בית הלל, כל העושה כדברי בית שמאי — לא יצא ידי חובתו.","\u0003רב נחמן בר יצחק אמר\u0004 דעה חריפה יותר: \u0003עשה כדברי בית שמאי\u0004 — \u0003חייב מיתה,\u0004 כלומר, חמור מעשהו עד מאד, עד שאפשר לומר שהוא חייב מיתה. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005],\u0006 \u0003אמר ר' טרפון\u0004 לחבריו: \u0003אני הייתי בא בדרך והטתי לקרות כדברי בית שמאי וסכנתי בעצמי מפני הלסטים, אמרו לו: כדאי היית לחוב ב\u0004מיתת \u0003עצמך, שעברת על דברי בית הלל.\u0004","מדיני קריאת שמע עצמה, עוברת המשנה לברכות הסמוכות לקריאת שמע. וכאן נקבע הסדר: לקריאת שמע של \u0003שחר מברך שתים לפניה,\u0004 האחת על המאורות, והשניה ברכת האהבה על התורה, \u0003ואחת לאחריה\u0004 הפותחת \"אמת ויציב\". \u0003ו\u0004אילו \u0003בערב מברך שתים לפניה\u0004 על המאורות ועל אהבת ה', \u0003ושתים לאחריה,\u0004 ברכת הגאולה המתחילה \"אמת ואמונה\", וברכת \"השכיבנו\". ועל ברכת \"אמת ואמונה\" הוא אומר כי \u0003אחת ארוכה ואחת קצרה,\u0004 כלומר, יכול הוא להאריך בה ויכול לקצר בה, כי בין שהיא ארוכה בין שהיא קצרה — יוצא הוא ידי חובה (תוספות).","ואולם בדרך כלל \u0003מקום שאמרו\u0004 שיש \u0003להאריך\u0004 בברכה — \u0003אינו רשאי לקצר,\u0004 ואף להיפך, \u0003לקצר\u0004 — \u0003אינו רשאי להאריך.\u0004 ואם אמרו חכמים \u0003לחתום\u0004 ולסכם את הברכה שנית באמירת \"ברוך\" וכו' בסיומה של הברכה — \u0003אינו רשאי שלא לחתום,\u0004 וכמו כן \u0003שלא לחתום\u0004 — \u0003אינו רשאי לחתום.\u0004","מתחילה מבררים את נוסחן של שתי הברכות שלפני קריאת שמע בשחרית, ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003מברך?\u0004","\u0003אמר ר' יעקב אמר ר' אושעיא:\u0004 הברכה מתרכזת בפסוק"],["\u0003\"יוצר אור ובורא חשך\u0004 עושה שלום ובורא רע אני ה' עושה כל אלה\" (ישעיה מה, ז).","על נוסחה של הברכה שואלים: ו\u0003לימא\u0004 \u0005[ויאמר]\u0006 בנוסח הברכה: \u0003\"יוצר אור ובורא נוגה\"\u0004 כדי לא לומר \"חושך\", שיש בו משום גנאי!","ומשיבים: \u0003כדכתיב קאמרינן\u0004 \u0005[כפי שנאמר אנו אומרים],\u0006 ואיננו משנים מנוסח המקרא.","את התשובה הזו מתקיפים: \u0003אלא מעתה \"עושה שלום ובורא רע\", מי קא אמרינן כדכתיב\u0004 \u0005[האם אומרים אנו כפי שנאמר]?!\u0006 \u0003אלא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"רע\" וקרינן\u0004 \u0005[ואנו קוראים]\u0006 \u0003\"הכל\"\u0004 שהוא \u0003לישנא מעליא\u0004 \u0005[לשון מעולה,\u0006 נקיה\u0005],\u0006 שלא להזכיר \"רע\", ואם כן \u0003הכא נמי לימא\u0004 \u0005[גם כאן יאמר]\u0006 \u0003\"נוגה\", לישנא מעליא\u0004 \u0005[בלשון נקיה]!\u0006","\u0003אלא אמר רבא:\u0004 הטעם שאנו מזכירים \"בורא חושך\" הוא \u0003כדי להזכיר מדת יום בלילה ומדת לילה ביום,\u0004 ועל ידי כך מצרפים את היום והלילה לאחדות שיש בה חלקים שונים.","ומוסיפים לשאול: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003מדת לילה ביום\u0004 מזכירים \u0003כדאמרינן\u0004 \u0005[כפי שאמרנו]:\u0006 \u0003\"יוצר אור ובורא חושך\", אלא מדת יום בלילה, היכי משכחת לה\u0004 \u0005[היכן מוצא אתה אותה]?\u0006 שהרי בברכת המאורות בלילה אין מזכירים \"יוצר אור\"?","\u0003אמר אביי:\u0004 בכל זאת מזכירים מדת יום בברכת הלילה במילים \u0003\"גולל אור מפני חשך וחשך מפני אור\".\u0004","ושואלים: \u0003ואידך מאי היא\u0004 \u0005[והאחרת מה היא]?\u0006 מה הוא נוסחה של הברכה האחרת מברכות קריאת שמע? \u0003אמר רב יהודה אמר שמואל: \"אהבה רבה\". וכן אורי ליה\u0004 \u0005[הורה לו]\u0006 \u0003ר' אלעזר לר' פדת בריה\u0004 \u0005[בנו],\u0006 שיש לומר \u0003\"אהבה רבה\".\u0004","ו\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אין אומרים \"אהבת עולם\", אלא \"אהבה רבה\". ו\u0004אף על פי כן \u0003רבנן אמרי\u0004 \u0005[חכמים אומרים]\u0006 שיש לומר \u0003\"אהבת עולם\", וכן הוא,\u0004 הכתוב, \u0003אומר,\u0004 וממנו סמך לכך: \u0003\"ואהבת עולם אהבתיך על כן משכתיך חסד\"\u0004 (ירמיהו לא, ג).","ברכת \"אהבה רבה\" עניינה הזכרת אהבת ה' לנו, ושבח על התורה. ולכן \u0003אמר רב יהודה אמר שמואל: השכים לשנות, עד שלא קרא קריאת שמע\u0004 — \u0003צריך לברך\u0004 ברכה מיוחדת על התורה. \u0003משקרא קריאת שמע\u0004 — \u0003אין צריך לברך, שכבר נפטר ב\"אהבה רבה\",\u0004 שאף משמעותה כברכה הרגילה על התורה. ואגב העיסוק בברכת התורה הובאו חילוקי דעות מה היא תורה לענין זה של חובת ברכה לפניה.","\u0003אמר רב הונא:\u0004 רק \u0003למקרא צריך לברך,\u0004 כי הוא דבר ה', \u0003ו\u0004אולם \u0003למדרש\u0004 ההלכה הנובע מתוך המקראות — \u0003אינו צריך לברך.\u0004","\u0003ור' אלעזר אמר: למקרא ולמדרש\u0004 שאף הוא בגדר הוצאת ההלכות מדברי המקראות עצמם \u0003צריך לברך,\u0004 אבל \u0003למשנה אינו צריך לברך,\u0004 שאינה אלא פסקי ההלכה כפי שיסדוה החכמים.","\u0003ור' יוחנן אמר: אף למשנה נמי\u0004 \u0005[גם כן]\u0006 \u0003צריך לברך,\u0004 כי היא כוללת את ההלכה הפסוקה והמחייבת, \u0003אבל לתלמוד\u0004 שהוא העיון במשנה ובטעמיה, \u0003אין צריך לברך.\u0004","\u0003ורבא אמר: אף לתלמוד צריך לחזור ולברך,\u0004 כי התלמוד הוא האמצעי האמיתי לברר את משמעותן של ההלכות ואין לימוד תורה לאמיתו אלא בדרך זו. ודברים אלה נסמכים על הלכה למעשה שראו במנהגו של רב.","ש\u0003אמר\u0004 תלמידו \u0003רב חייא בר אשי: זימנין סגיאין הוה קאימנא קמיה\u0004 \u0005[פעמים רבות הייתי עומד לפני]\u0006 \u0003רב לתנויי פרקין ב\"ספרא דבי רב\"\u0004 \u0005[ללמוד את פרקנו ב\"ספר של בית רב\",\u0006 \"תורת כהנים\"\u0005]\u0006 וראיתי שרב \u0003הוה\u0004 \u0005[היה]\u0006 \u0003מקדים וקא משי ידיה, ובריך, ומתני לן פרקין\u0004 \u0005[ורוחץ את ידיו, ומברך, ושונה לנו\u0006 את \u0005פרקנו].\u0006 ואם כן רואים מכאן שאף לפני לימוד והסברת \"תורת כהנים\" שהוא כלימוד גמרא — יש לברך.","ומבררים: \u0003מאי\u0004 \u0005[מה]\u0006 נוסח הברכה אותה \u0003מברך?\u0004 גם בנוסח ברכת התורה נחלקו הדעות; \u0003אמר רב יהודה אמר שמואל:\u0004 נוסחה הוא כשאר ברכות המצוות \"ברוך אתה ה' אלהינו מלך העולם \u0003אשר קדשנו במצותיו וצונו לעסוק בדברי תורה\". \u0004","\u0003ו\u0004אילו \u0003ר' יוחנן מסיים בה הכי\u0004 \u0005[\u0006מוסיף בה \u0005כסיום]\u0006 כעין ברכה נוספת \u0003\"הערב נא\u0004 (עשה את הדברים עריבים) \u0003ה' אלהינו את דברי תורתך בפינו ובפיפיות\u0004 (פיות) \u0003עמך בית ישראל ונהיה אנחנו וצאצאינו וצאצאי עמך בית ישראל כלנו יודעי שמך ועוסקי תורתך ברוך אתה ה' המלמד תורה לעמו ישראל\".\u0004","\u0003ורב המנונא אמר\u0004 נוסח אחר: \u0003\"אשר בחר בנו מכל העמים ונתן לנו את תורתו. ברוך אתה ה' נותן התורה\".\u0004 ועל כך \u0003אמר רב המנונא: זו היא מעולה שבברכות\u0004 התורה, שבנוסחה הקצר היא מצרפת הודאה לה' על התורה וקילוס לתורה ולישראל,","ומכיון שנאמרו בדבר זה שלוש נוסחות ברכה, אשר לכל אחת מעלה משלה, הוסכם כי \u0003הלכך\u0004 \u0005[לכן]\u0006 \u0003לימרינהו לכולהו\u0004 \u0005[שיאמרו את כולן]\u0006 כברכות התורה.","ומעתה שבים לעסוק בברכות קריאת שמע, ומביאים לשם כך מתוך תיאור נוהגי בית המקדש. \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת תמיד: בשחר \u0003אמר להם הממונה\u0004 על סדרי המקדש, לכהנים אנשי המשמר: \u0003\"ברכו ברכה אחת!\". והם\u0004 אנשי המשמר \u0003ברכו. ו\u0004עוד \u0003קראו עשרת הדברות,\u0004 ואת פרשיות \u0003\"שמע\", \"והיה אם שמוע\", \"ויאמר\"\u0004 כרגיל בקריאת שמע. \u0003ו\u0004עוד \u0003ברכו את העם שלש ברכות,\u0004 שהן \u0003\"אמת ויציב\",\u0004 שהיא הברכה שלאחר קריאת שמע, \u0003ועבודה,\u0004 ברכה מיוחדת על קבלת הקרבנות ברצון לפני ה', בדומה לברכת \"רצה\" אשר בשמונה עשרה, \u0003וברכת כהנים\u0004 בדרך תפילה ובלא נשיאת כפים (תוספות). \u0003ובשבת מוסיפין ברכה אחת למשמר היוצא,\u0004 כי ביום השבת מתחלפים משמרות הכהנים העובדים במקדש, ומוסיפים ברכה לכבוד המשמר הקודם. פרטים אחדים במשנה זו אינם ברורים למדי.","ראשית: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003\"ברכה אחת\"\u0004 שהורה הממונה לברך? איזו ברכה היא? ומסופר: \u0003כי הא\u0004 \u0005[כמו זה]\u0006 שאירע ש\u0003ר' אבא ור' יוסי בר אבא אקלעו לההוא אתרא\u0004 \u0005[נזדמנו למקום אחד]\u0006 שלא נתפרש שמו, \u0003בעו מנייהו\u0004 \u0005[שאלו מהם]\u0006 בני המקום: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003\"ברכה אחת\"\u0004 הכתובה במשנה? \u0003לא הוה בידייהו\u0004 \u0005[היה בידם]\u0006 תשובה. \u0003ו\u0004על כן \u0003אתו שיילוהו\u0004 \u0005[באו ושאלוהו]\u0006 את \u0003רב מתנה\u0004 וגם הוא \u0003לא הוה בידיה\u0004 \u0005[היתה בידו]\u0006 תשובה. \u0003אתו שיילוהו\u0004 \u0005[הלכו\u0006 אז \u0005ושאלו]\u0006 את \u0003רב יהודה.\u0004 והוא \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל, \"אהבה רבה\"\u0004 היא הברכה האחת שהיה משמר הכהנים מברך.","תשובה אחרת לשאלה זו \u0003אמר ר' זריקא, אמר ר' אמי, אמר ר' שמעון בן לקיש:\u0004 ברכה זו היא \"יוצר אור\". בבבל שמעו את דברי ר' שמעון בן לקיש בצורה זו. ואולם \u0003כי אתא\u0004 \u0005[\u0006כאשר \u0005בא]\u0006 \u0003רב יצחק בר יוסף\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 שלא כך היה המעשה, ו\u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 שאמר \u0003ר' זריקא\u0004 בשם ריש לקיש \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש אתמר\u0004 \u0005[נאמר]\u0006 \u0003אלא מכללא אתמר\u0004 \u0005[מכלל הדברים\u0006 של ריש לקיש וממסקנתם \u0005נאמר].\u0006 ש\u0003אמר ר' זריקא אמר ר' אמי, אמר ר' שמעון בן לקיש: זאת אומרת,\u0004 כלומר, ניתן להסיק מהביטוי \"ברכו ברכה אחת\" שבמסכת תמיד כי \u0003ברכות\u0004 שלפני קריאת שמע \u0003אין מעכבות זו את זו.\u0004 שאם אמר רק אחת מהן יצא ידי חובה באותה שאמר, כי שתי הברכות אינן תלויות זו בזו ומכאן הסיק ר' זריקא שדעת ריש לקיש שברכה אחת זו היא \"יוצר אור\". מדברי ר' שמעון בן לקיש הסיקו שלדעתו הברכה האחת היא ברכת \"יוצר אור\".","וכך היתה דרך השיקול של אותם חכמים: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי \u0003\"יוצר אור\" הוו אמרי\u0004 \u0005[היו אומרים],\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 המובן של דברי ריש לקיש \u0003ברכות אין מעכבות זו את זו, דלא קא אמרי\u0004 \u0005[שאינם אומרים]\u0006 \u0003\"אהבה רבה\"\u0004 אלא רק ברכת \"יוצר אור\" לבדה, ואף על פי כן יצאו ידי חובת ברכה זו."],["\u0003אלא, אי אמרת\u0004 \u0005[אם תאמר]\u0006 כי \u0003\"אהבה רבה\" הוו אמרי\u0004 \u0005[היו אומרים]\u0006 ודילגו על ברכת \"יוצר אור\" \u0003מאי\u0004 \u0005[מה],\u0006 מדוע תסיק מכאן ש\u0003ברכות אין מעכבות זו את זו?\u0004 שכן אפשר אז להסביר אמירתה של ברכה אחת בלבד בצורה אחרת: \u0003דלמא האי\u0004 \u0005[שמא זה]\u0006 ש\u0003לא אמרי\u0004 \u0005[אמרו]\u0006 \u0003\"יוצר אור\"\u0004 הוא \u0003משום\u0004 ש\u0003לא מטא\u0004 \u0005[הגיע]\u0006 \u0003זמן \"יוצר אור\",\u0004 שעדיין לא זרח אור השמש כי ברכות המשמר נאמרות בשעות הבוקר המוקדמות, הרבה לפני הזריחה, \u0003ו\u0004אחר כך \u0003כי מטא\u0004 \u0005[כאשר הגיע]\u0006 \u0003זמן \"יוצר אור\" הוו אמרי\u0004 \u0005[היו אומרים].\u0006 ואם כן, מן העובדה אשר הסיק ר' שמעון בן לקיש כי \"ברכות אין מעכבות זו את זו\" ברור שלדעתו הברכה שאמרו אנשי המשמר היתה \"יוצר אור\".","מאחר שטיעון זה נראה שקול ומשכנע, שואלים עתה: \u0003ואי מכללא\u0004 \u0005[ואם מכלל\u0006 הדברים\u0005]\u0006 ולא מאמירה מפורשת הוסקו \u0003מאי\u0004 \u0005[מה]\u0006 הפגם בשיקול הזה? שלכאורה אין להבין אחרת את דברי ריש לקיש.","ומשיבים: \u0003דאי מכללא\u0004 \u0005[שאם מכלל\u0006 הדברים הסיקו\u0005]\u0006 אפשר לומר כי \u0003לעולם \"אהבה רבה\" הוו אמרי\u0004 \u0005[היו אומרים].\u0006 \u0003וכי מטא\u0004 \u0005[כאשר הגיע]\u0006 \u0003זמן \"יוצר אור\" הוו אמרי ליה\u0004 \u0005[היו אומרים אותו].\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש הדברים\u0005]\u0006 \u0003\"ברכות אין מעכבות זו את זו\"\u0004 — \u0003סדר ברכות.\u0004 כלומר, ר' שמעון בן לקיש לא אמר שהברכות הנן בלתי תלויות זו בזו, אלא רק שסדר הברכות אינו מעכב, ואף אם אמר \"אהבה רבה\" לפני \"יוצר אור\" ולא כרגיל, יצא ידי חובתו. ואם כן איננו יכולים להוכיח מדבריו מה היתה דעתו ביחס לפירוש \"ברכה אחת\".","סופר מקודם כי הכהנים במקדש היו \u0003קורין עשרת הדברות\u0004 ואת פרשיות \u0003\"שמע\", \"והיה אם שמוע\", \"ויאמר\", \"אמת ויציב\", ועבודה, וברכת כהנים.\u0004","\u0003אמר רב יהודה אמר שמואל: אף בגבולין\u0004 (מחוץ לבית המקדש) \u0003בקשו לקרות כן\u0004 את עשרת הדברות בכל יום, מפני שהם יסודה של התורה (רמב\"ם), \u0003אלא שכבר בטלום\u0004 את קריאת הדברות \u0003מפני תרעומת המינין,\u0004 שהיו המינים אומרים ששאר התורה מחוץ לעשרת הדברות אינה מפי ה' (ירושלמי) ואם ידגישו את הדברות בקריאה בכל יום יהא זה כאילו חיזוק לדבריהם, ועל כן השמיטום מסדר התפילה.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 בריתא \u0005גם כן כך],\u0006 \u0003ר' נתן אומר: בגבולין בקשו לקרות כן, אלא שכבר בטלום מפני תרעומת המינין.\u0004","ומסופר כי כמה חכמים רצו לחדש את קריאת עשרת הדברות, וכמו ש\u0003רבה בר בר חנה סבר למקבעינהו\u0004 \u0005[חשב לקבען]\u0006 \u0003ב\u0004עיר \u0003סורא,\u0004 אך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: כבר בטלום מפני תרעומת המינין.\u0004","וכן כשרצה \u0003אמימר סבר למקבעינהו\u0004 \u0005[חשב לקבען]\u0006 \u0003ב\u0004עיר \u0003נהרדעא, אמר ליה\u0004 \u0005[לו]\u0006 גדול חכמי הדור, \u0003רב אשי: כבר בטלום מפני תרעומת המינין.\u0004","במשנה במסכת תמיד נאמר כי \u0003בשבת\u0004 היו \u0003מוסיפים\u0004 עוד \u0003ברכה אחת למשמר היוצא.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003ברכה אחת\u0004 זו? \u0003אמר ר' חלבו: משמר היוצא\u0004 המסיים את עבודתו בשבת זו \u0003אומר למשמר הנכנס: \"מי ששכן את שמו בבית הזה, הוא ישכין ביניכם אהבה ואחוה ושלום וריעות\".\u0004","שנינו במשנה: שב\u0003מקום שאמרו להאריך\u0004 אינו רשאי לקצר, וכן להיפך. הסוגיה הבאה עוסקת בבעיה הנסמכת במדה ידועה על מסקנות מדברי משנתנו זו. לשאלה העיקרית מקדימים בירור משני של בעיה פשוטה יותר; \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 כי \u0003היכא דקא נקיט כסא דחמרא בידיה וקסבר דשכרא\u0004 \u0005[היכן שאחז כוס יין בידו, וחשב ששכר]\u0006 \u0003הוא, ופתח ומברך אדעתא דשכרא\u0004 \u0005[על דעת ש\u0006המשקה הוא \u0005שכר],\u0006 שרצה לברך כדרך שמברכים על שתיית השכר ברכת \"שהכל נהיה בדברו\", ואחר כך שם לב שבידו יין \u0003וסיים בדחמרא\u0004 \u0005[בשל יין],\u0006 שסיים את הברכה כדרך הברכה על יין \"בורא פרי הגפן\" — ברור ש\u0003יצא,\u0004 שבמקרה מיוחד זה \u0003אי נמי\u0004 \u0005[אם גם,\u0006 אפילו\u0005]\u0006 \u0003אם אמר \"שהכל נהיה בדברו\"\u0004 כפי שחשב לומר מתחילה — \u0003יצא. דהא תנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003על כולם\u0004 (על כל מאכל) \u0003אם אמר \"שהכל נהיה בדברו\"\u0004 אף שלכתחילה נקבעו למיני מאכלים ברכות שונות, לאחר מעשה יפה כוחה של ברכה כללית זו (\"שהכל\") להוציאו ידי חובה בכל. ולכן אם חזר בו ואמר ברכת היין כתקונה — \u0003יצא\u0004 ידי חובתו בכל אופן.","\u0003אלא\u0004 מה יהא \u0003היכא דקא נקיט כסא דשכרא בידיה וקסבר דחמרא\u0004 \u0005[היכן שאחז כוס שכר בידו וחשב שיין]\u0006 \u0003הוא, פתח ובריך אדעתא דחמרא\u0004 \u0005[וברך על דעת יין],\u0006 שרצה לברך \"בורא פרי הגפן\", וכאשר שם לב שאין זה יין \u0003סיים בדשכרא\u0004 \u0005[בשל שכר],\u0006 בברכת \"שהכל\", \u0003מאי\u0004 \u0005[מה]\u0006 יהא דינה של ברכה זו? שלכאורה מורכבת ברכה זו משני חלקים, החלק הראשון (\"בורא פרי הגפן\") אינו יכול להוציא ידי חובה, ואילו החלק השני (\"שהכל\") הוא הברכה הראויה.","והשאלה היא: האם \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003עיקר\u0004 ה\u0003ברכה אזלינן\u0004 \u0005[אנו הולכים],\u0006 \u0003או בתר\u0004 \u0005[אחר]\u0006 ה\u0003חתימה אזלינן\u0004 \u0005[אנו הולכים].\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא הדנה במקרה הדומה לבעיה שלפנינו, וממנה פתרון אפשרי לבעיה זו: מי שברך ברכות קריאת שמע ב\u0003שחרית,\u0004 אם פתח \u0003ב\"יוצר אור\"\u0004 כראוי \u0003וסיים ב\"מעריב ערבים\"\u0004 — \u0003לא יצא\u0004 חובת הברכה. ואולם להיפך אם \u0003פתח ב\"מעריב ערבים\" וסיים ב\"יוצר אור\"\u0004 — \u0003יצא.\u0004","ומעין דברים אלה בברכת קריאת שמע ב\u0003ערבית, אם פתח ב\"מעריב ערבים\" וסיים ב\"יוצר אור\"\u0004 — \u0003לא יצא.\u0004 אך אם \u0003פתח ב\"יוצר אור\" וסיים ב\"מעריב ערבים\"\u0004 — \u0003יצא.\u0004","ומסכמת הברייתא את הדברים, \u0003כללו של דבר: הכל הולך אחר החתום.\u0004 ולפי הנחיה זו אפשר לפתור גם את השאלה בברכות הנהנין שהועלתה מקודם.","את ההוכחה הזו דוחים: \u0003שאני התם\u0004 \u0005[שונה שם,\u0006 בברכת המאורות\u0005]\u0006 \u0003דקאמר\u0004 \u0005[ש\u0006הוא \u0005אומר] \"ברוך\u0006 אתה ה' \u0003יוצר המאורות\"\u0004 (וכפי כן בערב הוא אומר \"ברוך אתה ה' המעריב ערבים\"), שמאחר שברכות אלה הינן ארוכות ומסתיימות בברכה בסופן שהיא מרכזה של הברכה, אפשר לומר שבגלל סיבה זו \"הכל הולך אחר החיתום\". ואולם בברכה קצרה כמו \"שהכל\" או \"בורא פרי הגפן\" יתכן שאם חלקה הראשון פגום — נפסלה הברכה כולה. החלוקה שנעשתה בין ברכת המאורות לברכת הנהנין היתה מבוססת על ההנחה כי חתימתה של ברכת המאורות \"ברוך אתה ה' יוצר המאורות\" הריהי ברכה מושלמת לעצמה.","ואולם דבר זה אינו ברור כל עיקר, כי \u0003הניחא\u0004 \u0005[זה נוח],\u0006 מה שאמרנו מתקבל \u0003ל\u0004שיטת \u0003רב\u0004 ש\u0003אמר\u0004 ש\u0003כל ברכה שאין בה הזכרת השם\u0004 — \u0003אינה ברכה,\u0004 ומכיון שבברכת \"יוצר אור\" יש הזכרת השם — הרי זו ברכה מושלמת לעצמה, \u0003אלא ל\u0004שיטת \u0003ר' יוחנן\u0004 ש\u0003אמר: כל ברכה שאין בה מלכות,\u0004 כלומר, הזכרת \"אלהינו מלך העולם\" — \u0003אינה ברכה,\u0004 הרי שחתימת ברכת \"יוצר אור\" שאין בה הזכרת מלכות אינה ברכה לעצמה, ולשיטה זו \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 כדי להבדיל בין חתימת ברכת הנהנין וחתימת ברכת המאורות?","ומשיבים: גם לדעת ר' יוחנן חתימתה של ברכת המאורות הינה מושלמת, \u0003אלא כיון\u0004 ש\u0003אמר רבה בר עולא\u0004 שמזכירים את \"בורא חושך\" ביום, ו\"גולל אור מפני חושך\" בלילה \u0003כדי להזכיר מדת יום בלילה ומדת לילה ביום,\u0004 הרי שפתיחת הברכה (שבה יש שם מלכות — בערב ובבוקר) מיוחדת ליום או ללילה ו\u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ברכה ומלכות מעיקרא\u0004 \u0005[מתחילה]\u0006 בראשיתה של הברכה — \u0003אתרוייהו קאמר\u0004 \u0005[על שניהם אמר],\u0006 גם על של יום וגם על של לילה. על כן אין להביא הוכחה מברכת המאורות לברכת הנהנין.","ומנסים להביא ראיה אחרת: \u0003תא שמע מסיפא\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006 פתרון לדבר \u0005מ\u0006מה ששנינו \u0005בסוף]\u0006 הברייתא שהובאה מקודם, המסיימת בלשון: \u0003\"כללו של דבר\": הכל הולך אחר החתום,\u0004 וסיומת זו \u0003\"כללו של דבר\" לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]?\u0006 מה היא באה להוסיף על הדוגמא המפורטת? \u0003לאו לאתויי הא דאמרן\u0004 \u0005[\u0006האם \u0005לא להביא\u0006 את \u0005מה שאמרנו]\u0006 ולהודיענו כי בכל מקרה בין בברכה ארוכה ובין בברכה קצרה — הכל הולך אחר החיתום?","ודוחים: \u0003לא, לאתויי נהמא ותמרי\u0004 \u0005[להביא לחם ותמרים],\u0006 שאחר אכילת הלחם מברכים ברכת המזון ארוכה, ואחר התמרים מברכים ברכה קצרה יותר (מעין שלוש). ועל טעויות בשתי ברכות אלה נאמר הכלל \"הכל הולך אחר החיתום\". ומבררים \u0003היכי דמי\u0004 \u0005[כיצד\u0006 היו הדברים \u0005בדיוק]\u0006 בטעות זו שבברכות. \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 ש\u0003אכל נהמא\u0004 \u0005[לחם],\u0006 \u0003וקסבר דתמרי\u0004 \u0005[וחשב שתמרים]\u0006 \u0003אכל, ופתח\u0004 בברכה \u0003אדעתא דתמרי\u0004 \u0005[על דעת תמרים]\u0006 \u0003וסיים בדנהמא\u0004 \u0005[בשל לחם]\u0006 — הלא \u0003היינו בעיין\u0004 \u0005[זוהי בעייתנו]\u0006 והיא זהה לשאלה בענין ברכת היין והשכר!","והתשובה: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 לא נאמר הדבר אלא למקרה מיוחד, בהקשר הבא: \u0003כגון\u0004 ש\u0003אכל תמרי\u0004 \u0005[תמרים],\u0006 \u0003וקסבר נהמא\u0004 \u0005[וחשב\u0006 ש\u0005לחם]\u0006 \u0003אכל, ופתח\u0004 בברכה \u0003בדנהמא\u0004 \u0005[בשל לחם],\u0006 \u0003וסיים בדתמרי\u0004 \u0005[בשל תמרים]\u0006 — \u0003יצא.\u0004 שכן במקרה זה \u0003אפילו סיים בנהמא\u0004 \u0005[לחם]\u0006 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003יצא.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 — \u0003דתמרי נמי מיזן זייני\u0004 \u0005[שהתמרים אף\u0006 הם \u0005מזינים],\u0006 ומי שאכל וברך עליהם ברכת המזון כברכה שעל הלחם, אף שלכתחילה אינו צריך לעשות זאת, אף על פי כן לאחר מעשה יצא ידי חובה. ועל מקרה מיוחד כגון זה נאמר בברייתא \"הכל הולך אחר החיתום\". והסיכום הוא איפוא שהשאלה ביחס לברכה שחציה הראשון אינו מתאים וחציה השני ראוי, נשארה ללא פתרון.","מכאן שבים לדון בבירור נוסחן של ברכות קריאת שמע. \u0003אמר רבה בר חיננא סבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: כל שלא אמר\u0004 בפתיחת הברכה שלאחר קריאת שמע \u0003\"אמת ויציב\"\u0004 ב\u0003שחרית, ו\"אמת ואמונה\"\u0004 ב\u0003ערבית\u0004 — \u0003לא יצא ידי חובתו\u0004 (המאירי), ורמז לשינוי זה ממה \u0003שנאמר: \"להגיד בבקר חסדך ואמונתך בלילות\"\u0004 (תהלים צב, ג), שבבוקר יש להזכיר את חסד ה', ובלילה להדגיש את צד האמונה.","\u0003ו\u0004עוד הביאו דברים ש\u0003אמר רבה בר חיננא סבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: המתפלל, כשהוא כורע\u0004 בברכות שצריך לכרוע בהן \u0003כורע ב\u0004שעה שהוא אומר \"ברוך\", \u0003וכשהוא זוקף\u0004 מכריעתו מיד אחר כך — \u0003זוקף ב\u0004שעה שהוא מזכיר \u0003שם\u0004 ה'.","\u0003אמר שמואל\u0004 שהיה חבירו של רב והאריך ימים אחריו, רמז לדברי רב אלה: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב\u0004 שבשעה שמזכיר שם ה' יזקוף — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003: \"ה' זוקף כפופים\"\u0004 (תהלים קמו, ח), שבהזכרת שם ה' קם הוא מכפיפתו להזכיר כי ה' תמיד זוקף כפופים.","\u0003מתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בשבחו של כהן: \u0003\"מפני שמי נחת הוא\"\u0004 (מלאכי ב, ה), ומכאן שעל האדם להיות נכנע (נחת) לפני שם ה', ולא לזקוף.","ומשיבים על כך: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"בשמי\"?\u0004 אלא \u0003\"מפני שמי\" כתיב\u0004 \u0005[נאמר],\u0006 והכוונה שלפני שהוא מזכיר את השם — אז הוא ניחת ונכנע, כשכורע ב\"ברוך\".","מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לחייא בר רב: בר אוריין\u0004 \u0005[בן תורה],\u0006 \u0003תא ואימא\u0004 \u0005[בוא ואומר]\u0006 \u0003לך מלתא מעלייתא\u0004 \u0005[דבר מעולה]\u0006 ש\u0003אמר אבוך\u0004 \u0005[אביך].\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבוך\u0004 \u0005[אביך]:\u0006 \u0003כשהוא כורע\u0004 — \u0003כורע ב\"ברוך\", כשהוא זוקף\u0004 — \u0003זוקף בשם.\u0004"],["ומענין הכריעות מסופר: \u0003רב ששת, כי\u0004 \u0005[כאשר]\u0006 \u0003כרע\u0004 — \u0003כרע כחיזרא\u0004 \u0005[כמקל]\u0006 בבת אחת ובלא להשתהות. \u0003כי קא זקיף\u0004 \u0005[כאשר היה זוקף]\u0006 — \u0003זקיף כחיויא\u0004 \u0005[זקף כנחש]\u0006 המגביה את עצמו מעט מעט, להראות שאימת ה' עליו, בכריעתו ובזקיפתו (הבונה).","\u0003ו\u0004עוד \u0003אמר רבה בר חיננא סבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב\u0004 בענין נוסח הברכות: \u0003כל השנה כולה אדם מתפלל\u0004 וחותם בברכה השלישית של שמונה עשרה בנוסח \u0003\"האל הקדוש\",\u0004 וכשהוא חותם את הברכה על השבת המשפט לישראל הוא חותם \u0003\"מלך אוהב צדקה ומשפט\", חוץ מעשרה ימים שבין ראש השנה ויום הכפורים\u0004 (הם המכונים \"עשרת ימי תשובה\", הכוללים את שני ימי ראש השנה ויום הכיפורים ושבעת הימים שביניהם), שבהם מדגישים את מלכות ה', \u0003ש\u0004אז \u0003מתפלל וחותם \"המלך הקדוש\", ו\u0004כן \u0003\"המלך המשפט\",\u0004 כלומר, המלך המגלה את עצמו במשפט.","\u0003ו\u0004לעומת זאת \u0003ר' אלעזר אמר\u0004 שאין להקפיד ו\u0003אפילו\u0004 אם \u0003אמר \"האל הקדוש\"\u0004 באותם עשרה ימים — \u0003יצא\u0004 ידי חובתו. וראיה לדבר ממה \u0003שנאמר: \"ויגבה ה' צבאות במשפט והאל הקדוש נקדש בצדקה\"\u0004 (ישעיה ה, טז), ומפרש: \u0003אימתי\u0004 שייך לומר \u0003\"ויגבה ה' צבאות במשפט\",\u0004 שהוא מתגלה במשפט — \u0003אלו עשרה ימים שמראש השנה ועד יום הכפורים, וקאמר\u0004 \u0005[ואמר]\u0006 שם בלשון \u0003\"האל הקדוש\",\u0004 הרי שביטוי זה דיו להדגיש את רוממות ה', ואין צורך לשנות.","ושואלים: \u0003מאי הוה עלה\u0004 \u0005[מה היה עליה]\u0006 על הלכה זו, לגבי פסק?","ואף בכך נחלקו הדעות: \u0003אמר רב יוסף\u0004 בדומה לשיטת ר' אלעזר: אין לשנות מן הנוסח הקבוע \u0003\"האל הקדוש\" ו\"מלך אוהב צדקה ומשפט\"\". רבה אמר\u0004 כדעת רב: \u0003\"המלך הקדוש\" ו\"המלך המשפט\".\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כרבה.\u0004","\u0003ו\u0004עוד \u0003אמר רבה בר חיננא סבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: כל שאפשר לו לבקש רחמים על חבירו ואינו מבקש\u0004 — \u0003נקרא \"חוטא\".\u0004 וראיה לדבר מדברי שמואל \u0003ש\u0004אחר שהוכיח קשות את העם \u0003נאמר: \"גם אנכי חלילה לי מחטא לה' מחדל להתפלל בעדכם\u0004 והוריתי אתכם בדרך הטובה והישרה\u0003\"\u0004 (שמואל א' יב, כג), הרי שאם היה חדל מהתפלל — היה זה חטא.","\u0003אמר רבא: אם תלמיד חכם הוא\u0004 וצריך לרחמים, לא די שיתפלל עליו אלא \u0003צריך שיחלה עצמו עליו,\u0004 בדאגה יתירה. מעתה באים לברר את מקור הלכה זו.","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אילימא\u0004 \u0005[אם לומר]\u0006 שהוא \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 שאמר שאול לאנשיו: \u0003\"ואין חלה מכם עלי ואין גולה את אזני\"\u0004 וגו' (שמואל א' כב, ח), שנראה כי שאול, כתלמיד חכם, ראוי שידאגו לו עד כדי שיחלו עליו — מכאן אין ראיה גמורה, כי \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003מלך שאני\u0004 \u0005[שונה\u0006 הוא\u0005],\u0006 ואולי דאגה יתירה כעין זו ראויה אך למלך לבדו. \u0003אלא מהכא\u0004 \u0005[מכאן]\u0006 יש להוכיח זאת: כאשר מספר דוד על שונאיו, דואג ואחיתופל שהיו תלמידי חכמים, אומר הוא: \u0003\"ואני בחלותם לבושי\u0004 שק עניתי בצום נפשי \u0003\"\u0004וגו' (תהלים לה, יג), הרי שעל תלמידי חכמים יש לדאוג ביותר, עד כדי לבישת שק וצום לבקש על הבראתם.","\u0003ו\u0004עוד \u0003אמר רבה בר חיננא סבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: כל העושה דבר עבירה ומתבייש בו\u0004 — \u0003מוחלין לו על כל עונותיו.\u0004 שהמתבייש על עבירה סימן הוא שהגיע למאוס את העבירה בכלל, וגדול כוחה של בושה זו למחול לו על כל עוונותיו (הריא\"ף). וראיה לדבר ממה \u0003שנאמר: \"למען תזכרי ובשת ולא יהיה לך עוד פתחון פה מפני כלמתך בכפרי לך לכל אשר עשית נאם ה' אלהים\"\u0004 (יחזקאל טז, סג).","ואולם ראיה זו נדחית: \u0003דילמא\u0004 \u0005[שמא]\u0006 ה\u0003צבור שאני\u0004 \u0005[שונה],\u0006 כי ממהרים למחול לציבור מליחיד. \u0003אלא\u0004 הראיה, שאף יחיד נמחלים עוונותיו אם התבייש בעבירה שעשה, היא \u0003מהכא\u0004 \u0005[מכאן]\u0006 מהמסופר בשאול המלך ששאל באוב את שמואל ערב המלחמה עם הפלישתים: \u0003\"ויאמר שמואל אל שאול למה הרגזתני להעלות אתי ויאמר שאול צר לי מאד ופלשתים נלחמים בי (וה') [ואלהים] סר מעלי ולא ענני עוד גם ביד הנביאים גם בחלמות ואקראה לך להודיעני מה אעשה\"\u0004 (שמואל א כח, טו). הרי ששאול מספר ששאל בנביאים וגם בחלומות, \u0003ואילו \"אורים ותומים\" לא קאמר\u0004 \u0005[אמר]\u0006 ששאל בהם, ולא נענה.","וטעמו של דבר — \u0003משום דקטליה\u0004 \u0005[שהרג]\u0006 \u0003לנוב עיר הכהנים\u0004 ונתבייש להזכיר אורים ותומים הנשאלים על ידי כהן, משום חטא נוב.","ומסיימים: \u0003ומנין דאחילו ליה\u0004 \u0005[שמחלו לו]\u0006 לשאול על עוונותיו \u0003מן שמיא\u0004 \u0005[השמים]\u0006 — \u0003שנאמר\u0004 שענה שמואל לשאול: \u0003\"ויאמר שמואל אל שאול ומחר אתה ובניך עמי\"\u0004 (שם יט), \u0003ואמר ר' יוחנן, \"עמי\"\u0004 משמעו לא רק שימות, אלא גם צד נחמה — \u0003במחיצתי\u0004 בין הצדיקים, הרי שנמחלו לו עוונותיו.","ואילו \u0003רבנן אמרי\u0004 \u0005[חכמים אומרים]\u0006 ומביאים ראיה אחרת לכך שנמחל לשאול, \u0003מהכא\u0004 \u0005[מכאן],\u0006 ממה שהגבעונים אמרו לדוד \u0003\"\u0004יותן לנו שבעה אנשים מבניו \u0003והוקענום לה' בגבעת שאול בחיר ה'\"\u0004 (שמואל ב כא, ו). וודאי שהגבעונים אשר זעמו על שאול לא קראו לו \"בחיר ה'\". ועל כן יש להבין ביטוי זה שאינו מדברי הגבעונים, אלא \u0003יצתה בת קול ואמרה \"בחיר ה'\",\u0004 שנמחלו עוונותיו, והוא נמנה בין הצדיקים הגמורים.","ומכאן שבים אל נושא הפרק, ענין קריאת שמע. \u0003אמר ר' אבהו בן זוטרתי אמר ר' יהודה בר זבידא: בקשו\u0004 חכמים \u0003לקבוע את פרשת בלק\u0004 (ברכות בלעם) \u0003בקריאת שמע,\u0004 שתהא חלק מן הקריאה שבכל יום, \u0003ומפני מה לא קבעוה\u0004 — \u0003משום טורח צבור,\u0004 שאין להטריח על הרבים בהוספת דברים.","ומעתה באים לברר \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 רצו להכניס את פרשת בלק? \u0003אילימא\u0004 \u0005[אם לומר]\u0006 \u0003משום\u0004 שהוזכרה בה יציאת מצרים, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה: \"אל מציאם ממצרים\u0004 כתועפות ראם לו\u0003\"\u0004 (במדבר כג כב) — אין פרשה זו מיוחדת בכך, שהרי מצויות פרשות רבות אחרות שהוזכרה בהן יציאת מצרים, ואם כן לטעם זה \u0003לימא\u0004 \u0005[יאמר]\u0006 \u0003פרשת רבית\u0004 (ויקרא כה, לה–לח), או \u0003פרשת משקלות\u0004 (שם יט, לג—לז), \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בהן\u0004 גם כן \u0003יציאת מצרים,\u0004 וקצרות הן ואין בהן טורח ציבור.","\u0003אלא אמר ר' יוסי בר אבין:\u0004 טעם הדבר הוא \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה\u0004 בפרשה זו \u0003האי קרא: \"כרע שכב כארי וכלביא מי יקימנו\u0004 מברכיך ברוך ואורריך ארור\" \u0005(במדבר כד, ט)\u0006, שיש בכך מעין הדברים שבקריאת שמע, \"בשכבך ובקומך\".","על כך שואלים: אם בשל פסוק זה בלבד חשובה פרשת בלק לאומרה בקריאת שמע, \u0003ולימא האי פסוקא\u0004 \u0005[ויאמר\u0006 אם כן \u0005פסוק זה]\u0006 בלבד \u0003ותו לא\u0004 \u0005[ולא עוד].\u0006","ודוחים: אי אפשר לעשות כן, כי \u0003גמירי\u0004 \u0005[למדנו]\u0006 ש\u0003כל פרשה\u0004 ש\u0003פסקה משה\u0004 — \u0003פסקינן\u0004 \u0005[פוסקים אנו]\u0006 ומותר לנו לקרוא אותה לחוד, אבל פרשה ש\u0003לא פסקה משה רבינו\u0004 — \u0003לא פסקינן\u0004 \u0005[אין אנו פוסקים]\u0006 או מוציאים חלק ממנה. ולקרוא את פרשת בלק כולה לא רצו משום טורח הציבור.","ודנים עוד: \u0003פרשת ציצית מפני מה קבעוה\u0004 בקריאת שמע? שהרי מצד תוכנה אינה שייכת לפרשיות הקודמות!","\u0003אמר ר' יהודה בר חביבא: מפני שיש בה חמשה דברים\u0004 נוסף לענין יציאת מצרים, שהיא עיקר טעמה (מלוא הרועים): \u0003מצות ציצית,\u0004 הזכרת \u0003יציאת מצרים,\u0004 קבלת \u0003עול מצות, ו\u0004אזהרה מפני \u0003דעת מינים,\u0004 מפני \u0003הרהור עבירה\u0004 של זנות, \u0003ו\u0004מפני \u0003הרהור עבודה זרה.\u0004","ומבררים את הדברים, \u0003בשלמא הני תלת מפרשן\u0004 \u0005[נניח שלוש אלה\u0006 הן \u0005מפורשות],\u0006 שכן \u0003עול מצות\u0004 מוזכר בפרשת ציצית במה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בפסוק \u0003\"וראיתם אתו וזכרתם את כל מצות ה'\u0004 ועשיתם אותם\u0003\"\u0004 (במדבר טו, לט), \u0003ציצית\u0004 מפורשת בכתוב, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ועשו להם ציצית וגו'\"\u0004 (שם לח), ואף \u0003יציאת מצרים\u0004 מפורשת בכתוב, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"אני ה' אלהיכם \u0003אשר הוצאתי\u0004 אתכם מארץ מצרים וגו'\" (שם מא). \u0003אלא\u0004 שאר דברים שהוזכרו \u0003דעת מינים, הרהור עבירה, והרהור עבודה זרה מנלן\u0004 \u0005[מנין לנו],\u0006 היכן הם בה?","כתשובה מביאים את מה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]\u0006 שבה נדרשים הדברים ברמז מן הפסוק \"ולא תתורו אחרי לבבכם ואחרי עיניכם אשר אתם זונים אחריהם\" (שם לט). \u0003\"אחרי לבבכם\" זו\u0004 ההליכה אחרי הרהורי כפירה ו\u0003מינות\u0004 העשויים לעלות בלבו של אדם, \u0003וכן\u0004 ראיה לדבר ממה ש\u0003הוא אומר\u0004 בכתוב: \u0003\"אמר נבל בלבו אין אלהים\u0004 השחיתו התעיבו עלילה אין עושה טוב\u0003\"\u0004 (תהלים יד, א). ואילו ההליכה אחרי העינים \u0003\"אחרי עיניכם\"\u0004 משמעה במקרא ש\u0003זה\u0004 להגרר אחרי \u0003הרהור עבירה\u0004 של זנות, שאדם רואה וחומד, \u0003שנאמר: \"ויאמר שמשון אל אביו אותה קח לי, כי היא ישרה בעיני\"\u0004 (שופטים יד, ג). \u0003\"אתם זונים\"\u0004 — \u0003זה\u0004 הזנות, מסמלת בדברי הנביאים גם \u0003עבודה זרה, וכן הוא אומר \"\u0004וישובו בני ישראל \u0003ויזנו אחרי הבעלים\"\u0004 (שם ח, לג).","מצוה מן התורה להזכיר את יציאת מצרים בלילות. ואולם היו שחשבו שמצוה זו (כמצוות תפילין או ציצית) מיוחדת לימים ולא ללילות. ועל כן פסקו: \u0003מזכירין יציאת מצרים בלילות,\u0004 בסמוך לקריאת שמע. ו\u0003אמר ר' אלעזר בן עזריה: הרי אני כבן שבעים שנה, ו\u0004אף שהחזקתי בשיטה זו מכל מקום \u0003לא זכיתי,\u0004 כלומר, לא הצלחתי לנצח (המאירי) ולהוכיח שחובה מן התורה היא לקיים את המנהג המקובל (הראב\"ד) ובשל כך \u0003שתאמר יציאת מצרים בלילות, עד שדרשה בן זומא\u0004 והוכיח שהיא חובה.","וכך דרש בן זומא: \u0003נאמר \"למען תזכר את יום צאתך מארץ מצרים כל ימי חייך\"\u0004 (דברים טז, ג). \u0003\"ימי חייך\"\u0004 משמעו — \u0003הימים,\u0004 ואילו הריבוי וההכללה מן המלה \"כל\" וכפי שנאמר \u0003\"כל ימי חייך\"\u0004 באה להוסיף את \u0003הלילות.\u0004","\u0003וחכמים\u0004 שסברו כי אין חובה מן התורה להזכיר יציאת מצרים בלילה, מפרשים את הרבוי \"כל\" בדרך אחרת. והם \u0003אומרים: \"ימי חייך\"\u0004 — \u0003ה\u0004ימים ב\u0003עולם הזה. \"כל\"\u0004 — \u0003להביא\u0004 (להוסיף) \u0003לימות המשיח.\u0004","הויכוח בין בן זומא וחכמים מבואר ביסודו במשנה, ובברייתא מובא המשכו. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006, כנגד דברי חכמים ש\"כל ימי חייך\" משמעו ימות המשיח, \u0003אמר להם בן זומא לחכמים: וכי מזכירין יציאת מצרים לימות המשיח! והלא כבר נאמר\u0004 שהנביא ירמיהו מנבא שבימות המשיח \u0003\"הנה ימים באים נאם ה' ולא יאמרו עוד חי ה' אשר העלה את בני ישראל מארץ מצרים כי אם חי ה' אשר העלה ואשר הביא את זרע בית ישראל מארץ צפונה ומכל הארצות אשר הדחתים שם\"\u0004 (ירמיה כג, ז—ח).","טענה זו דחו החכמים ו\u0003אמרו לו\u0004 כי משמעות הדברים היא \u0003לא ש\u0004לעתיד \u0003תעקר יציאת מצרים ממקומה\u0004 ושלא יזכירוה עוד, \u0003אלא שתהא\u0004 הגאולה מ\u0003שעבוד מלכיות עיקר,\u0004 ואותה יזכירו תמיד \u0003ויציאת מצרים טפל לו.\u0004","ו\u0003כיוצא בו אתה אומר:\u0004 משמעות הביטוי \"לא יאמר\" או \"לא יזכירו\" אינה החלטית, ודבר זה נלמד מן הכתוב \u0003\"לא יקרא שמך עוד יעקב כי אם ישראל יהיה שמך\"\u0004 (בראשית לה, י), שאף שם הפירוש הוא"],["\u0003לא שיעקר\u0004 השם \u0003\"יעקב\" ממקומו\u0004 לחלוטין, \u0003אלא\u0004 השם \u0003\"ישראל\"\u0004 יהיה \u0003עיקר ו\u0004השם \u0003\"יעקב\"\u0004 יהיה \u0003טפל לו,\u0004 שהרי נקרא בשם \"יעקב\" גם אחר כך. \u0003וכן הוא אומר\u0004 כיצד הגאולה אחרונה מאפילה על הגאולה הראשונה בפסוק \u0003\"אל תזכרו ראשנות וקדמניות אל תתבננו\"\u0004 (ישעיה מג, יח). ומפרשים: \u0003\"אל תזכרו ראשונות\"\u0004 — \u0003זה שעבוד מלכיות, \"וקדמוניות אל תתבננו\"\u0004 — \u0003זו יציאת מצרים\u0004 שהיתה עוד קודם לכן, לפני שעבוד מלכיות.","על הנאמר בהמשך כתוב זה: \u0003\"הנני עשה חדשה עתה תצמח\"\u0004 וגו' (שם, יט) \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 בברייתא: \u0003זו מלחמת גוג ומגוג\u0004 שלעתיד, המשכחת את המאורעות הקודמים.","ו\u0003משל למה הדבר דומה\u0004 — \u0003לאדם שהיה מהלך בדרך ופגע\u0004 (פגש) \u0003בו זאב וניצל ממנו, והיה מספר והולך מעשה זאב. פגע בו ארי וניצל ממנו, והיה מספר והולך מעשה ארי. פגע בו נחש וניצל ממנו, שכח מעשה שניהם, והיה מספר והולך מעשה נחש.\u0004 שבכל פעם שהמעשה מפליא יותר, ומספר על פגיעה מסוכנת יותר — מספר אדם והולך במעשה זה. \u0003אף כך ישראל\u0004 — \u0003צרות אחרונות משכחות את הראשונות,\u0004 ומזכירים בעיקר את הנס האחרון.","ואגב הזכרת שינוי שמו של יעקב, מביאים דברים בשינוי שמות אברהם ושרה. מה המובן בהחלפת השם \"אברם\" ל\"אברהם\"? שכן נאמר \u0003\"אברם הוא אברהם\"\u0004 (דברי הימים א' א, כז), ויש לפרש:","\u0003בתחלה נעשה אב\u0004 (שר וגדול) \u0003לארם\u0004 בלבד, ולכן נקרא \"אברם\" (=אב ארם), \u0003ולבסוף\u0004 עם ברכת ה' לו \u0003נעשה אב לכל העולם כולו,\u0004 \"אברהם\" (=אב המון, וכנאמר: \"אב המון גויים נתתיך\". בראשית יז, ה).","וכן מה המובן בהחלפת השם \"שרי\" ל\"שרה\"? ובדומה לאמור באברהם אף בשרה \u0003\"שרי היא שרה\".\u0004","ופירושו: \u0003בתחלה נעשית שרי לאומתה\u0004 בלבד (=שרה שלי), \u0003ולבסוף נעשית שרה\u0004 בכינוי כללי, לאמור: \u0003לכל העולם כולו.\u0004","ועוד בענין שמו של אברהם, \u0003תני\u0004 \u0005[שנה]\u0006 \u0003בר קפרא: כל הקורא לאברהם \"אברם\"\u0004 — \u0003עובר\u0004 על מצוות \u0003עשה. שנאמר: \"והיה שמך אברהם\"\u0004 (בראשית יז, ה) והוא ציווי שיהא זה שמו של אברהם, והמשנה עובר על מצווה זו. ו\u0003ר' אליעזר אומר:\u0004 הקורא לאברהם \"אברם\" \u0003עובר בלאו,\u0004 על מצוות \"לא תעשה\", \u0003שנאמר: \"ולא יקרא עוד את שמך אברם\u0004 והיה שמך אברהם כי אב המון גויים נתתיך\" (שם).","ומקשים: אם רואים דברים אלה כציוויים המחייבים את הכל, \u0003אלא מעתה הקורא לשרה \"שרי\" הכי נמי\u0004 \u0005[כך גם כן]\u0006 יעבור בכגון זה על מצוות עשה או לא תעשה?","ומשיבים: \u0003התם\u0004 \u0005[שם,\u0006 במקרה של שרה\u0005]\u0006 אין זה ציווי כללי, אלא ש\u0003קודשא בריך הוא\u0004 \u0005[הקדוש ברוך הוא]\u0006 \u0003אמר לאברהם\u0004 בלבד: \"ויאמר אלהים אל אברהם, \u0003שרי אשתך לא תקרא את שמה שרי כי שרה שמה\"\u0004 (שם, טו), ואילו באברהם נאמרו הדברים בדרך כוללת \"לא יקרא עוד שמך אברם\".","ושוב שואלים: \u0003אלא מעתה הקורא ליעקב\u0004 שנאמר בו \"לא יעקב יאמר עוד שמך כי אם ישראל\" \u0003\"יעקב\" הכי נמי\u0004 \u0005[גם כן כך,\u0006 יעבור על מצווה\u0005]?!\u0006","ומתרצים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003דהדר אהדריה קרא\u0004 \u0005[שחזר והחזירו הכתוב]\u0006 וקראו ה' עצמו שוב בשם \"יעקב\", \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לפני רדתו למצרים: \u0003\"ויאמר אלהים לישראל במראות הלילה ויאמר יעקב יעקב\u0004 ויאמר הנני\" (שם מו, ב).","\u0003מתיב\u0004 \u0005[משיב,\u0006 מקשה\u0005]\u0006 על כך \u0003ר' יוסי בר אבין, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהקשה זאת \u0003ר' יוסי בר זבידא\u0004 על דברי בר קפרא ור' אליעזר ממה שנאמר בסיפור מאורעות ישראל: \u0003\"אתה הוא ה' האלהים אשר בחרת באברם\u0004 והוצאתו מאור כשדים ושמתו שמו אברהם\" (נחמיה ט, ז), הרי שמזכירים את השם \"אברם\"!","ועל כך עונים: \u0003התם\u0004 \u0005[שם]\u0006 ה\u0003נביא הוא דקא מסדר לשבחיה דרחמנא\u0004 \u0005[שמסדר את שבחו של ה' ]\u0006 ובכלל השבח הוא \u0003מאי דהוה מעיקרא\u0004 \u0005[מה שהיה מתחילה]\u0006, לפני שנקרא \"אברהם\", ואכן הכתוב ממשיך ואומר: \"והוצאתו מאור כשדים ושמת שמו אברהם. ומצאת את לבבו נאמן לפניך וכרות עמו הברית לתת את ארץ הכנעני... לתת לזרעו ותקם את דבריך כי צדיק אתה\" (שם ז-ח).","\u0003הדרן עלך מאימתי\u0004","בעיה ראשונה הנידונה רק ברמז במשנה הריהי שאלת הכוונה. \u0003היה\u0004 אדם \u0003קורא בתורה\u0004 אותן פרשיות של קריאת שמע \u0003והגיע זמן המקרא\u0004 (קריאת שמע) בבוקר או בערב, \u0003אם כוון לבו\u0004 — \u0003יצא\u0004 ואינו צריך לחזור ולקרוא קריאת שמע במיוחד, ואף הברכות אינן מעכבות (ר\"ח). מלכתחילה ודאי שאין להפסיק בקריאת שמע, ואולם נחלקו תנאים עד כמה יש להחמיר בדבר, ובדבר החילוק בין הפסקות בין הקטעים לבין הפסקה בתוך הקטע.","\u0003בפרקים,\u0004 כלומר, בין הקטעים השונים בקריאת שמע, הקורא את שמע \u0003שואל\u0004 בשלום הבריות \u0003מפני הכבוד\u0004 כשהוא פוגש באנשים שחובה עליו לכבדם, \u0003ו\u0004כן \u0003משיב\u0004 להם שלום. \u0003ובאמצע\u0004 הקטע \u0003שואל מפני היראה\u0004 מאדם שהוא חושש שמא יזיק לו אם לא ישאל בשלומו (מאירי), \u0003ומשיב\u0004 לאדם כזה אם הקדים לשאול בשלומו, אלו \u0003דברי ר' מאיר,\u0004","\u0003ר' יהודה אומר:\u0004 יש לחלק בין שאילת שלום לתשובה, \u0003באמצע\u0004 הפרק \u0003שואל\u0004 הקורא את שמע \u0003מפני היראה,\u0004 ומותר לו ל\u0003השיב\u0004 גם \u0003מפני הכבוד. ו\u0004אילו \u0003בפרקים שואל מפני הכבוד, ומשיב שלום לכל אדם\u0004 אף אם אינו חייב בכבודו.","בעצם ההגדרה מה הוא הנקרא \"פרק\", \u0003אלו הן בין הפרקים: בין ברכה ראשונה לשניה, בין שניה ל\"שמע\", בין \"שמע\" ל\"והיה אם שמע\", בין \"והיה אם שמע\", ל\"ויאמר\", בין \"ויאמר\" ל\"אמת ויציב\".\u0004","שלדעת חכמים כל ברכה וכל פרשה בקריאת שמע הריהי ענין לעצמו, וביניהם הוא \"בין הפרקים\", ואילו \u0003ר' יהודה אומר: בין \"ויאמר\" ל\"אמת ויציב\"\u0004 שהוא תחלת הברכה הבאה — \u0003לא יפסיק,\u0004 שלדעתו יש לחבר אותם. מאחר שבתורה אין פרשיות קריאת שמע צמודות זו לזו, ואף סדרן בתורה שונה, יש להסביר מה טעם סודרו כך הפרשיות בקריאת שמע.","\u0003אמר ר' יהושע בן קרחה: למה קדמה\u0004 במצות קריאת שמע, \u0003פרשת \"שמע\" ל\"והיה אם שמע\"\u0004 — \u0003כדי שיקבל עליו עול מלכות שמים\u0004 שהיא ההכרה בה' ובאחדותו \u0003תחלה,\u0004 בפסוק הראשון של שמע, \u0003ואחר כך מקבל עליו עול מצות,\u0004 שעליהן מדובר באופן כולל ב\"והיה אם שמוע\". \"\u0003והיה אם שמע\"\u0004 קודמת \u0003ל\"ויאמר\"\u0004 — \u0003לפי ש\u0004הכתוב בפרשת \u0003\"והיה אם שמע\" נוהג בין ביום ובין בלילה,\u0004 ואילו \u0003\"ויאמר\" אינו נוהג אלא ביום בלבד, שהרי עניינה מצוות ציצית שאינה נוהגת אלא ביום.\u0004","שנינו במשנה שהקורא בתורה צריך לכוון לבו לקריאת שמע כדי לצאת ידי חובתו, ומכאן רוצים להסיק: \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי \u0003מצות צריכות כוונה,\u0004 שבשעת עשיית המצוה צריך להתכוון לצאת ידי חובה, ואם לא כיוון — \u0003לא יצא. ובכך תיפתר לנו בעיה המצויה במקומות רבים בתלמוד ללא פתרון. את המסקנה הזאת דוחים:\u0004","\u0003מאי\u0004 \u0005[מה,\u0006 פירוש\u0005] \"\u0006\u0003אם כוון לבו\"\u0004 — שכיוון לבו \u0003לקרות.\u0004 את ההסבר הזה מתקיפים: כיצד אפשר להסביר שצריך לשים לב ו\u0003לקרות?! והא קא קרי\u0004 \u0005[והרי הוא קורא]!\u0006 שהרי מדובר באדם הקורא בתורה. ואם כן שוב יש להבין לכאורה \"כוונה\" במובן של כוונה לצאת ידי המצווה.","ודוחים: אפשר לפרש כי המדובר כאן הוא \u0003בקורא להגיה,\u0004 שקורא את הדברים בספר לא כדי לקרוא בו, כי אם כדי לתקן את השגיאות בספר זה, וממילא לא היתה כוונתו כלל לשם קריאה, ועל כן, אם כיוון לבו לקרות בלבד — יצא, ואינו צריך להתכוון לקרות לשם מצווה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 ברייתא שנחלקו רבי וחכמים בלשון קריאת שמע, והיא משמשת מבוא לעיון נרחב בשאלת הכוונה בקריאה. ששנינו: \u0003קריאת שמע\u0004 נקראת \u0003ככתבה,\u0004 נקראת בשפה העברית בה היא כתובה, אלו \u0003דברי רבי. וחכמים אומרים:\u0004 קריאת שמע נקראת \u0003בכל לשון.\u0004","ומבררים \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 להלכה שקובע \u0003רבי?\u0004 ומשיבים: \u0003אמר קרא\u0004 מקור ההלכה הוא בהדגשת המילים \u0003\"והיו\u0004 הדברים האלה אשר אנכי מצוך היום על לבבך\u0003\"\u0004 (דברים ו, ו), ש\"והיו\" משמעו: \u0003בהוייתן\u0004 (כמות שהן) \u0003יהו\u0004 \u0005[יהיו],\u0006 שאין לשנותן מלשונן המקורית.","ומבררים עוד: \u0003ורבנן, מאי טעמייהו\u0004 \u0005[וחכמים, מה טעמם]?\u0006 ומשיבים: טעמם של חכמים במה ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"שמע\u0004 ישראל\" (שם, ד), והם מפרשים את הלשון \"שמע\" במובן הבנה — הבן \u0003בכל לשון שאתה שומע.\u0004 ומעתה מבררים כיצד מסביר כל צד במחלוקת את דברי ההוכחה של הצד השני.","\u0003ולרבי נמי\u0004 \u0005[גם כן],\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"שמע\"!\u0004 ומשיבים: הכתוב \u0003ההוא מבעי ליה\u0004 \u0005[נצרך לו],\u0006 כדי להשמיענו הלכה אחרת: \u0003השמע לאזניך מה שאתה מוציא מפיך,\u0004 שיש לקיים \"שמע\" כמשמעו, ולשמוע את הדברים שאדם אומר בקריאה.","\u0003ו\u0004אם כן יש לשאול מה אומרים \u0003רבנן\u0004 על פירוש זה? ותשובתם, שאין הם מקבלים את הפירוש המילולי של \"שמע\" אלא \u0003סברי להו כמאן דאמר\u0004 \u0005[סבורים הם כ\u0006דעת \u0005מי שאומר]\u0006 שמי שקרא ו\u0003לא השמיע לאזנו\u0004 את הדברים — \u0003יצא.\u0004","ועוד שואלים: \u0003ולרבנן נמי\u0004 \u0005[ול\u0006שיטת \u0005חכמים]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"והיו\",\u0004 וכיצד מפרשים הם הדגשה זו? ומשיבים: \u0003מבעי להו\u0004 \u0005[צריך להם\u0006 ביטוי זה\u0005]\u0006 ללמדנו הלכה \u0003שלא יקרא למפרע,\u0004 שלא יקרא את הפרשה שלא כסדרה כגון מסופה לראשה, אלא ישמור על הסדר הכתוב.","\u0003ורבי,\u0004 ענין זה \u0003שלא יקרא למפרע מנא ליה\u0004 \u0005[מניין לו]?\u0006 ומשיבים: רבי \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו\u0006 הדבר\u0005]\u0006 \u0003מ\u0004הדגשה אחרת שבכתוב \"והיו הדברים האלה אשר אנכי מצוך היום על לבבך\", שאפשר היה לכתוב \"\u0003דברים\u0004 אלה\", ואם כן ההדגשה שב—ה' הידיעה \"\u0003הדברים\"\u0004 כוונתה לחיזוק: הדברים האלה בסדר זה דווקא. \u0003ו\u0004אילו \u0003רבנן\u0004 \u0005[חכמים]\u0006 אינם סבורים שיש ללמוד מן הביטוי הזה, כי \u0003\"דברים\" \"הדברים\"\u0004 — \u0003לא דרשי\u0004 \u0005[אינם דורשים].\u0006 שלדעתם זהו ענין של סגנון שאין בו משמעות הלכתית.","את המחלוקת הזו מנסים לקשר עם מחלוקת אחרת, \u0003למימרא דסבר\u0004 \u0005[האם לומר שסבור]\u0006 \u0003רבי\u0004 כי \u0003כל התורה כולה בכל לשון נאמרה,\u0004 שכל פרשה שבתורה שיש מצוה בקריאתה (תוספות) ולימוד וקריאה בתורה בכלל (מאירי) מותרים בכל לשון, ולאו דווקא בלשון הקודש. והראיה לכך: \u0003דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך,\u0006 לומר\u0005]\u0006 שהתורה כולה \u0003בלשון הקודש נאמרה\u0004 ואסור לשנותה ללשון אחרת, אם כן \u0003\"והיו\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי?\u0004 שאין צורך בהדגשה מיוחדת בקריאת שמע, שהרי הכל אסור בקריאה בשינוי. ומאחר ויש צורך לכתוב \"והיו\", הרי שלדעתו מותר לקרוא את התורה כולה פרט לקריאת שמע בכל לשון.","ודוחים: אין הכרח לומר כך, ומה שכתוב \"והיו\" \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 במקרה זה \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 לשון \u0003\"שמע\"\u0004 והיינו מבינים כדעת חכמים שמותר לקרוא בכל לשון, על כן ההדגשה \"והיו\".","וכן מנסים לברר: \u0003למימרא דסברי רבנן\u0004 \u0005[האם לומר שסבורים חכמים]\u0006 ש\u0003כל התורה כולה בלשון הקודש נאמרה\u0004 ואין לשנות ללשון אחר, והראיה לכך: \u0003דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003בכל לשון נאמרה,\u0004 אם כן לשון \u0003\"שמע\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי?!\u0004 שהרי מותר לקרוא את כל התורה בכל לשון.","ודוחים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 לכתוב \"שמע\" בכל אופן \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"והיו\",\u0004 ואפשר היה להבין שאסור לשנות בקריאת שמע, כדעת רבי, על כן נאמר שוב \"שמע\".","על פסוקים אלה עצמם מתבססות מחלוקות יסודיות בשאלת חובת הקריאה והכוונה בקריאת שמע. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מן המלה \u0003\"והיו\"\u0004 למדים \u0003שלא יקרא למפרע, \"הדברים... על לבבך\"\u0004 משמעו — בכוונת הלב. ואולם \u0003יכול תהא כל הפרשה צריכה כוונה?\u0004 — \u0003תלמוד לומר \"האלה\"\u0004 ללמד כי \u0003עד כאן,\u0004 עד מילים אלה \u0003צריכה כוונה, מכאן ואילך אין צריכה כוונה,\u0004 ואף הקוראה בלא להתכוון יצא. אלו \u0003דברי ר' אליעזר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' עקיבא: הרי הוא,\u0004 הכתוב, \u0003אומר:\u0004"],["\u0003\"אשר אנכי מצוך היום על לבבך\",\u0004 הרי שהמלה \"האלה\" לא באה להגביל את מצוות הכוונה. ולהיפך, \u0003מכאן אתה למד שכל הפרשה כולה צריכה כוונה.\u0004","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: הלכה כר' עקיבא,\u0004 שכל הפרשה צריכה כוונה.","\u0003איכא דמתני לה אהא דתניא\u0004 \u0005[יש ששונים אותה\u0006 הלכה שאמר ר' יוחנן, \u0005על\u0006 דבר \u0005זה ששנינו\u0006 בתוספתא]. שמוצאים אנו מחלוקת תנאים, שלדעת התנא הראשון \u0003הקורא את שמע צריך שיכוין את לבו\u0004 בכל הקריאה כולה, ואילו \u0003ר' אחא משום\u0004 (בשם) \u0003ר' יהודה אומר: כיון שכוון לבו בפרק\u0004 ה\u0003ראשון\u0004 (\"שמע\") בלבד \u0003שוב אינו צריך\u0004 לכוון יותר. ועל ברייתא זו \u0003אמר רבה בר בר חנה אמר ר' יוחנן: הלכה כר' אחא שאמר משום ר' יהודה.\u0004 והרי זו נוסחה השונה מן הקודמת בצורתה החיצונית וזהה מבחינת תוכנה.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 העוסקת בנושא זה ומביאה דעות נוספות. נאמר בפרשת שמע \u0003\"והיו\",\u0004 ומלשון זה יש ללמוד \u0003שלא יקרא למפרע.\u0004 ומהמילים \u0003\"על לבבך\" ר' זוטרא אומר\u0004 יש ללמוד כי \u0003עד כאן מצות כוונה,\u0004 ו\u0003מכאן ואילך,\u0004 בפרשה השניה, \u0003מצות קריאה. ר' יאשיה אומר\u0004 שיש להבין את הדברים להיפך: \u0003עד כאן מצות קריאה,\u0004 ו\u0003מכאן ואילך\u0004 — \u0003מצות כוונה.\u0004 ומבררים את הברייתא.","לדעת ר' זוטרא מכאן ואילך — משני הפסוקים הראשונים — מצוות קריאה, ולכאורה \u0003מאי שנא\u0004 \u0005[מה שונה,\u0006 מדוע\u0005]\u0006 \u0003מכאן ואילך\u0004 שהיא \u0003מצות קריאה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בפרשה השניה: \u0003\"\u0004ולמדתם אותם את בניכם \u0003לדבר בם\"\u0004 (דברים יא, יט). ואולם מה הראיה בדבר? \u0003הכא נמי הא כתיב\u0004 \u0005[כאן,\u0006 בפרשה הראשונה, \u0005גם כן הרי נאמר]\u0006 \u0003\"ודברת בם\",\u0004 הרי שמצוות הדיבור, הקריאה, שייכת גם בפרשה הראשונה!","אלא יש לומר ש\u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 זו היתה כוונתו\u0005]:\u0006 \u0003עד כאן מצות כוונה וקריאה\u0004 יחד, ואולם \u0003מכאן ואילך\u0004 — \u0003קריאה\u0004 אף \u0003בלא כוונה.\u0004","ושוב שואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה,\u0006 משום מה\u0005]\u0006 סבר ר' זוטרא ש\u0003עד כאן\u0004 בפרשה הראשונה שייכת גם \u0003מצות כוונה ו\u0004גם מצות \u0003קריאה,\u0004 שכן מצויים בה שני היסודות, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 גם \u0003\"על לבבך\"\u0004 וגם \u0003\"ודברת בם\".\u0004 ואולם \u0003התם נמי הא כתיב\u0004 \u0005[שם\u0006 בפרשה השניה \u0005גם כן הרי נאמר]\u0006 \u0003\"\u0004ושמתם את דברי אלה \u0003על לבבכם... לדבר בם\",\u0004 הרי שגם בה יש צד של כוונה.","על כך משיבים: הפסוק \u0003ההוא מבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004שיטת \u0003ר' יצחק\u0004 ש\u0003אמר\u0004 כי הכתיב \u0003\"ושמתם את דברי אלה\"\u0004 מכוון באופן מילולי לפרשיות קריאת שמע המצויות בתוך התפילין וכוונת הפסוק: \u0003שתהא שימה\u0004 של התפילין על היד \u0003כנגד הלב.\u0004 ומעתה באים לברר את השיטה השניה.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא, \u0003ר' יאשיה אומר: עד כאן\u0004 בפרשה ראשונה \u0003מצות קריאה,\u0004 ואילו \u0003מכאן ואילך\u0004 — \u0003מצות כוונה.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה,\u0006 מדוע\u0005]\u0006 \u0003מכאן ואילך מצות כוונה\u0004 — \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 בפרשה השניה \u0003\"\u0004ושמתם את דברי אלה \u0003על לבבכם\",\u0004 ואולם \u0003הכא נמי הא כתיב\u0004 \u0005[כאן,\u0006 בפרשה הראשונה \u0005הרי נאמר גם כן]\u0006 \u0003\"על לבבך\"!\u0004","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך היתה כוונתו: \u0003עד כאן\u0004 בפרשה הראשונה, \u0003מצות קריאה וכוונה,\u0004 ואולם \u0003מכאן ואילך\u0004 — \u0003כוונה בלא\u0004 חובת \u0003קריאה. ועוד שואלים:\u0004","\u0003ומאי שנא\u0004 \u0005[ומה שונה,\u0006 משום מה\u0005]\u0006 \u0003עד כאן\u0004 בפרשה הראשונה יש \u0003מצות קריאה וכוונה\u0004 — \u0003שכן דכתיב\u0004 \u0005[שנאמר]\u0006 בה גם \u0003\"על לבבך\"\u0004 וגם \u0003\"ודברת בם\",\u0004 ואולם \u0003התם נמי הא כתיב\u0004 \u0005[שם\u0006 בפרשה השניה \u0005גם כן הרי נאמר]\u0006 \u0003\"\u0004ושמתם את דברי אלה \u0003על לבבכם...\u0004 ולמדתם אותם את בניכם \u0003לדבר בם\"!\u0004","על כך משיב ר' יאשיה: הכתוב \u0003ההוא בדברי תורה\u0004 בכלל הוא מדבר, ולאו דווקא בקריאת שמע. \u0003והכי קאמר רחמנא\u0004 \u0005[וכך אומרת התורה]:\u0006 \u0003אגמירו בנייכו\u0004 \u0005[למדו\u0006 את \u0005בניכם]\u0006 דברי \u0003תורה, כי היכי דליגרסו בהו\u0004 \u0005[כדי שיהיו בקיאים בהם].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת בענין הקורא קריאת שמע ואומר את הפסוק \u0003\"שמע ישראל ה' אלהינו ה' אחד\"\u0004 — \u0003עד כאן\u0004 בלבד \u0003צריכה כוונת הלב,\u0004 אלו \u0003דברי ר' מאיר. ואמר רבא:\u0004 בדבר זה \u0003הלכה כר' מאיר.\u0004","\u0003סומכוס אומר: כל המאריך ב\"אחד\"\u0004 בקריאת שמע, \u0003מאריכים לו\u0004 בשכר זה \u0003ימיו ושנותיו.\u0004 על כך \u0003אמר רב אחא בר יעקב: ו\u0004בלבד שיאריך \u0003בדלי\"ת,\u0004 כי אז נשמעת המלה \"אחד\" בשלימותה. \u0003אמר רב אשי: ובלבד שלא יחטוף בחי\"ת,\u0004 שלא יקרא אותה בחטיפה ובמהירות.","ומסופר: \u0003ר' ירמיה הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003ר' חייא בר אבא, חזייה דהוה\u0004 \u0005[ראהו שהוא]\u0006 \u0003מאריך טובא\u0004 \u0005[הרבה],\u0006 באמירת \"אחד\", \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כיון דאמליכתיה\u0004 \u0005[שהמלכת אותו,\u0006 את ה'\u0005]\u0006 במחשבה \u0003למעלה\u0004 בשמים \u0003ולמטה ולארבע רוחות השמים\u0004 — \u0003תו לא צריכת\u0004 \u0005[שוב אינך צריך]\u0006 להאריך.","\u0003אמר רב נתן בר מר עוקבא אמר רב יהודה: \"על לבבך\"\u0004 יאמר \u0003בעמידה.\u0004 על כך תמהים: \u0003\"על לבבך\" סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 כיצד אפשר לחשוב שיקרא רק שתי מילים אלה בעמידה, ומהו יחודן? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כי \u0003עד \"על לבבך\"\u0004 צריך הקורא את שמע לומר \u0003בעמידה. מכאן ואילך\u0004 — \u0003לא,\u0004 אינו חייב בכך. \u0003ו\u0004אילו \u0003ר' יוחנן אמר: את כל הפרשה\u0004 הראשונה \u0003כולה\u0004 צריך לומר \u0003בעמידה.\u0004","ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שהרי \u0003אמר רבה בר בר חנה אמר ר' יוחנן: הלכה כר' אחא שאמר משום \u0004 \u0005[בשם]\u0006 \u0003ר' יהודה.\u0004 שחייב אדם לקרוא בכוונה את כל הפרשה הראשונה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: הפסוק \u0003\"שמע ישראל ה' אלהינו ה' אחד\" זו\u0004 היא \u0003קריאת שמע של ר' יהודה הנשיא,\u0004 שהיה קורא בזמן הקריאה פסוק זה בלבד. ומסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לר' חייא\u0004 דודו: \u0003לא חזינא ליה\u0004 \u0005[ראיתי אותו]\u0006 את \u0003רבי,\u0004 ר' יהודה הנשיא, שהוא \u0003מקבל עליה\u0004 \u0005[עליו]\u0006 \u0003מלכות שמים,\u0004 שאין אני רואה אותו קורא קריאת שמע. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא דודו: \u0003בר פחתי\u0004 \u0005[בן אצילים],\u0006 \u0003בשעה שמעביר\u0004 רבי את \u0003ידיו על פניו\u0004 בבית המדרש בתוך שיעורו, אז \u0003מקבל\u0004 הוא \u0003עליו עול מלכות שמים.\u0004 שהרי קריאת שמע שלו לא היתה אלא פסוק אחד בלבד.","ביחס למנהגו של רבי נחלקו תלמידיו ובני ביתו, האם היה \u0003חוזר\u0004 מאוחר יותר \u0003וגומרה, או אינו חוזר וגומרה? בר קפרא אומר: אינו חוזר וגומרה,\u0004 ו\u0003ר' שמעון ברבי\u0004 (בנו של רבי), היה \u0003אומר: חוזר וגומרה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003בר קפרא לר' שמעון ברבי: בשלמא לדידי דאמינא\u0004 \u0005[נניח לשיטה שלי שאני אומר]\u0006 \u0003\"אינו חוזר וגומרה\", היינו דמהדר\u0004 \u0005[זהו\u0006 הטעם \u0005שמחזר]\u0006 \u0003רבי\u0004 בשעת לימודו \u0003אשמעתא דאית\u0004 \u0005[על הלכה שיש]\u0006 \u0003בה\u0004 מענין \u0003יציאת מצרים,\u0004 שעל ידי דיון בהלכה כזו מקיים הוא את המצווה להזכיר יציאת מצרים, שלדעתי אינו מסיים קריאת שמע ואין לו הזדמנות אחרת להזכירה. \u0003אלא לדידך דאמרת\u0004 \u0005[לשיטה שלך שאתה אומר]\u0006 ש\u0003חוזר וגומרה, למה ליה לאהדורי\u0004 \u0005[לו לחזר],\u0006 אחר הזכרת יציאת מצרים?","על כך ענה ר' שמעון: רבי עושה זאת \u0003כדי להזכיר יציאת מצרים בזמנה,\u0004 בזמן קריאת שמע.","ומענין הלכה זו \u0003אמר ר' אילא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר מרתא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: אם אמר\u0004 את הפסוק \u0003\"שמע ישראל ה' אלהינו ה' אחד\" ונאנס בשינה\u0004 (נרדם על כורחו) — \u0003יצא\u0004 ידי חובה. וכן \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לדרו עבדיה\u0004 \u0005[עבדו]:\u0006 \u0003בפסוקא קמא\u0004 \u0005[בפסוק ראשון ]\u0006 — \u0003צערן [\u0004\u0005צערני],\u0006 אם תראה שאני נרדם, \u0003טפי [\u0004\u0005יותר]\u0006 מכאן — \u0003לא תצערן\u0004 \u0005[אל תצערני].\u0006 וכן \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף לרב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה\u0004 בשאלה: \u0003אבוך היכי הוה עביד\u0004 \u0005[אביך כיצד היה עושה]?\u0006 וענה לו: \u0003בפסוקא קמא — הוה קא מצער נפשיה, טפי\u0004 — \u0003לא הוה מצער נפשיה\u0004 \u0005[בפסוק ראשון\u0006 — \u0005היה מצער\u0006 את \u0005עצמו,\u0006 שלא להרדם, \u0005יותר מזה\u0006 — \u0003לא היה מצער\u0004 את \u0005עצמו].\u0006","\u0003אמר רב יוסף:\u0004 השוכב \u0003פרקדן,\u0004 כלומר, על גבו, \u0003לא יקרא קריאת שמע,\u0004 שדרך שכיבה זו מכוערת היא. על כך שואלים: \u0003מקרא\u0004 \u0005[לקרוא]\u0006 \u0003הוא\u0004 ש\u0003לא ליקרי\u0004 \u0005[יקרא],\u0006 \u0003הא מיגנא שפיר דמי\u0004 \u0005[\u0006ו\u0005אולם לשכב\u0006 כך \u0005ראוי הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יהושע בן לוי לייט אמאן דגני אפרקיד\u0004 \u0005[היה מקלל את מי ששוכב פרקדן]!\u0006","ומתרצים: \u0003מיגנא כי מצלי\u0004 \u0005[שכיבת\u0006 פרקדן \u0005כאשר\u0006 הוא \u0005נוטה]\u0006 קצת הצידה — \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 מותר\u0005],\u0006 ואולם \u0003מקרא אף על גב דמצלי נמי\u0004 \u0005[לקרוא\u0006 קריאת שמע, \u0005אף על פי ש\u0006הוא \u0005נוטה\u0006 קצת \u0005גם כן]\u0006 — \u0003אסור.\u0004","על כך שואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יוחנן מצלי וקרי\u0004 \u0005[היה שוכב\u0006 פרקדן \u0005ומוטה\u0006 קצת \u0005וקורא]\u0006 קריאת שמע!","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 דינו של \u0003ר' יוחנן\u0004 לענין זה כיון ש\u0003בעל בשר הוה\u0004 \u0005[היה],\u0006 וקשה היה לו לקרוא באופן אחר.","במשנה הובאו דברי ר' מאיר ש\u0003בפרקים\u0004 שבין הפרשיות \u0003שואל\u0004 שלום מפני הכבוד ומשיב שלום, ובאמצע שואל מפני היראה ומשיב.","על כך שואלים: \u0003משיב מחמת מאי\u0004 \u0005[מה]?\u0006 \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שמשיב \u0003מפני הכבוד, השתא משאל שאיל, אהדורי מבעיא\u0004 \u0005[עכשיו\u0006 ששנינו שהרי הוא \u0005שואל\u0006 בשלום, וכי \u0005צריך\u0006 לומר שהוא \u0005משיב]?!\u0006 \u0003אלא\u0004 כך יש לפרש: \u0003שואל\u0004 שלום — \u0003מפני הכבוד, ומשיב שלום\u0004 — \u0003לכל אדם. ואם כן אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003\"ובאמצע שואל מפני היראה, ומשיב\".\u0004","ואף כאן יש לברר \u0003משיב מחמת מאי\u0004 \u0005[מה]?\u0006 \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שמשיב \u0003מפני היראה\u0004 — \u0003השתא משאל שאיל, אהדורי מבעיא\u0004 \u0005[עכשיו\u0006 ששנינו שהרי הוא \u0005שואל\u0006 בשלום, \u0005צריך\u0006 לומר שהוא \u0005משיב?]\u0006 \u0003אלא\u0004 ודאי כוונתו משיב שלום — אף \u0003מפני הכבוד.\u0004 ואם כן, \u0003היינו\u0004 \u0005[זוהי]\u0006 בדיוק השיטה \u0003דרבי יהודה דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 ש\u0003ר' יהודה אומר: באמצע\u0004 — \u0003שואל מפני היראה, ומשיב מפני הכבוד, ובפרקים\u0004 — \u0003שואל מפני הכבוד ומשיב שלום לכל אדם,\u0004 ואם כן מה המחלוקת ביניהם?","על כך אומרים: \u0003חסורי מחסרא, והכי קתני\u0004 \u0005[חסרה המשנה\u0006 ביטוי מסויים \u0005וכך\u0006 היא \u0005שנויה\u0006 בשלימותה\u0005]:\u0006 \u0003בפרקים\u0004 — \u0003שואל מפני הכבוד, ואין צריך לומר שהוא משיב. ובאמצע\u0004 — \u0003שואל מפני היראה, ואין צריך לומר שהוא משיב,\u0004 אלה \u0003דברי ר' מאיר. ר' יהודה אומר: באמצע\u0004 — \u0003שואל מפני היראה ומשיב מפני הכבוד,\u0004"]]};
